INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','monumento','Núcleos de población de Aracena','El término municipal incluye los siguientes núcleos de población: Carboneras, Jabuguillo, Linares de la Sierra -límite- y Valdezufre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','monumento','Gruta de las Maravillas','Extraordinaria cavidad natural kárstica de relevancia universal y primer lugar de interés turístico subterráneo de España, constituida por una colosal red de estancias y galerías excavadas de forma monumental por el agua bajo el cerro del castillo que alberga colosales formaciones de estalactitas, estalagmitas y lagos interiores de gran plasticidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','iglesia','Iglesia Prioral de Nuestra Señora del Mayor Dolor (Iglesia del Castillo)','Joya monumental del gótico tardío y renacimiento construida en sillería caliza calavera de primer orden en el siglo XIV al interior del recinto fortificado de la alcazaba andalusí, la cual exhibe tres elevadas naves de gran luz espacial cubiertas por intrincadas bóvedas de crucería estrellada compleja y una espectacular torre mudéjar que emula la Giralda de Sevilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','monumento','Cabildo Viejo','Edificio civil de estilo renacentista puro del siglo XVI edificado en sillería regular bajo trazas de la escuela de Hernán Ruiz II que presenta una fachada monumental con portalón dovelado flanqueada por blasones heráldicos imperiales labrados en relieve.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22004','iglesia','Convento de Jesús María (Dominicas)','Complejo monacal del siglo XVII edificado en piedra de montaña que conserva un bellísimo claustro barroco de planta cuadrangular porticada con columnas toscanas de piedra labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21053','monumento','Murallas de Niebla','Colosal e inexpugnable recinto fortificado de origen tartesio, romano y almohade (siglos XII y XIII) declarado Monumento Nacional, constituido por más de dos kilómetros de potentes lienzos almenados de tapial de cal de color rojizo y mampostería que conservan cuarenta y tres torreones y cinco puertas monumentales, destacando la Puerta del Buey y la de Sevilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21053','monumento','Castillo de los Guzmanes','Inmenso complejo fortificado medieval del siglo XV erigido por el condado de Niebla en sillería de cantería y mampostería basta sobre el alcázar andalusí, que destaca por su colosal torre del homenaje de planta cuadrada dotada de salas abovedadas góticas y adarves perimetrales intactos sobre el río Tinto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21053','iglesia','Iglesia de Santa María de la Granada','Joya monumental gótico-mudéjar de transición construida en cantería y ladrillo visto sobre la antigua mezquita aljama, que conserva de forma magistral su patio de los naranjos, arquerías califales de herradura y un espectacular presbiterio con bóvedas de crucería estrellada gótico tardías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21053','monumento','Puente Romano sobre el río Tinto','Estructura civil de ingeniería de origen romano imperial profundamente reconstruida en las épocas andalusí y bajomedieval que salva el cauce fluvial mediante robustos arcos de medio punto provistos de tajamares triangulares de gran solidez estructural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22001','monumento','Núcleos de población de Almonaster la Real','El término municipal incluye los siguientes núcleos de población: Gil Márquez, Calabazares, Cueva de la Mora y Escalada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22001','monumento','Mezquita-Castillo de Almonaster la Real','Joya monumental de la arquitectura islámica universal del siglo X declarada Monumento Nacional, emplazada de forma espectacular en el interior de una alcazaba defensiva militar bajomedieval que corona el cerro de la villa, constituida por una estructura de planta rectangular de ladrillo visto macizo, sillería caliza calavera y mampostería que conserva de forma magistral su patio de armas central, el oratorio o haram con arquerías de herradura sobre columnas romanas de acarreo y el mihrab intacto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22001','iglesia','Iglesia Parroquial de San Martín','Magna fábrica que fusiona el gótico final isabelino y el plateresco renacentista del siglo XVI construida en cantería de primer orden, destacando su espectacular portada manuelina de influjo portugués profusamente labrada con ricas molduras talladas de gran impacto plástico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22001','ermita','Ermita de Santa Eulalia','Santuario rural bajomedieval del gótico de reconquista primitivo levantado sobre un oppidum romano que presenta muros de piedra con arcos diafragma de cantería y yeserías exentas en su presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21055','monumento','Núcleos de población de Palos de la Frontera','El término municipal incluye los siguientes núcleos de población: Mazagón y La Rábida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21055','iglesia','Monasterio de Santa María de la Rábita','Joya monumental de la arquitectura gótico-mudéjar y Sitio Colombino universal del siglo XIV declarado Monumento Nacional, edificado en ladrillo visto y mampostería encalada, el cual deslumbra universalmente por albergar un bellísimo claustro mudéjar de planta cuadrangular, la capilla de los milagros donde oró Cristóbal Colón y salas capitulares con artesonados de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21055','iglesia','Iglesia Parroquial de San Jorge Mártir','Monumental templo del gótico tardío del siglo XV construido en cantería y ladrillo visto en el centro urbano, destacando su espectacular portada de los novios de fina tracería escultórica y un interior de colosal nave única cubierta por intrincadas bóvedas de crucería estrellada compleja.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21055','monumento','La Fontanilla','Humilde infraestructura civil e hidráulica tradicional mudéjar del siglo XV protegida por un templete de ladrillo visto de planta cuadrangular y bóveda de medio cañón, de donde se abastecieron históricamente de agua potable las carabelas descubridoras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21079','monumento','Casas Consistoriales / Ayuntamiento de Zufre','Joya monumental de la arquitectura civil renacentista de Andalucía del siglo XVI declarada Monumento Nacional, erigida en sillería de piedra regular caliza calavera sobre trazas de la escuela de Hernán Ruiz II, la cual presenta una fachada palaciega con un porche de columnas toscanas de piedra labrada y un interior que conserva la sillería del tribunal de la Inquisición intacta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21079','iglesia','Iglesia Parroquial de la Purísima Concepción','Templo gótico-mudéjar de transición del siglo XIV edificado en cantería sobre las ruinas de una mezquita andalusí que presenta una espaciosa nave central techada por una armadura de madera castellana de par y nudillo y un campanario construido sobre el antiguo alminar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21079','monumento','Provincia de Huelva','Completada al 100% (80 municipios, cerrado estrictamente tras Zufre conforme a su nomenclátor oficial).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21079','monumento','Próxima provincia sugerida para la Hoja de Ruta','Provincia de Cádiz (completando el arco atlántico meridional andaluz de forma natural y progresiva).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21079','monumento','Punto de arranque inmediato para la nueva sesión','Provincia de Cádiz, Letra A (comenzando estrictamente por municipios como Alcalá de los Gazules, Alcalá del Valle, Algar, Algeciras, Algodonales, Arcos de la Frontera, etcétera).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','monumento','Núcleos de población de Jerez de la Frontera','El término municipal incluye los siguientes núcleos de población: La Barca de la Florida, Torrecera, El Torno y San Isidro del Guadalete.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','monumento','Conjunto Monumental de el Alcázar y la Mezquita','Inmensa y colosal urbe palatina fortificada de origen almohade del siglo XII declarada Monumento Nacional, erigida en sillería regular y tapial de cal, la cual conserva de forma monumental su patio de armas, la Torre del','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','catedral','Santa Iglesia Catedral de San Salvador','Magna fábrica columnaria que fusiona el gótico final, el renacimiento y el fastuoso barroco internacional construida en cantería de la máxima finura técnica por Diego de Siloé y su escuela, la cual deslumbra universalmente por sus tres naves de colosal luz espacial, una espectacular fachada barroca esculpida flanqueada por una esbelta torre exenta y su cimborrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','iglesia','Cartuja de Santa María de la Defensión','Joya monumental universal de la arquitectura gótica, renacentista y barroca conventual fundada en el siglo XV en sillería de primer orden, la cual deslumbra por albergar un bellísimo claustro mayor porticado de doble galería, una espectacular fachada barroco-plateresca esculpida por Andrés de Ribera de valor universal y la capilla mayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','iglesia','Iglesia de San Miguel y de Santiago','Monumentales iglesias del gótico tardío y transición renacentista de los siglos XV y XVI construidas en cantería de primer orden, destacando por sus colosales naves cubiertas por intrincadas bóvedas de crucería estrellada compleja y sus espectaculares fachadas esculpidas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','palacio','Palacio de Campo Real / Palacio de Villapanés','Suntuosas residencias nobles señoriales de la arquitectura civil barroca y renacentista que presentan fachadas monumentales de sillería regular, grandes blasones heráldicos esculpidos en relieve, balconajes de forja artística y organizan sus dependencias en torno a bellísimos patios porticados tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','monumento','Núcleos de población de Vejer de la Frontera','El término municipal incluye los siguientes núcleos de población: El Palmar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','monumento','Recinto Amurallado de Vejer y Puertas Fortificadas','Inmenso complejo fortificado medieval de origen andalusí y posterior señorío de los duques de Medina Sidonia, el cual rodea por completo el casco histórico de la villa con potentes lienzos almenados de mampostería basta y tapial de cal adaptados al escarpado relieve del cerro, conservando de forma monumental cuatro portales fortificados, destacando el Arco de la Segur y la Puerta de la Villa provistos de grandes arcos dovelados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','iglesia','Iglesia Parroquial de del Divino Salvador','Joya góticomudéjar de transición construida en cantería caliza de primer orden sobre la antigua mezquita mayor, destacando su espectacular presbiterio del siglo XIV cubierto por complejas bóvedas de crucería estrellada de fina tracería escultórica y tres amplias naves de colosal luz espacial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11039','monumento','Castillo de Vejer','Vestigios del complejo militar andalusí de planta cuadrangular erigido en sillería y tapial de cal en el interior del entramado urbano, del que destaca su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16006','monumento','Núcleos de población de Castellar de la Frontera','El término municipal incluye los siguientes núcleos de población: Castillo de Castellar y Almoraima.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16006','monumento','Castillo-Fortaleza de Castellar (Castellar Viejo)','Espectacular e inexpugnable complejo fortificado medieval de origen andalusí de los siglos XII y XIII perfectamente conservado en un cerro escarpado del Campo de Gibraltar, construido en sillería y mampostería basta de caliza, el cual conserva de forma magistral sus potentes murallas almenadas con torres de flanqueo cuadrangulares, el alcázar señorial posterior, adarves intactos y un entramado urbano troglodítico interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16006','iglesia','Convento de San Miguel de la Almoraima','Complejo monacal de la orden descalza fundado en el siglo XVII profundamente reformado en estilo historicista neogótico por el ducado de Medinaceli, edificado en piedra y mampostería encalada que conserva una iglesia de grandes proporciones y una esbelta torre mirador.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','monumento','Núcleos de población de Medina-Sidonia','El término municipal incluye los siguientes núcleos de población: San José de Malcocinado y Los Badalejos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','iglesia','Iglesia Mayor Parroquial de Santa María la Coronada','Joya monumental universal del gótico tardío isabelino, el renacimiento y el mudéjar construida en sillería caliza calavera de primer orden por el ducado de Medina Sidonia, la cual destaca por su interior columnario cubierto por intrincadas bóvedas de crucería estrellada compleja y un colosal retablo mayor de madera tallada de valor nacional universal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','monumento','Castillo de Medina Sidonia y Murallas de la Villa','Inmenso complejo fortificado que integra el alcázar romano, el castillo andalusí del siglo XII y la posterior fortaleza medieval con cantería de primer orden, del que subsisten de forma monumental tres puertas monumentales, destacando la Puerta de la Pastora provista de un gran arco de herradura apuntado califal exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','monumento','Conjunto Hidráulico Romano (Cloacas y Conducciones Subterráneas)','Espectacular e histórico complejo de ingeniería civil romana del siglo I d.C. declarado Monumento Nacional, constituido por una colosal red de galerías y cloacas abovedadas subterráneas construidas con grandes bloques de sillería de piedra regular calavera perfectamente conservadas bajo el urbanismo del casco antiguo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','monumento','Provincia de Cádiz','Sub-bloques de las letras E, G, J y M completados de forma íntegramente correlativa hasta el municipio de Medina-Sidonia inclusive.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','monumento','Último sub-bloque procesado','Letras E, G, J y M (completado hasta el municipio de Medina-Sidonia, inclusive).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11023','monumento','Punto de arranque inmediato para la nueva sesión','Provincia de Cádiz, Letra O (comenzando estrictamente por municipios como Olvera, Paterna de Rivera, Prado del Rey, Puerto de Santa María (El) / El Puerto de Santa María, Puerto Real, Puerto Serrano, Rota, San Fernando, San José del Valle, San Roque, Sanlúcar de Barrameda, Setenil de las Bodegas, Tarifa, Trebujena, Ubrique, Vejer de la Frontera, Villaluenga del Rosario, Villamartín y Zahara de la Sierra).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26129','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26129','monumento','El Castillo de Davalillo','El Castillo de Davalillo (siglo XIII) es una fortaleza militar de planta poligonal mandada construir por la Corona de Castilla en sillería de piedra arenisca local para vigilar la línea del río Ebro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26129','iglesia','La Iglesia Parroquial de la Ascensión','La Iglesia Parroquial de la Ascensión (siglo XVI) es un templo de tipología gótico-renacentista erigido en cantería de arenisca que destaca por su gran nave única con bóvedas de crucería estrellada y su retablo mayor clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26129','iglesia','El Santuario de Santa María de la Estrella','El Santuario de Santa María de la Estrella (siglo XVXVI) es un conjunto monástico neogótico y renacentista edificado por la Orden de San Jerónimo utilizando sillería de arenisca rojiza de la zona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26129','monumento','El Barrio de las Bodegas','El Barrio de las Bodegas (siglos XVI-XIX) constituye un conjunto etnográfico preindustrial horadado en el subsuelo arcilloso del cerro de Cerrillo, caracterizado por sus zarceras de ventilación hechas en sillería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26130','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26130','iglesia','El Monasterio de Suso','El Monasterio de Suso (siglos VI-XI) es un cenobio de tipología eremítica, mozárabe y románica construido con mampostería de arenisca, conglomerados locales y toba caliza para las bóvedas de herradura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26130','iglesia','El Monasterio de Yuso','El Monasterio de Yuso (siglos XVI-XVIII) es un complejo monumental denominado "El Escorial de La Rioja",','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26130','iglesia','La Iglesia de San Millán de la Cogolla','La Iglesia de San Millán de la Cogolla (siglo XVI) presenta una planta de tres naves de igual altura (hallenkirche) resuelta con pilares cilíndricos y cubiertas de crucería de sillería de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26139','monumento','Núcleos de población de San Torcuato','El término municipal incluye los siguientes núcleos de población: San Torcuato.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26139','iglesia','Iglesia de San Torcuato (Siglo XVI)','Iglesia parroquial gótico-renacentista de nave única y cabecera ochavada, construida estructuralmente en mampostería compacta ligada con cal y reforzada con sillares de arenisca en sus contrafuertes y vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26142','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26142','monumento','El Complejo Amurallado de San Vicente','El Complejo Amurallado de San Vicente (siglo XII) es una plaza fuerte defensiva de la frontera navarra construida con mampostería y sillería de arenisca sobre un cerro que domina el valle del Ebro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26142','iglesia','La Iglesia de Santa María de la Piscina','La Iglesia de Santa María de la Piscina (siglo XII) es el ejemplo más puro de románico pleno en La Rioja, promovida por el infante Ramiro de Navarra en sillería regular de arenisca dorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26142','monumento','El Puente Mayor de San Vicente','El Puente Mayor de San Vicente (siglo XII-XIII) es un viaducto medieval de múltiples ojos con arcos apuntados y tajamares construido en sillería de arenisca para el cobro del pontazgo fronterizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26142','monumento','El Barrio de Bodegas de la Sonsierra','El Barrio de Bodegas de la Sonsierra (siglos XV-XVIII) agrupa decenas de lagares rupestres excavados directamente en las peñas de arenisca terciaria para el prensado tradicional del viñedo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26134','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26134','iglesia','La Iglesia Parroquial de la Asunción','La Iglesia Parroquial de la Asunción (siglo XVI) es un edificio de traza gótica tardía levantado en mampostería','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26134','iglesia','Las Ruinas del Monasterio de Santa María','Las Ruinas del Monasterio de Santa María (siglo X) representan el enclave histórico donde se celebraron las Cortes de Santa Coloma en el Reino de Nájera, conservando cimientos de sillería de piedra del país.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26135','monumento','Núcleos de población de Santa Engracia del Jubera','El término municipal incluye los siguientes núcleos de población: Bucesta, El Collado, Jubera, Reinares, San Bartolomé, San Martín y Santa Cecilia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26135','monumento','Castillo de Jubera (Siglo X)','Fortaleza de origen musulmán y posterior baluarte cristiano delCamino de Santiago de la sierra, levantado sobre un espigón rocoso mediante mampostería caliza gruesa y argamasa de cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26135','iglesia','Iglesia de San Paulino de Nola en Jubera (Siglo XVI)','Iglesia de tipología rural construida con sillarejo calizo y vigas de pino resinero de los montes del Jubera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','catedral','La Catedral de Santo Domingo de la Calzada','La Catedral de Santo Domingo de la Calzada (siglos XII-XVIII) es un templo de tipología de iglesia de peregrinación del Camino de Santiago, edificado en sillería de arenisca caliza con girola y una torre exenta barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','monumento','Las Murallas de Santo Domingo','Las Murallas de Santo Domingo (siglo XIV) forman el mayor recinto fortificado conservado en La Rioja, mandado levantar por Pedro I de Castilla mediante paños de mampostería encintada y torres de sillería de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','monumento','El Antiguo Hospital de Peregrinos','El Antiguo Hospital de Peregrinos (siglo XII) es una infraestructura logística de la ruta jacobea, reformada en estilo renacentista con estructura interna de madera de roble y muros de sillería de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26138','ermita','La Ermita del Puente','La Ermita del Puente (siglo XV) es un pequeño humilladero de peregrinos situado junto al río Oja, construido en sillería de arenisca para conmemorar la obra de ingeniería viaria de Santo Domingo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26140','monumento','Núcleos de población de Santurde de Rioja','El término municipal incluye los siguientes núcleos de población: Santurde.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26140','palacio','Palacio de los Condes de Baños (Siglo XIV)','Torre fuerte medieval de planta cuadrada reconvertida en residencia señorial, construida con gruesos muros de mampostería rodada del río Oja y esquinales de sillería arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26141','monumento','Núcleos de población de Santurdejo','El término municipal incluye los siguientes núcleos de población: Santurdejo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26141','iglesia','Iglesia de San Jorge (Siglo XVIII)','Templo barroco de estructura neoclásica temprana con planta de cruz latina, alzado con paramentos de mampostería pizarrosa de la sierra y sillería en el cuerpo de campanas de la torre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26143','monumento','Núcleos de población de Sojuela','El término municipal incluye los siguientes núcleos de población: Sojuela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26143','monumento','Casa de la Nieve de Moncalvillo (Siglos XVI-XVII)','Infraestructura preindustrial de abastecimiento de hielo compuesta por neveras de pozo circulares revestidas de mampostería caliza seca y cubiertas vegetales de matorral serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26144','monumento','Núcleos de población de Sorzano','El término municipal incluye los siguientes núcleos de población: Sorzano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26144','iglesia','Iglesia Parroquial de San Martín (Siglo XVI)','Templo renacentista de nave única con bóvedas de crucería estrellada, levantado con fábricas mixtas de mampostería del riachuelo Somalo y sillares de arenisca ocre en las esquinas principales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26145','monumento','Núcleos de población de Sotés','El término municipal incluye los siguientes núcleos de población: Sotés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26145','iglesia','Iglesia de San Martín (Siglo XVI)','Edificio religioso góticorenacentista con portada plateresca bajo arco de triunfo, construido mediante aparejo de sillería caliza compacta en su cabecera y mampostería revocada en los pies.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26146','monumento','Núcleos de población de Soto en Cameros','El término municipal incluye los siguientes núcleos de población: Trevijano, Luezas, San形 y los despoblados de el Cortijo y la Monjía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26146','monumento','Yacimientos de Icnitas de Soto (Período Cretácico)','Patrimonio arqueológico y paleontológico integrado por huellas de dinosaurios fosilizadas sobre lajas de caliza bituminosa y areniscas consolidadas de la cuenca de Cameros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26146','iglesia','Iglesia de San Esteban Protomártir (Siglo XVII)','Templo barroco columnario clasicista promovido por los indianos de la sierra, levantado con sillería de caliza gris del Camero Viejo y artesonados de madera de melojo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26147','monumento','Núcleos de población de Terroba','El término municipal incluye los siguientes núcleos de población: Terroba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26147','ermita','Ermita de la Virgen del Villar (Siglo XVII)','Construcción religiosa de tipología rural camerana erigida con muros de mampostería de losas de pizarra y arenisca desmoronable, con un pórtico protegido por vigas de madera de chopo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26148','monumento','Núcleos de población de Tirgo','El término municipal incluye los siguientes núcleos de población: Tirgo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26148','iglesia','Iglesia del Salvador (Siglo XII)','Templo románico de tipología perfecta de la Sonsierra con un ábside semicircular modificado por canecillos esculpidos, fabricado en sillería de arenisca dorada de grano medio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26149','monumento','Núcleos de población de Tobía','El término municipal incluye los siguientes núcleos de población: Tobía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26149','iglesia','Iglesia de Santa María (Siglo XVI)','Templo renacentista rural encajonado en el valle del río Tobía, edificado con aparejo de cantos rodados, piedra caliza de canteras locales y vigas maestras de pino silvestre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26150','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26150','iglesia','La Iglesia Parroquial de San Esteban','La Iglesia Parroquial de San Esteban (siglo XVI-XVIII) es un templo de planta de cruz latina edificado en mampostería de cantos rodados y sillería de arenisca en los esquinales con un retablo mayor clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26150','palacio','El Palacio de los Condes de Tormantos','El Palacio de los Condes de Tormantos (siglo XVIII) es una casona nobiliaria de estilo barroco civil construida con planta rectangular mediante muros de sillería de piedra arenisca y un gran escudo de armas central.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26153','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26153','iglesia','La Iglesia de Santiago Apóstol','La Iglesia de Santiago Apóstol (siglo XVII) es un templo barroco edificado sobre una plataforma rocosa utilizando mampostería de laja calcárea calavera y cubiertas de teja árabe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26153','monumento','El Núcleo Urbanístico de la Sierra','El Núcleo Urbanístico de la Sierra (siglos XVI-XVIII) constituye un conjunto etnográfico homogéneo de arquitectura serrana construido con muros gruesos de mampostería de piedra gris y entramados de madera de pino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26151','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26151','iglesia','La Iglesia Parroquial de San Martín','La Iglesia Parroquial de San Martín (siglo XVI) es un gran edificio renacentista de tres naves construido en cantería de piedra arenisca dorada con bóvedas de crucería estrellada complejas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26151','ermita','La Ermita de San Tómedes','La Ermita de San Tómedes (siglo X-XI) presenta trazas de origen prerrománico mozárabe y reformas románicas posteriores ejecutadas en mampostería de piedra del lecho del río Iregua.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26151','monumento','El Puente Medieval de Torrecilla','El Puente Medieval de Torrecilla (siglo XIV) es una infraestructura viaria de un único y apuntado ojo monumental levantado en sillería caliza para comunicar los barrios de San Martín y El Barruelo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26151','monumento','El Complejo Industrial de las Fábricas de Paños','El Complejo Industrial de las Fábricas de Paños (siglo XVIII) representa el patrimonio fabril preindustrial de la sierra con edificios de mampostería basta que albergaban los telares históricos de lana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26152','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26152','iglesia','La Iglesia de la Asunción','La Iglesia de la Asunción (siglo XVI-XVII) es un edificio religioso de transición renacentista edificado con muros de mampostería encintada y portadas de sillería de piedra arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26154','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26154','monumento','La Torre de los Condes de Hervías','La Torre de los Condes de Hervías (siglo XIV) es una torre de homenaje militar de planta cuadrangular levantada en sillería de piedra arenisca caliza con matacanes y almenas defensivas de la frontera castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26154','iglesia','La Iglesia Parroquial de Santo Domingo de Silos','La Iglesia Parroquial de Santo Domingo de Silos (siglo XVIII) es un pequeño templo neoclásico construido en ladrillo macizo visto y sillería en el frontis por los señores de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26155','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26155','iglesia','La Iglesia de Santa María Mayor','La Iglesia de Santa María Mayor (siglo XVI-XVII) es un gran templo gótico tardío y renacentista levantado en sillería regular de piedra arenisca de las canteras de la Obarenes con una esbelta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26155','ermita','La Ermita de la Concepción de San Pedro de Castillo','La Ermita de la Concepción de San Pedro de Castillo (siglo XII) es una construcción románica que conserva un ábside semicircular de excelente sillería arenisca con capiteles esculpidos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26157','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26157','iglesia','La Basílica de Santa María de los Arcos','La Basílica de Santa María de los Arcos (siglo V) es el monumento paleocristiano más antiguo de La Rioja, construido reutilizando grandes columnas romanas de mármol y arenisca procedentes de la antigua Tritium Magallum.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26157','iglesia','La Iglesia de San Bartolomé','La Iglesia de San Bartolomé (siglo XVIII) es un templo barroco de mampostería y ladrillo que destaca por su portada clasicista y por albergar enterramientos medievales documentados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26157','monumento','Los Yacimientos de Alfarería Romana de Tricio','Los Yacimientos de Alfarería Romana de Tricio (siglos I-III d.C.) constituyen el mayor complejo arqueológico industrial de producción de terra sigillata del Imperio Romano en Hispania.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26158','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26158','iglesia','La Iglesia Parroquial de Santa María','La Iglesia Parroquial de Santa María (siglo XVI-XVIII) es un templo barroco edificado en sillería de piedra arenisca y mampostería que destaca por su torre de ladrillo de estilo mudéjar riojano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26160','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26160','iglesia','La Iglesia Parroquial de San Servando y San Germán','La Iglesia Parroquial de San Servando y San Germán (siglo XVI) es un templo de factura gótico-renacentista edificado en sillería de piedra arenisca dorada que destaca por su nave única dividida en tres tramos con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26160','monumento','La Casa Consistorial','La Casa Consistorial (siglo XVIII) es un edificio civil de tipología barroca construido con muros portantes de ladrillo macizo sobre un basamento inferior de sillería de arenisca y herrajes de forja artesanal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26161','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26161','iglesia','La Iglesia Parroquial de la Concepción','La Iglesia Parroquial de la Concepción (siglo XVII) es un templo de tipología barroca rural edificado en mampostería de laja calcárea calavera con esquinales reforzados en sillería de arenisca y cubiertas de teja árabe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26161','monumento','El Yacimiento de Icnitas de la Virgen de Valdemadera','El Yacimiento de Icnitas de la Virgen de Valdemadera (Cretácico Inferior) constituye un hito arqueológicopaleontológico que conserva huellas de dinosaurios impresas sobre estratos de roca caliza y arenisca gris.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26162','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26162','iglesia','La Iglesia de San Andrés','La Iglesia de San Andrés (siglos XII-XVI) es un templo de origen románico reformado en época renacentista que está levantado en sillería y mampostería de caliza y arenisca de la Demanda con bóvedas de crucería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26162','ermita','La Ermita de Nuestra Señora de Tresfuentes','La Ermita de Nuestra Señora de Tresfuentes (siglo XIII) es una construcción de tipología románica tardía ejecutada en sillería regular de caliza que destaca por su ábside semicircular y sus canecillos decorados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26162','palacio','El Conjunto Etnográfico de Casonas Serranas','El Conjunto Etnográfico de Casonas Serranas (siglos XVII-XVIII) agrupa viviendas de la arquitectura tradicional del valle del Oja estructuradas con gruesos muros de piedra basta y vigas vistas de madera de haya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26163','monumento','Núcleos de población de Ventosa','El término municipal incluye los siguientes núcleos de población: Ventosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26163','iglesia','Iglesia de San Saturnino (Siglo XVI)','Templo renacentista situado en lo alto de un cerro estratégico del Camino de Santiago, edificado con gruesos muros de sillería caliza compactada y contrafuertes exteriores exentos de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26164','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26164','iglesia','La Iglesia Parroquial de San Pedro','La Iglesia Parroquial de San Pedro (siglo XVIII) es un edificio de proporciones monumentales barroconeoclásico construido con mampostería de pizarra y caliza calavera con una torre campanario rematada por un cupulín de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26164','ermita','La Ermita de Villavelayo','La Ermita de Villavelayo (siglo XVII) es un templo de montaña edificado en piedra basta del Alto Najerilla que servía como centro de devoción y pastoreo dentro de las rutas de la transhumancia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26165','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26165','iglesia','La Iglesia de San Esteban de Viguera','La Iglesia de San Esteban de Viguera (siglo XVI) es un templo renacentista de tres naves construido en cantería de arenisca rojiza que destaca por su imponente portada y su retablo mayor romanista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26165','ermita','La Ermita de San Esteban de los Monjes','La Ermita de San Esteban de los Monjes (siglo X) es una joya prerrománica mozárabe construida con mampostería y toba calcárea en el interior de una covacha natural que conserva pinturas murales románicas lineales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26165','monumento','El Castillo de Viguera','El Castillo de Viguera (siglo X) representa las ruinas de una fortaleza medieval islámica y posterior sede del Reino de Viguera emplazada sobre un espolón de conglomerados rocosos inaccesibles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26165','monumento','El Puente Romano de Viguera','El Puente Romano de Viguera (siglo I d.C.-XI) es una infraestructura viaria e hidráulica sobre el río Iregua reformada en época medieval mediante arcos apuntados de sillería de arenisca y caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26168','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26168','iglesia','La Iglesia Parroquial de la Asunción','La Iglesia Parroquial de la Asunción (siglo XVI) es un templo tardogótico y renacentista edificado en sillería de piedra arenisca dorada que posee una gran nave con bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26168','ermita','La Ermita de Santa Eufemia','La Ermita de Santa Eufemia (siglo XVII) es una edificación barroca de carácter popular construida mediante paramentos de mampostería encintada y ladrillo macizo visto con tejado a dos aguas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26166','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26166','iglesia','La Iglesia de San Pelayo','La Iglesia de San Pelayo (siglo XVI-XVIII) es un templo renacentista levantado en sillería de arenisca de los Montes Obarenes que alberga una importante portada plateresca y un coro alto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26166','palacio','La Casa-Palacio de los Cirac','La Casa-Palacio de los Cirac (siglo XVII) es un palacio civil barroco construido con muros de sillería arenisca que destaca por su gran escudo heráldico en la fachada principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26167','monumento','Núcleos de población de Villalobar de Rioja','El término municipal incluye los siguientes núcleos de población: Villalobar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26167','monumento','Torre de los Bustamante (Siglo XII)','Torre de defensa gótica de planta rectangular con almenas saeteras, fabricada con sillarejo de piedra arenisca dura y refuerzos angulares de bloques de gran tamaño.','inventario_monumentos_pdf');
