INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26172','iglesia','La Iglesia de la Virgen de la Redonda','La Iglesia de la Virgen de la Redonda (siglo XVII) es un pequeño templo de tipología barroca rural edificado en mampostería basta de piedra caliza y mortero de cal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26173','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26173','iglesia','La Iglesia de San Juan Bautista','La Iglesia de San Juan Bautista (siglo XVII) es un templo barroco edificado en mampostería de arenisca que destaca por su sobria volumetría integrada en el paisaje de la sierra de Cameros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26174','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26174','iglesia','La Iglesia de Santa María de la Asunción de Villarta','La Iglesia de Santa María de la Asunción de Villarta (siglo XVIII) es un edificio neoclásico levantado en mampostería encintada con una fachada rematada en frontón y sillería en los accesos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26174','iglesia','La Iglesia de San Andrés de Quintana','La Iglesia de San Andrés de Quintana (siglo XVI) presenta características del gótico final arcaizante construida con muros de cantos rodados y sillería de arenisca en sus contrafuertes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26177','monumento','Núcleos de población de Villoslada de Cameros','El término municipal incluye los siguientes núcleos de población: Hoyas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26177','ermita','Ermita de la Virgen de Lomos de Orios (Siglo XVIII)','Santuario barroco del alto monte de Cameros, edificado como centro de peregrinación ganadera mediante sillería de piedra caliza gris de la Sierra de Cebollera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26177','monumento','Fábrica de Paños de Villoslada (Siglo XVII)','Centro fabril textil trashumante de la corona borbónica del cual se','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26178','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26178','iglesia','La Iglesia de la Asunción','La Iglesia de la Asunción (siglo XVI) es un imponente edificio de sillería de arenisca rojiza con una esbelta torre campanario de tipología defensiva y bóvedas de crucería góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26178','monumento','El Conjunto Urbano de Casas de Indianos','El Conjunto Urbano de Casas de Indianos (siglos XIXXX) constituye un hito de arquitectura civil monumental con palacetes neoclásicos y eclécticos edificados en sillería, piedra caliza labrada y rejerías de hierro fundido.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26178','ermita','La Ermita de la Soledad','La Ermita de la Soledad (siglo XVII) es una construcción barroca clasicista construida en sillería de arenisca que marca el inicio de los caminos de la Sierra de la Demanda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26179','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26179','iglesia','La Iglesia de la Magdalena','La Iglesia de la Magdalena (siglo XVI-XVII) es un templo renacentista edificado en mampostería de piedra gris calcárea y esquinales de sillería de arenisca con un coro de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26179','monumento','El Lavadero Medieval y Conjunto Etnográfico','El Lavadero Medieval y Conjunto Etnográfico (siglos XVI-XVIII) representa la infraestructura de la lana con calles empedradas de cantos rodados y casas de piedra basta con corrales integrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26180','monumento','Núcleos de población de Zarratón','El término municipal incluye los siguientes núcleos de población: Zarratón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26180','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26180','iglesia','La Iglesia de la Asunción','La Iglesia de la Asunción (siglo XIV-XVI) es un edificio de transición gótico-renacentista edificado en sillería de arenisca dorada por encargo de los condes de Haro que conserva una portada tardogótica con decoración flamígera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26180','palacio','El Palacio de los Casafuerte','El Palacio de los Casafuerte (siglo XV) es una residencia señorial fortificada construida con potentes muros de sillería de arenisca que destaca por sus torreones angulares y sus vanos apuntados medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26180','ermita','La Ermita de San Blas','La Ermita de San Blas (siglo XVII) es un templo barroco exento levantado en mampostería encintada con esquinales de sillería de piedra arenisca de la comarca de Haro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26181','monumento','Núcleos de población de Zarzosa','El término municipal incluye los siguientes núcleos de población: Zarzosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26181','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26181','iglesia','La Iglesia de Santiago','La Iglesia de Santiago (siglo XVII) es un edificio barroco de carácter rural edificado en mampostería basta de laja calcárea de Cameros y vigas de madera de pino con una modesta espadaña de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26183','monumento','Núcleos de población de Zorraquín','El término municipal incluye los siguientes núcleos de población: Zorraquín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26183','iglesia','Iglesia de San Esteban (Siglo XIII)','Templo románico tardío de la comarca de la Demanda con bóveda de cañón apuntada en el ábside, fabricado con sillería de arenisca ferruginosa y entramados de techumbre de madera de haya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22199','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22199','iglesia','La Iglesia de San Juan de Busa','La Iglesia de San Juan de Busa (siglo XI) es un templo del románico del Serrablo que destaca por su ábside con friso de baquetones y un arco de herradura de filiación mozárabe ejecutado en sillarejo de caliza gris.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22199','iglesia','La Iglesia de San Pedro de Lárrede','La Iglesia de San Pedro de Lárrede (siglo XI) es el monumento cumbre de la arquitectura serrablesa, construida en sillarejo de piedra caliza local con ventanas ajimezadas y una esbelta torre-campanario defensiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22199','monumento','El Castillo de Larrés','El Castillo de Larrés (siglo XIV) es una fortaleza gótica señorial reconvertida en museo, estructurada en torno a un patio de armas con dos torres rectangulares de mampostería y sillarejo de caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22199','monumento','El Museo Ángel Orensanz y Artes del Serrablo','El Museo Ángel Orensanz y Artes del Serrablo (siglo XIX) es un conjunto etnológico ubicado en una antigua casa pirenaica hecha con muros de mampostería caliza, vigas de abeto y cubiertas de losas de pizarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22200','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22200','iglesia','La Santuario de Nuestra Señora de Guayente','La Santuario de Nuestra Señora de Guayente (siglo XVI) es un complejo religioso y educativo renacentista edificado sobre un espolón rocoso mediante muros de piedra granítica y sillería caliza del valle de Benasque.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22200','iglesia','La Iglesia de San Juan Bautista de Sanavastre','La Iglesia de San Juan Bautista de Sanavastre (siglo XII) es una ermita románica pirenaica con ábside semicircular construida con mampuesto de granito, esquinales de sillería y techumbre de losas de pizarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22201','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22201','iglesia','El Santuario de la Virgen de la Candelera','El Santuario de la Virgen de la Candelera (siglo XIIXVIII) es un conjunto arquitectónico situado en la cresta de la sierra, levantado en sillería de arenisca sobre restos de una fortaleza hispanomusulmana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22201','iglesia','La Iglesia Parroquial de Santa Ana','La Iglesia Parroquial de Santa Ana (siglo XVI) es un templo de transición gótico-renacentista ejecutado en cantería de arenisca con capillas laterales integradas entre los contrafuertes interiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22202','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22202','iglesia','La Iglesia de San Vicente Mártir','La Iglesia de San Vicente Mártir (siglo XVIII) es un edificio de tipología barroca clasicista construido con muros de ladrillo macizo sobre un zócalo inferior de sillarejo de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22202','ermita','La Ermita del Plano','La Ermita del Plano (siglo XIII) es una edificación románica tardía ejecutada en sillería regular de arenisca que conserva un arco triunfal de medio punto y bóveda de cañón apuntado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22203','monumento','Núcleos de población de Salillas','El término municipal incluye los siguientes núcleos de población: Salillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22203','palacio','Palacio de los Condes de Guara (Siglo XVI)','Caserón palaciego renacentista aragonés provisto de una galería superior de arquillos de medio punto, construido enteramente con ladrillo rojo cocido y zócalos de sillería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22204','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22204','iglesia','La Iglesia de la Asunción','La Iglesia de la Asunción (siglo XVI) es un templo gótico tardío pirenaico mandado construir por Juan de Lanuza en sillería de piedra caliza y pizarra, albergando un retablo mayor plateresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22204','monumento','El Puente Medieval de Sallent','El Puente Medieval de Sallent (siglo XVI) es una estructura de un solo ojo de gran luz, alzada sobre el río Aguas Limpias mediante arcos de cantería de piedra caliza del valle de Tena.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22204','monumento','La Torre de los Martón','La Torre de los Martón (siglo XIV-XV) es una casa-torre defensiva de tipología militar pirenaica ejecutada en mampostería basta de pizarra y granito con vanos defensivos y saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22205','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22205','iglesia','La Iglesia Parroquial de San Esteban','La Iglesia Parroquial de San Esteban (siglo XVII) es un templo de grandes proporciones barroco-mudéjar edificado en mampostería encintada y aparejo de ladrillo visto sobre cimientos de roca arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22205','monumento','Las Ruinas del Castillo de Rocafort','Las Ruinas del Castillo de Rocafort (siglo XI) constituyen una plataforma defensiva de la frontera de la Reconquista con muros perimetrales levantados en sillería caliza irregular y argamasa de yeso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22207','monumento','Núcleos de población de San Juan de Plan','El término municipal incluye los siguientes núcleos de población: San Juan en el Valle de Gistaín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22207','iglesia','Iglesia de San Juan Bautista (Siglo XVI)','Iglesia pirenaica con pervivencias románicas en su estructura, erigida con mampostería gruesa de piedra granítica y caliza del río Cinqueta, coronada por un tejado de losas de pizarra negra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22903','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22903','iglesia','La Iglesia de la Virgen de la Asunción de Pomar','La Iglesia de la Virgen de la Asunción de Pomar (siglo XVI) es un edificio adscrito al estilo gótico tardío con pervivencias mudéjares construido en ladrillo visto y mampostería sobre cimientos de piedra arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22903','iglesia','La Iglesia de San Miguel de Santalecina','La Iglesia de San Miguel de Santalecina (siglo XVI) presenta una morfología de nave única con capillas laterales levantada en aparejo de ladrillo y tapial aglomerado con remates de cantería caliza en sus contrafuertes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22206','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22206','iglesia','La Iglesia de San Francisco de Asís','La Iglesia de San Francisco de Asís (siglo XVIII) es una obra monumental del barroco clasicista aragonés ejecutada enteramente en ladrillo mudéjar con una fachada rematada por dobles pilastras jónicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22206','monumento','Las Torres del Castillo de Sangarrén','Las Torres del Castillo de Sangarrén (siglo XIV) son restos de una antigua fortificación señorial integrados en viviendas contemporáneas, construidos con sillares regulares de arenisca monegrina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22208','monumento','Núcleos de población de Santa Cilia','El término municipal incluye los siguientes núcleos de población: Somanés y el despoblado de Banaguás.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22208','iglesia','Iglesia del Salvador (Siglo XVII)','Templo barroco de la ruta del Camino de Santiago Aragonés, levantado con aparejo regular de cantos rodados del río Aragón trabados con cal y esquinales de sillería de piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22209','monumento','Núcleos de población de Santa Cruz de la Serós','El término municipal incluye los siguientes núcleos de población: Santa Cruz y la pedanía de Binacua.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22209','iglesia','Monasterio de Santa María de la Serós (Siglo XI)','Cenobio románico jaqués de la orden benedictina promovido por las infantas reales de Aragón, cuya iglesia destaca por su linterna octogonal y su fábrica perfecta de sillería de piedra caliza gris.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22209','iglesia','Iglesia de San Caprasio (Siglo XI)','Templo románico lombardo primitivo provisto de arcuaciones ciegas y pilastras en sus paramentos, construido íntegramente con pequeños sillarejos de piedra caliza local toscamente labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22906','iglesia','Santuario de Nuestra Señora de Dulcis en Buera (Siglo XVII)','Templo barroco clasicista con exuberante decoración interior de yeserías mudéjares, edificado externamente con paramentos de arenisca dorada y ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22212','monumento','Núcleos de población de Santaliestra y San Quílez','El término municipal incluye los siguientes núcleos de población: localidades de Santaliestra y San Quílez.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22212','ermita','Ermita de San Quílez (Siglo XII)','Capilla románica rural situada en un escarpado rocoso sobre el río Ésera, armada con sillarejo de piedra caliza de montaña y cubierta a dos aguas de losas rústicas de pizarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22213','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22213','iglesia','La Cartuja de Nuestra Señora de las Fuentes','La Cartuja de Nuestra Señora de las Fuentes (siglo XVIII) es un inmenso complejo monástico neoclásico fundado por los condes de Sástago en ladrillo macizo, piedra caliza y yeso, famoso por sus pinturas al fresco de Manuel Bayeu.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22213','iglesia','La Iglesia de San Salvador','La Iglesia de San Salvador (siglo XVIII) es un gran templo barroco de planta basilical reconstruido tras la contienda civil empleando sillería de arenisca caliza en su portada principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22214','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22214','iglesia','El Santuario de Torreciudad','El Santuario de Torreciudad (Nuevo) (año 1975) es un complejo monumental contemporáneo diseñado por Heliodoro Dols empleando ladrillo visto prensado, mármol de alabastro para el retablo y hormigón armado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22215','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22215','iglesia','El Monasterio de San Pedro de Tabernas','El Monasterio de San Pedro de Tabernas (siglo IX-XI) presenta vestigios prerrománicos y románicos de lo que fue un centro monástico pirenaico capital, construidos con cantería basta de pizarra y caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22220','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22220','iglesia','La Iglesia de San Juan Bautista','La Iglesia de San Juan Bautista (siglo XVI) es un edificio de transición gótico-renacentista levantado en sillería de arenisca que destaca por su ábside poligonal y portón con arquivoltas decoradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22220','ermita','La Ermita de Nuestra Señora del Juncar','La Ermita de Nuestra Señora del Juncar (siglo XVII) es un templo barroco exento construido en mampostería con esquinales de sillería de arenisca y cúpula sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22221','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22221','iglesia','La Iglesia de San Ginés de Sesué','La Iglesia de San Ginés de Sesué (siglo XII) es una construcción románica lombarda de una nave con ábside semicircular decorado con un friso de dientes de sierra en sillarejo de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22221','ermita','La Ermita de San Saturnino de Sos','La Ermita de San Saturnino de Sos (siglo XII) es un pequeño templo románico pirenaico edificado con mampostería basta de pizarra y mortero de cal, rematado por una cubierta de losas planas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22222','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22222','iglesia','La Iglesia de San Pedro de Liesa','La Iglesia de San Pedro de Liesa (siglo XIII) es un templo románico tardío construido en sillería de arenisca caliza que conserva pinturas murales góticas de estilo lineal en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22222','palacio','El Castillo-Palacio de los Condes de Aranda','El Castillo-Palacio de los Condes de Aranda (siglo XIV) es una fortaleza gótica residencial dañada en la guerra civil, de la que restan potentes lienzos de muralla y torreones de sillería de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22223','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22223','iglesia','El Monasterio de Santa María de Alaón','El Monasterio de Santa María de Alaón (siglo XII) es una obra maestra del románico lombardo de la cuenca del Noguera Ribagorzana, edificada en sillarejo perfectamente alineado de caliza gris con un suelo de mosaico medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22223','monumento','El Puente de la Salva','El Puente de la Salva (siglo XII) es una estructura medieval de un arco apuntado construida en sillería caliza para salvar el desfiladero de Collegats.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22225','monumento','Núcleos de población de Tamarite de Litera','El término municipal incluye los siguientes núcleos de población: capital histórica de la Litera, Algayón y la pedanía de La Melusa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22225','iglesia','Iglesia de Santa María Mayor (Siglo XII-XVI)','Colegiata románica de transición al gótico con gran cimborrio octogonal y retablo renacentista, fabricada en sillería arenisca dorada fina y mármol local pulido en los capiteles de la portada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22229','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22229','iglesia','La Iglesia de San Cristóbal de Luzás','La Iglesia de San Cristóbal de Luzás (siglo XII) es un templo románico de tres naves con ábsides decorados con arcuaciones lombardas ejecutado en perfecto sillarejo de piedra caliza gris.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22229','monumento','El Castillo de Fals','El Castillo de Fals (Torre de Tolva) (siglo XI) es una fortaleza militar fronteriza que conserva una torre cilíndrica de sillería caliza con muros de más de dos metros de espesor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22230','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22230','iglesia','La Iglesia de San Salvador','La Iglesia de San Salvador (siglo XVI) es un templo gótico de tipología pirenaica edificado con muros de mampostería de piedra caliza y granito, portada renacentista y tejado de losas de pizarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22230','monumento','El Casco Urbano de Torla','El Casco Urbano de Torla (siglos XV-XVIII) destaca por sus casonas señoriales fortificadas (Casa Viu, Casa Ruba) con ventanas góticas, escudos heráldicos y monumentales chimeneas troncocónicas de espantabrujas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22230','monumento','El Puente de los Navarros','El Puente de los Navarros (siglo XVI-XVIII) es un puente de un solo arco de piedra caliza que salva el río Ara en el acceso logístico tradicional hacia el valle de Ordesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22232','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22232','iglesia','La Iglesia de San Pedro','La Iglesia de San Pedro (siglo XVI) es un edificio de tipología mudéjar aragonesa tardía edificado en ladrillo visto sobre zócalo de sillería de piedra arenisca monegrina con una torre decorada con paños de rombos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22226','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22226','iglesia','La Iglesia de Santiago el Mayor','La Iglesia de Santiago el Mayor (siglo XVI) es un templo gótico tardío aragonés destruido en la guerra civil y reconstruido en ladrillo y mampostería de arenisca, conservando su bóveda de crucería estrellada original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22226','monumento','El Acueducto de Tardienta','El Acueducto de Tardienta (año 1941) es una infraestructura hidráulica monumental del Canal de Monegros construida en hormigón armado e ingeniería civil de gran envergadura para salvar el barranco de la dehesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22227','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22227','monumento','El Dolmen de Tella','El Dolmen de Tella (Losa de la Campa) (III milenio a.C.) es un megalito prehistórico de tipología de cámara pirenaica simple construido con grandes losas verticales y cobertura de piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22227','iglesia','La Iglesia de los Santos Juan y Pablo de Tella','La Iglesia de los Santos Juan y Pablo de Tella (siglo XI) es una ermita románica consagrada en 1019, levantada en aparejo de sillarejo rústico calizo colgada sobre un farallón del Pirineo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22227','iglesia','La Iglesia de San Esteban de Sin','La Iglesia de San Esteban de Sin (siglo XVI) es un templo fortificado pirenaico con muros de mampostería de pizarra y caliza con una gran torre defensiva que servía de refugio vecinal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22228','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22228','iglesia','La Iglesia de Nuestra Señora de la Asunción','La Iglesia de Nuestra Señora de la Asunción (siglo XVIII) es una obra neoclásica ejecutada con paramentos de mampostería encintada y ladrillo sobre zócalo de sillería de piedra arenisca de la Hoya de Huesca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22233','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22233','iglesia','La Iglesia de Santa María de Vilas del Turbón','La Iglesia de Santa María de Vilas del Turbón (siglo XII) es un templo románico rural construido con aparejo rústico de sillarejo calizo al pie del macizo calcáreo del Turbón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22234','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22234','iglesia','La Iglesia de la Magdalena','La Iglesia de la Magdalena (siglo XVIII) es una obra barroca clasicista construida con fábrica de mampostería, esquinales de sillería de piedra arenisca y una gran cúpula central encamonada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22235','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22235','iglesia','La Iglesia Parroquial de Nuestra Señora de la Asunción','La Iglesia Parroquial de Nuestra Señora de la Asunción (siglo XII-XVIII) presenta un origen románico visible en su cabecera de sillería caliza y reformas barrocas ejecutadas en ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22236','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22236','iglesia','La Iglesia de San Pedro','La Iglesia de San Pedro (siglo XVII) es un templo barroco aragonés construido en ladrillo macizo y mampostería encintada con una torre campanario de planta cuadrada de tres cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22239','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22239','iglesia','La Iglesia de la Virgen del Puy','La Iglesia de la Virgen del Puy (siglo XVI) es un templo gótico-renacentista edificado en sillería de arenisca bajo una inmensa peña de roca arenisca erosionada característica del paisaje de la Hoya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26171','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26171','iglesia','La Iglesia de San Juan Bautista','La Iglesia de San Juan Bautista (siglo XVI-XVIII) es un edificio religioso neoclásico con base renacentista edificado en mampostería con esquinales de sillería de arenisca y torre de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26175','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26175','iglesia','La Iglesia de Santa María','La Iglesia de Santa María (siglos XI-XVI) es un templo con cabecera mozárabe y naves renacentistas edificado en mampostería de piedra arenisca y caliza con una pila bautismal románica del siglo XII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26175','ermita','El Ermita de San Aurea','El Ermita de San Aurea (siglo XVII) es un edificio religioso barroco dedicado a la santa nacida en la villa, levantado con gruesos muros de mampostería serrana y madera de pino en su techumbre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26176','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26176','iglesia','La Iglesia de la Asunción','La Iglesia de la Asunción (siglo XVI-XVII) es un templo de traza renacentista edificado en sillería de arenisca','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22243','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22243','iglesia','La Iglesia de San Esteban de Llert','La Iglesia de San Esteban de Llert (siglo XII) es una pequeña edificación románica de la Ribagorza levantada en sillarejo de piedra caliza con una nave única rematada por un ábside semicircular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22901','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22901','iglesia','El Monasterio de San Pedro de Siresa','El Monasterio de San Pedro de Siresa (siglos IX-XIII) es una monumental iglesia románica de tipología carolingia edificada por la Corona de Aragón en grandes sillares de piedra caliza con una gran nave y bóveda de cañón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22901','iglesia','La Iglesia de San Martín de Hecho','La Iglesia de San Martín de Hecho (siglo XVI) es un templo gótico pirenaico construido con muros portantes de mampostería caliza, contrafuertes exteriores y cubiertas de losas de pizarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22901','monumento','El Conjunto Urbano de Hecho','El Conjunto Urbano de Hecho (siglos XV-XVIII) destaca por su arquitectura etnográfica pirenaica homogénea con portalones de medio punto de sillería, portaladas esculpidas y chimeneas troncocónicas con espantabrujas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22901','monumento','La Calzada Romana del Valle de Hecho','La Calzada Romana del Valle de Hecho (Summo Pyrenaeo) (siglo I d.C.) es un hito logístico-arqueológico de la vía romana que unía Caesaraugusta con Bearn, conservando tramos de pavimentación con grandes losas de caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22244','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22244','iglesia','La Iglesia de San Esteban de Serrate','La Iglesia de San Esteban de Serrate (siglo XII) es un templo románico lombardo edificado en sillarejo de piedra caliza gris con frisos de baquetones y arcuaciones ciegas en su ábside.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22247','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22247','monumento','La Torre de Viacamp','La Torre de Viacamp (siglo XI) es una monumental torre de vigilancia militar de planta circular y más de veinte metros de altura construida en sillería de piedra caliza regular sobre una cresta rocosa fortificada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22247','iglesia','La Iglesia de la Virgen del Congost de Chiriveta','La Iglesia de la Virgen del Congost de Chiriveta (siglo XII) es una ermita románica colgada sobre el desfiladero de Mont-rebei levantada en sillarejo calizo con un ábside semicircular perfecto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22247','monumento','El Castillo de Chiriveta','El Castillo de Chiriveta (siglo XI) es un baluarte fronterizo de la reconquista aragonesa que conserva su torre cilíndrica de sillería defensiva y lienzos de muralla de argamasa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22249','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22249','iglesia','La Iglesia de Santa María','La Iglesia de Santa María (siglo XII) es un templo románico lombardo del Valle de Benasque edificado en sillarejo de granito y caliza con una torre campanario','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22249','monumento','Casa Sento','Casa Sento (siglo XVI) es una tipología de casa torreada fortificada de la baja nobleza pirenaica construida con muros de mampostería de piedra de río, saeteras de defensa y tejado de losa de pizarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22251','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22251','iglesia','El Real Monasterio de Santa María de Sigena','El Real Monasterio de Santa María de Sigena (siglo XII) es un cenobio de la Orden de San Juan de Jerusalén fundado por la reina Sancha de Castilla en estilo románico y mudéjar empleando sillería caliza de gran calidad en su famosa portada de catorce arquivoltas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22251','monumento','La Casa Natal de Miguel Servet','La Casa Natal de Miguel Servet (siglo XVI) es un edificio de tipología de palacio aragonés construido en ladrillo macizo con arquerías dobladas en la última planta y patio interior sobre pilares de arenisca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22252','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22252','iglesia','La Iglesia Parroquial de San Lorenzo','La Iglesia Parroquial de San Lorenzo (siglo XVI) es un templo gótico tardío edificado en sillería de piedra caliza con bóvedas de crucería estrellada y torre campanario de planta rectangular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22252','monumento','Las Ermitas de la Ruta de Santa Orosia','Las Ermitas de la Ruta de Santa Orosia (siglos XIIXVII) constituyen un conjunto etnográfico y religioso rupestre (San Cornelio, las Cuevas) construidas aprovechando los abrigos naturales de las rocas calizas del monte.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22252','iglesia','La Iglesia de San Juan de Orús','La Iglesia de San Juan de Orús (siglo XII) es una edificación románica de la escuela del Serrablo levantada en sillarejo fino calizo con friso de baquetones y un ábside semicircular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22253','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22253','iglesia','La Iglesia de San Saturnino','La Iglesia de San Saturnino (siglo XVI) es un edificio de planta de cruz latina edificado en mampostería caliza pirenaica que conserva una torre medieval anterior reconvertida en campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22253','palacio','El Casco Viejo y Casonas de Yésero','El Casco Viejo y Casonas de Yésero (siglos XVI-XVIII) destaca por sus portadas monumentales de sillería caliza, ventanas con dinteles labrados y chimeneas tradicionales de gran volumen con espantabrujas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22254','monumento','Núcleos de población de Zaidín','El término municipal incluye los siguientes núcleos de población: Zaidín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22254','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22254','iglesia','La Iglesia Parroquial de San Juan Bautista','La Iglesia Parroquial de San Juan Bautista (siglo XVIII) es un gran templo barroco edificado en ladrillo visto y mampostería sobre un basamento perimetral de sillería de arenisca que cuenta con una monumental portada clasicista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22254','monumento','Las Ruinas del Castillo de Zaidín','Las Ruinas del Castillo de Zaidín (siglo XII-XIV) representan la antigua fortaleza medieval que controlaba la frontera del río Cinca conservando fragmentos de muros de sillería caliza irregular y cimentaciones de yeso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90061','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90061','iglesia','La Iglesia de Sant Esteve d''Abella de la Conca','La Iglesia de Sant Esteve d''Abella de la Conca (siglo XII) es un templo románico edificado en sillarejo de piedra caliza local colgado sobre un acantilado que destaca por su planta basilical de tres naves y ábsides con arcuaciones lombardas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90061','monumento','El Castillo de Abella','El Castillo de Abella (siglo XI) representa los restos de una fortaleza medieval fronteriza de la Marca Superior construida con aparejo rústico de piedra caliza y argamasa de cal directamente sobre la roca madre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90061','monumento','El Conjunto de Casas Rupestres de les Lluquines','El Conjunto de Casas Rupestres de les Lluquines (siglos XI-XIV) constituye un hito etnográfico medieval formado por viviendas e infraestructuras agrarias excavadas en los abrigos naturales de los estratos calcáreos de la sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28030','monumento','Núcleos de población de Abrera','El término municipal incluye los siguientes núcleos de población: Abrera, Santa Maria de Vilalba, Can Vilalba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28030','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28030','iglesia','La Iglesia de Sant Pere d''Abrera','La Iglesia de Sant Pere d''Abrera (siglo XI-XII) es un templo románico lombardo levantado en sillarejo regular','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28030','monumento','El Castillo de Voltrera','El Castillo de Voltrera (siglo VIII-XI) es una fortaleza defensiva del bajo Llobregat en estado de ruina consolidada, construida con mampostería basta de pizarra y caliza que conserva la cabecera románica de su capilla de Sant Pere.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28030','monumento','El Pou de Glaç d''Abrera','El Pou de Glaç d''Abrera (siglo XVIII) es una estructura subterránea preindustrial de almacenamiento de hielo edificada con planta circular mediante gruesos muros de mampostería encintada y cúpula de ladrillo macizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27015','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27015','iglesia','La Colegiata de Sant Pere d''Àger','La Colegiata de Sant Pere d''Àger (siglo XI) es un conjunto monumental románico y gótico que incluye un claustro de piedra caliza y una iglesia basilical promovida por Arnau Mir de Tost empleando sillería regular.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27015','palacio','El Castillo-Palacio de Àger','El Castillo-Palacio de Àger (siglo XI) es una fortaleza de la reconquista construida sobre cimientos romanos y un ribat islámico utilizando aparejo regular de piedra caliza de la sierra del Montsec.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27015','iglesia','La Iglesia de la Mare de Déu de la Pertusa','La Iglesia de la Mare de Déu de la Pertusa (siglo XI-XII) es una ermita románica colgada de forma inverosímil sobre el desfiladero de Mont-rebei, ejecutada en sillarejo rústico calizo con techumbre de losas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27015','monumento','La Vía Romana de Àger','La Vía Romana de Àger (siglo II d.C.) es una infraestructura logística que conserva un tramo pavimentado con grandes losas de piedra caliza pulida para salvar el paso hacia el Pallars.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90062','monumento','Núcleos de población de Aiguamúrcia','El término municipal incluye los siguientes núcleos de población: Aiguamúrcia, Santes Creus, Les Pobles, L''Albà, El Pla de Manlleu.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90062','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90062','iglesia','Real Monasterio de Santa Maria de Santes Creus','Real Monasterio de Santa Maria de Santes Creus (siglos XII-XIV) es una de las obras cumbres del arte cisterciense en la Península Ibérica, edificado con sillería de piedra calcárea fina y arenisca por la Orden del Císter bajo patrocinio real.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90062','monumento','Las Tumbas Reales de Santes Creus','Las Tumbas Reales de Santes Creus (siglo XIV) albergan los restos de los reyes Pedro el Grande y Jaime II de Aragón, esculpidas en mármol de Girona y pórfido rojo por orden de Jaime II en estilo gótico flamenco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90062','monumento','El Castillo de l''Albà','El Castillo de l''Albà (siglo X) representa las ruinas de una fortaleza defensiva fronteriza construida con muros de tapial y mampostería caliza basta que domina el valle del río Gaià.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90062','monumento','El Celler Cooperatiu de Santes Creus','El Celler Cooperatiu de Santes Creus (año 1919) es una bodega de estilo modernista industrial diseñada por el arquitecto Cèsar Martinell empleando arcos parabólicos de ladrillo visto y muros de mampostería mixta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90063','monumento','Núcleos de población de Aiguaviva','El término municipal incluye los siguientes núcleos de población: Aiguaviva, Güell, Mas Aliu, Rajoleries.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90063','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90063','iglesia','La Iglesia de Sant Joan d''Aiguaviva','La Iglesia de Sant Joan d''Aiguaviva (siglos XII-XVI) es un templo de origen románico transformado en estilo gótico tardío que está construido en sillería de piedra caliza gerundense con una portalada esculpida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90063','monumento','La Casa Templaria de Aiguaviva','La Casa Templaria de Aiguaviva (Comanda de Gardeny) (siglo XIII) representa los restos arquitectónicos civiles y militares de la orden del Temple','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25038','monumento','Análisis Atómico de Hitos','Análisis Atómico de Hitos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25038','iglesia','La Iglesia de Sant Antolí','La Iglesia de Sant Antolí (siglo XVIII) es un templo barroco clasicista de dimensiones monumentales edificado con una fachada de sillería de arenisca que imita modelos jesuitas del centro de Europa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25038','monumento','El Castillo de Aitona','El Castillo de Aitona (siglo XII-XVI) es una fortaleza señorial de la baronía de Aitona construida con sillares de arenisca local sobre una colina que domina el valle del río Segre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25038','monumento','El Yacimiento Arqueológico de Genó','El Yacimiento Arqueológico de Genó (Edad del Bronce) constituye un poblado prehistórico que conserva basamentos de viviendas rectangulares hechos con piedra basta y barro donde se documentó la producción de cerveza más antigua de la península.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40194','monumento','Acueducto Romano','Obra maestra de la ingeniería romana del siglo II d.C., construido con sillares de granito unidos sin argamasa; uno de los mejor conservados del mundo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40194','monumento','Alcázar de Segovia','Castillo palacio del siglo XII con perfiles de cuento de hadas, clave en la historia de la Corona de Castilla y residencia de los Reyes Católicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40194','catedral','Catedral de Nuestra Señora de la Asunción','Conocida como la "Dama de las Catedrales", es una obra cumbre del gótico tardío con un imponente claustro y torre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40156','monumento','Castillo de Pedraza','Fortaleza del siglo XIII reedificada en el siglo XV, excelentemente conservada, que protege el flanco de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40156','monumento','Plaza Mayor Porticada','Una de las plazas castellanas más puras y antiguas, rodeada de casas palaciegas con soportales de columnas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40156','monumento','Cárcel de la Villa','Edificio del siglo XIII perfectamente conservado donde se aprecian las mazmorras y los cepos de la época medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51025','monumento','Muralla de Ávila','El recinto amurallado medieval más completo y mejor conservado del mundo (siglo XI a XIV), con 2,5 kilómetros de perímetro y 87 torreones enteros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51025','catedral','Catedral de Cristo Salvador','Primera catedral gótica de España, concebida originalmente como templo y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51025','iglesia','Basílica de San Vicente','Joya del románico de transición (siglo XII) edificada en el lugar del martirio de San Vicente, con una portada occidental bellísima.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09003','catedral','Catedral de Santa María','Obra cumbre del gótico clásico europeo (siglos XIII-XVI) declarada Patrimonio de la Humanidad de forma individual; destaca su fachada principal con agujas caladas calizas diseñadas por Juan de Colonia, el espectacular Cimborrio Plateresco, la Escalera Dorada de Diego de Siloé y la Capilla de los Condestables.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09003','iglesia','Monasterio de las Huelgas Reales','Abadía cisterciense femenina fundada en 1187 por Alfonso VIII; panteón real de reyes castellanos, conserva un claustro románico ("las Claustrillas"), una iglesia gótica defensiva y el Museo de Telas Medievales con ropajes reales intactos únicos en el mundo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09003','iglesia','Cartuja de Santa María de Miraflores','Complejo monástico gótico final (siglo XV) situado a las afueras; alberga en su iglesia el espectacular retablo mayor esculpido por Gil de Siloé y el sepulcro de alabastro','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09003','monumento','Arco de Santa María','Monumental arco de triunfo del siglo XVI construido en sillería caliza calavera sobre la antigua puerta de la muralla medieval; decorado con estatuas nicho que representan a héroes castellanos como el Cid Campeador y al emperador Carlos V.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09003','monumento','Castillo de Burgos y Murallas','Ruinas consolidadas de la fortaleza medieval del siglo IX que corona el cerro de la ciudad; conserva el tramo de cubos defensivos, puertas como la de San Esteban y el pozo medieval con su red de galerías subterráneas. [1, 2, 3]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','monumento','Recinto Amurallado de Albarracín','Colosal complejo fortificado medieval de los siglos X al XIV labrado en sillería de piedra arenisca roja (pétreo rodeno) y yeso local, universal por trepar de forma inverosímil por la cresta de la montaña jalonado por la Torre del Andador y cubos defensivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','catedral','Catedral de San Salvador','Basílica renacentista iniciada en el siglo XVI en excelente cantería, asentada sobre una peña escarpada, provista de una nave única con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','palacio','Palacio Episcopal','Residencia monumental del siglo XVIII en sillería arenisca y revocos tradicionales de yeso rojo de Albarracín, que destaca por su gran portalada heráldica barroca y un claustro interior porticado de líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','monumento','Torre de Doña Blanca','Recia torre de defensa bajomedieval del siglo XIII levantada en aparejo regular de rodeno rojo en un extremo del cortado rocoso, constituida por muros ciegos de tres cuerpos de altura y saeteras artilleras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43001','monumento','Entramado Urbano y Casa de la Julianeta','Excepcional conjunto histórico-artístico de arquitectura popular medieval edificado en mampostería de rodeno, entramado de vigas de madera de pino y cerramientos de yeso rojizo que vuelan sobre el plano de las calles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','palacio','Palacio Real','Residencia oficial del rey de España; majestuoso palacio barroco-clasicista del siglo XVIII construido sobre el antiguo Alcázar de los Austrias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','catedral','Catedral de la Almudena','Templo neoclásico en el exterior y neogótico en el interior, con una cripta neorrománica del siglo XIX de gran valor arquitectónico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','monumento','Plaza Mayor','Icono del Madrid de los Austrias proyectado por Juan de Herrera en el siglo XVI, porticado y presidido por la estatua de Felipe III.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','palacio','Palacio de Cristal','Estructura romántica de hierro y cristal de 1887 ubicada en el Retiro, inspirada en la arquitectura industrial británica de la época.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28079','iglesia','Monasterio de las Descalzas Reales','Palacio plateresco reconvertido en convento en el siglo XVI, con una impresionante colección de arte renacentista y barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28131','iglesia','Monasterio de El Escorial','Obra cumbre de Juan de Herrera encargada por Felipe II en el siglo XVI; colosal complejo que unifica palacio, basílica, biblioteca y panteón real.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28131','monumento','Casita del Príncipe','Palacete neoclásico del siglo XVIII diseñado por Juan de Villanueva, rodeado de jardines de estilo francés de gran simetría.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','monumento','Universidad de Alcalá (Colegio Mayor de San Ildefonso)','Obra cumbre del plateresco renacentista español diseñada por Rodrigo Gil de Hontañón en el siglo XVI; destaca su fachada esculpida, el Patio de Santo Tomás de Villanueva y el Paraninfo con artesonado mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','catedral','Catedral-Magistral de los Santos Justo y Pastor','Templo del gótico tardío (siglos XV-XVI) construido bajo el mecenazgo del Cardenal Cisneros; posee el raro privilegio eclesiástico de ser "Magistral" y custodia una impresionante cripta visigoda y bajomedieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','monumento','Yacimiento Arqueológico de Complutum','Impresionante conjunto de la ciudad romana del siglo I d.C.; incluye el foro, la Basílica, las Termas, la Casa de los Grifos (con pinturas murales intactas) y la monumental Casa del Hippolytus con mosaicos polícromos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','palacio','Palacio Arzobispal','Fortaleza y residencia palaciega iniciada en el siglo XIII con ampliaciones mudéjares, renacentistas y barrocas; fue escenario de la primera entrevista entre los Reyes Católicos y Cristóbal Colón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','monumento','Casa Natal de Miguel de Cervantes','Reconstrucción museo de una auténtica casa hidalga del siglo XVI, que conserva la estructura porticada del patio central, las dependencias domésticas y el pozo original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','monumento','Corral de Comedias de Alcalá','Uno de los teatros públicos más antiguos de Europa (1601); conserva la estructura del patio de comedias barroco, el pozo, los aposentos de las cazuelas y su transformación posterior en teatro romántico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','iglesia','Monasterio de San Bernardo (Las Bernardas)','Obra cumbre del barroco clasicista madrileño del siglo XVII diseñada por Juan Gómez de Mora, con una fachada monumental de ladrillo y granito y una iglesia de planta elíptica única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29001','monumento','Recinto Amurallado','Murallas medievales de los siglos XIV y XV que rodeaban la ciudad histórica, jalonadas por torres cuadrangulares y la monumental Puerta de Madrid (siglo XVIII). [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29003','palacio','Palacio Real de Aranjuez','Residencia de primavera de los reyes de España iniciada por Juan de Herrera (siglo XVI) y culminada por Carlos III y Santiago Bonavía (siglo XVIII); destaca su fachada bicroma de ladrillo y piedra de Colmenar, el Gabinete de Porcelana, la Sala de Espejos y el Salón del Trono.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29003','monumento','Casa del Labrador','Palacete de recreo de Carlos IV de estilo neoclásico imperial diseñado por Juan de Villanueva; alberga un despliegue de lujo decorativo absoluto con sedas valencianas, frescos de Maella, mármoles y maderas nobles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29003','monumento','Jardín del Príncipe','Inmenso parque paisajístico de estilo anglo-francés del siglo XVIII a orillas del río Tajo; alberga fuentes mitológicas (Apolo, Narciso), el Estanque de los Chinescos con sus templetes exóticos y el Museo de Falúas Reales (embarcaciones de la corte).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29003','monumento','Jardín de la Isla','Jardín renacentista del siglo XVI trazado sobre una isla artificial del río Tajo, decorado con una red monumental de fuentes de mármol e Italia (Hércules e Hidra, Baco, la de la Espina).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29003','monumento','Plaza de Toros de Aranjuez','Coso taurino monumental inaugurado en 1797 por Carlos IV, uno de los más antiguos e intactos de España, con una estructura exterior de piedra y graderíos de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29003','iglesia','Iglesia de San Antonio de Padua','Templo barroco de planta centralizada con una gran cúpula y una galería porticada de arcos que cierra monumentalmente la Plaza de Mariblanca, diseñada por Bonavía en el siglo XVIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29003','monumento','Estación de Ferrocarril de Aranjuez','Joya de la arquitectura neomudéjar de principios del siglo XX (1922), decorada con azulejos polícromos, artesonados de madera y mosaicos que conmemoran la segunda línea férrea de España (el Tren de la Fresa).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28082','monumento','Castillo Nuevo de los Mendoza','Obra cumbre de la arquitectura militar y palaciega bajomedieval (1475) erigida por Juan Guas; fortaleza residencial de planta cuadrada construida en granito, con espectaculares torres cilíndricas, una galería gótica calada de un refinamiento extremo y almenas decoradas con bolas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28082','monumento','Castillo Viejo de Manzanares','Ruinas consolidadas de la fortaleza original del siglo XIV situada a las afueras, construida en mampostería y piedra berroqueña caliza con fines netamente defensivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28082','iglesia','Iglesia de Nuestra Señora de las Nieves','Templo del siglo XIV-XV que fusiona elementos del gótico tardío y el renacimiento; destaca su pórtico renacentista y su ábside poligonal de cantería de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28082','monumento','Puente de la Cañada Real','Estructura civil barroca de piedra sobre el cauce original del río Manzanares, clave en las rutas históricas de la Mesta y la trashumancia nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28052','monumento','Plaza Mayor de Chinchón','Una de las plazas medievales porticadas más famosas del mundo; conjunto urbano consolidado entre los siglos XV y XVII de estructura irregular, rodeado de casas de dos y tres','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28052','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo monumental barroco y plateresco iniciado por los Condes de Chinchón en el siglo XVI; carece de torre y alberga en su espectacular altar mayor un lienzo original pintado por Francisco de Goya en 1812 ("La Asunción de la Virgen").','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28052','iglesia','Torre de Chinchón (Torre de la Iglesia de San Andrés)','Curioso hito arquitectónico exento; se trata de la torre campanario de la antigua iglesia gótica destruida por las tropas francesas en 1808. De ahí el dicho popular: "Chinchón tiene una torre sin iglesia y una iglesia sin torre".','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28052','monumento','Castillo de los Condes de Chinchón','Fortaleza renacentista del siglo XVI construida en sillares de piedra caliza; presenta una planta rectangular con torres cilíndricas en las esquinas y un foso defensivo perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28052','iglesia','Monasterio de los Agustinos (Parador Nacional)','Convento barroco del siglo XVII fundado por los condes de la villa; destaca su claustro acristalado, sus bóvedas y su integración arquitectónica civil actual.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28052','iglesia','Convento de las Clarisas','Complejo monacal del siglo XVII de estilo barroco castellano, construido en ladrillo y cajones de mampostería caliza, famoso por su sobria clausura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28027','monumento','Recinto Amurallado de Buitrago','La muralla medieval más completa y mejor conservada de toda la Comunidad de Madrid (declarada Monumento Nacional); cinturón defensivo de más de 800 metros de origen mudéjar (siglos XI-XII) que abraza el meandro del río Lozoya, jalonado por torres corachas, adarves y barbacanas transitables.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28027','monumento','Castillo de los Mendoza (Alcázar)','Fortaleza góticomudéjar construida en el siglo XV en el ángulo de la muralla; palacio residencial fortificado de planta cuadrada con siete torres macizas decoradas con ladrillo visto y un patio de armas que albergó a la corte castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28027','iglesia','Iglesia de Santa María del Castillo','Templo del siglo XIV de estilo gótico-mudéjar; destaca su espectacular torre mudéjar exenta con arquerías ciegas entrelazadas y su artesonado neomudéjar reconstruido en el interior de la nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28027','monumento','Puente del Arrabal (Puente Viejo)','Estructura de piedra de sillería del siglo XIV que cruza el río Lozoya, construida con un solo arco central apuntado para salvar la corriente y conectar con el arrabal exterior de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28027','monumento','Torre del Reloj','Torre defensiva pentagonal integrada en la muralla que servía como puerta principal de acceso a la villa fortificada, coronada por un cuerpo barroco que alberga la maquinaria del reloj.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28145','monumento','El Ábside de los Milagros','Espectacular cabecera de una iglesia románico-mudéjar del siglo XIII, levantada con ladrillo visto y arquerías ciegas superpuestas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28145','iglesia','La Cartuja','Complejo agrícola y monacal del siglo XVII fundado por los monjes de El Paular, con bodegas abovedadas excelentemente conservadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28145','monumento','Puente Romano','Estructura que conserva restos de sillería romana y reconstrucciones medievales, clave en las rutas de la cuenca del Jarama.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28120','iglesia','Monasterio de Santa María de El Paular','Monasterio cartujo fundado en el siglo XIV por Enrique II, con un claustro gótico flamígero y un retablo de alabastro policromado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28120','monumento','Puente del Perdón','Estructura de piedra del siglo XVIII que cruza el río Lozoya frente al monasterio, construida para sustituir un puente de madera anterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28151','iglesia','Iglesia de la Magdalena','Espléndido templo gótico del siglo XV, cuna del Cardenal Cisneros, con una monumental portada y un retablo de la escuela de Berruguete.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28151','palacio','Palacio de Salinas','Edificio renacentista con una fachada plateresca del siglo XVI atribuida a los talleres reales de la zona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28107','monumento','Arquitectura Negra de Patones','Todo el pueblo en sí es un monumento a la arquitectura popular; viviendas e infraestructuras del siglo XVII construidas íntegramente con pizarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28107','ermita','Ermita de la Virgen de la Oliva','Ruinas de un templo románico-mudéjar del siglo XII localizadas en los alrededores, de sobria fábrica de ladrillo y mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28043','monumento','Plaza Mayor de Colmenar de Oreja','Obra cumbre del urbanismo castellano barroco (siglos XVII-XVIII); la plaza está suspendida en el aire, levantada sobre el barranco del Zacatín gracias a una colosal red de túneles y arcos de piedra caliza (Arco de Zacatín).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28043','iglesia','Iglesia de Santa María la Mayor','Majestuoso templo fortificado levantado originalmente por la Orden de Santiago en el siglo XIII y ampliado en el XVI por Gil de Hontañón; alberga en su interior frescos barrocos monumentales del pintor Ulpiano Checa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28043','monumento','Teatro Municipal Diéguez','Joya de la arquitectura civil decimonónica (1881), construido siguiendo el modelo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28043','ermita','Ermita del Cristo del Humilladero','Gran santuario barroco del siglo XVII de planta de cruz latina, que constituye un conjunto monumental exento rodeado de cuidados jardines y cipreses.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28043','monumento','Los Jardines y Fuentes de los Zacatines','Red de fuentes y lavaderos monumentales del siglo XVIII excavados en piedra caliza viva en el fondo del barranco de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28031','palacio','Palacio de Villena','Impresionante palacio-fortaleza de origen mudéjar (siglo XV) reformado en el siglo XVI con un refinado estilo renacentista; destaca su fachada de cantería de granito, sus jardines históricos y su gran estanque de recreo nobiliario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28031','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo iniciado en el siglo XV de estilo gótico tardío y finalizado en el XVI; cuenta con recios muros de sillería berroqueña, contrafuertes góticos y un interior de gran altura basilical.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28031','iglesia','Yacimiento de la Iglesia Mudéjar (La Mezquita)','Restos arqueológicos consolidados de una iglesia','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28031','ermita','Ermita de Santa Ana','Pequeño templo exento del siglo XVII de estilo barroco rural con una sobria portada de piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28099','ermita','Ermita de San Blas','Pequeño templo de arquitectura popular religiosa castellana con muros de mampostería, reconstruido tras la destrucción de la antigua edificación rural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','monumento','Teatro y Anfiteatro Romanos','Conjunto universal Patrimonio de la Humanidad inaugurado por Agripa en el año 15 a.C. que conserva intacta su columnata corintia de mármol del frente escénico junto al foso y graderíos del anfiteatro anejo ejecutados en opus caementicium y sillería granítica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','monumento','Acueducto de los Milagros','Monumental obra de ingeniería hidráulica romana del siglo I d.C. de la que se conservan formidables pilares de sillería caliza y ladrillo alternado que alcanzan los veinticinco metros de altura sobre el valle del río Albarregas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','monumento','Puente Romano sobre el Guadiana','El puente más largo de la antigüedad clásica con cerca de ochocientos metros de longitud, edificado en el siglo I a.C. íntegramente en sillería de granito berroqueño con tajamares redondeados para mitigar la corriente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','monumento','Alcazaba Arabe','Fortaleza militar omeya del siglo IX, la más antigua de la península, construida con sillares romanos reutilizados que alberga en su interior un','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','iglesia','Templo de Diana','Edificio religioso romano del siglo I d.C. de planta períptera y columnas estriadas de granito con capiteles corintios que se conserva de forma excepcional gracias a su integración medieval en el palacio renacentista del Conde de los Corbos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06018','iglesia','Basílica de Santa Eulalia','Templo cristiano de origen visigodo y reconstruido en el siglo XIII en estilo gótico que cuenta con una cripta arqueológica excepcional donde se conservan los restos del mausoleo de la mártir y vestigios romanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06023','monumento','Alcázar de los Duques de Feria','Espectacular palacio fortificado de primer orden alzado en el siglo XV que conserva su recio aspecto exterior con torres cilíndricas angulares y un soberbio patio central renacentista de mármol blanco de traza clasicista atribuida a Juan de Herrera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06023','iglesia','Colegiata de de Nuestra Señora de la Candelaria','Monumental iglesia gótico-renacentista iniciada en el siglo XVI que destaca por su esbelta torre de sillería granítica calavera y un impresionante retablo mayor barroco que custodia nueve magníficas tablas de Francisco de Zurbarán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06023','monumento','Plazas Grande y Chica','Conjunto urbano medieval protegido que constituye el corazón de la villa, caracterizado por sus bellas arquerías de medio punto sobre columnas de granito berroqueño y fachadas encaladas donde se celebraba el comercio tradicional local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06023','iglesia','Convento de Santa Clara','Edificio religioso del siglo XV fundado por la Casa de Feria que conserva una magnífica iglesia gótica con enterramientos mudéjares y un claustro de severas líneas clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06019','monumento','Núcleos de población de Olivenza','El término municipal incluye los siguientes núcleos de población: San Benito de la Contienda, San Francisco de Olivenza, San Jorge de Alor, San Rafael de Olivenza, Santo Domingo de Guzmán, Villarreal y Taliga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06019','iglesia','Iglesia de de Santa María de la Magdalena','Obra maestra universal del estilo manuelino portugués iniciada en el siglo XVI que impresiona por su soberbio interior de tres naves donde las columnas centrales imitan gruesas sogas marineras torsionadas de piedra caliza que sostienen complejas bóvedas de crucería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06019','monumento','Alcázar Rey Don Denis y Torre del Homenaje','Fortaleza medieval lusa del siglo XIV construida en sillería de granito berroqueño que alberga el Museo Etnográfico y destaca por su monumental torre defensiva de treinta y seis metros de altura accesible mediante rampas abovedadas de ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06019','iglesia','Iglesia de de Santa María del Castillo','Templo renacentista del siglo XVI levantado sobre la antigua mezquita que alberga un espectacular retablo del Árbol de Jesé, una joya de madera tallada y policromada que representa la genealogía de la Virgen María mediante ramas exultantes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06019','monumento','Recinto Amurallado y Puertas Monumentales','Impresionante sistema de fortificaciones abaluartadas de estilo Vauban de los siglos XVII y XVIII ejecutado en cantería y tapial que rodea la ciudad histórica, conservando puertas monumentales de sillería neoclásica como la de Alconchel y la del Calvario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06019','iglesia','Capilla del Santo Hospital de la Santa Casa de la Misericordia','Joya del barroco portugués del siglo XVIII cuyos muros interiores se encuentran completamente','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06014','monumento','Fortaleza Templaria y Torre Sangrienta','Alcázar medieval de primer orden alzado en el siglo XIII por la Orden del Temple sobre cimientos árabes que destaca por su muralla de mampostería granítica reforzada con cubos semicirculares y su célebre torre del homenaje donde fueron ejecutados los últimos caballeros templarios de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06014','iglesia','Iglesia de San Bartolomé','Templo gótico-renacentista modificado en el siglo XVIII que impresiona a nivel mundial por su espectacular torre-fachada barroca, una obra cumbre labrada en ladrillo, yeso y azulejería polícroma con una profusión ornamental barroca sin parangón en Extremadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06014','iglesia','Iglesia de San Miguel Arcángel','Monumental edificio gótico iniciado en el siglo XV que domina la plaza principal con otra soberbia torre barroca de gran altura calada con arquerías, hornacinas y pináculos de piedra caliza de gran impacto visual.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06014','iglesia','Iglesia de Santa María de la Encarnación','El templo más antiguo de la ciudad, de origen visigodo y reedificado en el siglo XV, que presenta un interior de severas proporciones góticas y una torre exenta barroca que completa el característico perfil de siluetas de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06006','monumento','Alcazaba de Badajoz','La alcazaba árabe más grande de Europa por perímetro amurallado, construida en el siglo XII por los almohades, con la icónica Torre de Espantaperros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06006','catedral','Catedral de San Juan Bautista','Iglesia fortificada del siglo XIII con un impresionante claustro gótico-mudéjar y ventanas de traza renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06006','monumento','Puente de Palmas','Obra de traza herreriana construida en el siglo XVI sobre el río Guadiana, custodiada en sus extremos por las antiguas puertas de la muralla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06015','iglesia','Iglesia de Nuestra Señora de la Granada','Templo barroco con una soberbia fachada porticada de dos pisos de arquerías de estilo mudéjar andaluz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06015','monumento','Plaza de España','Espléndido coso porticado portador de balconadas mudéjares de ladrillo, sede histórica del Tribunal de la Inquisición en Extremadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06080','monumento','Teatro Romano de Medellín','Espectacular monumento clásico del siglo I a.C. integrado en la ladera del cerro del castillo que conserva en impecable estado de conservación su graderío original de piedra caliza calavera, la orquesta y los restos monumentales del frente escénico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06080','monumento','Castillo de Medellín','Fortaleza de primer orden de origen musulmán reedificada en el siglo XIV que domina el río Guadiana con un imponente doble recinto amurallado de sillería y mampostería reforzado por torres cuadrangulares y una monumental torre del homenaje palaciega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06080','monumento','Puente Barroco sobre el Guadiana','Monumental obra de ingeniería civil del siglo XVII ejecutada en sillería granítica berroqueña que cuenta con veinte ojos de arcos de medio punto y contrafuertes diseñados para resistir las grandes crecidas del río.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06080','iglesia','Iglesia de Santiago Apóstol','Templo tardomedieval edificado sobre restos romanos que combina muros de mampostería con una cabecera gótica, sirviendo actualmente de centro de interpretación para el área arqueológica de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06075','monumento','Castillo de Magacela','Fortaleza de origen califal cedida a la Orden de Alcántara en el siglo XIII que corona un escarpado cerro de pizarra rústica, conservando potentes lienzos de muralla, aljibes excavados en la roca viva y restos de una torre del homenaje tardomedieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06075','iglesia','Iglesia de Santa Ana','Templo gótico-mudéjar construido en el siglo XV dentro del recinto del castillo que destaca por su techumbre de madera de sabina de tradición morisca y sus arcadas apuntadas de ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06075','monumento','Dolmen de Magacela','Monumental sepulcro megalítico prehistórico perfectamente musealizado que consta de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90064','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo de origen barroco (siglo XVII) construido en mampostería de pizarra y piedra, que destaca por su crucero de madera, un retablo mayor de transición renacentista-barroco y una valiosa cruz procesional de plata.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90064','iglesia','Santuario de la Fuente de la Virgen','Pequeño oratorio rural integrado en el paisaje de la sierra, ejemplo de la arquitectura religiosa popular ligada a las rutas de pastoreo tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90064','monumento','Molino de la Acebeda','Infraestructura hidráulica preindustrial del siglo XVIII construida en piedra caliza y pizarra, que conserva parte de la cacera y la estructura de molienda original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90065','iglesia','Iglesia de la Purísima Concepción','Templo renacentista del siglo XVI de tres naves, construido en ladrillo y aparejo toledano, que alberga un magnífico artesonado mudéjar en su cabecera y un retablo barroco del siglo XVIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90065','ermita','Ermita de la Soledad','Construcción religiosa del siglo XVII situada en el casco urbano, caracterizada por su sobria fachada de ladrillo y su planta de cajón típicamente castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90065','ermita','Ermita de San Roque','Pequeño humilladero del siglo XVI ubicado en los antiguos caminos de acceso, restaurado, que muestra la devoción popular contra las pestes medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90066','iglesia','Iglesia de Santa Marina Virgen y Mártir','Edificio que combina elementos del gótico tardío (siglo XV) en su cabecera y reformas renacentistas, con una imponente torre campanario de piedra y un coro alto de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90066','ermita','Ermita de la Virgen de la Antigua','Templo románico de transición (siglo XIII) situado a las afueras, que conserva muros de mampostería originales y una estructura de arcos fajones apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90066','monumento','Yacimiento Arqueológico de la Cueva de la Alameda','Restos de ocupación prehistórica y visigoda en los abrigos rocosos del entorno, documentados por arqueólogos con hallazgos de industria lítica y cerámica antigua.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90067','iglesia','Iglesia de San Pedro Apóstol','Templo de origen renacentista (siglo XVI) con severas reconstrucciones neoclásicas y del siglo XX; conserva una sobria torre campanario de piedra y ladrillo que domina el casco antiguo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90067','ermita','Ermita de Nuestra Señora de la Paz','Edificio religioso del siglo XVII levantado en el emplazamiento de un antiguo culto medieval; destaca su portada barroca y el retablo interior que cobija a la patrona de la localidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90067','monumento','Yacimiento de la Dehesa de Alcobendas','Enclave arqueológico con restos documentados de asentamientos de la Edad del Bronce y de época romana, claves para el estudio del poblamiento temprano del valle del Jarama.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29002','monumento','Castillos de San José de Valderas','Conjunto de palacetes de estilo neogótico sajón construidos a principios del siglo XX (1917) por encargo de los marqueses de Valderas, utilizando piedra, grandes ventanales apuntados y torreones circulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29002','iglesia','Iglesia de Santa María la Blanca','Templo parroquial de origen mudéjar (siglo XVI) declarado Bien de Interés','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29002','ermita','Ermita de la Virgen de los Remedios','Pequeño templo de arquitectura popular religiosa edificado en ladrillo y piedra caliza entre los siglos XVII y XVIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90068','iglesia','Iglesia Parroquial de San Pedro Apóstol','Edificio del siglo XVIII construido sobre restos del siglo XVI; presenta una nave única con bóvedas de cañón y una torre campanario exenta realizada en sillería de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90068','monumento','Puente de la Pedrera','Estructura de piedra de sillería sobre el río Alberche, con arcos de medio punto construidos en época ilustrada (siglo XVIII) para mejorar las comunicaciones reales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90068','ermita','Ermita del Satélite','Pequeña construcción devocional rural del siglo XIX, ejemplo de la arquitectura religiosa integrada en las dehesas del suroeste de Madrid.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90069','iglesia','Iglesia de la Asunción de Nuestra Señora','Monumental templo del siglo XVI atribuido a las trazas de Alonso de Covarrubias; destaca su grandioso espacio interior de tres naves, sus columnas toscanas y un retablo mayor de transición al barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90069','monumento','Presa del Rey (Canal de Cabarrús)','Obra de ingeniería hidráulica de finales del siglo XVIII (1799) ideada por el Conde de Cabarrús, construida en sillería de granito para el riego y la navegación parcial de la zona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90070','iglesia','Iglesia de la Asunción de Nuestra Señora','Edificio fortificado del siglo XVI de estilo gótico tardío renacentista, levantado íntegramente con sillería de granito extraído de las canteras locales; posee un imponente muro de contención y espadaña maciza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90070','monumento','Canteras Históricas de Granito','Espacio de patrimonio industrial y arquitectónico etnológico del siglo XIX y XX, de donde se extrajo el material para monumentos nacionales como el Palacio Real de Madrid o el Valle de los Caídos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90071','palacio','Palacio de los Marqueses de Legarda','Espléndido palacio barroco del siglo XVII de influencia herreriana, con una fachada asimétrica de ladrillo y piedra caliza de las canteras de la Alcarria, y un patio interior porticado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90071','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo barroco construido sobre trazas mudéjares anteriores; conserva una torre campanario exenta y capillas laterales con yeserías ornamentales del siglo XVII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90071','monumento','El Encino de Ambite','Aunque es un monumento natural (árbol centenario), está catalogado en el patrimonio municipal al estar ligado históricamente al origen de la villa y sus leyendas medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90072','iglesia','Iglesia Parroquial de Santa María Magdalena','Templo del siglo XVI edificado en el estilo renacentista rural castellano, con fábrica de ladrillo y sillería en los contrafuertes, que destaca por su pila bautismal románica del siglo XIII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90072','ermita','Ermita de la Virgen de la Oliva','Pequeño santuario del siglo XVIII edificado a las afueras, construido con aparejo toledano y tejado a dos aguas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28014','iglesia','Iglesia de San Juan Bautista','Templo monumental que fusiona el estilo renacentista y el barroco herreriano (siglos XVI-XVII); cuenta con una imponente torre campanario de 57 metros y un retablo mayor que alberga tallas de la escuela de Gregorio Fernández.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28014','monumento','Casa del Rey','Palacete fortificado de finales del siglo XVI mandado construir por el embajador de Alemania, Hans Khevenhüller, y frecuentado por Felipe III; presenta una sobria fachada herreriana con escudos de armas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28014','ermita','Ermita de Nuestra Señora de la Soledad','Edificio barroco del siglo XVII de planta de cruz latina, que destaca por su cúpula sobre pechinas ricamente decorada con pinturas murales y yeserías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28014','monumento','Puente de Arganda','Estructura de hierro remachado del siglo XIX (diseño de la escuela de Eiffel), clave en la ingeniería civil de la época y escenario de combates cruciales durante la Batalla del Jarama.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28015','monumento','Torreón de Arroyomolinos (Castillo de Gonzalo Chacón)','Espectacular torre del homenaje del siglo XV que formaba parte de una fortificación señorial; construida en ladrillo de gran calidad con esquinas de sillería caliza, destaca por sus escudos heráldicos y sus saeteras intactas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28015','iglesia','Iglesia Parroquial de San Juan Bautista','Templo neoclásico que sustituyó a la antigua fábrica medieval, de líneas sobrias con muros de mampostería y un interior de planta basilical.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28016','iglesia','Iglesia de Santa Catalina','Pequeño templo parroquial del siglo XVII de estilo barroco rural, levantado en mampostería de pizarra local, con un interior sobrio de una nave y una espadaña tradicional para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28016','monumento','CIUDAD ROMANA DE COMPLUTUM - ALCALÁ DE HENARES','CIUDAD ROMANA DE COMPLUTUM - ALCALÁ DE HENARES (MADRID) 5 ene 2023 — En Alcalá de Henares se sitúa uno de los más importantes yacimientos arqueológicos de Madrid. El conjunto incluye el antiguo foro ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28017','palacio','Castillo de Batres (Palacio de los Lasso de la Vega)','Joya del gótico-mudéjar civil del siglo XV; fortaleza','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28017','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo de origen mudéjar (siglo XVI) exento, vinculado históricamente al señorío del castillo, con una nave única de muros de mampostería y un presbiterio reformado en época barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28017','monumento','Fuente de Garcilaso','Pequeña construcción monumental de piedra caliza situada en los jardines y olivares del entorno del castillo, donde la tradición sitúa la inspiración del célebre poeta renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28017','monumento','Puente de la Sacristana','Restos de infraestructura hidráulica y de paso de origen medieval y moderno sobre el río Guadarrama, clave para el antiguo paso de caballerías señoriales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28018','iglesia','Iglesia Parroquial de San Andrés Apóstol','Templo de estilo rural fortificado levantado en el siglo XVI con grandes sillares de granito; destaca su torre campanario exenta de tres cuerpos y un pórtico renacentista apoyado sobre columnas toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28018','monumento','Fuente de los Tres Caños','Obra de arquitectura civil hidráulica del siglo XIX esculpida íntegramente en bloques de granito local, con un pilón monumental que servía tradicionalmente como abrevadero de ganado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28018','ermita','Ermita del Santo Cristo del Buen Consejo','Pequeña edificación religiosa construida a mediados del siglo XX en piedra de cantería, que sigue la tipología y estética de la arquitectura tradicional serrana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28019','iglesia','Iglesia de Nuestra Señora de la Estrella','Monumental templo renacentista iniciado en el siglo XVI, edificado con aparejo de mampostería y sillería caliza; posee un imponente ábside semicircular y un gran arco triunfal de acceso al presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28019','ermita','Ermita de San Isidro / Ermita de la Virgen de la O','Conjunto de pequeños templos barrocos de los siglos XVII y XVIII integrados en las lomas agrícolas, de planta de cajón castellana y fachadas sobrias de piedra y yeso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28019','monumento','Plaza de la Constitución','Espacio urbano de traza tradicional castellana con elementos porticados y balconadas que combinan piedra y madera, representativo de la comarca de Las Vegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28021','monumento','Atalaya de El Berrueco (Torrepedrera)','Torre vigía de origen andalusí construida en el siglo X durante el califato de Córdoba; de planta circular y fábrica de mampostería de granito, formaba parte de la red defensiva militar de la Marca Media.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28021','iglesia','Iglesia de Santo Tomás Apóstol','Templo de transición del románico al gótico (siglos XII-XIII), que conserva una impresionante portada románica con arquivoltas apuntadas y capiteles decorados, además de muros de sillería de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28021','monumento','La Picota (Crucero)','Monumento de piedra del siglo XVI situado en el centro del pueblo; monolito de granito que','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28021','monumento','Museo del Agua y Cantería (Patrimonio Etnográfico)','Conjunto de antiguas canteras y estructuras tradicionales integradas en el paisaje urbano que explican el histórico oficio de los picapedreros serranos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28020','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio religioso barroco del siglo XVII edificado con aparejo rústico de pizarra y esquinales de granito; cuenta con un interior muy sobrio de una nave y una espadaña defensiva exenta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28022','palacio','Palacio del Infante Don Luis','Obra cumbre del barroco tardío y neoclasicismo civil español (1765) diseñada por Ventura Rodríguez; majestuosa fachada alargada de ladrillo y piedra, que alberga un espectacular jardín italiano de tres terrazas, fuentes y salas con frescos pomposos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28022','iglesia','Convento de la Encarnación (Carmelitas Descalzas)','Complejo monástico barroco del siglo XVII catalogado como Bien de Interés Cultural, con una iglesia de fachada clasicista de ladrillo y granito rematada por un gran frontón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28022','iglesia','Iglesia de San Cristóbal','Templo parroquial de origen mudéjar (siglo XIII) con reformas del siglo XV y XVII; conserva muros originales con la técnica de cajones de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28022','monumento','Puente de San Antón / Puente de la Dehesa','Estructuras de paso e hidráulicas del siglo XVIII proyectadas por el entorno de Ventura Rodríguez para conectar los accesos señoriales al palacio y sus fincas forestales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28023','monumento','Núcleos de población de El Boalo','El término municipal incluye los siguientes núcleos de población: Cerceda y Mataelpino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28023','iglesia','Iglesia de Nuestra Señora de la Blanca (Cerceda)','Espléndido templo de estilo gótico tardío y renacentista (siglo XVI) clasificado como BIC; construida íntegramente en granito, destaca su techumbre de madera, su cabecera poligonal y una pila bautismal renacentista decorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28023','iglesia','Iglesia de San Sebastián (El Boalo)','Templo rural del siglo XVII construido en mampostería de piedra berroqueña, con un característico soportal castellano sobre columnas graníticas y espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28023','ermita','Ermita de San Isidro','Pequeña construcción devocional contemporánea levantada en la ladera de la sierra que respeta los materiales de piedra caliza y granito de la arquitectura de la zona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90073','iglesia','Iglesia de San Vicente Mártir','Templo originalmente edificado en el siglo XV y reformado en el XVII por los duques de Pastrana; cuenta con una maciza torre fortificada de piedra y alberga un retablo mayor barroco','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90073','ermita','Ermita del Buen Suceso','Capilla rural del siglo XVII situada en las afueras, edificada en mampostería de granito y pizarra caliza con un pequeño campanil tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28025','iglesia','Iglesia de la Asunción de Nuestra Señora','Majestuoso templo del siglo XVIII de estilo neoclásico con proporciones catedralicias; presenta una imponente fachada de sillares y un interior cubierto con cúpula sobre pechinas policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28025','ermita','Ermita de San Roque','Pequeña ermita barroca del siglo XVII construida en ladrillo y mampostería, situada en el antiguo camino de acceso para proteger a los caminantes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28025','ermita','La Ermita de Santa Catalina','Ruinas de un templo rural medieval localizadas en el término municipal, que conserva tramos de muros de piedra y argamasa antigua.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28026','monumento','Plaza Mayor de Brunete','Conjunto monumental diseñado en la década de 1940 por la Dirección General de Regiones Devastadas, imitando fielmente la arquitectura herreriana del siglo XVII; plaza porticada simétrica con columnas de piedra caliza y balcones de hierro forjado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28026','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo reconstruido tras la Guerra Civil sobre la fábrica original del siglo XVI; conserva parte de los lienzos de muros de piedra exteriores, la portada plateresca y la torre del campanario de sillares de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28028','iglesia','Iglesia de la Purísima Concepción','Templo del siglo XVI con una espectacular torre campanario de origen románico (siglo XIII) con vanos pareados; destaca su ábside gótico-renacentista y un pórtico porticado de sillería de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28028','ermita','Ermita de Nuestra Señora de la Soledad','Pequeño santuario barroco del siglo XVII exento, edificado en piedra de cantería con tejado a cuatro aguas en los accesos al municipio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28028','monumento','Torre de la Mina','Restos de una antigua explotación minera e instalación preindustrial de extracción de plata y arsénico que data del siglo XVII, de alto valor para la arqueología industrial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28029','iglesia','Iglesia Parroquial de San Juan Bautista','Templo original del siglo XVII con reformas barrocas y neoclásicas, levantado en recia mampostería de granito, que destaca por su espadaña de tres vanos y su cuerpo de campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28029','monumento','Puente de San Roque','Antigua infraestructura de paso construida con grandes losas de granito sobre el arroyo de la Vega, ejemplo de la arquitectura civil de caminos rurales castellanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28032','iglesia','Iglesia de San Pedro Apóstol','Joya del románicomudéjar madrileño (siglo XIII); conserva intacto un espectacular ábside de ladrillo con arquerías ciegas superpuestas y, en su interior, unas pinturas murales medievales románicas únicas en la región.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28032','ermita','Ermita de la Virgen del Rosario','Pequeña edificación religiosa del siglo XVI construida con aparejo toledano (ladrillo y mampostería de piedra caliza).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28033','iglesia','Iglesia de Santa María del Castillo','Templo renacentista del siglo XVI construido sobre el emplazamiento de una antigua fortaleza medieval; catalogado como BIC, destaca por sus bóvedas de crucería estrellada y su magnífico emplazamiento que domina el paisaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28033','ermita','Ermita de la Virgen de los Remedios / Ermita del Santísimo Cristo','Red de ermitas barrocas del siglo XVII situadas en los accesos urbanos, construidas en piedra caliza de la Alcarria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28034','monumento','Puente Canto','Espectacular puente medieval del siglo XIV construido en sillería de granito sobre el arroyo de Canencia, caracterizado por su perfil lomo de asno y sus dos arcos asimétricos (uno apuntado y otro de medio punto).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28034','monumento','Puente de la Cadena','Estructura civil histórica de piedra de un solo ojo apuntado, integrada de forma perenne en las antiguas rutas ganaderas de la sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28034','iglesia','Iglesia de Santa María del Castillo','Templo del siglo XV con reformas renacentistas del XVI, construido con grandes bloques de granito berroqueño, con un coro de madera tallada de gran valor etnológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28035','monumento','Yacimiento de la Necrópolis Visigoda','Necrópolis altomedieval datada entre los siglos VI y VII d.C., donde se han documentado enterramientos en cista y ajuares visigodos de gran valor para la arqueología nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28035','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo del siglo XVI edificado en piedra caliza con una robusta torre campanario de sillería y restos mudéjares en sus cimientos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28035','palacio','Palacio del Virrey de las Indias','Edificio señorial de arquitectura civil barroca del siglo XVII con un escudo de armas esculpido en piedra caliza sobre su portada principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28035','monumento','Balneario y Fábrica de Aguas de Carabaña','Conjunto de patrimonio industrial del siglo XIX y principios del XX ligado a la explotación de sus famosas aguas mineromedicinales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28036','iglesia','Iglesia de Santiago Apóstol','Templo parroquial reconstruido en el siglo XVIII de líneas neoclásicas, levantado sobre la base de una ermita barroca anterior, con una sencilla torre de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28037','monumento','Piedra Escrita de Cenicientos','Monumento megalítico y monolito de granito natural esculpido en el siglo II d.C. por los romanos; se trata de un santuario rural consagrado a la diosa Diana que conserva relieves de tres figuras humanas y una inscripción votiva latina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28037','iglesia','Iglesia Parroquial de San Esteban Protomártir','Templo monumental del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de granito; destaca su ábside poligonal con contrafuertes y un magnífico artesonado mudéjar en la nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28037','ermita','Ermita de la Virgen de la Encina','Edificio religioso barroco del siglo XVII situado a las afueras, ejemplo de la arquitectura popular ligada a la devoción agrícola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28038','monumento','Calzada y Puentes Romanos del Valle de la Fuenfría','Restos de la calzada romana del siglo I d.C. que unía Segovia con Miacum; conserva tres puentes históricos de piedra (Puente del Descalzo, Puente de Enmedio y Puente de la Venta) reformados en época ilustrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28038','iglesia','Iglesia de San Sebastián','Templo que corona el casco urbano, edificado originalmente en el siglo XII en estilo románico (del que conserva la base de la torre y la pila bautismal) y ampliado en el siglo XVI con un gran crucero renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28038','monumento','Estación de Ferrocarril y Tren de la Naturaleza','Conjunto de patrimonio arquitectónico e industrial de principios del siglo XX (1923), de estilo alpino centroeuropeo, que marcaba el inicio del ferrocarril eléctrico del Guadarrama.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28039','iglesia','Iglesia de Santa María de los Remedios','Pequeño templo de arquitectura barroca rural (siglo XVII) construido con muros de mampostería de pizarra y granito berroqueña, con un interior desprovisto de grandes lujos y una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28040','iglesia','Iglesia Parroquial de Santa María Magdalena','Templo barroco de gran envergadura proyectado en el siglo XVI y modificado en el XVII por Ventura Rodríguez; posee una gran nave con bóvedas de cañón y una torre exenta de ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28040','monumento','Complejo Sanatorial de San Juan de Dios y del Sagrado Corazón','Conjunto arquitectónico asistencial del siglo XIX de estilo neomudéjar e industrial, pionero en la salud mental en España.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28040','monumento','Salinas de Espartinas','Yacimiento arqueológico e industrial minero con restos de explotación de sal comun y sulfatos que datan desde la Prehistoria hasta la época romana y moderna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28041','iglesia','Iglesia de San Cipriano','Templo del siglo XVI catalogado como Bien de Interés Cultural; presenta una magnífica fábrica renacentista de tres naves separadas por columnas toscanas de piedra y una fachada renacentista plateresca muy elegante.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28041','monumento','Fuentecilla de Cobeña','Pequeña construcción civil hidráulica barroca del siglo XVII ejecutada en ladrillo visto y piedra de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28046','monumento','Yacimiento Romano de El Beneficio (Mi累積)','Restos excavados y consolidados de una posada o "mansio" romana del siglo IV d.C. situada en la calzada de la Fuenfría; conserva los cimientos de la zona residencial, las termas y las cocinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28046','iglesia','Iglesia de San Ildefonso','Templo parroquial del siglo XVIII edificado en estilo neoclásico sobre restos medievales, construido íntegramente en granito serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28046','ermita','Ermita de Nuestra Señora del Rosario','Pequeña construcción religiosa rural exenta, de mampostería basta y tejado tradicional a dos aguas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28047','iglesia','Iglesia de Nuestra Señora del Enebral','Templo fortificado de origen bajomedieval (siglo XIV) con importantes reformas en el XVI; destaca su imponente torre campanario de sillería de granito y su galería porticada renacentista exterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28047','monumento','Piedra del Concejo','Monumento civil de origen medieval situado junto a la iglesia; graderío de roca de granito donde se reunía históricamente el concejo abierto de la villa para dictar ordenanzas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28042','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo proyectado en el siglo XVI con trazas de sillería renacentista; cuenta con una robusta torre defensiva de piedra berroqueña y un retablo barroco del siglo XVIII en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28042','monumento','Puente de la Fragua y Puente de las Infantas','Conjunto de puentes medievales y de época moderna construidos en piedra de un solo ojo apuntado sobre el arroyo que cruza el casco urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28045','iglesia','Basílica de la Asunción de Nuestra Señora','Obra cumbre del gótico tardío de transición al renacimiento (siglos XV-XVI) atribuida a Juan Guas y Rodrigo Gil de Hontañón; destaca su impresionante torre campanario calada de granito de 50 metros de altura y su colosal retablo mayor renacentista plateresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28045','monumento','Yacimiento de Remedios y Necrópolis Visigoda','Conjunto de yacimientos altomedievales (siglos VI-VII d.C.) con tumbas excavadas en la roca y cistas de piedra, situadas en torno a la actual Ermita de Nuestra Señora de los Remedios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28045','monumento','Puente del Grajal','Estructura de piedra del siglo XVII construida sobre restos medievales y árabes para salvar el curso alto del río Manzanares, de cantería de granito impecable.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28045','ermita','Ermita de Santa Ana','Pequeño santuario mudéjar del siglo XIV construido con hileras de ladrillo y mampostería berroqueña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28044','iglesia','Iglesia de Santiago Apóstol','Templo parroquial del siglo XVI de estilo renacentista rural herreriano, edificado en recios sillares de granito, que conserva una fachada austera y un coro alto de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28044','monumento','Fuente de las Escaleras','Construcción hidráulica ilustrada del siglo XVIII de piedra berroqueña, concebida para el abastecimiento público en los antiguos caminos reales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28048','iglesia','Iglesia de Santo Domingo de Silos','Templo del siglo XVI edificado con fábrica de sillería y ladrillo (aparejo toledano), con una torre campanario renacentista y capillas barrocas con decoración de yeserías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28048','palacio','Palacio del Marqués de Corpa (Casa de los Mondéjar)','Ruinas y restos de la fachada de una casa','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28048','monumento','Fuente del Rey','Fuente monumental barroca del siglo XVII famosa por la calidad de sus aguas, que eran enviadas históricamente a la corte de Madrid para el consumo real.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28049','iglesia','Iglesia de San Pedro Apóstol','Sencillo templo de origen barroco (siglo XVII) edificado en ladrillo visto y mampostería toledana, profundamente reformado en el siglo XX tras los daños sufridos en contiendas históricas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28049','monumento','Escultura de la Mujer de Coslada','Monumento de arte civil contemporáneo fundido en bronce por el célebre escultor Antonio López, erigido como hito urbano de la localidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28050','iglesia','Iglesia de San Andrés Apóstol','Templo del siglo XII-XIII de estilo románico-mudéjar; conserva un espectacular ábside poligonal de ladrillo visto con tres pisos de arquerías ciegas y dobladas de gran pureza formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28050','iglesia','Monasterio de Santa María de la Cruz (Convento de Juana la Local)','Complejo monástico barroco edificado en el siglo XV y ampliado en el XVII en el lugar de unas famosas apariciones marianas; destaca su claustro y su iglesia de ladrillo castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28053','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo del siglo XVI reconstruido tras sufrir un devastador incendio en el siglo XX; conserva su antigua torre campanario renacentista de piedra y ladrillo y parte de sus muros perimetrales de aparejo toledano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28053','ermita','Ermita de la Virgen del Espino','Pequeño templo barroco del siglo XVII de planta de cajón castellana situado en las lomas agrícolas del municipio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28054','monumento','Casita del Príncipe','Pequeño palacio de recreo neoclásico del siglo XVIII diseñado por Juan de Villanueva para el futuro rey Carlos IV; destaca su exquisita decoración interior de sedas, frescos y estucos, y sus jardines de diseño versallesco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28054','iglesia','Monasterio de Prestado (El Casón)','Edificio fortificado del siglo XIV de mampostería de granito; sirvió de residencia provisional a Felipe II y como centro logístico','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28054','iglesia','Iglesia de San Bernabé','Obra maestra del Renacimiento herreriano (siglo XVI) proyectada por Francisco de Mora por orden de Felipe II; destaca su extrema sobriedad geométrica, sus muros desnudos de granito y su pureza de líneas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28054','monumento','Cruz de la Horca / Cruz del Siglo','Monumentos conmemorativos e hitos camineros de piedra tallada del siglo XVI que delimitaban el territorio eclesiástico y real del Real Sitio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28055','iglesia','Iglesia Parroquial de los Santos Justo y Pastor','Gran templo herreriano de transición al barroco (siglos XVIXVII); posee muros de mampostería con esquinales de sillería de piedra caliza de la Alcarria y un valioso órgano histórico en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28055','monumento','Cueva de Pedro Fernández','Yacimiento arqueológico prehistórico situado en los acantilados de yeso sobre el río Tajo, con restos documentados de enterramientos y materiales cerámicos de la Edad del Bronce.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28055','ermita','Ermita del Santo Cristo de la Buena Dicha','Pequeña construcción barroca del siglo XVII con fachada de ladrillo y planta rectangular de cajón típicamente castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28056','iglesia','Iglesia de San Bartolomé Apóstol','Templo del siglo XVI edificado en el estilo renacentista rural de la sierra oeste;','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28056','monumento','Las Casas del Pintón (Arquitectura Etnológica)','Conjunto de viviendas e infraestructuras agrarias de los siglos XVII y XVIII integradas en el casco urbano, decoradas con el característico esgrafiado serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28057','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo del siglo XVI edificado por orden del Marqués de Santillana; combina elementos del gótico tardío y del mudéjar renacentista, destacando sus techumbres de madera tallada y su portada de ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28057','palacio','Palacio de los Marqueses de Torote','Ruinas consolidadas de la antigua casa palaciega y hacienda agrícola del siglo XVI, ejemplo único de urbanismo señorial rural cerrado de la cuenca del Jarama.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28058','iglesia','Iglesia Parroquial de San Esteban Protomártir','Templo barroco erigido sobre una fábrica medieval anterior (siglos XVI-XVII); conserva en su altar mayor un monumental retablo barroco atribuido al taller de José de Churriguera y lienzos de la escuela madrileña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28058','ermita','Ermita de Belén o del Santo Cristo','Edificio barroco del siglo XVII construido en ladrillo visto y cajones de mampostería (aparejo toledano), profundamente reformado tras los daños sufridos en el siglo XX.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28059','iglesia','Iglesia de San Pedro Apóstol','Monumental templo del siglo XVI de tres naves separadas por grandes columnas toscanas de piedra caliza; destaca su retablo mayor barroco del siglo XVIII de tres cuerpos profusamente decorado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28059','ermita','Ermita de la Soledad','Pequeña construcción civilreligiosa barroca del siglo XVII ejecutada en ladrillo visto con planta de cruz latina y cúpula sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28060','monumento','Castillo de Santiago (Torre de Doña Urraca)','Ruinas señoriales de una imponente fortaleza medieval del siglo XII construida por la Orden de Santiago en sillería de piedra caliza y argamasa; conserva una imponente torre del homenaje poligonal de gran valor estratégico sobre el Tajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28060','monumento','Puente de Hierro de Fuentidueña','Espectacular estructura de ingeniería civil de hierro forjado y remachado diseñada en 1871, uno de los primeros puentes de la escuela francesa construidos en la península sobre pilares de sillería de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28060','iglesia','Iglesia Parroquial de San Andrés Apóstol','Templo barroco del siglo XVII construido con aparejo toledano, que destaca por su gran nave basilical y una fachada rematada por un frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28060','monumento','Torre del Reloj','Antigua torre exenta del siglo XVII situada en el centro del casco urbano que ejercía las funciones de torre civil de control y concejo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28061','monumento','Calzada Romana de Galapagar','Fragmentos visibles y consolidados de la antigua calzada militar romana del siglo I d.C. que cruzaba la Sierra de Guadarrama, construida con grandes losas de granito berroqueño de canteras locales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28061','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo del siglo XVI edificado bajo trazas góticas y renacentistas herrerianas con sillería de granito; destaca su gran torre campanario con remate de chapitel y su pila bautismal del siglo XV.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28061','monumento','Puente de Torrelodones / Puente de las Minas','Estructuras civiles de paso construidas en el siglo XVIII bajo el reinado de Carlos III para el nuevo trazado del Camino Real de Castilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28062','monumento','Núcleos de población de Garganta de los Montes','El término municipal incluye los siguientes núcleos de población: El Cuadrón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28062','iglesia','Iglesia de San Pedro Apóstol','Templo del siglo XV-XVI de estilo gótico rural con importantes añadidos barrocos, construido con mampostería de gneis y granito berroqueño, con un coro de madera tallada tradicional en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28062','iglesia','Iglesia de Nuestra Señora del Pilar (El Cuadrón)','Pequeño templo rural del siglo XVII construido siguiendo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28063','iglesia','Iglesia de San Benito Abad','Templo mudéjar con reformas barrocas (siglos XIV-XVII); conserva arcos apuntados de ladrillo visto en su interior y muros perimetrales de mampostería de piedra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28063','ermita','Ermita de la Trinidad','Pequeño oratorio rural del siglo XVII exento, ejemplo de la arquitectura religiosa integrada en los pastos ganaderos de la cuenca alta del río Lozoya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28064','iglesia','Iglesia Parroquial de Santo Tomás Apóstol','Templo del siglo XVII reconstruido tras la Guerra Civil respetando los volúmenes originales; presenta muros de mampostería de pizarra local, contrafuertes y una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28065','catedral','Catedral de la Magdalena','Espléndido templo renacentista y barroco proyectado por Alonso de Covarrubias y construido por Juan Gómez de Mora (siglos XVI-XVII); catalogado como BIC, posee una imponente torre mudéjar de ladrillo y un impresionante retablo barroco churrigueresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28065','monumento','Hospital de San José (Hospitalillo)','Edificio civil asistencial fundado en 1515, construido siguiendo el estilo mudéjar con un bellísimo patio interior porticado de madera y una capilla con retablos barrocos.','inventario_monumentos_pdf');
