INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28065','monumento','Colegio de Escuelas Pías','Edificio barroco del siglo XVIII de grandes proporciones construido en ladrillo con una sobria fachada conventual castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28066','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo de origen mudéjar (siglo XIV) profundamente reformado en los siglos XVI y XVII; destaca por su torre de ladrillo visto, sus muros de aparejo toledano y un altar mayor renacentista con pinturas de la escuela madrileña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28066','iglesia','Convento de la Encarnación (Clarisas)','Complejo de clausura monástica del siglo XVII edificado en ladrillo y mampostería, ejemplo del barroco monacal más sobrio de la comarca suroeste.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28067','iglesia','Iglesia de San Juan Bautista','Monumental templo edificado en el siglo XVI con sillería de granito berroqueño; destaca su espectacular portada de estilo gótico plateresco y su alta torre campanario de tres cuerpos rematada en capiteles de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28067','ermita','Ermita de la Virgen del Espinar','Pequeño templo barroco del siglo XVII de planta de cajón situado en los accesos al valle que actualmente domina el embalse de Pedrezuela.','inventario_monumentos_pdf');
