INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28068','iglesia','Iglesia de San Miguel Arcángel (Antigua)','Ruinas de la iglesia medieval del siglo XV de la que se conserva la torre fortificada de piedra y los arcos de sillería, hoy integrada en espacios culturales públicos.','inventario_monumentos_pdf');
