INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28070','monumento','Fragua de Horcajo / Potro de Herrar de Aoslos','Conjunto etnológico de arquitectura civil tradicional serrana del siglo XIX, construido con grandes bloques rústicos de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28071','iglesia','Iglesia Parroquial de San Nicolás de Bari','Templo de estilo gótico rural (siglo XV); conserva muros perimetrales de pizarra, una capilla gótica con bóveda de crucería y una valiosa talla gótica de la Virgen.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28071','ermita','Ermita de Nuestra Señora de los Dolores','Pequeña construcción del siglo XVII de estilo barroco serrano integrada en las praderas de la Sierra del Rincón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28072','iglesia','Iglesia Parroquial de Nuestra Señora del Rosario','Edificio del siglo XVI con importantes modificaciones barrocas y contemporáneas; levantado en granito, conserva una espadaña y su pila bautismal renacentista.','inventario_monumentos_pdf');
