INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28074','iglesia','Iglesia del Salvador','Monumental templo barroco del siglo XVII que alberga un colosal retablo mayor considerado una de las obras cumbre de José de','inventario_monumentos_pdf');
