INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28901','iglesia','Iglesia de San Pedro Apóstol (Lozoyuela)','Templo del siglo XVI edificado en mampostería de piedra rústica de la sierra con una imponente espadaña lateral.','inventario_monumentos_pdf');
