INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28083','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI con proporciones catedralicias, diseñado por Rodrigo Gil de Hontañón; destaca su impresionante cabecera barroca de sillería caliza y su imponente nave central con bóvedas de crucería.','inventario_monumentos_pdf');
