INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28096','ermita','Ermita de San Juan Bautista / Ermita de la Veracruz','Conjunto de templos barrocos del siglo XVII construidos en aparejo toledano (ladrillo y cajones de mampostería caliza) integrados en el entramado urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28097','iglesia','Iglesia de San Mamés','Joya del románico-mudéjar (siglo XII-XIII); conserva un ábside semicircular único levantado en mampostería y ladrillo visto, y en su interior alberga pinturas murales medievales fragmentarias de gran interés arqueológico. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28101','iglesia','Iglesia de San Pedro Apóstol','Templo del siglo XVI edificado con fábrica de mampostería caliza, con reformas barrocas y una austera espadaña de dos cuerpos que domina el entramado de viviendas encaladas del casco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28102','iglesia','Iglesia de San Juan Evangelista','Templo barroco del siglo XVII de planta de cruz latina, construido con muros de mampostería de piedra caliza de la Alcarria, con una torre campanario exenta de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28102','ermita','Ermita de la Virgen de la Bella','Pequeña construcción devocional barroca situada en un paraje natural sobre el valle del Tajuña, de planta de cajón castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28104','iglesia','Iglesia de San Vicente Mártir','Templo del siglo XVI con importantes transformaciones barrocas en el XVII; levantado en ladrillo visto y mampostería, conserva muros perimetrales de aparejo toledano y una sobria torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28104','palacio','Palacio de Medinaceli','Ruinas consolidadas y portalón de la antigua casa señorial de los duques de Medinaceli, testimonio de la jurisdicción nobiliaria de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28106','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo barroco del siglo XVI profundamente reformado en el siglo XVIII por el arquitecto real Bartolomé Elorriaga; de líneas sobrias, destaca por su gran nave y su fábrica de ladrillo y granito caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28106','ermita','Ermita de Nuestra Señora de la Soledad','Edificio barroco del siglo XVII de planta rectangular, ejemplo de la arquitectura popular religiosa del sur de Madrid.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28109','iglesia','Monasterio de Santa María de la Valdediós','Impresionante complejo monástico fundado en el siglo XII (1150) por Alfonso VII; sus ruinas consolidadas muestran la evolución desde el románico cisterciense y el gótico hasta el claustro renacentista de trazas herrerianas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28109','monumento','Pinturas Rupestres de la Enfermería','Yacimiento arqueológico prehistórico de arte esquemático en los abrigos graníticos del entorno, datado en la Edad del Bronce.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28110','monumento','Risco de las Cuevas','Espectacular monumento arqueológico nacional; conjunto de unas 50 cuevas excavadas en un acantilado de yeso caliza por comunidades del Neolítico y la Edad del Bronce,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28110','iglesia','Iglesia de Santa María del Castillo','Templo barroco edificado sobre los cimientos de una antigua fortaleza bajomedieval, de muros recios de mampostería toledana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28111','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo del siglo XVI de tres naves separadas por columnas toscanas de piedra caliza; conserva una espectacular galería porticada exterior de estilo renacentista mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28111','monumento','La Picota de Pezuela','Monumento civil de cantería del siglo XVI; columna barroca de piedra caliza con ganchos de hierro en su capitel que atestigua el rango de villa judicial autónoma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28113','monumento','Torre de Éboli (Castillo de Pinto)','Espectacular torre del homenaje bajomedieval del siglo XIV, construida con recia mampostería de granito y esquinas de sillería caliza; fortaleza defensiva famosa por haber sido el lugar de encierro de la Princesa de Éboli por orden de Felipe II.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28113','iglesia','Iglesia Parroquial de Santo Domingo de Silos','Templo del siglo XVI de grandes proporciones con portadas renacentistas platerescas y un interior de tres naves con bóvedas de crucería estrellada góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28113','ermita','Ermita de San Antón','Pequeño humilladero del siglo XVII de ladrillo visto y planta de cajón típicamente castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28115','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo de origen renacentista (siglo XVI) con severas reconstrucciones barrocas y contemporáneas tras sufrir destrucciones bélicas; conserva una sobria torre campanario de ladrillo y piedra berroqueña caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28116','iglesia','Iglesia de San Salvador','Templo renacentista del siglo XVI proyectado bajo la influencia de los talleres reales alcalaínos; destaca por su fábrica de sillería de piedra caliza de la Alcarria, sus tres naves de gran altura y una sobria portada neoclásica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28117','iglesia','Iglesia de Santo Domingo de Silos','Templo originalmente románico-mudéjar (siglo XIII) con un pórtico norte medieval porticado intacto de gran valor; las excavaciones arqueológicas en su interior descubrieron un taller medieval de fundición de campanas único en la península ibérica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28118','iglesia','Iglesia Parroquial de la Purísima Concepción','Templo barroco rural del siglo XVII edificado íntegramente con mampostería basta de pizarra local y piedras calizas de río, con un interior sobrio de nave única y un retablo de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28902','monumento','Núcleos de población de Puentes Viejas','El término municipal incluye los siguientes núcleos de población: Mangirón, Cinco Villas, Paredes de Buitrago y Serrada de la Fuente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28902','monumento','Torre de Mirabel (Mangirón)','Ruinas consolidadas de una torre vigía y fortificación medieval de planta cuadrada, levantada en mampostería de piedra rústica caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28902','monumento','Frente del Agua (Paredes de Buitrago)','Impresionante conjunto de patrimonio histórico-militar fortificado que incluye búnkeres, nidos de ametralladoras y trincheras de hormigón y mampostería intactos de la contienda de 1936.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28902','iglesia','Iglesia de San Roque (Cinco Villas)','Templo rural del siglo XVI edificado en piedra berroqueña de líneas castellanas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28122','iglesia','Iglesia de San Pedro Apóstol','Edificio mudéjar del siglo XV con reformas renacentistas, levantado con la técnica de cajones de mampostería e hileras de ladrillo visto, con un artesonado de madera tallada de gran valor en la cabecera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28123','palacio','Ruinas del Palacio de Rivas / Real Cortijo de San Isidro','Vestigios y estructuras agrícolas preindustriales del siglo XVIII ligadas a las antiguas fundaciones e infraestructuras reales de la cuenca del Jarama.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28124','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo barroco del siglo XVII de mampostería rústica de pizarra, reconstruido en su interior con elementos contemporáneos respetando la tipología exterior serrana y su espadaña de piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28125','iglesia','Iglesia de la Asunción de Nuestra Señora','Impresionante templo-fortaleza de estilo gótico tardío del siglo XV, edificado íntegramente con sillería de granito berroqueño; destaca su aspecto exterior militar con matacanes y contrafuertes, y en su interior alberga un magnífico retablo mayor hispanoflamenco y unas exclusivas pinturas medievales de dragones en las bóvedas de crucería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28125','ermita','Ermita de la Virgen de la Navahonda','Templo barroco del siglo XVII exento, de planta de cajón castellana situado en un valle de gran valor paisajístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28126','iglesia','Iglesia Parroquial de Santiago Apóstol','Edificio barroco rural del siglo XVII levantado con aparejo rústico de piedra caliza y pizarra, con una espadaña de dos vanos y un interior muy austero adaptado al clima de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28127','iglesia','Iglesia de San Miguel Arcángel','Templo parroquial de origen renacentista (siglo XVI) edificado con muros de ladrillo y granito berroqueña caliza, reconstruido de manera fiel tras sufrir graves destrucciones en los frentes defensivos de la contienda civil española.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28128','iglesia','Iglesia de San Juan Bautista','Templo del siglo XVI de estilo renacentista rural de la sierra oeste; construido con grandes sillares de granito berroqueño, posee una nave única con techumbre de madera tallada y espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28128','monumento','Navarredonda y San Mamés 7 nov 2018 — Durante la Guerra Civil, sufrió importantísimos daños, por lo que tuvo que ser prá','Navarredonda y San Mamés 7 nov 2018 — Durante la Guerra Civil, sufrió importantísimos daños, por lo que tuvo que ser prácticamente reedificada, siendo reinaugurada en e...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28129','iglesia','Iglesia Parroquial de los Santos Niños Justo y Pastor','Templo de origen renacentista (siglo XVI) construido con cajones de mampostería y ladrillo visto; conserva un esbelto pórtico de sillería de granito y su torre campanario barroca original.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28129','monumento','Acueducto de la Retuerta','Impresionante infraestructura hidráulica de ingeniería decimonónica (1854) perteneciente al Canal de Isabel II, edificada en sillería de granito y caliza con grandes arcos de medio punto sobre el río Guadalix.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28130','monumento','Plaza de España y Fachada del Real Sitio','Conjunto arquitectónico civil neoclásico del siglo XVIII proyectado como Real Fábrica de Paños por orden de Fernando VI;','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28130','monumento','Ayuntamiento (Antigua Real Fábrica)','Edificio institucional integrado en los restos consolidados del complejo fabril borbónico, exponente del patrimonio industrial temprano en España.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28132','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo renacentista del siglo XVI modificado en el XVII; de una sola nave con muros de mampostería toledana y contrafuertes de sillería de piedra caliza, destaca por su amplio presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28133','monumento','Castillo de la Coracera','Espectacular fortaleza bajomedieval del siglo XV mandada construir por Álvaro de Luna; edificada íntegramente en sillería de granito berroqueña, destaca su imponente Torre del Homenaje cilíndrica y su patio de armas amurallado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28133','iglesia','Iglesia Parroquial de San Martín Obispo','Monumental templo de traza renacentista y herreriana del siglo XVI proyectado por Pedro de Tolosa; presenta una gran','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28133','ermita','Ermita del Santísimo Cristo del Humilladero','Edificio barroco del siglo XVII situado en los accesos al casco urbano, con una planta de cruz latina construida en sillería y ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28134','iglesia','Iglesia Parroquial de San Sebastián Mártir','Templo barroco construido entre los siglos XVI y XVII sobre trazas mudéjares; destaca su cabecera poligonal y una sobria portada de granito caliza, reconstruida en su interior tras los daños de contiendas históricas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28135','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo del siglo XVI de estilo renacentista rural herreriano, levantado en sillería de granito de la sierra oeste; posee muros limpios y una espadaña defensiva de dos cuerpos bien conservada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28136','monumento','Castillo de Torremocha','Ruinas consolidadas de la fortaleza residencial de los arzobispos de Toledo (siglos XIII-XIV); conserva tramos de sus murallas de mampostería caliza, cubos defensivos cilíndricos y sirvió históricamente como cárcel de estado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28136','iglesia','Iglesia de San Torcuato','Templo mudéjar y renacentista del siglo XVI levantado sobre el emplazamiento de una antigua iglesia bajomedieval, con un magnífico ábside y arquerías de ladrillo toledano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28137','iglesia','Iglesia de San Pedro Apóstol','Monumental templo del siglo XVI que domina el valle del Henares desde un cerro; de estilo renacentista plateresco con trazas herrerianas, presenta muros de piedra caliza de la Alcarria y bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28137','ermita','Ermita de la Virgen de la Soledad','Pequeña construcción barroca del siglo XVII exenta, de planta de cajón castellana y líneas sobrias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28138','iglesia','Iglesia Parroquial de San Andrés Apóstol','Sencillo templo de arquitectura barroca popular serrana (siglo XVII) edificado con piedras rústicas de pizarra local, con un interior sobrio de una nave y espadaña de un cuerpo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28140','iglesia','Iglesia Parroquial de San Nicolás de Bari','Templo de origen barroco (siglo XVIII) construido en ladrillo visto y cajones de mampostería castellana, profundamente restaurado en su estructura contemporánea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28141','palacio','Palacio de Baíllo','Edificio civil residencial de arquitectura barroca y clasicista del siglo XVII, edificado en ladrillo visto con portadas de piedra de sillería y blasones nobiliarios en la fachada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28141','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo de traza castellana del siglo XVIII con muros de aparejo toledano y tejado tradicional a dos aguas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28143','ermita','Ermita de Nuestra Señora de la Soledad','Pequeño templo de arquitectura barroca rural de montaña (siglo XVII), edificado en mampostería basta de granito y pizarra para dar refugio espiritual en el histórico paso del puerto de Somosierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28144','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo del siglo XVI con ampliaciones barrocas del XVIII, edificado íntegramente con grandes sillares de granito berroqueño; destaca su esbelta torre campanario y una pila bautismal renacentista decorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28146','iglesia','Iglesia de los Santos Niños Justo y Pastor','Gran templo barroco del siglo XVII de planta de cruz latina, construido en aparejo toledano de ladrillo y piedra caliza, con una cúpula sobre pechinas y bóvedas decoradas con yeserías.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28146','ermita','Ermita de los Santos Niños (Gorgonilla)','Santuario rural edificado en el siglo XVIII sobre un abrigo rocoso caliza, sitio de devoción ancestral de la comarca de Las Vegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28147','monumento','Yacimiento de la Titulcia Romana (Mi累積)','Enclave arqueológico clave donde se han documentado restos de la antigua ciudad y nudo de comunicaciones carpetano y romano, con hallazgos de gran valor como la "Pátera de Titulcia".','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28147','iglesia','Iglesia Parroquial de Santa María Magdalena','Templo del siglo XVI edificado con fábrica de ladrillo y mampostería, que conserva muros perimetrales originales y capillas barrocas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28148','iglesia','Iglesia de San Juan Evangelista','Templo barroco del siglo XVI y XVII de tres naves separadas por columnas,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28148','monumento','Casa Grande','Antiguo complejo agrícola y residencial del siglo XVI fundado por la Compañía de Jesús, que conserva sus bodegas abovedadas de ladrillo y portaladas de piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28149','iglesia','Iglesia Parroquial de San Cristóbal','Templo barroco del siglo XVII construido siguiendo los cánones de la arquitectura castellana de ladrillo y cajones de mampostería, con un interior sobrio de una sola nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28150','monumento','Castillo de Puñonrostro','Fortaleza bajomedieval del siglo XV erigida por los señores de Arias Dávila; conserva una imponente torre del homenaje rectangular de mampostería de piedra caliza con esquinas de sillería y restos del recinto amurallado perimetral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28150','iglesia','Iglesia de San Esteban Protomártir','Templo renacentista del siglo XVI de grandes dimensiones, construido con muros de cantería caliza y una gran torre campanario barroca de ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28152','monumento','Atalaya de Torrelodones','Torre vigía de planta circular erigida en el siglo X durante el califato andalusí; levantada en mampostería de granito berroqueño, formaba parte del sistema fortificado de la Marca Media del Tajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28152','palacio','Palacio de Canto del Pico','Edificio civil residencial de principios del siglo XX (1920) de estilo ecléctico e historicista, construido incorporando elementos arquitectónicos góticos y renacentistas procedentes de monumentos nacionales destruídos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28154','iglesia','Iglesia de la Asunción de Nuestra Señora','Espléndido templo del siglo XVI de estilo renacentista mudéjar; destaca por su magnífica galería porticada exterior apoyada sobre columnas jónicas de piedra caliza y sus techumbres de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28154','ermita','Ermita de la Soledad','Pequeño templo barroco del siglo XVII con una portada de sillería rematada por un frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28903','monumento','Estructuras del Canal de Isabel II','Pequeñas construcciones hidráulicas y respiraderos de piedra de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28155','iglesia','Iglesia de San Juan Bautista','Templo barroco proyectado en el siglo XVII bajo influencia herreriana; posee muros recios de mampostería de piedra caliza de la Alcarria y una torre campanario rematada con un capitel castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28156','palacio','Palacio de los Marqueses de Campoflorido','Edificio civil palaciego del siglo XVII de estilo barroco clasicista; presenta una fachada de ladrillo con portalada de sillería caliza decorada con escudos heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28156','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de tres naves, edificado con aparejo toledano de ladrillo y piedra, conectado históricamente al complejo del palacio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28157','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo del siglo XV-XVI de estilo gótico rural con reformas renacentistas, levantado en mampostería de piedra caliza; conserva un ábside poligonal y bóvedas de crucería en su cabecera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28157','monumento','Casa del Cura','Edificio civil residencial renacentista del siglo XVI que muestra una bella fachada con ventanas de piedra caliza labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28158','monumento','Potro de Herrar y Canteras Históricas (Patrimonio Etnológico)','Conjunto de estructuras de piedra de granito tradicionales del siglo XIX que documentan las actividades ganaderas y de los picapedreros serranos tradicionales de la zona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28159','monumento','Puente Mocho','Impresionante puente medieval (siglos XIII-XIV) construido con sillería y mampostería de granito berroqueño sobre el río Cofio; cuenta con cinco ojos con arcos de medio punto y tajamares triangulares bien conservados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28159','iglesia','Iglesia de San Lorenzo Mártir','Templo renacentista del siglo XVI edificado con grandes bloques de granito de líneas sobrias castellanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28161','monumento','Plaza de la Constitución','Espectacular plaza porticada castellana del siglo XVII; de planta rectangular, presenta edificios de tres plantas con balconadas de madera y el','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28161','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Monumental templo barroco del siglo XVIII; catalogado como BIC, posee una gran nave central con bóvedas de cañón y capillas laterales que custodian lienzos originales de Francisco de Goya y Claudio Coello.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28161','iglesia','Convento de la Encarnación (Clarisas)','Complejo de clausura monástica fundado en el siglo XVII por el Duque de Lerma, de estilo barroco madrileño sobrio, construido en ladrillo visto y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28161','monumento','Fuente de la Villa','Obra de arquitectura civil hidráulica barroca de 1605, esculpida en piedra caliza con escudos reales, concebida para el abastecimiento público y abrevadero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28162','iglesia','Iglesia de la Inmaculada Concepción (Valdeolmos)','Templo mudéjar del siglo XV edificado en ladrillo y cajones de mampostería (aparejo toledano); conserva una magnífica torre campanario mudéjar con vanos de medio punto y arquerías ciegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28162','iglesia','Iglesia de San Cristóbal (Alalpardo)','Edificio renacentista del siglo XVI edificado con muros de piedra y ladrillo, con una robusta espadaña de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28163','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI levantado en aparejo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28164','monumento','Yacimiento Romano de la Cabecera','Restos arqueológicos excavados de una gran villa romana de explotación agrícola y residencial (siglos II-IV d.C.), donde se documentaron restos de mosaicos y termas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28164','iglesia','Iglesia de la Natividad de Nuestra Señora','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra, con una esbelta torre campanario de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28165','iglesia','Iglesia de San Martín Obispo','Joya del románicomudéjar madrileño (siglo XIII); catalogada como BIC, conserva un espectacular ábside poligonal de ladrillo visto con tres pisos de arquerías ciegas y dobladas y, en su interior, unos frescos medievales fragmentarios de gran interés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28166','iglesia','Iglesia Parroquial de Santo Tomás Apóstol','Templo de origen renacentista (siglo XVI) de líneas rurales castellanas, edificado con muros de mampostería caliza y ladrillo, con una pequeña espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28167','iglesia','Iglesia Parroquial de San Sebastián','Templo de origen barroco (siglo XVII) construido con aparejo de ladrillo visto y mampostería toledana, reconstruido en gran parte de su nave en el siglo XX respetando sus proporciones históricas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28168','monumento','Núcleos de población de El Vellón','El término municipal incluye los siguientes núcleos de población: El Espartal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28168','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo del siglo XVI de estilo renacentista rural herreriano, levantado en sillería de piedra caliza local; posee una robusta torre campanario de tres cuerpos y un pórtico exterior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28168','monumento','Atalaya de El Espartal','Ruinas consolidadas de una torre vigía de origen andalusí (siglo X) de planta circular, integrada en la red militar califal del Jarama.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28169','monumento','Atalaya de Venturada','Espectacular torre vigía de origen andalusí del siglo X; de planta circular y construida en mampostería de gneis y granito berroqueño, corona un cerro estratégico dominando los accesos a la sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28169','iglesia','Iglesia de Santiago Apóstol','Templo románico de transición (siglo XII-XIII) edificado en piedra berroqueña rústica, que conserva una portada románica de arcos de medio punto con arquivoltas lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28171','iglesia','Iglesia de Santiago Apóstol','Monumental templofortaleza del gótico tardío y renacimiento (siglo XVI), edificado íntegramente con grandes sillares de granito berroqueño; catalogado como BIC, posee una imponente torre defensiva de 32 metros y un interior cubierto con bóvedas de crucería estrellada y pinturas murales mudéjares singulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28171','ermita','Ermita de Nuestra Señora de la Poveda','Gran santuario barroco del siglo XVII situado en un paraje natural a orillas del río Alberche, de planta de cajón castellana con ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28170','iglesia','Iglesia Parroquial de San Nicolás de Bari','Templo barroco de gran envergadura iniciado en el siglo XVI con muros de mampostería de piedra caliza de las canteras locales y contrafuertes de sillería berroqueña, con una torre campanario herreriana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28172','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra caliza, edificado en aparejo toledano, con capillas barrocas decoradas con yeserías en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28173','iglesia','Iglesia de los Santos Justo y Pastor','Templo del siglo XVI y XVII de arquitectura castellana sobria, levantado con muros de ladrillo visto y mampostería de piedra caliza de la cuenca del Tajo, con una pequeña espadaña lateral.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28174','iglesia','Iglesia Parroquial de Santa María de la Asunción','Templo renacentista del siglo XVI edificado en granito berroqueño caliza; las excavaciones arqueológicas en su entorno han descubierto restos de necrópolis paleocristianas y cimientos romanos identificados históricamente con la ceca de Mantuani.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28175','iglesia','Iglesia Parroquial de San Miguel Arcángel','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica de ladrillo y mampostería rústica de piedra, con una sencilla torre campanario de ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28176','monumento','Conjunto Urbano de Regiones Devastadas','Trazado urbano, plazas porticadas e Iglesia de Santiago Apóstol proyectados en la década de 1940 siguiendo un estilo neoclásico y herreriano simétrico para sustituir el pueblo totalmente destruído en la Batalla de Brunete.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28178','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo reconstruido en el siglo XX respetando los volúmenes de la antigua fábrica barroca rural castellana, edificado con aparejo de ladrillo y piedra rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28177','iglesia','Iglesia Parroquial de San Lucas','Edificio de ladrillo visto y piedra berroqueña caliza, construido dentro del plan de reconstrucción monumental unificada de Regiones Devastadas tras la Guerra Civil española.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28179','iglesia','Iglesia Parroquial de Nuestra Señora de la Antigua','Templo renacentista del siglo XVI edificado con fábrica de mampostería caliza de la Alcarria; conserva una cabecera poligonal y una esbelta torre campanario de sillería caliza bien conservada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28180','monumento','Castillo de Villarejo de Salvanés (Torre del Homenaje)','Espectacular e inusual torre del homenaje bajomedieval (siglos XIII-XIV) perteneciente a la Encomienda Mayor de la Orden de Santiago; de planta cuadrada con ocho cubos semicilíndricos adosados a sus muros de sillería caliza, constituye un hito militar único en la península ibérica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28180','iglesia','Iglesia Parroquial de San Andrés Apóstol','Templo monumental del siglo XIV fortificado, con aspecto de bastión militar conectado históricamente a las defensas del castillo; posee una cabecera poligonal de gran altura con ventanas saeteras y contrafuertes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28180','iglesia','Santuario de Nuestra Señora de la Victoria (Convento de Franciscanos)','Complejo barroco del siglo XVI fundado por Juan de Austria para conmemorar la victoria en la Batalla de Lepanto; destaca su iglesia y claustro de ladrillo y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28181','monumento','Castillo de Villaviciosa de Odón','Impresionante fortaleza del siglo XV reconstruida en el siglo XVI por el célebre arquitecto Juan de Herrera por orden de los condes de Chinchón; de planta cuadrada con tres torres circulares y una gran torre del homenaje poligonal, destaca por su fábrica de granito y sillería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28181','palacio','Palacio de Manuel de Godoy','Edificio civil residencial barroco de finales del siglo XVIII diseñado por los talleres','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28182','ermita','Arco de la Ermita (Arquitectura Mudéjar)','Ruinas consolidadas de un antiguo arco apuntado de ladrillo visto perteneciente a una edificación mudéjar bajomedieval (siglo XIV) integrada en el entramado urbano serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28182','iglesia','Iglesia de la Inmaculada Concepción','Templo rural barroco construido con aparejo rústico de mampostería de piedra rústica caliza y pizarra local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28183','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI edificado en el puro estilo renacentista herreriano con grandes bloques de granito berroqueño caliza; de líneas sobrias y proporciones geométricas limpias, fue construida por canteros vinculados a las obras de El Escorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28183','monumento','Calzada y Conducciones Históricas de Piedra','Conjunto de patrimonio civil y caminares de piedra de sillería del siglo XVI que comunicaban los diferentes núcleos serranos con las fincas reales del Monasterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90074','iglesia','Iglesia de Nuestra Señora de la Asunción','Monumental templo declarado BIC que combina una cabecera del gótico tardío con un impresionante cuerpo barroco; destaca su altísima torre de ladrillo visto y piedra caliza, y un magnífico retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90074','palacio','Palacio de los Condes de Adanero','Edificio civil residencial del siglo XVII de estilo barroco castellano, con una fachada severa de ladrillo, amplios balcones de hierro forjado y portalón con el escudo de armas señorial tallado en piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90074','ermita','Ermita de Jesús Nazareno','Pequeño humilladero barroco del siglo XVII de planta de cajón con fábrica mixta de ladrillo y mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90075','iglesia','Iglesia Parroquial de San Juan Evangelista','Templo del siglo XVI edificado con fábrica modesta de mampostería y refuerzos de sillería de granito en las esquinas, con una espadaña tradicional de dos vanos y un interior muy sobrio de nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90076','iglesia','Antiguo Convento de las Monjas Dominicas (El Monasterio)','Ruinas consolidadas y estancias conservadas de un complejo conventual de la Orden de Predicadores fundado en el siglo XV; destaca su claustro tardogótico con arquerías de granito y el refectorio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90076','iglesia','Iglesia Parroquial de Santa Cruz','Templo de estilo gótico flamenco y renacentista (siglo XVI), construido íntegramente con grandes bloques de granito berroqueño, con un magnífico artesonado mudéjar en su cabecera poligonal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90077','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo de origen mudéjar (siglo XIII) profundamente reformado en los siglos XVI y XVII; conserva muros con hileras de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90078','iglesia','Iglesia de San Juan Bautista','Sencillo templo de arquitectura renacentista rural (siglo XVI), levantado en recia mampostería de granito berroqueño de las dehesas del Valle de Amblés, con una espadaña defensiva de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51008','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del siglo XV de estilo gótico tardío construido en sillería de granito, que destaca por sus recios contrafuertes exteriores y una techumbre interior de madera de pino serrano tallada de gran valor etnológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51008','ermita','Ermita de la Virgen de las Angustias','Pequeña edificación religiosa exenta del siglo XVIII con un sobrio porche porticado apoyado sobre columnas de piedra berroqueña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51001','monumento','Castillo de Don Álvaro de Luna (Castillo de la Triste Condesa)','Espectacular fortaleza bajomedieval del siglo XV erigida por los Condes de Oropesa; palacio fortificado de planta cuadrada construido en cantería de granito,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51001','palacio','Palacio del Infante Don Luis de Borbón (Palacio de la Mosquera)','Majestuoso palacio neoclásico del siglo XVIII (1780) diseñado por Ventura Rodríguez; presenta una imponente fachada neoclásica simétrica y dependencias señoriales que albergaron una corte ilustrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51001','iglesia','Santuario de San Pedro de Alcántara','Complejo conventual fortificado del siglo XVIII edificado en un paraje natural; alberga la Capilla Real diseñada por Ventura Rodríguez, una joya barroca clasicista de mármoles y jaspes polícromos con cúpula linterna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51001','iglesia','Iglesia de Nuestra Señora de la Asunción','Monumental templo del gótico tardío (siglo XIV) levantado en sillería de granito, con una esbelta torre campanario poligonal de tres cuerpos que domina el casco histórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51001','monumento','Puente Aquelcabos','Hermoso puente medieval del siglo XIV que cruza el río Arenal, construido en piedra de granito con perfil lomo de asno y un gran ojo central apuntado flanqueado por tajamares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90079','iglesia','Iglesia Parroquial de San Cristóbal','Templo rural barroco (siglo XVII) edificado con muros bastos de mampostería berroqueña caliza, con una espadaña de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51002','monumento','Castillo de Arévalo','Impresionante fortaleza señorial del siglo XV construida en ladrillo y sillería, donde pasó su infancia Isabel la Católica; destaca su colosal Torre del Homenaje circular de estilo mudéjar, adaptada posteriormente como silo y parque de artillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51002','iglesia','Iglesia de Santa María la Mayor','Joya cumbre del románico-mudéjar (siglo XII-XIII); conserva un espectacular ábside semicircular de ladrillo visto con pisos de arquerías ciegas entrelazadas y, en su interior, un coro y pinturas murales góticas excepcionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51002','iglesia','Iglesia de San Martín (Las Torres Gemelas)','Templo mudéjar del siglo XII clasificado como BIC; destaca por sus dos esbeltas torres de ladrillo visto con vanos apuntados y un pórtico norte medieval porticado intacto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51002','iglesia','Iglesia de San Miguel','Templo mudéjar que alberga una magnífica cabecera de ladrillo y un interior de gran anchura basilical con un espectacular retablo renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51002','monumento','Plaza de la Villa','Espectacular plaza medieval porticada castellana; conjunto urbano rodeado de casas con entramado de madera, fachadas mudéjares de ladrillo visto y soportales con columnas de piedra caliza y madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51002','monumento','Puente de Medina y Puente de los Tapia','Monumentales puentes mudéjares medievales (siglo XIV) construidos combinando arcos de ladrillo visto y pilares de sillería sobre los ríos Adaja y Arevalillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90080','iglesia','Iglesia de San Juan Bautista','Templo del siglo XVI de estilo renacentista castellano rural, levantado en aparejo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90081','iglesia','Iglesia de San Bartolomé','Pequeño templo de arquitectura barroca popular (siglo XVII) edificado con piedras de granito rústicas de la sierra de Gredos, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51003','monumento','Castillo de Valdecorneja','Impresionante fortaleza bajomedieval del siglo XIV erigida por la Casa de Alba sobre un castro vetton y romano; de planta cuadrada con torres circulares en los ángulos, conserva su patio de armas, murallas defensivas y una gran Torre del Homenaje de cantería de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51003','monumento','Puente Viejo (Puente Románico)','Espectacular estructura de ingeniería civil construida en el siglo XII sobre el río Tormes utilizando pilares romanos; cuenta con ocho arcos asimétricos de medio punto hechos de sillería de granito y tajamares angulares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51003','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo monumental del gótico tardío (siglos XIV-XV) con proporciones catedralicias; destaca su cabecera poligonal con contrafuertes y un interior cubierto con bóvedas de crucería y un colosal retablo barroco churrigueresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('51003','monumento','Murallas de El Barco y Puerta del Campillo','Restos del recinto amurallado medieval del siglo XII que rodeaba la villa, conservando cubos defensivos y la puerta monumental de acceso de piedra berroqueña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90082','iglesia','Iglesia de Nuestra Señora de la Asunción','Monumental templo edificado en el siglo XVI con grandes sillares de granito berroqueño; de estilo renacentista con trazas herrerianas puras, presenta muros limpios y una gran torre campanario con remate de bolas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90082','monumento','Torre de los Gaznatas','Ruinas consolidadas de una torre defensiva bajomedieval de mampostería rústica situada en los alrededores, testimonio de la jurisdicción señorial de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90083','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo mudéjar del siglo XIII levantado con la técnica de cajones de mampostería e hileras de ladrillo visto; conserva un ábside de ladrillo con arquerías ciegas y una espadaña tradicional modificada en época barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90084','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo monumental del siglo XVI edificado con fábrica de sillería de granito; destaca su espectacular retablo mayor barroco polácromo y un artesonado mudéjar policromado en la nave de gran riqueza formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90084','ermita','Ermita del Santo Cristo de la Agonía','Gran capilla barroca exenta del siglo XVII construida en piedra caliza y granito con un porche sobre columnas toscanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05025','monumento','Núcleos de población de Becedillas','El término municipal incluye los siguientes núcleos de población: Casillas de Chicapierna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05025','iglesia','Iglesia de la Virgen de la Asunción','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica rústica de mampostería de granito berroqueño y una espadaña tradicional de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05026','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo del siglo XVI de tres naves construido en ladrillo visto y aparejo toledano, que destaca por su gran nave central con arcos de medio punto y un presbiterio barroco bien conservado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05029','iglesia','Iglesia de San Martín Obispo','Joya del románicomudéjar (siglo XIII); conserva un espectacular ábside poligonal de ladrillo visto con tres pisos de arquerías ciegas dobladas de gran pureza geométrica y muros de mampostería caliza castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05030','iglesia','Iglesia Parroquial de San Juan Bautista','Templo barroco rural del siglo XVII edificado íntegramente con mampostería basta de piedra berroqueña local, con un interior sobrio de nave única y una espadaña defensiva tradicional de un cuerpo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05033','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI construido en ladrillo visto y cajones de mampostería caliza castellana, con una torre campanario barroca de líneas sencillas y un coro alto de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05034','iglesia','Iglesia de San Martín','Templo de origen mudéjar (siglo XIII) modificado en el XVI con trazas renacentistas; conserva arcos apuntados de ladrillo visto en su interior y muros perimetrales de aparejo de mampostería tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05035','iglesia','Iglesia de San Boal','Templo barroco del siglo XVII de planta de cruz latina, construido en ladrillo visto y piedra caliza con una hermosa cúpula sobre pechinas decorada con yeserías ornamentales en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05037','monumento','Núcleos de población de Bohoyo','El término municipal incluye los siguientes núcleos de población: Los Guijuelos, Navamediana y Navamojada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05037','iglesia','Iglesia de la Asunción de Nuestra Señora','Monumental templo del siglo XVI de estilo gótico tardío y renacentista, levantado íntegramente con sillería de granito serrano; posee muros limpios y una gran torre campanario con remates herrerianos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05037','ermita','Ermita del Santo Ángel de la Guarda','Pequeño santuario barroco rural del siglo XVII exento, edificado en piedra de cantería con tejado a cuatro aguas en los accesos al valle.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05038','iglesia','Iglesia Colegiata de San Martín','Espléndido templo del siglo XV de estilo gótico puro con proporciones catedralicias; catalogado como BIC, destaca por su colosal espacio de nave única de gran anchura, sus bóvedas de crucería y una imponente torre campanario fortificada de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05038','palacio','Castillo-Palacio de los Obispos de Ávila','Fortaleza bajomedieval del siglo XIV que servía de residencia','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05038','monumento','Recinto Amurallado de Bonilla','Restos de la muralla bajomedieval del siglo XIV que rodeaba la villa fortificada, destacando la Puerta de la Villa (o de San Martín) de sillería berroqueña intacta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05039','monumento','Núcleos de población de Brabos','El término municipal incluye los siguientes núcleos de población: Blacha.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05039','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado con fábrica rústica de mampostería de granito de líneas castellanas tradicionales, con espadaña y un pórtico castellano tradicional de entrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05040','monumento','Núcleos de población de Bularros','El término municipal incluye los siguientes núcleos de población: Muñochas y Villaverde.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05040','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Edificio barroco rural del siglo XVII levantado con aparejo rústico de piedra caliza y granito, con una espadaña de dos vanos y un interior muy austero adaptado a las llanuras de la Moraña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05041','iglesia','Abadía de Santa María de Burgohondo','Impresionante complejo monástico agustiniano fundado en el siglo XII; catalogado como BIC, conserva una monumental iglesia románica cisterciense de tres naves construida en piedra','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05041','ermita','Ermita de San Roque','Pequeño templo de arquitectura barroca popular (siglo XVII) edificado con piedras rústicas de granito y pizarra local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05042','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo rural barroco (siglo XVII) edificado con muros de ladrillo visto y mampostería toledana en la comarca de la Moraña, con una torre campanario castellana y un interior de una sola nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05043','iglesia','Iglesia Parroquial de San Juan Evangelista','Templo de origen mudéjar (siglo XIII) reformado en los siglos XVI y XVII; conserva muros mixtos de ladrillo y mampostería, y un coro alto de madera tallada tradicional en el interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05044','iglesia','Iglesia Parroquial de San Juan Bautista','Templo monumental del siglo XVI edificado con grandes sillares de granito berroqueño; destaca por su esbelta torre campanario de tres cuerpos y un presbiterio cubierto con un artesonado mudéjar bien conservado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05044','ermita','Ermita de la Virgen de la Salud','Pequeña construcción barroca del siglo XVII exenta, de planta de cajón castellana con porche porticado sobre columnas de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40037','iglesia','Iglesia de la Asunción de Nuestra Señora','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras rústicas calizas y adobe, con una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05046','iglesia','Iglesia Parroquial de San Cristóbal','Templo del siglo XVI con importantes modificaciones barrocas; construido en ladrillo visto y cajones de mampostería, destaca por su gran nave y su artesonado de madera de tradición castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05047','monumento','Castro Celta de El Freíllo (El Raso)','Espectacular yacimiento arqueológico prerromano (siglos V-I a.C.) de la cultura de los vettones; conserva los cimientos de piedra de viviendas celtas, calles pavimentadas, murallas defensivas y una necrópolis intacta de gran valor nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05047','iglesia','Santuario de Nuestra Señora de Chilla','Monumental complejo religioso barroco del siglo XVIII erigido en un paraje natural de la Sierra de Gredos; destaca por su iglesia central, sus ermitas exentas y una rica colección de exvotos y azulejería polícroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05047','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del gótico tardío (siglo XV) construido íntegramente con grandes sillares de granito; posee una robusta torre campanario y un espectacular retablo mayor renacentista plateresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05047','monumento','Casas de la Judería (Arquitectura Civil)','Conjunto de viviendas tradicionales del siglo XV y XVI con fachadas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05048','iglesia','Iglesia de San Pedro Apóstol','Joya del románicomudéjar abulense (siglo XIII); conserva un espectacular ábside semicircular de ladrillo visto con pisos de arquerías ciegas superpuestas y dobles, de gran valor formal para la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05049','monumento','Castro de Las Cogotas','Impresionante yacimiento arqueológico y Monumento Nacional; castro vettón de la Edad del Hierro (siglos V-III a.C.) labrado sobre un cerro de granito viva, conservando recintos amurallados, zonas de talleres artesanales y cementerios de cistas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05049','iglesia','Iglesia de la Santa Cruz','Templo renacentista del siglo XVI construido con cantería de granito berroqueño berroqueña; conserva una imponente torre campanario de tres cuerpos y una portada de estilo plateresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05049','ermita','Ermita de la Virgen del Berrocal','Edificio religioso barroco del siglo XVII de planta de cajón castellana situado en las afueras, rodeado de canteras de piedra históricas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05052','iglesia','Iglesia de Santiago Apóstol','Templo herreriano del siglo XVI levantado en sillería de granito serrano; de líneas sobrias y proporciones geométricas limpias, posee muros desnudos y espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05053','iglesia','Iglesia de San Juan Evangelista','Pequeño templo de arquitectura barroca popular (siglo XVII) edificado con aparejo rústico de piedra caliza y pizarra, con una espadaña de dos cuerpos y un interior desprovisto de grandes lujos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05054','iglesia','Iglesia Parroquial de San Juan Bautista','Templo barroco del siglo XVII construido en mampostería de granito y sillería caliza; destaca por su gran nave central con bóvedas de cañón y su torre campanario exenta de líneas herrerianas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05054','monumento','Puente de la Margara','Antigua infraestructura de paso de un solo ojo apuntado sobre la garganta de Casavieja, ejemplo de la arquitectura civil de caminos serranos medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05055','iglesia','Iglesia de San Antonio de Padua','Sencillo templo de origen barroco (siglo XVIII) construido en mampostería rústica de piedra berroqueña, con un interior sobrio','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05056','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo mudéjar del siglo XIII levantado con la técnica de cajones de mampostería e hileras de ladrillo visto; conserva una cabecera poligonal mudéjar bien conservada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05057','iglesia','Iglesia de Santiago Apóstol','Monumental templo clasicista y herreriano del siglo XVI diseñado por Francisco de Mora y Herrera el Mozo; conocida como la "Catedral de la Sierra", destaca por sus proporciones catedralicias, sus colosales pilares toscanos de granito y sus bóvedas limpias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05057','ermita','Ermita de la Virgen de Valsordo','Gran santuario barroco del siglo XVII de planta de cruz latina, que alberga pinturas murales barrocas monumentales y yeserías en el interior de su cúpula sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05057','iglesia','Ruinas de la Iglesia de la Vieja (San Cristóbal)','Vestigios consolidados de una iglesia mudéjar del siglo XIV de la que se conserva la cabecera, la torre campanario de sillería caliza y los arranques de los arcos apuntados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05057','monumento','Puente de la Pasada / Puente de la Sordo','Conjunto de puentes barrocos e ilustrados del siglo XVIII erigidos en','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05058','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo del siglo XVI edificado con grandes bloques de granito berroqueño serrano; posee una espadaña defensiva maciza y un coro interior de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05058','monumento','El Rollo Jurisdiccional de Cepeda','Monumento civil de piedra del siglo XV; columna cilíndrica de granito berroqueño que atestigua el rango de villa judicial autónoma y el poder del señorío feudal de la época.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05067','monumento','Castro de la Mesa de Miranda','Impresionante Monumento Nacional y yacimiento arqueológico celta del siglo V a.C.; colosal oppidum vettón que conserva tres recintos amurallados defensivos de granito, una espectacular muralla con torres cuadrangulares y un campo de piedras hincadas para frenar las cargas de caballería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05060','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de la Moraña, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05061','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado con sillería de arenisca y granito extraído de las canteras locales; conserva una fachada austera y una espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05061','monumento','Canteras Históricas de "Piedra Caleña"','Espacio de patrimonio industrial y arquitectónico etnológico del que se extrajo el característico material arenisco polícromo utilizado para edificar la Catedral de Ávila y San Vicente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05062','iglesia','Iglesia de los Dolores','Joya del románico-mudéjar (siglo XIII); conserva un espectacular ábside de ladrillo visto con tres pisos de arquerías ciegas y dobladas de gran pureza formal e hileras de aparejo toledano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05063','iglesia','Iglesia Parroquial de San Martín Obispo','Templo del siglo XVI de estilo renacentista rural castellano, construido con fábrica de ladrillo y mampostería rústica de piedra berroqueña caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05064','iglesia','Iglesia Parroquial de San Martín','Edificio barroco del siglo XVII de traza castellana tradicional, construido con ladrillo visto y cajones de mampostería caliza, con una torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05065','monumento','Núcleos de población de Crespos','El término municipal incluye los siguientes núcleos de población: Chaherrero y Pascualcobo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05065','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI con importantes reformas barrocas en el XVII; de una sola nave con muros de aparejo toledano de ladrillo y piedra, destaca por su amplio presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05066','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo del siglo XV con ampliaciones barrocas del XVIII, edificado íntegramente con grandes sillares de granito berroqueño; destaca su esbelta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05066','ermita','Ermita de la Virgen de las Angustias','Pequeño santuario mudéjar del siglo XIV construido con hileras de ladrillo y mampostería berroqueña caliza en los accesos al puerto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05903','monumento','Núcleos de población de Diego del Carpio','El término municipal incluye los siguientes núcleos de población: Diego Álvaro y Carpio Media.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05903','iglesia','Iglesia Parroquial de San Pedro Apóstol (Diego Álvaro)','Templo gótico tardío del siglo XVI edificado con grandes sillares de granito; destaca su magnífica portada con arcos conopiales y su coro de madera tallada tradicional en el interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05903','ermita','Ermita de la Virgen de la Colorada','Pequeño templo barroco del siglo XVII de planta de cajón situado en las lomas agrícolas del municipio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05072','iglesia','Iglesia Parroquial de San Andrés Apóstol','Templo que conserva un magnífico ábside mudéjar del siglo XIII levantado con hiladas de ladrillo visto y arquerías ciegas dobladas; su interior alberga un coro alto de madera tallada de tradición castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05073','monumento','Núcleos de población de Flores de Ávila','El término municipal incluye los siguientes núcleos de población: El Ajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05073','iglesia','Iglesia Parroquial de Santa María del Castillo','Monumental templo del siglo XVI que combina elementos góticos y mudéjares; custodia un espectacular retablo mayor plateresco con tablas pintadas por el Maestro de Flores, una de las joyas pictóricas de la provincia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05073','iglesia','Iglesia de San Juan Bautista (El Ajo)','Templo de origen mudéjar (siglo XIII) modificado en el siglo XVI, edificado con aparejo mixto de ladrillo visto y mampostería caliza castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05074','iglesia','Iglesia de San Cipriano','Una de las iglesias de estilo mudéjar más grandes y monumentales de toda la cuenca del Duero (siglos XII-XVI); declarada BIC, destaca por su colosal cabecera de ladrillo con arquerías ciegas superpuestas y sus impresionantes cubiertas interiores con artesonados mudéjares polícromos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05074','iglesia','Iglesia del Convento de la Madre de Dios (Carmelitas Descalzos)','Templo barroco del siglo XVII levantado sobre la casa natal de San Juan de la Cruz; presenta una sobria fachada conventual de ladrillo castellano y piedra, y una cripta con los restos de los padres del santo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05074','monumento','Monumento a San Juan de la Cruz','Escultura civil monumental en bronce erigida en la plaza principal, flanqueada por casonas palaciegas de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05075','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo de origen renacentista (siglo XVI) construido con gruesos muros de mampostería de granito berroqueño, con una espadaña tradicional de dos vanos y un interior muy austero de una sola nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05077','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05078','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo que combina una cabecera gótica tardía con reformas barrocas del siglo XVII; construida con aparejo toledano en la llanura de la Moraña, destaca por su amplio presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05078','palacio','Palacio de los Marqueses de Fuentes de Año','Ruinas consolidadas de una casa palaciega del siglo XVI con blasones nobiliarios esculpidos sobre el portalón de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05079','monumento','Núcleos de población de Gallegos de Altamiros','El término municipal incluye los siguientes núcleos de población: Gallegos y Altamiros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05079','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica rústica de mampostería de granito y una espadaña defensiva de dos cuerpos bien conservada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05080','monumento','Núcleos de población de Gallegos de Sobrinos','El término municipal incluye los siguientes núcleos de población: Blascojimeno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05080','iglesia','Iglesia Parroquial de San Cristóbal','Templo barroco rural (siglo XVII) edificado con muros bastos de mampostería berroqueña, con un interior desprovisto de grandes adornos y un pequeño campanil tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05081','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del siglo XVI edificado con grandes bloques de granito berroqueño de la sierra de Gredos; posee muros desnudos y espadaña de dos cuerpos adaptada al clima de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05082','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo barroco del siglo XVII de planta de cruz latina, construido en mampostería de granito y sillería caliza; posee una torre campanario exenta de líneas sencillas de tradición serrana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05086','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del siglo XVI edificado con fábrica de ladrillo visto y cajones de mampostería caliza, con una torre campanario barroca de líneas sencillas y un coro alto de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05087','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo del siglo XVI edificado en estilo renacentista rural; destaca por sus muros de mampostería caliza y ladrillo, y por albergar la pila bautismal donde la tradición vincula a los antepasados de Santa Teresa de Jesús.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05087','monumento','Palomar de Doña Ahumada (Patrimonio Etnológico)','Espectacular palomar medieval de planta cuadrada edificado en adobe, ladrillo visto y tapial; perteneció a la familia de Santa Teresa de Jesús y es un modelo único de arquitectura preindustrial conservada en la península.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05087','ermita','Ermita de Nuestra Señora de las Nieves','Pequeño templo barroco del siglo XVII exento, edificado en ladrillo y mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05088','monumento','Núcleos de población de Grandes y San Martín','El término municipal incluye los siguientes núcleos de población: Grandes y San Martín de las Chinietas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05088','iglesia','Iglesia Parroquial de San Martín','Sencillo templo de arquitectura barroca popular (siglo XVII) edificado con piedras rústicas de granito local, con una espadaña tradicional de un solo vano para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05089','monumento','Casco Histórico de Guisando','Todo el conjunto urbano funciona como monumento; viviendas tradicionales de los siglos XVI al XVIII con fachadas entramadas de madera, solanas salientes de pino, tejados volados y cimientos de granito berroqueño adaptados a la ladera de la sierra de Gredos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05089','iglesia','Iglesia Parroquial de la Purísima Concepción','Templo del siglo XVI edificado íntegramente con grandes sillares de granito; posee una robusta espadaña defensiva y un coro interior de madera tallada tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05090','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado con fábrica mixta de ladrillo y mampostería toledana en las llanuras de la Moraña, con una torre campanario castellana y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05092','iglesia','Iglesia Parroquial de San Martín','Edificio barroco del siglo XVII de traza castellana tradicional, construido con ladrillo visto y cajones de mampostería caliza, con una torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05093','monumento','Núcleos de población de Herradón de Pinares','El término municipal incluye los siguientes núcleos de población: La Cañada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05093','iglesia','Iglesia Parroquial de Santa María la Mayor','Monumental templo del siglo XVI de estilo gótico tardío y renacentista, levantado íntegramente con sillería de granito serrano; posee muros limpios y una gran torre campanario con remates herrerianos de bolas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05093','monumento','Puente de la Cañada','Antigua infraestructura de paso de piedra construida en el siglo XVIII para asegurar las comunicaciones ganaderas y mesteñas de la zona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05094','iglesia','Iglesia Parroquial de San Juan Evangelista','Templo del siglo XVI edificado con fábrica rústica de mampostería de granito, con espadaña y un pórtico castellano tradicional de entrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05095','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería de granito berroqueño, con una fachada rematada por un gran frontón clásico y una pila bautismal renacentista decorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05099','iglesia','Iglesia de San Julián y Santa Basilisa','Joya del románico-mudéjar (siglo XIII); conserva un espectacular ábside de ladrillo visto con tres pisos de arquerías ciegas de gran pureza geométrica, integrado en un edificio ampliado en época renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05101','iglesia','Iglesia Parroquial de San Juan Bautista','Templo monumental del siglo XVI edificado con grandes sillares','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05101','ermita','Ermita del Santo Cristo','Pequeña construcción barroca del siglo XVII exenta, de planta de cajón castellana situada en los accesos al pinar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05103','monumento','Núcleos de población de Hoyorredondo','El término municipal incluye los siguientes núcleos de población: El Castillo, Las Casas, Las Navas y San Bartolomé.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05103','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del siglo XVI de estilo renacentista rural, construido con fábrica mixta de ladrillo y mampostería rústica de piedra berroqueña, con espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05106','iglesia','Iglesia Parroquial de San Pedro','Pequeño templo de arquitectura barroca popular (siglo XVII) construido con piedras rústicas de granito serrano, con un interior sobrio de una nave y espadaña tradicional de un cuerpo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05104','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo rural barroco (siglo XVII) edificado con muros bastos de mampostería berroqueña, con una espadaña de dos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05105','iglesia','Santuario de Nuestra Señora del Espino','Monumental templo del gótico tardío (siglo XV) levantado en sillería de granito berroqueño; posee un retablo mayor tardogótico policromado de gran valor artístico y una imagen románica de la Virgen.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05105','monumento','El Crucero de Hoyos','Espectacular monumento gótico del siglo XV situado a las afueras; cruz de granito berroqueño tallada con filigranas flamígeras que servía de hito caminero e hito jurisdiccional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05107','monumento','Núcleos de población de Hurtumpascual','El término municipal incluye los siguientes núcleos de población: Viñegra de la Sierra y Gamonal de la Sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05107','iglesia','Iglesia Parroquial de San Blas','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica de ladrillo y mampostería rústica de piedra berroqueña caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05108','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica rústica de mampostería de granito, con una espadaña tradicional de dos vanos y un interior muy sobrio con techumbre de madera de pino serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05109','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo que conserva una cabecera mudéjar del siglo XIII levantada en ladrillo visto con arquerías ciegas dobladas; destaca su arco triunfal apuntado en el interior y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05110','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado en sillería de granito berroqueño; de estilo renacentista rural con trazas herrerianas, destaca por su amplio presbiterio y un retablo mayor con tablas pictóricas de la época.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05110','monumento','Puente de la Abantera','Estructura civil histórica de piedra de un solo ojo apuntado sobre la garganta de Lanzahíta, clave en las rutas ganaderas tradicionales del Valle del Tiétar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05113','monumento','Núcleos de población de Los Llanos de Tormes','El término municipal incluye los siguientes núcleos de población: Hermosillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05113','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo del siglo XVI edificado con grandes bloques de granito berroqueño; posee una espadaña de dos cuerpos y muros limpios adaptados al clima de la sierra de Gredos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05114','monumento','Recinto Amurallado de Madrigal','Espectacular muralla medieval de estilo mudéjar (siglos XIII-XIV) única en España por su trazado ovalado perfecto; conserva cerca de 2,3 kilómetros de perímetro perimetral, unos 23 torreones o cubos de ladrillo y mampostería caliza, y cuatro puertas monumentales intactas (Arévalo, Cantalapiedra, Medina y Peñaranda).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05114','iglesia','Monasterio de Nuestra Señora de Gracia (Palacio Real de Juan II)','Antiguo palacio real mudéjar del siglo XIV donde nació la reina Isabel la Católica, reconvertido posteriormente en convento; destaca por sus claustros de ladrillo visto con arquerías apuntadas, salones con techumbres artesonadas mudéjares y la alcoba real fortificada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05114','iglesia','Iglesia de San Nicolás de Bari','Joya cumbre del románico-mudéjar (siglo XIII); declarada Monumento Nacional, posee la torre campanario mudéjar más alta de la provincia (65 metros) decorada con arquerías ciegas y, en su interior, una impresionante techumbre mudéjar calada polícroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05114','iglesia','Iglesia de Santa María del Castillo','Templo mudéjar sobreelevado en una loma que formaba parte del sistema defensivo; conserva un espectacular ábside semicircular de ladrillo visto con tres pisos de arquerías ciegas y dobladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05114','monumento','Ruinas del Real Hospital de la Purísima Concepción','Vestigios consolidados de un hospital civil gótico-mudéjar del siglo XV fundado por la corte castellana, de gran valor institucional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05115','monumento','Núcleos de población de Maello','El término municipal incluye los siguientes núcleos de población: Fontiveros, Dehesa de Pancorbo y Prado Encinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05115','iglesia','Iglesia Parroquial de San Juan Bautista','Monumental templo del siglo XVI edificado con fábrica mixta de ladrillo visto y mampostería toledana en las llanuras castellanas; posee una robusta torre campanario de líneas sencillas y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05116','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, con un presbiterio cubierto con un artesonado mudéjar bien conservado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05117','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI con importantes reformas barrocas en el XVII; de una sola nave con muros de aparejo toledano de ladrillo visto y piedra, destaca por su amplio presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05122','monumento','Núcleos de población de Martínez','El término municipal incluye los siguientes núcleos de población: Montalvo y El Parque.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05122','iglesia','Iglesia Parroquial de San Quirico y Santa Julita','Templo barroco rural (siglo XVII) edificado con muros bastos de mampostería berroqueña caliza, con una espadaña de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05123','iglesia','Iglesia Parroquial de San Juan Bautista','Edificio barroco rural del siglo XVII levantado con aparejo rústico de piedra caliza y granito, con una espadaña de dos vanos y un interior muy austero adaptado al clima.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05125','monumento','Calzada Histórica del Puerto de Menga','Fragmentos visibles y consolidados de una antigua vía y calzada romana reformada en la Edad Media para las rutas mesteñas de trashumancia, construida con grandes losas rústicas de granito berroqueño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05125','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo del siglo XVI edificado con grandes bloques de granito berroqueño, con una espadaña defensiva maciza.','inventario_monumentos_pdf');
