INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05127','iglesia','Iglesia Parroquial de San Juan Bautista','Templo barroco del siglo XVII de planta de cruz latina, construido en mampostería de granito y sillería caliza; destaca por su gran nave central con bóvedas de cañón y su torre campanario exenta de líneas herrerianas.','inventario_monumentos_pdf');
