INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05128','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo monumental del siglo XVI edificado con grandes sillares de granito berroqueño; destaca por su esbelta torre campanario de tres cuerpos.','inventario_monumentos_pdf');
