INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05179','iglesia','Iglesia Parroquial de San Juan Evangelista','Templo barroco del siglo XVII de traza castellana tradicional, construido con ladrillo visto y cajones de mampostería caliza, con una torre campanario de líneas sencillas.','inventario_monumentos_pdf');
