INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05186','palacio','Palacio de los Duques de Alba','Obra cumbre de la arquitectura palaciega neoclásica del siglo XVIII (1755-1766) diseñada por el arquitecto francés Jaime Marquet; majestuoso complejo residencial edificado con sillería de granito berroqueño, famoso por albergar a la corte ilustrada de la Duquesa de Alba y por los frescos y jardines franceses que inspiraron a Goya.','inventario_monumentos_pdf');
