INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05902','monumento','Núcleos de población de Santa María del Cubillo','El término municipal incluye los siguientes núcleos de población: San Esteban de los Patos y Blascoeles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05902','iglesia','Iglesia Parroquial de San Pedro Apóstol (Blascoeles)','Templo renacentista del siglo XVI de tres naves separadas por columnas, edificado con aparejo toledano, con capillas barrocas decoradas con yeserías en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05227','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo de origen renacentista (siglo XVI) construido con gruesos muros de mampostería de granito berroqueño, con una espadaña tradicional de dos vanos y un interior muy sobrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05228','monumento','Núcleos de población de Santiago del Collado','El término municipal incluye los siguientes núcleos de población: El Collado, Nogal y Zarzal.','inventario_monumentos_pdf');
