INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05904','monumento','Núcleos de población de Santiago del Tormes','El término municipal incluye los siguientes núcleos de población: La Aliseda de Tormes, Lastra del Cano y Cardedal.','inventario_monumentos_pdf');
