INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05229','iglesia','Iglesia Parroquial de Santo Domingo de Silos','Edificio barroco del siglo XVII de traza castellana tradicional, construido con ladrillo visto y cajones de mampostería caliza, con una torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05230','iglesia','Iglesia Parroquial de Santo Tomé','Templo mudéjar del siglo XIII levantado con la técnica de cajones de mampostería e hileras de ladrillo visto; conserva una cabecera mudéjar bien conservada y una cruz procesional medieval de plata.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05232','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de granito y mampostería, con una robusta torre campanario y un interior de una sola nave de líneas castellanas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05233','iglesia','Iglesia Parroquial de San Serapio','Edificio del siglo XVI de estilo renacentista rural serrano, construido con fábrica rústica de mampostería de granito y una espadaña tradicional de dos cuerpos adaptada al clima de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05234','iglesia','Iglesia Parroquial de San Juan Evangelista','Templo barroco rural (siglo XVII) edificado con muros bastos de mampostería berroqueña, con un interior desprovisto de grandes lujos y una espadaña tradicional de un cuerpo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05235','iglesia','Iglesia de San Juan Bautista','Joya del románicomudéjar (siglo XIII); conserva un espectacular ábside poligonal de ladrillo visto con tres pisos de arquerías ciegas y dobladas de gran pureza formal e hileras de aparejo toledano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05236','monumento','Núcleos de población de Solana de Ávila','El término municipal incluye los siguientes núcleos de población: Los Cuartos, Tremedal, La Zarza y Mazalinos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05236','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI de estilo renacentista rural, construido con fábrica mixta de granito y mampostería','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05237','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, con una torre campanario de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05238','monumento','Núcleos de población de Solosancho','El término municipal incluye los siguientes núcleos de población: Villaviciosa, Baterna y Robledillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05238','monumento','Castillo de Villaviciosa','Impresionante fortaleza bajomedieval del siglo XV erigida por los señores de Ávila; de planta cuadrada con torres circulares en los ángulos, conserva su patio de armas, murallas defensivas de sillería de granito y una gran Torre del Homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05238','monumento','Verraco de Villaviciosa','Escultura zoomorfa de piedra monumental esculpida por los vettones en la Edad del Hierro (siglos V-I a.C.); representa un toro de gran tamaño tallado en un solo bloque de granito berroqueño vivo, situado en la plaza del castillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05238','monumento','Castro de la Ulaca','Espectacular yacimiento arqueológico celta prerromano (siglos V-I a.C.) de la cultura de los vettones; conserva un altar de sacrificios tallado en roca, murallas de piedra seca y los cimientos de viviendas de gran valor arqueológico nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05238','iglesia','Iglesia Parroquial de San Vicente','Templo del siglo XVI edificado con grandes bloques de granito berroqueño, conectado históricamente al señorío del castillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05239','iglesia','Iglesia Parroquial de la Purísima Concepción','Templo monumental del siglo XVI edificado con grandes sillares de granito berroqueño; destaca por su esbelta torre campanario de tres cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05245','monumento','Verracos de Tornadizos','Conjunto de esculturas zoomorfas de piedra monumental esculpidas por los vettones en la Edad del Hierro (siglos V-I a.C.) integradas en el entorno rural del municipio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05245','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo del siglo XVI edificado con sillería de granito; de estilo renacentista castellano rural, conserva una fachada austera y espadaña.','inventario_monumentos_pdf');
