INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05252','iglesia','Iglesia Parroquial de San Juan Bautista','Templo barroco rural (siglo XVII) edificado íntegramente con mampostería basta de piedra berroqueña local, con un interior sobrio de nave única y una espadaña defensiva tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05254','iglesia','Iglesia Parroquial de San Isidro','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en','inventario_monumentos_pdf');
