INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05260','monumento','Verracos de Villanueva','Dos esculturas zoomorfas de piedra monumental esculpidas por los vettones en la Edad del Hierro (siglos V-I a.C.); el mayor de ellos está considerado uno de los verracos más grandes de la península ibérica.','inventario_monumentos_pdf');
