INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05263','monumento','Castillo de Villatoro','Ruinas consolidadas de una fortaleza gótico-mudéjar del siglo XV; conserva lienzos de murallas de mampostería de piedra caliza con cubos cilíndricos y elementos defensivos de gran valor histórico.','inventario_monumentos_pdf');
