INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90086','palacio','Palacio de Sotofermoso','Originalmente una fortaleza templaria del siglo XIII, reconvertida en palacio en el siglo XV por los Duques de Alba; destaca su claustro mudéjar de dos plantas con arcos de herradura apuntados y sus jardines renacentistas italianos, escenario de tertulias de la intelectualidad del Siglo de Oro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90086','iglesia','Iglesia Parroquial de Santo Domingo de Guzmán','Templo que combina elementos góticos (siglo XV) y mudéjares, levantado en cantería de granito y sillería caliza, con un ábside poligonal y un retablo renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90086','monumento','Puente Medieval sobre el río Ambroz','Estructura de piedra de sillería de granito con un solo ojo de gran luz, clave en el trazado histórico de la Vía de la Plata.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90087','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XV-XVI edificado en estilo gótico rural mudéjar; destaca por su fábrica mixta de mampostería y ladrillo visto, contrafuertes robustos de sillería y una pila bautismal renacentista decorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90088','iglesia','Iglesia Parroquial de Nuestra Señora de los Ángeles','Monumental templo del siglo XVI clasificado como Bien de Interés Cultural, diseñado por el arquitecto Pedro de Ybarra; levantado íntegramente en sillares de granito, destaca por sus bóvedas de crucería estrellada y su magnífico retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90088','monumento','Casco Urbano de Acebo (Arquitectura Civil)','Conjunto de viviendas tradicionales con entramado de madera, voladizos pronunciados de pino y fachadas de piedra con bellos blasones heráldicos nobiliarios de la hidalguía local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90089','iglesia','Iglesia de San Juan Bautista','Inmueble parroquial modificado en el siglo XVII que utiliza materiales locales como la pizarra rústica y la mampostería encalada, caracterizado por su torre campanario exenta y un interior cubierto por bóvedas de arista barrocas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90090','iglesia','Iglesia Parroquial de Santa Marina','Templo rural ordinario del siglo XVI levantado con sillarejos de granito y mampostería vista que presenta una singular torre campanario exenta construida sobre una estructura pétrea exenta de la nave principal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90091','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de granito, que conserva un espléndido retablo plateresco y un presbiterio cubierto de crucería gótica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90091','monumento','Crucero de Ahigal','Espectacular cruz de término gótica del siglo XV esculpida en piedra de granito vivo con relieves de la Pasión.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90092','iglesia','Iglesia de Santa María Magdalena','Pequeño inmueble parroquial modificado en el siglo XVII que utiliza caliza y mampostería encalada, caracterizado por su espadaña de doble cuerpo y un interior austero compartimentado por arcos fajones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06003','monumento','Puente Romano de Alcántara','Obra maestra universal de la ingeniería clásica construida en el año 104 d.C. por el arquitecto Cayo Julio Lacer íntegramente en sillería granítica almohadillada sin mortero, elevándose imponente sobre el río Tajo con seis arcos de medio punto custodiados por un arco de triunfo central dedicado al emperador Trajano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06003','iglesia','Convento de San Benito','Monasterio matriz de la Orden de Alcántara edificado en el siglo XVI que constituye una de las joyas del renacimiento extremeño, destacando su espectacular claustro gótico-renacentista y la imponente fachada exterior de la galería de Carlos V con tres pisos de arquerías labradas en granito berroqueño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06003','iglesia','Iglesia de Santa María de Almocóvar','Templo del siglo XIII de transición románico-gótica levantado sobre la antigua mezquita mayor que conserva tres portadas tardorrománicas de arcos abocinados y un interior de tres naves con pilares cruciformes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06003','monumento','Recinto Amurallado y Puerta de la Concepción','Sistema defensivo medieval modificado en el siglo XVII con baluartes artilleros de estilo Vauban que rodea el','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90093','palacio','Palacio de los Pizarro-Carvajal','Ruinas señoriales consolidadas de un imponente palacio fortificado','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90093','iglesia','Iglesia Parroquial de Santa Catalina','Templo del siglo XVI edificado con fábrica de granito de líneas castellanoextremeñas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90094','iglesia','Basílica de Santa Lucía del Trampal','Joya prerrománica y visigoda única en la península ibérica (mediados del siglo VII d.C.); se trata del único templo visigodo en pie que conserva su cabecera con tres ábsides rectangulares exentos y una estructura interior de naves separadas por arcos de herradura visigodos de gran pureza formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90094','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo monumental del gótico tardío del siglo XVI levantado en cantería de granito berroqueño, con un coro de madera tallada tradicional en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90095','iglesia','Iglesia Parroquial de San Martín Obispo','Templo del siglo XVI edificado con grandes sillares de granito; de estilo gótico-renacentista herreriano, destaca por su aspecto exterior fortificado con matacanes defensivos y muros desnudos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10212','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo que combina una cabecera del gótico tardío (siglo XV) con un cuerpo renacentista; conserva un original ábside semicircular en forma de torre defensiva cilíndrica y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10212','monumento','Casco de Aldeanueva (Arquitectura de la Vera)','Conjunto monumental de arquitectura popular de los siglos XVI al XVIII; viviendas con fachadas entramadas de madera, solanas voladas de pino serrano y canalizaciones de agua viva en sus calles empedradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90096','monumento','Puente Romano sobre el río Ambroz','Estructura que conserva restos de sillería y pilares de origen romano (siglo I d.C.) y reconstrucciones medievales, clave en las rutas comerciales de la Calzada de la Plata.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90096','iglesia','Iglesia de Nuestra Señora del Olmo y de San Servando','Dos iglesias históricas que correspondían a las antiguas demarcaciones de las diócesis de Plasencia y Coria en el propio casco urbano, de fábrica barroca del siglo XVII.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90097','iglesia','Iglesia de San Blas','Templo rural ordinario del siglo XVI edificado en mampostería encalada que presenta una cabecera cupulada sobre pechinas y una espadaña de ladrillo visto situada a los pies de la nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90098','iglesia','Iglesia Parroquial de Santa Catalina','Joya del mudéjar extremeño-andaluz del siglo XV; declarada BIC, destaca por su colosal ábside poligonal de ladrillo visto profusamente decorado con frisos de arquerías ciegas entrelazadas, rombos y dientes de sierra, y en su interior alberga un impresionante artesonado mudéjar policromado intacto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90098','ermita','Ermita de Nuestra Señora de la Concepción','Pequeño templo barroco del siglo XVII exento, edificado en ladrillo y mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90099','iglesia','Iglesia de Nuestra Señora de la Asunción Templo','Templo renacentista del siglo XVI levantado con sillarejos de granito y mampostería vista que presenta una portada clasicista y un centro de interpretación anejo dedicado al famoso tesoro tartésico de la Aliseda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90100','iglesia','Iglesia Parroquial de San Andrés Apóstol','Monumental templo del siglo XVI de tres naves separadas por columnas toscanas de granito; posee un','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90101','iglesia','Iglesia del Salvador','Edificio del siglo XVI construido con paramentos de mampostería granítica de la zona que destaca por su recia torre campanario de tres cuerpos y un retablo mayor barroco de madera dorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10021','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Impresionante templo tardogótico y renacentista del siglo XV-XVI; declarado BIC, alberga en su presbiterio el colosal Retablo de Luis de Morales "El Divino", compuesto por 20 tablas pintadas y dos esculturas, considerada la obra cumbre indiscutible de este genio de la pintura renacentista española.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10021','iglesia','Convento de San Francisco','Edificio barroco del siglo XVII de la orden franciscana, que conserva su patio interior porticado y una austera fachada conventual de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10021','ermita','Ermita de la Virgen de la Luz','Santuario barroco del siglo XVIII exento, situado en un paraje natural que acoge las romerías históricas de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10022','iglesia','Iglesia de Santiago Apóstol','Templo mudéjar tardío del siglo XVI construido en mampostería de granito y pizarra que alberga un sobrio púlpito de cantería y una espadaña de dos cuerpos rematada por pináculos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10023','iglesia','Iglesia Parroquial de Nuestra Señora de la Consolación','Templo del siglo XVI edificado con fábrica de mampostería y ladrillo visto, con una robusta torre campanario de sillería berroqueña y un retablo barroco en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10024','monumento','Termas Romanas de Baños','Yacimiento arqueológico e hidráulico romano del siglo I d.C.; conserva en el sótano del balneario actual las antiguas piscinas abovedadas romanas de sillería de granito donde manaban las aguas mineromedicinales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10024','iglesia','Iglesia Parroquial de Santa María','Templo del siglo XVI con importantes modificaciones barrocas; construido en sillería de granito, conserva una espadaña y su pila bautismal renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10025','iglesia','Iglesia Parroquial de San Sebastián','Edificación rural ordinaria del siglo XVI ejecutada con muros de mampostería granítica vista y pizarra rústica que alberga una nave única compartimentada por sencillos arcos fajones.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10026','monumento','Castillo de Belvís de Monroy','Espectacular fortaleza palaciega de primer orden iniciada en el siglo XIII con reformas gótico-platerescas del siglo XVI que presenta un imponente perfil almenado con torres cilíndricas angulares y un patio de armas con arquerías renacentistas de cantería granítica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10026','iglesia','Convento de San Francisco de Asís','Cenobio fortificado fundado en el siglo XVI del que subsisten los potentes contrafuertes de su iglesia y un claustro mudéjar de doble piso ejecutado con verdugadas de ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10026','monumento','Rollo-Picota Jurisdiccional','Monumento plateresco exento labrado en granito en el siglo XVI que exhibe un fuste cilíndrico moldurado sobre gradas escalonadas y cuatro cabezas de león talladas en su capitel cónico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10027','iglesia','Iglesia Parroquial de San Pedro Apóstol','Pequeño inmueble del siglo XVI levantado con cajones de mampostería encalada y piedra rústica que presenta una espadaña lateral de dos vanos y un interior austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10028','iglesia','Iglesia de Nuestra Señora de la Asunción','Templo de filiación renacentista castellana construido en el siglo XVI mediante aparejo de mampostería vista con refuerzos de sillería berroqueña en las esquinas y una sobria portada clasicista. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10029','iglesia','Iglesia de de San Juan Bautista','Monumental templo gótico-renacentista del siglo XVI declarado patrimonio protegido por albergar en su presbiterio el suntuoso relicario de San Fulgencio y Santa Florentina, estructurado en tres espaciosas naves cubiertas por complejas bóvedas de crucería de sillería caliza calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10030','monumento','Yacimiento Romano de Augustobriga (Los Mármoles)','Impresionante pórtico de un templo romano del siglo II d.C. trasladado a la orilla del embalse de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10032','iglesia','Iglesia de Santa María de la Asunción','Magna iglesia del siglo XVI construida enteramente en sillería de granito berroqueño bajo las directrices del arquitecto real Pedro de Ybarra, caracterizada por sus monumentales portadas gótico-platerescas y un interior de tres naves de igual altura cubiertas por bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10032','palacio','Castillo-Palacio de la Encomienda','Fortaleza militar de la Orden de Alcántara reedificada en el siglo XIV que fusiona muros de mampostería compacta con una refinada logia renacentista de arquerías de medio punto orientadas al patio de armas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10032','iglesia','Convento de Nuestra Señora de la Luz','Inmueble religioso del siglo XVI que presenta un claustro de líneas herrerianas labrado en cantería de granito y un presbiterio cupulado con pinturas murales populares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10032','monumento','Qué ver en la provincia de Cáceres','8 rutas y 40 lugares 26 jul 2025 — Entre los templos destaca la Catedral de Santa María de la Asunción, de estilo gótico-renacentista, con una impresionante torre ca...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10032','monumento','Pueblos en Cáceres Monumentos y lugares de interés Los visitantes de este municipio podrán alternar paisajes naturales c','Pueblos en Cáceres Monumentos y lugares de interés Los visitantes de este municipio podrán alternar paisajes naturales con muestra de su arquitectura...','inventario_monumentos_pdf');
