INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10117','iglesia','Iglesia Parroquial de Santiago Apóstol','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica rústica de mampostería de granito y una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10118','iglesia','Iglesia Parroquial de Nuestra Señora de la Gracia','Joya renacentista del siglo XVI diseñada íntegramente por Pedro de Ybarra en sillería de granito berroqueño; declarada BIC, destaca por sus impresionantes bóvedas gótico-renacentistas y una portada plateresca de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10119','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo barroco del siglo XVII de planta de cajón castellana, construido en ladrillo visto y mampostería de granito en los límites de la Sierra de San Pedro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10120','monumento','Puente de las Veredas','Impresionante puente medieval (siglos XIII-XIV) construido con sillería y mampostería de granito sobre el río Ibor; cuenta con ojos con arcos de medio punto y tajamares triangulares bien conservados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10120','iglesia','Iglesia Parroquial de San Leandro','Templo renacentista del siglo XVI edificado en piedra berroqueña de líneas extremeñas tradicionales.','inventario_monumentos_pdf');
