INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10122','iglesia','Iglesia Parroquial de San Francisco de Asís','Inmueble parroquial ordinario del siglo XVI edificado con muros de mampostería vista y ladrillo mudéjar que alberga una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10123','monumento','Castillo de Mirabel (Castillo de la Peña del Acero)','Fortaleza bajomedieval del siglo XV erigida por los señores de la villa sobre restos árabes; conserva tramos de sus murallas de sillería de granito, cubos defensivos cilíndricos y una imponente torre del homenaje poligonal de gran valor estratégico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10123','iglesia','Iglesia Parroquial de Santa María de la Consolación','Templo de estilo gótico tardío y renacentista (siglo XVI), levantado íntegramente con sillería de granito, con un artesonado mudéjar policromado en su cabecera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10124','iglesia','Iglesia Parroquial de San Ildefonso','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra, con una esbelta torre campanario de ladrillo en la comarca de Trasierra-Tierras de Granadilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10125','monumento','Castillo de Monroy','Espectacular palacio fortificado señorial edificado en el siglo XIV con masivas reformas renacentistas que destaca por su silueta almenada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10125','iglesia','Iglesia Parroquial de Santa Catalina','Templo del siglo XV construido en mampostería vista que posee una cabecera poligonal protegida por contrafuertes y una portada con decoración polilobulada de tradición mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10126','monumento','Castillo de Montánchez','Imponente fortaleza de primer orden de origen romano y almohade reedificada por la Orden de Santiago en el siglo XIV sobre un escarpado risco de cuarcita que domina toda la llanura extremeña, del cual subsiste su monumental torre del homenaje de sillería berroqueña y un triple circuito de murallas con espectaculares aljibes subterráneos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10126','iglesia','Iglesia Parroquial de San Mateo','Monumental edificio gótico-renacentista del siglo XVI levantado en sillería granítica que cuenta con una majestuosa portada clasicista herreriana y un espacioso interior cubierto por complejas bóvedas estrelladas atribuidas al foco de canteros trujillanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10126','ermita','Ermita de Nuestra Señora de la Consolación','Santuario barroco del siglo XVIII emplazado en un mirador natural de la sierra que cuenta con un camarín cupulado profusamente decorado con molduras de yesería popular polícroma.','inventario_monumentos_pdf');
