INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10133','iglesia','Iglesia Parroquial de Nuestra Señora de la O','Edificio de gran envergadura del siglo XVI construido en mampostería granítica y cantería que destaca por su portada renacentista de líneas clasicistas y una amplia nave única cubierta por bóvedas de arista barrocas.','inventario_monumentos_pdf');
