INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10162','iglesia','Iglesia Parroquial de San Ildefonso','Edificio barroco del siglo XVIII de planta de cruz latina, construido con muros recios de mampostería y una portada austera con frontón neoclásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10163','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo tardogótico y renacentista (siglo XVI), levantado íntegramente con sillería de granito berroqueño, con un magnífico coro alto y bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10163','monumento','Pozos de Nieve de Salvatierra','Estructuras de piedra preindustriales del siglo XVII destinadas al almacenamiento y conservación de hielo para el surtido de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10164','monumento','Casco Histórico de San Martín de Trevejo','Declarado Conjunto Histórico; conserva de forma impecable viviendas de los siglos XV y XVI con fachadas entramadas de madera, solanas salientes de pino, arroyos de agua viva canalizados que cruzan sus calles empedradas y los célebres "boigas" o bodegas excavadas en granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10164','iglesia','Iglesia Parroquial de San Martín de Tours','Templo monumental del siglo XVI que custodia en su interior tres tablas pintadas de incalculable valor artístico firmadas por el pintor renacentista Luis de Morales "El Divino".','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10164','monumento','Torre Campanario de la Plaza','Torre civil exenta de sillería de granito del siglo XVI situada en la plaza mayor junto al palacio de los comendadores de la Orden de San Juan.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10165','iglesia','Iglesia Parroquial de Santa Ana','Inmueble parroquial común del siglo XVI levantado con cajones de mampostería vista y barro que presenta una portada adintelada de granito muy sencilla y una modesta espadaña de dos vanos con tejadillo moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10166','monumento','Yacimiento de la Sierra de Santa Cruz','Enclave arqueológico que conserva cimientos de un oppidum celta vettón y una posterior fortaleza medieval tallada en la roca del cerro.','inventario_monumentos_pdf');
