INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10166','iglesia','Iglesia Parroquial de la Vera Cruz','Templo gótico tardío del siglo XV construido íntegramente con grandes sillares de granito.','inventario_monumentos_pdf');
