INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10167','iglesia','Iglesia Parroquial de Santa María de la Magalena','Templo del siglo XVI con muros de cantería y ladrillo visto, que conserva en su interior un coro alto de madera tallada tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10168','iglesia','Iglesia Parroquial de Santa Marta','Edificación renacentista del siglo XVI construida en mampostería granítica que presenta una sobria portada de líneas clasicistas y una nave única que remata en un presbiterio cupulado sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10170','iglesia','Iglesia Parroquial de Santiago Apóstol','Inmueble de traza renacentista castellana del siglo XVI edificado con muros de mampostería granítica vista que alberga un coro alto de madera labrada y una espadaña lateral de dos cuerpos decrecientes.','inventario_monumentos_pdf');
