INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10171','iglesia','Iglesia Parroquial de San Pedro','Templo gótico del siglo XV construido en sillería de granito berroqueño que cuenta con una cabecera ochavada protegida por contrafuertes exteriores y una portada de líneas tardomedievales muy austeras.','inventario_monumentos_pdf');
