INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10173','iglesia','Iglesia Parroquial de San Juan Bautista','Monumental fábrica gótico-renacentista del siglo XVI calificada como excelencia comarcal destacado que presenta una imponente fachada de cantería granítica y un suntuoso presbiterio cubierto por complejas bóvedas de crucería estrellada labradas en sillería caliza calavera de gran envergadura.','inventario_monumentos_pdf');
