INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10176','iglesia','Iglesia Parroquial de San Ildefonso','Templo renacentista castellano ordinario del siglo XVI ejecutado mediante cajones de mampostería de pizarra local y ladrillo mudéjar que presenta una espadaña lateral de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10177','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Inmueble del siglo XVI construido con paramentos de mampostería granítica de la zona que destaca por su presbiterio cupulado sobre pechinas barrocas y una recia torre campanario adosada a los pies de la nave única. [1]','inventario_monumentos_pdf');
