INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10188','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Edificación renacentista del siglo XVI construida en mampostería granítica que presenta una sobria portada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10185','iglesia','Iglesia Parroquial de Nuestra Señora de los Ángeles','Templo del siglo XVI edificado con fábrica modesta de mampostería de granito y esquinas de sillería berroqueña de las faldas de la Sierra de Gata.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10186','iglesia','Iglesia Parroquial de Santa Catalina','Templo renacentista castellano ordinario del siglo XVI levantado con cajones de mampostería vista y barro que cuenta con una nave de tramos regulares rematada en un presbiterio cupulado y una espadaña de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10190','monumento','Pinturas Rupestres del Castillo de Monfragüe','Espectacular abrigo arqueológico prehistórico con arte rupestre esquemático datado en la Edad del Bronce, pintado sobre los abrigos cuarcíticos del entorno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10190','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo renacentista del siglo XVI edificado en piedra berroqueña de líneas castellano-extremeñas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10189','monumento','Núcleos de población de Torrejoncillo','El término municipal incluye los siguientes núcleos de población: Valdencín.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10189','iglesia','Iglesia Parroquial de San Andrés Apóstol','Monumental edificio gótico-renacentista del siglo XVI construido en sillería berroqueña que exhibe una fachada sobria de líneas clasicistas herrerianas, una potente torre campanario adosada y un presbiterio cubierto por complejas bóvedas estrelladas de gran envergadura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10191','monumento','Torre de Torremenga','Ruinas consolidadas de una imponente torre vigía y defensiva originalmente visigoda (siglo VII) y reformada en la Edad Media por las órdenes militares, levantada en mampostería basta de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10191','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo rural del siglo XVI edificado en granito de líneas castellanas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10192','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Edificación renacentista castellana del siglo XVI ejecutada mediante cajones de mampostería vista y verdugadas de ladrillo mudéjar que presenta una recia torre campanario adosada a los pies de la nave. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10193','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI levantado con sillarejos de granito y mampostería que presenta una interesante portada renacentista de orden plateresco atribuida a la influencia constructiva de la cercana Cáceres.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10194','ermita','Ermita de Nuestra Señora del Salor','Joya del románico-mudéjar (siglo XIII); conserva un espectacular ábside de ladrillo visto con tres pisos de arquerías ciegas de gran pureza formal e hileras de aparejo toledano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10194','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica mixta de ladrillo y mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','monumento','Castillo de Trujillo','Espectacular e imponente fortaleza medieval de origen árabe construida en el siglo XII sobre el alcázar almohade y ampliada en el XIV por los reinos cristianos; corona el cerro de la Cabeza del Zorro y conserva un colosal perímetro amurallado de sillería de granito berroqueño, cubos defensivos cilíndricos, torres cuadradas, dos grandes aljibes árabes subterráneos y una imponente albacara defensiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','monumento','Plaza Mayor de Trujillo','Una de las plazas públicas más espectaculares del mundo; conjunto urbano consolidado entre los siglos XV y XVI, rodeado de palacios señoriales y casas señoriales con soportales de granito, presidido por la colosal escultura ecuestre en bronce de Francisco Pizarro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','iglesia','Iglesia de Santa María la Mayor','Joya del gótico flamígero y renacimiento (siglos XIII-XVI) erigida en sillería de granito; posee dos espectaculares torres (la Torre Julia románica y la torre nueva campanario) y alberga sepulcros monumentales de los linajes de la villa y de los conquistadores americanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','palacio','Palacio de la Conquista (Palacio de los Pizarro)','Obra cumbre del plateresco renacentista civil del siglo XVI; destaca por su espectacular fachada con un balcón de esquina profusamente esculpido con relieves heráldicos y bustos que representan a Francisco Pizarro y su familia noble.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','palacio','Palacio de San Carlos (Duques de San Carlos)','Monumental palacio plateresco del siglo XVI con una grandiosa fachada simétrica que alberga una colosal portada jónica y un claustro interior clásico de dos plantas con arquerías de granito de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10195','iglesia','Iglesia de San Martín de Tours','Monumental templo del siglo XVI que cierra la Plaza Mayor; de planta de cajón con muros de cantería caliza, posee una gran cúpula sobre pechinas y capillas con yeserías ornamentales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10196','iglesia','Iglesia Parroquial de Santa María de la Gracia','Templo del siglo XVI de estilo renacentista rural del Valle del Jerte, edificado con grandes bloques de granito berroqueño de canteras locales, con espadaña de dos cuerpos y un interior de gran sobriedad rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10197','iglesia','Iglesia Parroquial de San Blas','Templo renacentista del siglo XVI de tres naves separadas por columnas, edificado con aparejo de granito en los límites de las llanuras agrícolas del Tajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10198','palacio','Palacio de los Sande','Espléndido edificio civil palaciego de arquitectura renacentista herreriana del siglo XVI; presenta una fachada de ladrillo y sillería caliza con una gran portada simétrica de gran pureza geométrica y un patio interior porticado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10198','iglesia','Iglesia Parroquial de Nuestra Señora de la Bienvenida','Templo barroco del siglo XVII de planta de cruz latina, construido en aparejo de ladrillo visto y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10199','iglesia','Iglesia Parroquial de Santa María Magdalena','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de las llanuras, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10200','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI levantado con la técnica de cajones de mampostería y ladrillo visto, que conserva en su interior un coro alto de madera de pino serrano tallada de gran valor etnológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10201','iglesia','Iglesia Parroquial de San Andrés','Sencillo inmueble parroquial mudéjar modificado en el siglo XVIII mediante el uso de materiales locales como la mampostería encalada y el ladrillo visto, caracterizado por una pequeña espadaña lateral de dos vanos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10202','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo gótico-renacentista del siglo XVI edificado con muros de mampostería granítica de la zona que presenta una interesante portada de orden plateresco atribuida a la influencia constructiva del foco placentino y una nave única que remata en un presbiterio cubierto por bóveda de arista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10203','monumento','Conjunto Dolménico de Valencia de Alcántara','Impresionante conjunto arqueológico compuesto por 41 dólmenes prehistóricos del Neolítico y Calcolítico declarados Bien de Interés Cultural; sepulcros de corredor y cámaras funerarias perfectamente conservados (como el Dolmen de la Tapiada o de las Lanchas) levantados con gigantescos bloques y ortostatos rústicos de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10203','iglesia','Iglesia de Rocamador','Monumental templo gótico del siglo XV declarado Monumento Nacional; levantado íntegramente con sillares de granito, destaca por sus bóvedas de crucería estrellada y por haber sido el escenario de las bodas reales entre la infanta Isabel (hija de los Reyes Católicos) y el rey Manuel I de Portugal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10203','monumento','Barrio Gótico-Judío de Valencia de Alcántara','Espectacular entramado urbano bajomedieval de los','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10203','monumento','Castillo de Valencia de Alcántara','Fortaleza bajomedieval del siglo XIII erigida sobre el alcázar romano y árabe; conserva tramos de sus murallas defensivas de sillería berroqueña, la barbacana y una gran torre del homenaje almenada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10204','monumento','Casco Histórico de Valverde de la Vera','Declarado Conjunto Histórico-Artístico; conserva de forma impecable su urbanismo de encrucijada del siglo XVI, con casas entramadas de madera, solanas voladas de pino y un sistema de escorrentías de agua viva en sus calles empedradas conocidas como "regueras".','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10204','monumento','Castillo de los Condes de Nieva','Ruinas consolidadas de la fortaleza residencial señorial del siglo XIV; conserva muros de mampostería de granito caliza, cubos defensivos cilíndricos y la torre del homenaje, que fue integrada posteriormente como campanario de la iglesia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10204','iglesia','Iglesia Parroquial de Fuentes Claras','Templo monumental del gótico tardío y renacimiento (siglo XVI), levantado con sillería de granito, con un espectacular ábside poligonal con contrafuertes y bóvedas de crucería góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10205','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Monumental obra del siglo XVI diseñada bajo la influencia de Pedro de Ybarra en sillería de granito berroqueño; destaca por sus bóvedas góticorenacentistas y un colosal retablo mayor renacentista plateresco de gran valor formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10206','iglesia','Iglesia Parroquial de los Santos Justo y Pastor','Templo del siglo XVI edificado con fábrica rústica de mampostería de granito berroqueño de la sierra de Gredos, con una espadaña de dos vanos y un interior muy austero de nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10207','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI edificado con fábrica mixta de granito y mampostería, con una robusta torre campanario y restos de elementos góticos en el presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10208','iglesia','Iglesia Parroquial de Santiago Apóstol','Sencillo edificio del siglo XVI levantado con cajones de mampostería encalada y piedra de pizarra rústica que presenta una modesta espadaña de ladrillo visto situada a los pies de la nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10209','iglesia','Iglesia Parroquial de Santo Domingo de Guzmán','Templo del siglo XVI de estilo renacentista castellanoextremeño rural, levantado en aparejo de mampostería y ladrillo visto, con una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10210','monumento','Núcleos de población de Villamiel','El término municipal incluye los siguientes núcleos de población: Trevejo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10210','monumento','Castillo de Trevejo (en la pedanía de Trevejo)','Impresionante fortaleza bajomedieval del siglo XV erigida por la Orden de San Juan sobre restos árabes en la cima de un crestón de granito vivo; sus imponentes ruinas conservan la colosal torre del homenaje fortificada de sillería berroqueña caliza, murallas defensivas con almenas y un cementerio medieval a sus pies con tumbas antropomorfas excavadas en la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10210','iglesia','Iglesia Parroquial de Santa María Magdalena (Villamiel)','Templo del siglo XVI edificado con grandes sillares de granito, conectado históricamente al señorío de la comarca de la Sierra de Gata.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10211','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de tres naves separadas por columnas, edificado con aparejo de mampostería caliza y ladrillo toledano, con una torre campanario de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10212','monumento','Casco Histórico de Villanueva de la Vera','Declarado Conjunto Histórico-Artístico; conserva de forma impecable su trama urbana medieval, destacando su espectacular Plaza Anaya, una plaza porticada castellana rodeada de casas con entramados de madera, solanas de pino serrano y soportales sustentados por columnas rústicas de granito y pies derechos de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10212','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Monumental templo del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de granito berroqueño; destaca por su esbelta torre campanario de tres cuerpos y bóvedas de crucería estrellada góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10214','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Inmueble del siglo XV edificado en estilo mudéjar tardío con muros de mampostería encalada que destaca por su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10213','monumento','Núcleos de población de Villar del Pedroso','El término municipal incluye los siguientes núcleos de población: Navatrasierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10213','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI de estilo renacentista herreriano, edificado en recios sillares de granito de la comarca de la Jara, que','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10215','palacio','Casa de la Mujer de la Gata (Palacio)','Edificio civil residencial renacentista del siglo XVI que muestra una bellísima fachada con ventanas y portaladas de piedra caliza labrada con filigranas platerescas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10215','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del siglo XVI edificado en sillería de granito berroqueño, con espadaña y un pórtico castellanoextremeño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10216','monumento','Conjunto Histórico de Granadilla','Impresionante villa amurallada bajomedieval fundada en el siglo IX por los árabes y desocupada a mediados del siglo XX por el embalse; catalogada como Conjunto Histórico, conserva íntegro su espectacular Recinto Amurallado Almohade circular de mampostería de pizarra, jalonado por adarves transitables, calles empedradas intactas y el Castillo de Granadilla (colosal fortaleza del siglo XV erigida por el Duque de Alba, caracterizada por su inusual planta polilobulada en forma de trébol de sillería granítica caliza única en Europa).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10216','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción (Zarza)','Templo renacentista del siglo XVI edificado con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10217','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI con importantes modificaciones barrocas; construido en mampostería de granito berroqueño, conserva una espadaña y su pila bautismal renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10218','iglesia','Iglesia Parroquial de San Andrés Apóstol','Monumental templo gótico-renacentista del siglo XVI edificado en la raya portuguesa en sillería berroqueña que presenta un espacioso interior de tres naves cubiertas por complejas bóvedas estrelladas de sillería caliza calavera y una imponente torre-fachada defensiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10218','monumento','Castillo de Peñafiel','Ruinas de una fortaleza medieval de origen árabe de la que perviven lienzos dispersos de muralla ejecutados con mampostería rústica y tapial sobre un cerro que domina el paisaje transfronterizo del río Erjas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10219','iglesia','Iglesia Parroquial de San Pablo','Edificación renacentista castellana del siglo XVI ejecutada mediante cajones de mampostería y verdugadas de ladrillo mudéjar que presenta una sobria torre campanario adosada de dos cuerpos decrecientes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10219','monumento','Abrir inventario de la Provincia de Badajoz','Abrir inventario de la Provincia de Badajoz','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10219','monumento','Abrir inventario de la Provincia de Ciudad Real','Abrir inventario de la Provincia de Ciudad Real','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10219','monumento','Comarca de Coria','Comarca de Coria (Cáceres)(y II) 2 oct 2016 — Iglesia Parroquial Nuestra Señora de Asunción. Es una construcción del siglo XVI realizada de mampostería de pizarra y refuerzos d...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10219','monumento','Pueblos en Cáceres El municipio de Torrecillas de la Tiesa','Pueblos en Cáceres El municipio de Torrecillas de la Tiesa se encuentra ubicado en la zona central de la provincia de Cáceres, perteneciente a la com...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10169','monumento','Conjunto Megalítico de Santiago','Red de dólmenes prehistóricos (siglos IV-III a.C.) en perfecto estado de conservación, compuestos por grandes losas de pizarra caliza en corona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10169','monumento','Abrigo Rupestre de El Buraco','Yacimiento arqueológico con arte rupestre esquemático datado en la Edad del Bronce en las formaciones de la Sierra de San Pedro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10169','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo del siglo XVI edificado con grandes bloques de granito berroqueño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90103','monumento','Núcleos de población de Abajas','El término municipal incluye los siguientes núcleos de población: Abajas y las fincas agrícolas de la comarca de La Bureba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90103','iglesia','Iglesia de Santa María','Joya del románico burebano del siglo XII erigida en sillería caliza de tonalidades doradas que destaca por su portada meridional de tres arquivoltas profusamente ornamentadas con capiteles historiados, donde se representan sirenas de doble cola y motivos zoomorfos de gran finura escultórica, rematada exteriormente por una elegante espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90104','iglesia','Iglesia Parroquial de Santa Columba','Templo del siglo XVI edificado en estilo renacentista castellano; presenta una sólida torre campanario de sillería, muros de mampostería caliza y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90104','ermita','Ermita del Santo Cristo de los Remedios','Pequeño humilladero barroco del siglo XVII situado en las lomas que dominan el valle del Duero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90105','monumento','Núcleos de población de Aguas Cándidas','El término municipal incluye los siguientes núcleos de población: Quintanaopio y Río Quintanilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90105','iglesia','Iglesia de San Juan Bautista (Río Quintanilla)','Templo románico del siglo XII que destaca por su ábside y una notable portada decorada con canecillos polímodos que representan animales y figuras humanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90105','iglesia','Iglesia Parroquial de San Martín (Aguas Cándidas)','Edificio de mampostería caliza del siglo XVI con una espadaña tradicional de dos vanos integrada en el paisaje del Valle de Caderechas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90106','monumento','Núcleos de población de Aguilar de Bureba','El término municipal incluye los siguientes núcleos de población: Aguilar de Bureba y sus fincas cerealistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90106','iglesia','Iglesia de San Guillermo','Templo románico de finales del siglo XII que mantiene su fisonomía original en sillería caliza compacta, llamando la atención su majestuoso ábside semicircular decorado con columnas adosadas y capiteles de temática vegetal, complementado por un interior umbrío de nave única con bóveda de cañón apuntada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90107','monumento','Núcleos de población de Albillos','El término municipal incluye los siguientes núcleos de población: Albillos y las fincas agrarias de la cuenca del Arlanzón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90107','monumento','Torre de los de Cartagena','Restos fortificados de una antigua casa-fuerte defensiva bajomedieval del siglo XV erigida en mampostería regular con refuerzos angulares de cantería fina, cuya estructura de planta cuadrangular conserva estrechas saeteras y vanos con arcos escarzanos vinculados a los linajes nobles burgaleses.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90108','monumento','Núcleos de población de Alcocero de Mola','El término municipal incluye los siguientes núcleos de población: Alcocero de Mola y sus caseríos agrarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90108','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo rural modificado sustancialmente en el periodo barroco utilizando aparejo mixto de piedra caliza y sillería tosca en las esquinas, cuya fachada principal se ve coronada por una robusta espadaña de dos ojos con pináculos pétreos en su atrio parroquial arbolado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90109','monumento','Núcleos de población de Alfoz de Bricia','El término municipal incluye los siguientes núcleos de población: Barrio de de Bricia, Bricia, Campino, Cilleruelo de de Bricia, Lomas de de Villamediana, Montejo de de Bricia, Presillas, Valderías, Villanueva de de Carrales y Villamediana de de Lomas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90109','ermita','Ermita Rupestre de San Miguel en Presillas','Extraordinaria joya del eremitismo rupestre altomedieval de los siglos VIII y IX tallada de forma preindustrial de manera directa sobre un descomunal monolito exento de roca arenisca viva, la cual cuenta con dos plantas conectadas por escaleras esculpidas, un altar rupestre, vanos en forma de arco de herradura y una necrópolis de tumbas antropomorfas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90109','iglesia','Iglesia de San Cristóbal en Montejo de de Bricia','Templo de origen románico del siglo XII modificado en las etapas renacentista y barroca empleando piedra caliza calavera bien labrada que conserva ventanas saetadas y una robusta espadaña exenta sobre un relieve paisajístico que domina los páramos norteños.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09907','monumento','Núcleos de población de Alfoz de Quintanadueñas','El término municipal incluye los siguientes núcleos de población: Quintanadueñas, Arroyal, Marmellar de de Abajo, Páramo de de Arroyo y Villanueva de de Río Ubierna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09907','iglesia','Iglesia Parroquial de Nuestra Señora del de Rosario en Quintanadueñas','Templo monumental de los siglos XVI y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90110','monumento','Núcleos de población de Alfoz de Santa Gadea','El término municipal incluye los siguientes núcleos de población: Higón, Quintanilla de Santa Gadea y Santa Gadea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90110','iglesia','Iglesia de San Andrés (Santa Gadea)','Templo del siglo XV-XVI de estilo gótico tardío construido en sillería caliza; presenta recios contrafuertes exteriores y una techumbre de madera de pino serrano tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90111','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Sencillo templo de origen barroco (siglo XVII) edificado con muros bastos de mampostería caliza en el límite con la comunidad riojana, con una espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90112','monumento','Torre de los Guevara','Imponente torre fortificada bajomedieval del siglo XIV; construida con recia mampostería de piedra caliza y esquinas de sillería, presenta saeteras, ventanas ojivales y un carácter netamente defensivo de frontera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90112','iglesia','Iglesia Parroquial de Santa María','Templo gótico del siglo XV que conserva una portada románica de transición y muros de sillería berroqueña caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90113','monumento','Núcleos de población de Anguix','El término municipal incluye los siguientes núcleos de población: Anguix y sus fincas vitivinícolas de la Ribera del Duero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90113','iglesia','Iglesia de la Asunción de Nuestra Señora','Templo de traza renacentista y barroca clasicista del siglo XVIII levantado con una fábrica mixta de mampostería caliza y esquinales de sillería de Hontoria de la Cantera que presenta una monumental fachada geométrica simétrica, coronada por un frontón triangular y flanqueada por una robusta torre de campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09001','monumento','Núcleos de población de Aranda de Duero','El término municipal incluye los siguientes núcleos de población: Aranda de Duero, La Aguilera, Sinovas y Fuentespina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09001','iglesia','Iglesia de Santa María la Real','Obra cumbre e hito absoluto del gótico flamígero y el estilo isabelino de finales del siglo XV que destaca universalmente por su espectacular fachadaretablo meridional, labrada en finísima sillería caliza por Simón de Colonia con una profusión escultórica exenta que cubre las arquerías polilobuladas con relieves de la Pasión, coronada por un suntuoso escudo de los Reyes Católicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09001','iglesia','Iglesia de San Juan','Templo monumental gótico del siglo XIV edificado en cantería bien escuadrada que destaca por haber sido la sede del célebre Concilio de Aranda de 1473, cuya portada de siete arquivoltas apuntadas da paso a un interior basilical umbrío que hoy alberga el Museo Sacro de la Ribera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09001','iglesia','Iglesia de Santa Ana en Sinovas','Joya del románico rural del siglo XII profundamente reformada en el periodo mudéjar que conserva un bellísimo e historiado artesonado mudéjar policromado del siglo XIV, el cual cubre la nave única con una intrincada tracería de lazo de par y nudillo considerada única en la provincia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09001','iglesia','Santuario de la Virgen de las Viñas','Templo barroco del siglo XVII emplazado sobre una colina paisajística que presenta una planta de cruz latina construida con sillería y mampuesto calizo, cuyo altar mayor custodia la venerada imagen patronal rodeada de un suntuoso retablo de madera noble labrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90114','monumento','Núcleos de población de Arandilla','El término municipal incluye los siguientes núcleos de población: Arandilla y sus fincas de cultivo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90114','iglesia','Iglesia Parroquial de San Cornelio y San Cipriano','Templo de origen románico rural modificado en las etapas renacentista y barroca empleando aparejo calizo mampuesto con cadenas de sillería dorada en los esquinales, rematado en su fachada por una robusta espadaña barroca de tres cuerpos que dota de verticalidad al núcleo urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90115','monumento','Núcleos de población de Arauzo de Miel','El término municipal incluye los siguientes núcleos de población: Arauzo de Miel y las fincas agrarias de la Sierra de la Demanda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90115','iglesia','Iglesia de Santa Eulalia','Templo de traza renacentista edificado en el siglo XVI con excelente cantería caliza que presenta una planta de tres naves separadas por pilares cilíndricos, cuyo presbiterio custodia un suntuoso retablo mayor ejecutado por maestros de la escuela castellana y enterramientos nobiliarios blasonados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09021','monumento','Núcleos de población de Arauzo de Salce','El término municipal incluye los siguientes núcleos de población: Arauzo de Salce y sus caseríos ganaderos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09021','iglesia','Iglesia Parroquial de la Asunción','Templo de tradición rural construido en el siglo XVI combinando muros portantes de mampostería caliza con esquinales reforzados de sillería tosca, cuya fachada principal se ve coronada por una robusta espadaña barroca de tres cuerpos en su atrio parroquial arbolado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09022','monumento','Núcleos de población de Arauzo de Torre','El término municipal incluye los siguientes núcleos de población: Arauzo de Torre y sus fincas cerealistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09022','iglesia','Iglesia de San Pedro','Templo románico de finales del siglo XII modificado en el periodo barroco utilizando aparejo mixto','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31029','palacio','Palacio Arzobispal de Arcos','Ruinas y restos consolidados de la residencia palaciega veraniega de los arzobispos de Burgos (siglos XIV-XVI); conserva portalones señoriales de sillería caliza con escudos de armas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31029','iglesia','Iglesia Parroquial de San Miguel','Templo que combina el gótico mudéjar y el renacimiento, con una espectacular torre campanario de ladrillo visto y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('31029','monumento','Puertas de la Muralla (Arco de Abajo)','Restos del recinto amurallado medieval del siglo XIV que protegía la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09024','iglesia','Iglesia Parroquial de Santa María','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09025','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo ecléctico edificado a principios del siglo XX utilizando mampostería caliza y granito, con un interior sobrio de gran anchura basilical.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09026','monumento','Núcleos de población de Arlanzón','El término municipal incluye los siguientes núcleos de población: Agés, Galarde, Santovenia de Oca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09026','iglesia','Iglesia de Santa Eulalia (Agés)','Templo de origen gótico (siglo XV) levantado con cantería caliza; posee una robusta torre campanario y custodia sepulcros medievales vinculados a los peregrinos jacobeos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09026','iglesia','Iglesia Parroquial de San Miguel (Arlanzón)','Templo monumental del siglo XVI edificado con grandes sillares de granito y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09027','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Pequeño templo de arquitectura barroca popular (siglo XVII) edificado con aparejo rústico de piedra caliza, con una espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09029','monumento','Núcleos de población de Atapuerca','El término municipal incluye los siguientes núcleos de población: Olmos de Atapuerca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09029','monumento','Yacimientos de la Sierra de Atapuerca','Aunque es un conjunto de monumentos arqueológicos y paleontológicos naturales (Trinchera del Ferrocarril, Gran Dolina, Sima de los Huesos), constituyen el patrimonio científico más importante de Europa por conservar los restos fósiles del Homo antecessor de más de 800.000 años de antigüedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09029','iglesia','Iglesia Parroquial de San Martín','Templo del siglo XVI edificado con fábrica de piedra de líneas castellanas tradicionales, con una robusta torre campanario que domina la loma histórica del Camino de Santiago.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09030','monumento','Núcleos de población de Los Ausines','El término municipal incluye los siguientes núcleos de población: San Juan, Santiago y San Pedro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09030','iglesia','Iglesia de San Juan (Ausines)','Joya del románico de transición (siglo XII); conserva un espectacular ábside semicircular de sillería caliza y una hermosa portada de arquivoltas abocinadas decorada con motivos vegetales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09030','monumento','Puente Medieval sobre el río Papasol','Estructura civil histórica de piedra de sillería de un solo ojo de gran luz, clave en las comunicaciones medievales de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09032','monumento','Núcleos de población de Avellanosa de Muñó','El término municipal incluye los siguientes núcleos de población: Paúles, Pinedo y Torrecitores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09032','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, con una robusta torre campanario de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09033','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica rústica de mampostería de piedra caliza, con espadaña y un pórtico castellano tradicional de entrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09034','iglesia','Iglesia de San Millán','Monumental obra del siglo XIII al XV de proporciones catedralicias; levantada íntegramente con colosales sillares de piedra caliza, destaca por su portada gótica, sus altísimas columnas barroco-renacentistas y un colosal retablo mayor del siglo XVIII de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09034','iglesia','Iglesia de San Esteban','Templo de estilo gótico puro (siglo XIV) edificado en sillería; presenta una imponente fachada con una gran escalinata de piedra y un interior cubierto con intrincadas bóvedas de crucería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09034','monumento','Arco de la Guía','Antigua puerta de acceso fortificada del recinto amurallado medieval del siglo XIV hecha en sillería de granito y caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09035','monumento','Yacimiento de la Villa Romana de Santa Cruz','Impresionante conjunto arqueológico de una gran villa residencial romana (siglos IV-V d.C.); conserva el espectacular Mosaico de Baco, uno de los mosaicos geométricos y figurativos más grandes e intactos de la península ibérica, que representa el triunfo del dios romano del vino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09035','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del siglo XVI de traza renacentista herreriana con una sobria portada de sillería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09036','iglesia','Iglesia Parroquial de San Juan Bautista','Templo rural barroco (siglo XVII) edificado con muros de mampostería caliza de la comarca de la Bureba, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09041','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza e hileras de ladrillo, con una robusta torre campanario barroca de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09043','monumento','Núcleos de población de Los Barrios de Bureba','El término municipal incluye los siguientes núcleos de población: Solduengo y Terrazas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09043','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre campanario barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09044','monumento','Núcleos de población de Barrios de Colina','El término municipal incluye los siguientes núcleos de población: Hiniestra y Quintanapalla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09044','iglesia','Iglesia Parroquial de San Martín (Quintanapalla)','Templo del siglo XVI edificado en piedra de sillería de líneas castellanas tradicionales; las crónicas históricas la sitúan como el escenario del matrimonio real entre el rey Carlos II y María Luisa de Orleans en 1679.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09045','monumento','Núcleos de población de Basconcillos del Tozo','El término municipal incluye los siguientes núcleos de población: Fuente Úrbel, La Rad, Santa Cruz del Tozo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09045','iglesia','Iglesia de San Julián y Santa Basilisa (Fuente Úrbel)','Joya del románico rural (siglo XII) levantada en sillería caliza; conserva un ábside semicircular intacto con capiteles labrados con esmero y una portada abocinada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09045','monumento','Eremitorio Rupestre de Tozo','Pequeña construcción e iglesia altomedieval excavada en los cortados de roca caliza viva de la comarca del Tozo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09048','monumento','Núcleos de población de Belorado','El término municipal incluye los siguientes núcleos de población: Puras de Villafranca y San Miguel de Pedroso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09048','iglesia','Iglesia de Santa María la Mayor','Monumental templo gótico-renacentista del siglo XVI edificado en sillería caliza; destaca por sus altísimas bóvedas de crucería estrellada, sepulcros nobiliarios de gran valor y un colosal retablo mayor barroco churrigueresco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09048','monumento','Cuevas de San Caprasio (Puras de Villafranca)','Conjunto monumental de eremitorios rupestres altomedievales (siglo X) excavados en los cortados','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09048','monumento','Casco Histórico y Judería (Camino de Santiago)','Trazado urbano medieval de la villa fortificada que conserva casas tradicionales con entramados de madera, soportales de piedra caliza y plazas porticadas destinadas al mercado jacobeo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09048','monumento','Castillo de Belorado','Ruinas consolidadas de una imponente fortaleza medieval de frontera del siglo XII; conserva lienzos de murallas defensivas de sillería de granito y cubos defensivos sobre el cerro que domina la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09050','monumento','Núcleos de población de Berberana','El término municipal incluye los siguientes núcleos de población: Valpuesta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09050','iglesia','Colegiata de Santa María de Valpuesta','Espléndido templo de origen visigodo y medieval reformado en estilo gótico tardío (siglos XIV-XVI) declarado BIC; de colosales dimensiones, es un hito de la historia nacional por haberse hallado en su archivo los Cartularios de Valpuesta (siglo IX), los documentos que contienen las palabras más antiguas escritas en lengua castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09050','monumento','Torre de Berberana','Torre fortificada bajomedieval del siglo XIV erigida en sillería caliza, de planta cuadrada con saeteras defensivas intactas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09051','iglesia','Iglesia Parroquial de San Andrés Apóstol','Templo herreriano del siglo XVI de gran sobriedad geométrica,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09052','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo rural barroco (siglo XVII) edificado con muros de mampostería caliza de la comarca de la Bureba, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30011','monumento','Castillo de Blanca','Ruinas consolidadas de una antigua fortaleza militar de origen andalusí emplazada de forma espectacular sobre una peña caliza que domina el Valle de Ricote, de la que restan de forma monumental paños de muralla de tapial y mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30011','iglesia','Iglesia Parroquial de San Juan Evangelista','Fábrica del siglo XVI de líneas renacentistas con reformas dieciochescas levantada en aparejo tosco que cuenta con un presbiterio con techumbre interior de madera de tradición mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09002','iglesia','Monasterio de Santa Clara','Obra maestra del renacimiento español (siglo XVI) declarada Monumento Nacional; alberga en su iglesia el espectacular Retablo Mayor de Santa Clara, una colosal estructura de 24 metros de altura esculpida íntegramente en madera de nogal sin policromar por Diego de Siloé y Juan de Anchieta, considerada una de las cumbres absolutas de la escultura renacentista mundial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09002','iglesia','Colegiata de Santa María la Mayor','Majestuoso templo neoclásico del siglo XVIII diseñado por los arquitectos reales sobre una fábrica gótica anterior; de proporciones catedralicias, posee una monumental portada simétrica de dos cuerpos con columnas calizas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09002','monumento','Casco Histórico (La Bien Trazada)','Conjunto urbano planificado en el siglo XIV con un diseño ortogonal perfecto de calles simétricas; conserva palacios señoriales de cantería de piedra con blasones heráldicos como el Palacio de los Soto Guzmán.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09057','iglesia','Monasterio de Santa María de Bugedo','Impresionante complejo monástico preindustrial cisterciense fundado en el siglo XII (1172) declarado BIC; conserva de forma impecable su iglesia románica de tres naves de sillería caliza, destacando las ventanas abocinadas y capiteles del ábside de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09060','iglesia','Iglesia Parroquial de San Martín','Monumental templo del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de piedra caliza de la Bureba; destaca su ábside poligonal con contrafuertes y un magnífico artesonado mudéjar en la nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09061','iglesia','Iglesia Parroquial de San Martín','Templo del siglo XII de estilo románico; conserva un ábside semicircular de sillería caliza muy bien ejecutado y una portada abocinada decorada con motivos vegetales tradicionales del valle de Esgueva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09062','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Sencillo templo renacentista del siglo XVI edificado con fábrica rústica de mampostería caliza de la Sierra de la Demanda, con una espadaña tradicional de dos vanos y un interior muy sobrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09004','iglesia','Real Monasterio de Santo Domingo de Caleruega','Colosal complejo monástico del siglo XIII al XVI fundado por Alfonso X el Sabio; alberga la Torre de los Guzmanes (recio torreón fortificado medieval del siglo XII de piedra caliza con almenas), el claustro gótico con arquerías apuntadas y la cripta con el lugar de nacimiento de Santo Domingo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09004','iglesia','Iglesia Parroquial de San Sebastián','Templo románico del siglo XII; conserva la portada original con arquivoltas lisas y la pila bautismal románica donde fue bautizado el santo local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09065','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de piedra de la Ribera del Duero; presenta una sólida torre campanario de líneas castellanas y un retablo mayor barroco en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09066','iglesia','Iglesia Parroquial de Santa Catalina','Edificio barroco rural del siglo XVII levantado con aparejo rústico de mampostería caliza, con una espadaña de dos vanos adaptada al entorno montañoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09067','iglesia','Iglesia Parroquial de San Pedro Apóstol','Monumental templo del siglo XVI de estilo renacentista castellano; edificado con grandes sillares de piedra de la Sierra de la Demanda, destaca por su amplia nave central y una espadaña robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09070','monumento','Yacimiento de los Castillejos de Carazo','Espectacular castro de la Edad del Hierro (siglos V-I a.C.) de la cultura celta; conserva recintos amurallados defensivos de mampostería caliza sobre una escarpada meseta rocosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09070','iglesia','Iglesia Parroquial de Santa Eugenia','Templo gótico tardío del siglo XV con aspecto de bastión fortificado, levantado íntegramente con sillería caliza calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09071','monumento','Núcleos de población de Carcedo de Bureba','El término municipal incluye los siguientes núcleos de población: Arconada y Quintanaurria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09071','iglesia','Iglesia Parroquial de Santa Eulalia (Arconada)','Joya del románico de transición de la Bureba (siglo XII); conserva un ábside semicircular intacto con capiteles labrados con esmero y una portada abocinada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09072','monumento','Núcleos de población de Carcedo de Burgos','El término municipal incluye los siguientes núcleos de población: Modúbar de la Cuesta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09072','iglesia','Iglesia Parroquial de San Román Abad','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra, con una esbelta torre campanario de líneas herrerianas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09073','iglesia','Iglesia Parroquial de San Martín','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza e hileras de ladrillo castellano, con una robusta torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09074','monumento','Núcleos de población de Cardeñajimeno','El término municipal incluye los siguientes núcleos de población: San Medel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09074','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en piedra caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09075','monumento','Núcleos de población de Cardeñuela Riopico','El término municipal incluye los siguientes núcleos de población: Villalval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09075','iglesia','Iglesia Parroquial de Santa Eulalia','Templo del siglo XVI con muros de cantería caliza, vinculado históricamente a las paradas de carruajes y peregrinos del Camino de Santiago.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09076','iglesia','Iglesia Parroquial de San Saturnino','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09077','iglesia','Iglesia Parroquial de San Facundo y San Primitivo','Templo renacentista del siglo XVI levantado en la llanura de la Bureba, edificado en aparejo de mampostería caliza, con una sobria torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09078','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo que combina una cabecera del gótico tardío (siglo XV) con reformas renacentistas, construido íntegramente con piedra de sillería de canteras locales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09079','iglesia','Iglesia Parroquial de San Esteban','Templo del siglo XVI edificado con fábrica mixta de ladrillo y mampostería caliza de líneas castellanas tradicionales, con una espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09083','iglesia','Monasterio de la Asunción de Nuestra Señora','Impresionante complejo monástico cisterciense fundado en el siglo XII (1182) declarado BIC; conserva de forma impecable su iglesia románica de sillería caliza, destacando las ventanas abocinadas y los capiteles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09082','iglesia','Iglesia Parroquial de San Pedro Apóstol','Monumental templo del siglo XVI de estilo renacentista herreriano en el Camino de Santiago; posee una fachada rematada por un gran frontón clásico y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09084','monumento','Necrópolis y Eremitorio de Cuyacabras','Espectacular conjunto altomedieval (siglos IX-X) excavado directamente en afloramientos de roca caliza viva; conserva decenas de tumbas antroporfas excavadas e indicios de una antigua ermita rupestre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09084','iglesia','Iglesia Parroquial de San Esteban','Templo monumental del siglo XVI edificado con grandes sillares de granito de la Sierra de la Demanda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09085','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, con una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09086','iglesia','Monasterio de San Pedro de Cardeña','Monumental e histórico complejo monástico trapense fundado en el siglo IX; de alto valor nacional por su vinculación con la leyenda del Cid Campeador (quien estuvo enterrado aquí), conserva la Torre del Cid (torreón románico del siglo XI), un bellísimo claustro de los mártires y una iglesia reformada en estilo barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09090','monumento','Yacimiento de la Mota de Judíos','Impresionante enclave arqueológico nacional que conserva los restos excavados de la antigua judería medieval (siglos XI-XIV); atestigua la traza urbana de las viviendas, alfares e infraestructuras de la comunidad sefardí de la provincia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09090','iglesia','Iglesia Parroquial de San Esteban','Templo renacentista del siglo XVI construido en sillería caliza castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09091','iglesia','Colegiata de Nuestra Señora del Manzano','Majestuoso templo iniciado en el siglo XIII que fusiona el gótico puro y el renacimiento; de proporciones catedralicias, custodia la imagen románica de la Virgen del Manzano y sepulcros monumentales de la nobleza castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09091','monumento','Castillo de Castrojeriz','Impresionante fortaleza señorial de origen romano y medieval que corona el cerro de la villa; conserva un cinturón defensivo massivo de sillería caliza calavera, cubos cilíndricos y estancias de la antigua fortaleza del Conde de Castrojeriz.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09091','iglesia','Iglesia de San Juan','Monumental templo del gótico flamígero (siglo XV) diseñado por los talleres catedralicios de Burgos; destaca por sus intrincadas bóvedas de crucería estrellada y su magnífico claustro gótico exento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09091','iglesia','Ruinas del Convento de San Antón','Situado en los accesos de la villa; espectaculares y colosales ruinas de un hospital cisterciense del siglo XIV cuyos arcos góticos ojivales cruzan de forma monumental sobre el propio asfalto del Camino de Santiago.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09063','palacio','Torre-Palacio de los Rojas','Espectacular fortaleza residencial civil bajomedieval del siglo XV; construida en sillería caliza de cantería impecable, presenta una gran planta cuadrada con cubos cilíndricos en los ángulos,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09063','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo que conserva un ábside románico (siglo XII) mudéjar, adosado a un cuerpo de nave renacentista levantado en piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09095','iglesia','Iglesia Parroquial de San Miguel Arcángel','Joya del románico de transición (siglo XII); conserva un ábside de sillería caliza calavera con tres pisos de arquerías ciegas de gran pureza formal e hileras de aparejo tradicional castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09098','monumento','Cuevas de San Vitores','Conjunto monumental de eremitorios rupestres altomedievales excavados en los cortados de roca caliza viva de la cuenca del Tirón, centro de devoción primitiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09098','iglesia','Iglesia Parroquial de San Nicolás de Bari','Templo del siglo XVI edificado con grandes sillares de piedra; conserva muros perimetrales originales y una portada plateresca diseñada por los talleres reales de la zona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09098','monumento','Castillo de Cerezo','Ruinas de la fortaleza medieval del siglo X que vigilaba la frontera del Reino de Castilla frente a Navarra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09100','iglesia','Iglesia Parroquial de Santa Eulalia','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42061','monumento','Núcleos de población de Cidones','El término municipal incluye los siguientes núcleos de población: Ocenilla, Villaverde del Monte y Herreros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42061','iglesia','Iglesia de San Juan Bautista (Cidones)','Fábrica del siglo XVI ejecutada en mampostería caliza con refuerzo de sillares en las esquinas, destacando su espadaña clasicista asentada sobre el muro de los pies y un interior barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42061','iglesia','Iglesia de Nuestra Señora de la Asunción (Herreros)','Templo renacentista del siglo XVI construido en sillería caliza, provisto de un presbiterio poligonal reforzado por estribos oblicuos y una notable pila bautismal románica troncocónica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09102','monumento','Eremitorio Rupestre de San Juan','Pequeña construcción e iglesia altomedieval (siglo X) excavada en roca viva en el entorno de las Merindades.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09102','iglesia','Iglesia Parroquial de Nuestra Señora de la Antigua','Templo del siglo XVI de estilo renacentista rural castellano, construido con fábrica rústica de mampostería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09103','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado con fábrica mixta de ladrillo visto y mampostería caliza, con una torre campanario barroca de líneas sencillas y un coro alto de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09104','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09105','iglesia','Iglesia Parroquial de San Sebastián','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra, con una esbelta torre campanario de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09108','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta torre campanario de sillería y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09109','monumento','Núcleos de población de Condado de Treviño','El término municipal incluye los siguientes núcleos de población: Añastro, Grandival, Sáseta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09109','monumento','Eremitorios Rupestres de Laño (Las Gobas y Santorkaria)','Espectacular conjunto de iglesias y viviendas artificiales altomedievales (siglos VI-IX d.C.) excavadas íntegramente en paredones verticales de roca caliza blanda, considerado una de las joyas de la arqueología eremítica europea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09109','iglesia','Iglesia Parroquial de San Pedro (Treviño)','Monumental templo gótico del siglo XIV edificado en sillería caliza; destaca por su bellísima portada del gótico de transición y una imponente torre campanario tardorrenacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09005','monumento','Torreón de Fernán González (Torre de Doña Urraca)','Obra maestra absoluta del arte militar mozárabe y altomedieval del siglo X (año 950); espectacular torre defensiva de planta troncopiramidal construida con bloques colosales de piedra caliza, único en Europa por su antigüedad, traza y estado de conservación militar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09005','iglesia','Excolegiata de San Cosme y San Damián','Espléndido templo del siglo XV de estilo gótico puro con proporciones catedralicias; catalogado como BIC, alberga en su interior el claustro tardogótico, una magnífica colección de sepulcros góticos (entre ellos el del conde Fernán González y la infanta Kristina de Noruega) y un órgano barroco del siglo XVII intacto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09005','monumento','Murallas de Covarrubias y Archivo de Adelantamiento','Restos del recinto defensivo de piedra del siglo XII mandado edificar por los reyes castellanos, junto al edificio renacentista diseñado por Juan de Herrera en el siglo XVI con una fachada de sillería de piedra impecable.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09005','monumento','Casco Histórico de Covarrubias (Arquitectura Popular)','Uno de los mejores conjuntos de arquitectura popular de entramado de madera de toda la península ibérica; viviendas de dos y tres plantas con plantas voladas, vigas de madera de sabina y fachadas de adobe encaladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09114','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo del siglo XVI edificado con sillería de piedra caliza extraída de las canteras locales; conserva una fachada austera y espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09114','monumento','Canteras Históricas de "Piedra de Hontoria"','Espacio de patrimonio industrial y arquitectónico etnológico de donde se extrajo el material calizo blanco utilizado para edificar la Catedral de Burgos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09115','iglesia','Iglesia Parroquial de San Millán','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca de la Bureba, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09115','monumento','Burgos | Excma. Diputacion Provincial de Burgos Información General Municipio','Burgos (capital de municipio) Zona turística: Alfoz de Burgos Distancia a la capital: 0 km Partido ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09115','monumento','Qué visitar, ver y hacer en Burgos, Castilla y León. - ANDORREANDO POR EL MUNDO 21 ago 2021 — Vistas desde el mirador qu','Qué visitar, ver y hacer en Burgos, Castilla y León. - ANDORREANDO POR EL MUNDO 21 ago 2021 — Vistas desde el mirador que hay cerca del Castillo de Burgos, Castilla y León ( Comunidad Autónoma de Castilla y León ) .','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09115','monumento','10 cosas que ver en Burgos en un día. Cerca del Paseo de la Isla','10 cosas que ver en Burgos en un día. Cerca del Paseo de la Isla se encuentra el Monasterio de las Huelgas Reales, fundado en 1187 por el rey Alfonso VIII y nuestra últ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09122','iglesia','Iglesia Parroquial de San Millán','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, con una robusta torre campanario de piedra de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09006','palacio','Palacio de los Marqueses de Chiloeches','Espectacular palacio renacentista del siglo XVI; destaca su imponente fachada de sillería caliza flanqueada por dos robustas torres cuadradas y una portalada plateresca decorada con escudos heráldicos monumentales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09006','monumento','Torre de los Velasco','Imponente torre fortificada bajomedieval del siglo XIV erigida en sillería caliza; de planta cuadrada con saeteras, modillones y matacanes defensivos intactos, ejemplo único de arquitectura militar señorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09006','iglesia','Iglesia Parroquial de Santa Cecilia','Monumental templo del gótico tardío y renacimiento (siglo XVI), proyectado por los maestros catedralicios de Burgos, con bóvedas de crucería estrellada de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09006','palacio','Palacio de los Marqueses de Cuevas de Velasco','Edificio civil residencial herreriano del siglo XVII diseñado con una severa sobriedad geométrica y escudos de armas de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09123','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de piedra de las estribaciones de la Demanda; presenta una espadaña tradicional de dos vanos en el trazado del Camino de Santiago.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09125','monumento','Núcleos de población de Estépar','El término municipal incluye los siguientes núcleos de población: Hormaza, Mazuelo de Muñó, Medinilla de la Dehesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09125','monumento','Torreón de Mazuelo de Muñó','Espectacular torre del homenaje bajomedieval del siglo XIV; construida con recia mampostería de piedra caliza y esquinas de sillería calavera, conserva almenas y ventanales ojivales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09125','iglesia','*Iglesia Parroquial de San Esteban (Estépar)','Templo del siglo XVI con una robusta torre campanario renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09127','iglesia','Iglesia Parroquial de Santa Olaja','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09128','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra, con una esbelta torre campanario de ladrillo castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09129','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica rústica de mampostería de piedra caliza de la Sierra de la Demanda, con una espadaña tradicional de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09130','iglesia','Iglesia Parroquial de San Martín','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09133','iglesia','Iglesia Parroquial de San Román Abad','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09132','iglesia','Iglesia Parroquial de San Andrés Apóstol','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09007','monumento','Castillo de los Duques de Frías (Castillo de los Velasco)','Impresionante fortaleza bajomedieval (siglos XII-XV) colgada de forma inverosímil sobre el precipicio de la muela rocosa; destaca su colosal Torre del Homenaje de sillería caliza exenta sobre una roca viva, sus adarves defensivos, matacanes flamígeros y recintos amurallados intactos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09007','monumento','Puente Medieval Fortificado de Frías','Una de las cumbres de la ingeniería civil militar medieval europea; colosal puente del siglo XII al XIV construido en sillería caliza sobre el río Ebro, caracterizado por sus 9 arcos asimétricos y una espectacular Torre Defensiva Central','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09007','iglesia','Iglesia de San Vicente Mártir','Templo monumental iniciado en el románico (del que conserva trazas y capillas) y reconstruido en el gótico y barroco; corona el perfil de la ciudad colgada y alberga capillas nobiliarias y un retablo de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09007','monumento','Casas Colgadas de Frías (Arquitectura Popular)','Espectacular conjunto de viviendas tradicionales medievales de los siglos XIV y XV; edificadas con entramados de madera de toba y adobe, sus fachadas traseras se asientan y cuelgan de forma perimetral sobre el mismo borde del precipicio de la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09135','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca de la Bureba, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09136','iglesia','Iglesia Parroquial de San Mamés','Monumental templo del siglo XVI de estilo renacentista plateresco en la Ribera del Duero; destaca por su hermosa portada con arcos tallados y un presbiterio cubierto con un artesonado mudéjar bien conservado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09138','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de la cuenca del Duero, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09139','iglesia','Iglesia Parroquial de San Bartolomé','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta torre campanario barroca de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09140','iglesia','Iglesia Parroquial de San Lorenzo Mártir','Monumental templo edificado en el siglo XVI con sillería de piedra caliza; de estilo renacentista castellano, conserva una fachada herreriana limpia y un presbiterio con bóvedas de crucería góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09141','ermita','Ermita de la Virgen de la Vega','Gran santuario barroco del siglo XVII de planta de cruz latina; catalogado como BIC, destaca por albergar pinturas murales barrocas monumentales y yeserías en el interior de su cúpula sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09141','iglesia','Iglesia Parroquial de San Miguel','Templo renacentista del siglo XVI de tres naves separadas por columnas de granito caliza, con una esbelta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09143','monumento','Núcleos de población de Galbarros','El término municipal incluye los siguientes núcleos de población: Ahedo de Bureba, San Pedro de la Cardeña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09143','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo que conserva una cabecera mudéjar del siglo XIII levantada con la técnica de cajones de mampostería e hileras de ladrillo visto, con una espadaña modificada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09148','iglesia','Iglesia de Nuestra Señora de los Reyes','Obra maestra indiscutible del gótico puro clásico rural (siglos XIII-XIV) declarada Monumento Nacional; de proporciones colosales que emulan a las catedrales urbanas, destaca por su tracería caliza, sus impresionantes bóvedas de crucería estrellada caladas y unos vitrales ojivales de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09149','iglesia','Iglesia Parroquial de San Andrés Apóstol','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca de la Bureba, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09151','iglesia','Iglesia de Santa María de la Asunción','Monumental e histórico templo gótico del siglo XIV que conserva en su fachada principal un colosal tapiz-retablo barroco esculpido en piedra caliza blanca en el siglo XVII, considerado una de las obras cumbre de este estilo en la región; alberga un interior basilical de tres naves de gran altura y un magnífico retablo mayor tardogótico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09151','monumento','Casco Histórico de Gumiel','Conserva un trazado medieval fortificado impecable con casonas palaciegas de piedra, soportales de granito caliza y bodegas subterráneas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09152','iglesia','Iglesia Parroquial de San Pedro','Espléndido templo del siglo XV de estilo gótico puro con proporciones catedralicias; destaca por su colosal torre campanario fortificada caliza y bóvedas de crucería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09152','monumento','Puertas de la Muralla (Arco de San Pedro y de Carramercado)','Restos del recinto amurallado','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09154','monumento','Árboles Fósiles de Hacinas','Aunque de origen geológico (Cretácico), varios colosales troncos fosilizados de más de 120 millones de años están expuestos de forma monumental en las calles del casco antiguo, integrados en el patrimonio arqueológico y etnológico local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09154','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI edificado con fábrica de sillería caliza de la Sierra de la Demanda, con una robusta torre campanario y un presbiterio con bóvedas de crucería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09155','monumento','Castillo de Haza y Recinto Amurallado','Fortaleza bajomedieval de frontera (siglos XII-XV) emplazada de forma espectacular sobre una escarpada muela rocosa; conserva una imponente Torre del Homenaje cuadrada de sillería caliza calavera y lienzos de murallas almenadas con cubos defensivos enteros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09155','iglesia','Iglesia Parroquial de San Miguel','Templo de estilo gótico rural mudéjar integrado en los adarves de la muralla defensiva del castillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09159','iglesia','Iglesia de la Inmaculada Concepción','Monumental templo del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de piedra caliza; destaca su ábside poligonal con recios contrafuertes y su altísima torre campanario que domina el valle donde se cobija el pueblo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09159','monumento','Hospital de San Juan (Ruinas)','Vestigios consolidados de un antiguo hospital de peregrinos medieval (siglo XIV) de gran valor institucional para la ruta jacobea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09160','iglesia','Iglesia Parroquial de San Juan Bautista','Templo herreriano del siglo XVI de gran sobriedad geométrica,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09162','monumento','Canteras Históricas de Hontoria','Espectacular espacio de patrimonio industrial y arquitectónico etnológico romano y medieval; minas a cielo abierto y galerías subterráneas de donde se extrajo la emblemática piedra caliza blanca calavera utilizada para edificar la Catedral de Burgos, el Monasterio de las Huelgas Reales y el Palacio Ducal de Lerma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09162','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo renacentista del siglo XVI edificado íntegramente con la impecable sillería blanca de sus propias canteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09163','monumento','Núcleos de población de Hontoria del Pinar','El término municipal incluye los siguientes núcleos de población: Aldea del Pinar y Navas del Pinar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09163','monumento','Puente Romano o de la Serna','Hermoso puente medieval de traza e influencia romana (siglos XII-XIII) construido en sillería caliza calavera sobre el río Lobos; presenta un perfil en lomo de asno con un solo ojo central de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09163','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI de trazas renacentistas serranas edificado con grandes bloques de piedra de sillería de canteras locales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09166','monumento','Núcleos de población de Las Hormazas','El término municipal incluye los siguientes núcleos de población: Borja, Tremello y La Parte.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09166','iglesia','Iglesia Parroquial de San Esteban (Tremello)','Joya del gótico rural de transición (siglo XIV); conserva un espectacular ábside de sillería caliza y una hermosa portada de arquivoltas abocinadas decorada con relieves medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09167','iglesia','Iglesia Parroquial de Santa María','Monumental templo del gótico tardío (siglo XVI), levantado íntegramente con sillería caliza en el corazón de las parameras castellanas del Camino de Santiago; destaca su amplia planta basilical herreriana y una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09168','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI levantado en la comarca de la Ribera del Duero; de estilo renacentista con trazas barrocas en su fachada, destaca por su robusta torre campanario y su patrimonio de bodegas subterráneas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09170','monumento','Torreón de Hoyales','Espectacular torre del homenaje bajomedieval del siglo XV; construida con recia mampostería de piedra caliza y esquinas de sillería, conserva matacanes y saeteras que controlaban el paso del Duero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09175','monumento','Núcleos de población de Humada','El término municipal incluye los siguientes núcleos de población: Congosto, Ordejón de abajo, San Martín de Humada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09175','monumento','Yacimiento de la Peña de Amaya (Entorno)','Restos excavados y arqueológicos de un gran oppidum y castro celta vettón y posteriormente ciudad romana y medieval fortificada sobre el imponente macizo rocoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09176','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza de la cuenca de Burgos, con una robusta torre campanario barroca de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09177','monumento','Núcleos de población de Ibeas de Juarros','El término municipal incluye los siguientes núcleos de población: Cueva de Juarros, Salgüero de Juarros, San Millán de Juarros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09177','iglesia','Monasterio de San Cristóbal de Ibeas (Ruinas)','Vestigios consolidados de una gran abadía bajomedieval de muros de mampostería caliza de la cuenca del Arlanzón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09177','iglesia','Iglesia Parroquial de San Martín','Templo renacentista del siglo XVI de grandes dimensiones, edificado en sillería caliza castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09178','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo de origen barroco rural (siglo XVII) edificado con muros de mampostería caliza en la llanura de la Riojilla Burgalesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09179','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09180','iglesia','Iglesia Parroquial de San Martín','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta torre campanario de sillería y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09181','monumento','Núcleos de población de Isar','El término municipal incluye los siguientes núcleos de población: Palacios de Benaver y Villorejo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09181','iglesia','Monasterio de San Salvador (Palacios de Benaver)','Impresionante complejo monástico benedictino fundado en el siglo XIII declarado BIC; de colosales dimensiones, conserva una monumental iglesia gótica cisterciense y un valioso retablo de madera tallada renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09182','monumento','Puente de Itero (Puente Fitero)','Espectacular e histórica obra de ingeniería civil del siglo XII (año 1103) mandada edificar por el rey Alfonso VI sobre el río Pisuerga; cuenta con 11 monumentales arcos de medio punto construidos en sillería caliza calavera, hito fundamental del Camino de Santiago.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09182','ermita','Ermita de San Nicolás','Pequeño santuario de estilo gótico rural mudéjar del siglo XIII adosado a los pies del puente histórico, antiguo hospital de peregrinos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09183','iglesia','Iglesia de Nuestra Señora de la Asunción','Obra maestra del románico clásico porticado (siglo XII) declarada Monumento Nacional; destaca por su espectacular galería porticada norte con siete magníficas arquerías de medio punto sobre columnas pareadas con capiteles exquisitamente esculpidos con motivos zoomorfos, y una torre fortificada massiva de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09184','iglesia','Iglesia Parroquial de San Martín','Templo del siglo XVI edificado con fábrica rústica de mampostería de piedra caliza de la Sierra de la Demanda, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09189','monumento','Núcleos de población de Junta de Traslaloma','El término municipal incluye los siguientes núcleos de población: Castrobarto, Lastras de las Eras, Tabliega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09189','iglesia','Iglesia de San Andrés (Tabliega)','Joya del románico rural de las Merindades (siglo XII); conserva un ábside semicircular intacto con capiteles labrados con esmero y una portada abocinada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09190','monumento','Núcleos de población de Junta de Villalba de Losa','El término municipal incluye los siguientes núcleos de población: Villalba de Losa y Murita.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09190','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09191','monumento','Núcleos de población de Jurisdicción de Lara','El término municipal incluye los siguientes núcleos de población: Lara de los Infantes, Aceña de Lara.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09191','monumento','Yacimiento Romano de Lara de los Infantes','Impresionante enclave que conserva la mayor colección de lápidas y aras romanas de la provincia integradas en los muros de la villa, testimonios de la antigua colonia romana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09192','monumento','Núcleos de población de Jurisdicción de San Zadornil','El término municipal incluye los siguientes núcleos de población: San Zadornil y Arroyo de San Zadornil.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09192','iglesia','Iglesia Parroquial de San Zadornil','Templo del siglo XVI edificado con fábrica rústica de mampostería de piedra caliza, con una espadaña castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','palacio','Palacio Ducal de Lerma (Parador Nacional)','Obra cumbre de la arquitectura civil clasicista y herreriana española, diseñado por Francisco de Mora a principios del siglo XVII (1601-1617) por encargo del Duque de Lerma; colosal complejo palaciego exento edificado con sillería caliza blanca y rematado por cuatro majestuosas torres angulares con chapiteles de pizarra, que alberga un espectacular patio porticado renacentista de doble piso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','monumento','Plaza Mayor de Lerma (Gran Plaza Ducal)','Una de las plazas públicas barrocas más grandes y colosales de Europa; inmenso espacio urbano simétrico porticado diseñado en el siglo XVII para acoger las fastuosas fiestas reales de la corte de Felipe III.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','iglesia','Colegiata de San Pedro','Espléndido templo del siglo XVII de proporciones catedralicias; destaca por su majestuoso interior herreriano cubierto con bóvedas limpias y por albergar la monumental escultura orante en bronce dorado del arzobispo Cristóbal de Rojas, obra de Juan de Arfe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','iglesia','Monasterio de San Blas (Monjas Dominicas) y Convento de Santa Teresa','Conjunto de colosales conventos barrocos del siglo XVII que cierran el entramado urbano de la villa palaciega, de impecable fábrica de sillería caliza calavera y ladrillo castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','monumento','Puerta de la Cárcel (Arco de la Cárcel)','Antigua e imponente puerta de acceso fortificada de la muralla medieval reformada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09195','iglesia','Iglesia Parroquial de San Martín','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca de la Bureba, con una espadaña de dos vanos para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09196','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI de estilo renacentista castellano; presenta una sólida torre campanario de sillería caliza, muros de mampostería y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09197','monumento','Núcleos de población de Madrigalejo del Monte','El término municipal incluye los siguientes núcleos de población: Montuenga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09197','iglesia','Iglesia Parroquial de San Martín','Edificio del siglo XVI edificado con fábrica mixta de mampostería caliza e hileras de ladrillo castellano, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09198','iglesia','Iglesia de San Miguel','Monumental obra del siglo XIII al XVI de proporciones catedralicias; levantada íntegramente con sillería caliza, destaca por su portada gótica, sus altísimas bóvedas de crucería y un colosal retablo mayor renacentista plateresco de gran valor artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09198','monumento','El Rollo Jurisdiccional de Mahamud','Monumento civil de piedra del siglo XV; espectacular columna','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09200','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado con fábrica rústica de mampostería caliza de la comarca de Lara, con una espadaña tradicional de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09199','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado en la comarca de la Ribera del Duero; posee una robusta torre campanario de piedra y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09202','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo rural barroco (siglo XVII) edificado con muros de mampostería caliza, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09206','iglesia','Iglesia Parroquial de Santa Ruiz','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09009','monumento','Alcázar de los Velasco (Las Torres)','Impresionante fortaleza señorial del siglo XIV erigida por los Condestables de Castilla; destaca por sus dos colosales torres cuadradas de sillería caliza de gran altura unidas por un cuerpo central fortificado, ejemplo único de arquitectura militar palaciega.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09009','iglesia','Monasterio de Santa Clara','Complejo monástico gótico del siglo XIV declarado Monumento Nacional; alberga el panteón familiar de los Velasco con espectaculares sepulcros de alabastro y una iglesia mudéjar con un rico patrimonio artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09009','monumento','Casco Histórico y Murallas','Trazado urbano medieval de la villa que conserva casas tradicionales con entramados de madera, soportales de piedra caliza y puertas fortificadas como el Arco de la Cadena.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09211','iglesia','Iglesia de la Asunción de Nuestra Señora','Monumental templo del siglo XVI diseñado por los grandes maestros renacentistas (influencia de Gil de Hontañón); de proporciones colosales, posee una espectacular sillería caliza, tres naves de gran altura con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09211','monumento','Infraestructuras del Canal de Castilla (San Carlos Abenójar)','Obra cumbre de la ingeniería civil de la Ilustración (siglo XVIII); conserva acueductos de sillería, esclusas y estructuras hidráulicas ligadas a la navegación interior de la meseta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09213','monumento','Núcleos de población de Merindad de Cuesta-Urria','El término municipal incluye los siguientes núcleos de población: Nofuentes, Paralacuesta.','inventario_monumentos_pdf');
