INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09214','monumento','Núcleos de población de Merindad de Montija','El término municipal incluye los siguientes núcleos de población: Bercedo, Villasante.','inventario_monumentos_pdf');
