INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09216','palacio','Palacio de los Porras (Puentedey)','Edificio civil fortificado del siglo XV erigido de forma espectacular sobre el puente natural de piedra caliza esculpido por el río Nela; presenta dos robustas torres cuadradas y muros almenados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09217','monumento','Núcleos de población de Merindad de Valdivielso','El término municipal incluye los siguientes núcleos de población: Quecedo, El Almiñé.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09217','iglesia','Iglesia de San Pedro de Tejada (El Almiñé)','Obra cumbre del románico clásico burgalés (siglo XII) declarada Monumento Nacional; destaca por su torre campanario exenta sobre el crucero y una colección de canecillos y relieves eróticos de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09010','iglesia','Iglesia de Santa María','Templo gótico-renacentista del siglo XVI levantado en sillería caliza; destaca por sus','inventario_monumentos_pdf');
