INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09224','ermita','Ermita de Nuestra Señora del Valle','Joya absoluta del románico clásico (siglo XII) declarada Monumento Nacional; destaca por la pureza de sus líneas, su ábside semicircular de sillería impecable con columnas adosadas y capiteles magníficamente labrados.','inventario_monumentos_pdf');
