INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09228','iglesia','Iglesia Parroquial de San Pedro','Templo renacentista del siglo XVI con una sólida torre de sillería caliza.','inventario_monumentos_pdf');
