INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09231','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo del siglo XVI edificado con fábrica mixta de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09232','iglesia','Iglesia Parroquial de Santa María','Monumental templo del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de granito de la Sierra de la Demanda; destaca su ábside poligonal con contrafuertes y su torre fortificada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09235','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre campanario barroca de la Ribera del Duero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09011','iglesia','Real Monasterio de San Salvador de Oña','Colosal e histórico complejo monástico cluniacense fundado en','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09011','monumento','Casco Histórico y Judería','Conjunto urbano fortificado de calles empedradas de origen medieval, rodeado de restos de murallas de piedra y torres como el Arco de la Estrella.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09011','iglesia','Iglesia Parroquial de San Juan','Templo fortificado de estilo gótico rural mudéjar adosado al complejo del monasterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09246','monumento','Necrópolis Medieval de El Castillo','Espectacular cementerio altomedieval (siglos IX-XI) excavado directamente en roca caliza y granito; conserva decenas de tumbas antropomorfas, nichos y estelas de gran valor para la arqueología de la cuenca del Duero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09246','iglesia','Iglesia Parroquial de Santa Eulalia','Templo del siglo XVI construido en sillería de piedra de la sierra, con una robusta torre campanario y un presbiterio con bóvedas de crucería góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09012','monumento','Castillo de Santa Marta (Las Runas)','Fortaleza bajomedieval de frontera (siglos XII-XIV) emplazada de forma espectacular sobre las crestas del desfiladero; conserva lienzos de murallas y cubos defensivos de sillería caliza que dominaban el paso de la Bureba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09012','monumento','Fortaleza de Santa Engracia','Complejo militar fortificado del siglo XVIII edificado en lo alto de las peñas, escenario clave en la Guerra de la Independencia, de gran valor estratégico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09012','iglesia','Iglesia Parroquial de Santiago','Templo de estilo gótico puro (siglo XIV) levantado en piedra caliza con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09256','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI levantado en la comarca de la Ribera del Duero; de estilo renacentista castellano, destaca por su robusta torre campanario de piedra y su patrimonio de bodegas subterráneas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09259','iglesia','Iglesia Parroquial de San Julián y Santa Basilisa','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en piedra caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09013','palacio','Palacio de los Condes de Miranda (Palacio de Avellaneda)','Obra cumbre de la arquitectura civil renacentista y plateresca española, diseñado por Francisco de Colonia en el siglo XVI; posee una espectacular fachada de sillería caliza con portalada plateresca y, en su interior, un claustro porticado y salones con artesonados mudéjares de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09013','monumento','Castillo de Peñaranda','Impresionante fortaleza bajomedieval (siglos X-XV) que corona el perfil de la peña; conserva una colosal Torre del Homenaje cuadrada de sillería caliza calavera, adarves defensivos, matacanes y recintos amurallados intactos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09013','iglesia','Excolegiata de la Abadía de Santa Ana','Espléndido templo barroco clasicista diseñado en el siglo XVII por los arquitectos reales; de proporciones catedralicias, posee una monumental fachada simétrica de dos cuerpos con columnas calizas y una escalinata que preside la Plaza Mayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09013','monumento','Rollo Jurisdiccional de Peñaranda','Joya del arte gótico civil (siglo XV) situado en la Plaza Mayor; colosal y esbelta columna de piedra caliza calavera labrada con filigranas flamígeras que atestigua el rango de villa judicial autónoma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09266','iglesia','Iglesia de San Esteban Protomártir','Obra maestra del románico porticado (siglo XII) declarada Monumento Nacional; destaca por su espectacular galería porticada sur con arquerías de medio punto sobre columnas pareadas con capiteles magníficamente esculpidos con motivos zoomorfos y vegetales, y una torre fortificada de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09268','iglesia','Iglesia Parroquial de San Cristóbal','Templo del siglo XVI edificado con fábrica rústica de mampostería de piedra caliza de la Sierra de la Demanda, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09269','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo que conserva trazas góticas (siglo XV) en su cabecera y muros de sillería caliza, reformado en época moderna con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09014','monumento','Castillo de los Rojas','Impresionante fortaleza señorial bajomedieval (siglo XIV) colgada de forma espectacular sobre el precipicio de la muela rocosa; conserva una imponente torre de sillería caliza sobre una roca viva y recintos amurallados que dominan la Bureba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09014','monumento','Recinto Amurallado de Poza','Espectacular muralla medieval de piedra caliza que abraza el casco histórico; conserva casi intacto su perímetro jalonado por torres corachas, cubos defensivos y puertas monumentales como el Arco del Convento y la Puerta del Ayuntamiento.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09014','monumento','El Complejo Etnológico de las Salinas','Monumental espacio de patrimonio industrial preindustrial de origen romano y medieval; red de eras de evaporación de sal construidas en piedra caliza, canales y pozos de almacenamiento de salmuera que constituyen un paisaje único en España.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09014','iglesia','Iglesia de San Cosme y San Damián','Templo monumental de estilo gótico puro (siglo XIV) edificado en sillería; presenta una imponente fachada con una hermosa portada y un interior cubierto con intrincadas bóvedas de crucería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09273','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca de la Bureba, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09274','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI con importantes modificaciones barrocas y neoclásicas, levantado en sillería de piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09280','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo rural barroco (siglo XVII) edificado con muros de mampostería caliza de la comarca de la Bureba, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09287','iglesia','Iglesia Parroquial de San Martín','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza e hleras de ladrillo castellano, con una robusta torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09289','monumento','Necrópolis Medieval de Cuyacabras (Entorno)','Impresionante conjunto altomedieval (siglos IX-X) excavado directamente en afloramientos de roca de la Sierra de la Demanda; conserva decenas de tumbas antroporfas y cistas de piedra que atestiguan los asentamientos de la repoblación castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09289','iglesia','Iglesia Parroquial de San Cristóbal','Templo renacentista del siglo XVI construido en sillería de canteras locales, con una sólida torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09292','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca de la Bureba, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09901','monumento','El Territorio Artlanza (Patrimonio Etnológico)','Monumental recreación a escala real de un auténtico pueblo castellano de los siglos XVI y XVII construido con materiales tradicionales reciclados (madera, piedra caliza, adobe), concebido como espacio de conservación de la arquitectura popular regional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09901','iglesia','Iglesia Parroquial de la Natividad (Tordueles)','Templo del siglo XVI edificado en piedra de sillería de líneas castellanas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09298','iglesia','Iglesia Parroquial de San García','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09301','iglesia','Iglesia Parroquial de Santa Eulalia','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09302','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica rústica de mampostería de piedra caliza de la Sierra de la Demanda, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09303','monumento','Núcleos de población de Rábanos','El término municipal incluye los siguientes núcleos de población: Miranda de Duero, Navalcaballo y Tardajos de Duero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09303','iglesia','Iglesia de San Pedro Apóstol (Los Rábanos)','Fábrica del siglo XVI construida en mampostería caliza con esquinas reforzadas con bloques de cantería, rematada por una espadaña de dos cuerpos decrecientes con vanos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09303','iglesia','Iglesia de Santo Domingo de Silos (Tardajos de Duero)','Templo de origen románico profundamente reformado en el siglo XVIII, del cual pervive una sencilla portada meridional de arquivoltas lisas de medio punto sobre jambas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09309','monumento','Yacimiento de Icnitas de El Frontal','Aunque geológico (Cretácico), este afloramiento conserva espectaculares huellas fosilizadas de dinosaurio integradas de forma monumental en el patrimonio cultural y didáctico de la comarca serrana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09309','iglesia','Necrópolis de la Iglesia','Conjunto de tumbas antroporfas altomedievales (siglos IX-X) talladas en la roca de granito viva que rodea la iglesia parroquial de San Adrián, templo del siglo XVI.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09310','iglesia','Iglesia Parroquial de San Martín','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca de la Bureba, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09311','iglesia','Iglesia Parroquial de San Esteban','Joya del románico de transición (siglo XII); conserva un ábside de sillería caliza calavera con tres pisos de arquerías ciegas de gran pureza formal e hileras de aparejo tradicional castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09314','monumento','Núcleos de población de Revilla del Campo','El término municipal incluye los siguientes núcleos de población: Quintanalara.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09314','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza e hileras de ladrillo, con una robusta torre campanario barroca de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09316','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09315','monumento','Núcleos de población de Revillarruz','El término municipal incluye los siguientes núcleos de población: Humienta y Olmosalbos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09315','iglesia','Iglesia Parroquial de San Pedro','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra, con una esbelta torre campanario de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09317','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09318','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de piedra de la Sierra de la Demanda; presenta una sólida torre campanario de líneas castellanas y un presbiterio con bóvedas de crucería góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09016','iglesia','Excolegiata de Nuestra Señora de la Asunción','Monumental e histórico templo gótico del siglo XV-XVI;','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09016','monumento','Recinto Amurallado de Roa','Restos del imponente recinto defensivo de piedra caliza del siglo XII mandado edificar por los reyes castellanos sobre el espolón que domina el río Duero, conservando paños y el cubo de San Juan.','inventario_monumentos_pdf');
