INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09323','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, con una robusta torre campanario de piedra de sillería en la Bureba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09325','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
