INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09328','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo rural barroco (siglo XVII) edificado con muros de mampostería caliza de la comarca de la Bureba, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09332','monumento','Núcleos de población de Saldaña de Burgos','El término municipal incluye los siguientes núcleos de población: Ventas de Saldaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09332','palacio','Palacio de Saldañuela','Espléndido palacio renacentista del siglo XVI de estilo plateresco italiano; destaca su elegante fachada con un patio porticado interior con arquerías de piedra caliza y una imponente torre fortificada medieval integrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09332','iglesia','Iglesia Parroquial de la Santa Cruz','Templo del siglo XVI construido en sillería y mampostería castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09332','monumento','(Nota técnica','Este municipio pertenece históricamente a Álava, País Vasco. Si te refieres a las salinas burgalesas, están integradas en Poza de la Sal, ya descrita).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09334','monumento','Complejo de las Salinas de Salinillas','Infraestructura preindustrial de origen medieval para la obtención de sal por evaporación de salmuera; conserva balsas y canales de piedra integrados en el paisaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09334','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09335','iglesia','Iglesia Parroquial de San Adrián','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica mixta de mampostería caliza de la cuenca del Arlanzón y una robusta espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09337','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo renacentista del siglo XVI levantado en la comarca de la Ribera del Duero; posee una robusta torre campanario de piedra y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09338','iglesia','Iglesia Parroquial de San Mamés','Edificio del siglo XVI edificado con fábrica mixta de mampostería caliza e hileras de ladrillo castellano, con una robusta torre campanario de líneas sencillas de la periferia metropolitana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09339','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en piedra caliza, con una fachada rematada por un gran frontón clásico y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09340','iglesia','Iglesia de San Millán','Joya absoluta del románico de la Sierra de la Demanda (siglo XII) declarada BIC; destaca por la pureza de su ábside semicircular de sillería caliza y su magnífica galería porticada exterior con capiteles profusamente decorados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09360','iglesia','Iglesia de la Asunción de Nuestra Señora (San Vicente)','Joya del arte visigodo y prerrománico (siglo VIVII d.C.); conserva elementos de la basílica original, hileras de piedra caliza tallada y un arco de herradura visigodo de gran pureza formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09343','iglesia','Iglesia Parroquial de Santa Cecilia','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09345','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de tres naves separadas por columnas, edificado con aparejo de mampostería, con una torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09346','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica rústica de mampostería de piedra caliza de la Sierra de la Demanda, con una espadaña tradicional de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09347','monumento','Castillo de Santa Gadea y Recinto Amurallado','Fortaleza bajomedieval de frontera (siglos XI-XV) que corona la villa; conserva casi intacto su cinturón de murallas de sillería caliza, jalonado por cubos defensivos circulares, adarves y dos monumentales puertas fortificadas (Arco de las Eras y Arco de la Villa).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09347','iglesia','Iglesia Parroquial de San Pedro','Espléndido templo del gótico puro (siglo XIV) edificado en sillería; presenta una imponente fachada con una hermosa portada plateresca, altísimas bóvedas de crucería y un retablo mayor con tablas pictóricas renacentistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09347','ermita','Ermita de Nuestra Señora de las Eras','Pequeño templo gótico del siglo XV exento, situado en los accesos de la villa medieval amurallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09348','iglesia','Iglesia Parroquial de Santa Inés','Edificio barroco rural del siglo XVII levantado con aparejo rústico de piedra caliza y granito, con una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09350','iglesia','Iglesia de la Asunción de Nuestra Señora','Obra maestra gótico-renacentista del siglo XVI declarada Monumento Nacional; destaca su espectacular Torre Plateresca, una colosal estructura diseñada por Diego de Siloé y Juan de Vallejo considerada una de las cumbres absolutas de la arquitectura renacentista española; alberga en su interior un suntuoso púlpito mudéjar y un retablo mayor gótico de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09350','monumento','Puertas de la Muralla (Arco de la Fuente y de la Vega)','Restos del imponente recinto defensivo medieval de piedra caliza del siglo XIV que protegía la villa judicial autónoma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09351','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra caliza, edificado en aparejo de mampostería castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09352','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de tres naves,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09353','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de piedra caliza; destaca su ábside poligonal con recios contrafuertes y un magnífico artesonado mudéjar en la nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09354','iglesia','Iglesia Parroquial de Santa Eulalia','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza, con una torre campanario barroca de líneas sencillas en la Bureba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09355','ermita','Ermita de San Salvador','Joya del románico de transición (siglo XII); conserva un espectacular ábside de sillería caliza calavera y una portada abocinada decorada con canecillos e hileras de aparejo tradicional castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09355','iglesia','Iglesia Parroquial de San Nicolás','Templo del siglo XVI con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09356','monumento','Núcleos de población de Santibáñez del Val','El término municipal incluye los siguientes núcleos de población: Barriosuso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09356','ermita','Ermita de Santa Cecilia (Barriosuso)','Obra maestra indiscutible del arte mozárabe y del románico primitivo (siglo X); espectacular y pequeño templo levantado en sillería caliza que conserva un arco de herradura mozárabe intacto en su portada, capiteles prerrománicos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09356','iglesia','Iglesia Parroquial de Santiago (Santibáñez del Val)','Templo gótico del siglo XV edificado en sillería caliza castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09018','iglesia','Abadía del Monasterio de Santo Domingo de Silos','Colosal complejo monástico benedictino fundado en el siglo X; declarado Monumento Nacional de forma','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09018','iglesia','Iglesia Monacal de Silos','Templo neoclásico proyectado en el siglo XVIII por el arquitecto de la corte Ventura Rodríguez sobre la antigua basílica románica, con una cúpula majestuosa de piedra blanca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09018','ermita','Ermita de la Virgen del Camino y Desfiladero de la Yecla','Estructuras de patrimonio religioso y caminares de piedra integradas en las laderas rocosas calizas de la comarca serrana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49210','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI levantado en la comarca de la Tierra del Vino','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09363','monumento','Núcleos de población de Sasamón','El término municipal incluye los siguientes núcleos de población: Olmillos de Sasamón y Castrillo de Murcia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09363','iglesia','Iglesia Colegiata de Santa María la Real','Espléndido templo del siglo XIII y XIV de proporciones catedralicias calificado como BIC; destaca por su majestuosa portada meridional, réplica de la Puerta del Sarmental de la Catedral de Burgos, un colosal claustro gótico flamígero de Juan de Colonia y un interior cubierto con bóvedas de crucería de gran altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09363','palacio','Castillo de Olmillos de Sasamón (Palacio de los Florín)','Espectacular fortaleza residencial gótico-mudéjar del siglo XV; edificado con cantería caliza impecable, presenta una planta cuadrada con esbeltos cubos cilíndricos almenados provistos de gárgolas esculpidas y una Torre del Homenaje señorial entera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09363','monumento','Puente Medieval sobre el río Brullés y Murallas Romanas','Monumentales puentes medievales e infraestructuras civiles construidas aprovechando las pilastras de la antigua calzada y campamento militar romano de Segisama (siglo I a.C.).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09363','monumento','Cruz de los Humilladeros','Monumento gótico civil (siglo XV); cruz de cantería esculpida con filigranas flamígeras que se asienta en la plaza mayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09369','palacio','Palacio Consistorial y Casa Grande','Espectacular palacio consistorial barroco del siglo XVIII erigido íntegramente con piedra de sillería caliza, con una elegante fachada y escudos heráldicos reales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09369','iglesia','Iglesia Parroquial de Santa Águeda','Templo monumental del siglo XVI edificado con sillería en la Ribera del Duero; destaca por su esbelta torre campanario de tres cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09372','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de tres naves separadas por columnas, edificado con aparejo toledano en la cuenca de Burgos, con una torre campanario de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09373','monumento','Núcleos de población de Sotresgudo','El término municipal incluye los siguientes núcleos de población: Amaya, Salazar de Amaya.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09373','monumento','Yacimiento de la Peña de Amaya','Impresionante conjunto arqueológico nacional; restos excavados del gran oppidum celta vettón de la Edad del Hierro, conquistado por los romanos y capital de los pueblos cántabros medievales, que conserva murallas defensivas de piedra seca e infraestructuras primitivas talladas sobre un imponente macizo rocoso calizo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09373','iglesia','Iglesia de San Miguel (Salazar de Amaya)','Joya del románico de transición (siglo XII) levantada en sillería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39085','iglesia','Iglesia Parroquial de San Martín','Templo de origen barroco rural (siglo XVII) edificado con muros bastos de mampostería caliza, con una espadaña tradicional de un vano para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09374','iglesia','Iglesia Parroquial de San Vicente','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en piedra caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09375','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza y ladrillo, con una robusta torre campanario barroca de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09377','monumento','Yacimiento Romano de Deobrigula','Restos excavados y consolidados de una gran villa de explotación agrícola y nudo de comunicaciones romana (siglos II-IV d.C.) en el trazado del Camino de Santiago.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09377','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo parroquial del siglo XVIII edificado en estilo neoclásico sobre restos medievales, construido íntegramente con ladrillo visto y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09378','iglesia','Iglesia Parroquial de San Pedro','Templo que conserva una cabecera mudéjar del siglo XIII levantada en ladrillo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09380','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de piedra caliza de la cuenca del Duero, con una espadaña y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09381','iglesia','Iglesia Parroquial de Santa Eulalia (Tañabueyes)','Joya del románico rural (siglo XII) levantada en sillería caliza calavera de la Sierra de la Demanda; conserva un ábside semicircular intacto con capiteles labrados con esmero y una pila bautismal románica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09382','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza, con una robusta torre campanario barroca de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09384','monumento','Puente Romano sobre el río Arlanza','Espectacular obra de ingeniería civil romana del siglo I d.C. (época de Trajano); monumental puente de sillería caliza calavera que conserva 22 arcos de medio punto (varios enterrados) y tajamares angulares, hito de las comunicaciones antiguas de la provincia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09384','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado en piedra de sillería conectado históricamente al puente.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09386','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09387','monumento','Castillo de Torregalindo','Ruinas consolidadas de una fortaleza gótico-mudéjar del siglo XV; conserva lienzos de murallas de mampostería de piedra caliza con cubos cilíndricos y elementos defensivos que controlaban el valle del río Riaza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09387','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado en piedra berroqueña caliza de líneas castellanas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09388','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo del siglo XVI de estilo renacentista rural castellano, construido con fábrica de ladrillo y mampostería rústica de piedra berroqueña caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09389','iglesia','Iglesia Parroquial de San Esteban','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09390','iglesia','Monasterio de la Virgen de los Valles (Ruinas)','Vestigios consolidados de un gran convento e iglesia del gótico tardío (siglo XV) de muros de cantería caliza de la comarca del Esgueva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09390','iglesia','Iglesia Parroquial de San Martín','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza, con un presbiterio con bóvedas de crucería góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09391','iglesia','Monasterio de Santa María de la Vid (Tórtoles)','Ruinas y dependencias consolidadas de una gran abadía agustina del siglo XII-XIV; conserva lienzos de murallas de sillería de granito, cubos defensivos circulares y estancias palaciegas medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09391','iglesia','Iglesia Parroquial de San Esteban','Templo de estilo gótico tardío y renacentista (siglo XVI), levantado de forma unificada en sillería caliza de la cuenca de Esgueva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09392','ermita','Ermita Rupestre de la Virgen de la Peña','Espectacular santuario altomedieval (siglo X) excavado por completo en una pared vertical de roca caliza viva; destaca su fachada encalada que asoma de la montaña, un hito singular de la ruta jacobea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09019','monumento','Castillo de Tedeja','Considerada una de las fortalezas cristianas de la Reconquista más antiguas de Castilla (siglos V-IX d.C.); sus ruinas consolidadas sobre el desfiladero de la Horadada muestran la transición desde muros romanos y visigodos hasta las torres altomedievales de sillería caliza calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09019','monumento','Yacimiento de la Necrópolis de Cillaperlata','Conjunto arqueológico altomedieval con tumbas antropomorfas excavadas en roca caliza viva de las Merindades.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09395','iglesia','*Iglesia de San Juan (Tubilla)','Templo románico del siglo XII; conserva un ábside semicircular intacto con capiteles labrados con motivos de filigranas vegetales y una portada abocinada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09395','monumento','Cascada de Tubilla (Patrimonio Etnológico)','Entorno urbano monumental donde la arquitectura popular de piedra caliza y toba se entrelaza de forma perenne con saltos de agua y canales hidráulicos medievales de molienda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09396','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, con una robusta torre campanario de piedra de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09398','monumento','Castillo de Úrbel','Ruinas consolidadas de una imponente fortaleza del siglo XII erigida en un crestón de roca viva inaccesible; conserva cubos defensivos circulares y lienzos de murallas que dominaban los valles altos del Úrbel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09400','monumento','Recinto Amurallado de Vadocondes','Espectacular muralla medieval de piedra caliza del siglo XIV que abraza el meandro del río Duero; conserva casi intacto su perímetro jalonado por torres, adarves y dos monumentales puertas intactas (Arco de Burgos y Arco de la Trinidad).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09400','monumento','Puente Medieval sobre el Duero','Monumental obra de ingeniería civil del siglo XV erigida en sillería caliza calavera, caracterizada por sus arcos de medio punto y tajamares angulares massivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09400','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo monumental del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de granito; destaca su ábside poligonal con contrafuertes y un magnífico artesonado mudéjar en la nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09400','monumento','Rollo Jurisdiccional de Vadocondes','Monumento civil de cantería del siglo XVI; columna de piedra con ganchos de hierro que atestigua el rango de villa judicial autónoma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09403','monumento','Yacimiento Romano de Ciella','Restos excavados y consolidados de una gran villa de explotación agrícola romana (siglos II-IV d.C.), que conserva basamentos de piedra e inscripciones latinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09403','monumento','(Nota de consistencia','Entidad integrada en el Valle de Sedano; se detallará de forma unificada bajo el epígrafe municipal del Valle de Sedano en la letra V).','inventario_monumentos_pdf');
