INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09908','ermita','Ermita de San Pantaleón de Losa','Obra maestra indiscutible del románico clásico exótico (siglo XII) declarada Monumento Nacional; emplazada de forma espectacular sobre una peña en forma de proa de barco, destaca por sus ventanas abocinadas y capiteles esculpidos con relieves enigmáticos únicos (gigantes, atlantes y motivos esotéricos) de un valor artístico universal.','inventario_monumentos_pdf');
