INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09409','iglesia','Iglesia de San Miguel (San Miguel de Cornezuelo)','Joya absoluta del románico clásico (siglo XII) declarada Monumento Nacional; destaca por la pureza de su ábside semicircular de sillería impecable con columnas adosadas y capiteles labrados.','inventario_monumentos_pdf');
