INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40031','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra caliza, con una esbelta torre campanario de líneas herrerianas de gran sobriedad geométrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40032','monumento','Núcleos de población de Boceguillas','El término municipal incluye los siguientes núcleos de población: Aldeanueva del Campanario y Turrubuelo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40032','iglesia','Iglesia Parroquial de Nuestra Señora del Rosario','Templo del siglo XVI de traza castellana tradicional,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40033','iglesia','Iglesia Parroquial de Santiago Apóstol','Sencillo templo de origen barroco rural (siglo XVII) edificado con muros bastos de mampostería caliza, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42041','iglesia','Iglesia de San Juan Bautista','Fábrica rural modesta del siglo XVII levantada con aparejo tosco de piedra caliza del terreno, caracterizada por su planta rectangular unicelular con cubierta de madera vista sobre vigas de pino.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40034','ermita','Ermita de San Frutos / Ermita de la Fuente','Pequeño oratorio medieval (siglo XIII) edificado en piedra de sillería sobre un manantial donde se custodian las reliquias de San Valentín y Santa Engracia, ligadas a un rito secular contra la sequía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40034','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI con muros de mampostería caliza, contrafuertes góticos y una torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40035','monumento','Núcleos de población de Cabañas de Polendos','El término municipal incluye los siguientes núcleos de población: Mata de Quintanar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40035','iglesia','Iglesia Parroquial de San Lorenzo','Edificio de origen románico (siglo XII) profundamente modificado en los siglos XVI y XVII; conserva muros con cajones de mampostería, esquinales de sillería caliza y espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40039','monumento','Núcleos de población de Campo de San Pedro','El término municipal incluye los siguientes núcleos de población: Fuentemizarra y Valdevarnelo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40039','iglesia','Iglesia de Nuestra Señora del Rosario (Fuentemizarra)','Joya del románico rural (siglo XII); conserva un ábside semicircular intacto de sillería caliza y una hermosa galería porticada con arquerías de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40039','iglesia','Iglesia Parroquial de San Pedro (Campo de San Pedro)','Templo renacentista del siglo XVI de líneas herrerianas sobrias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40040','iglesia','Iglesia Parroquial de San Andrés','Templo del siglo XVI edificado con grandes sillares de piedra caliza; destaca por su esbelta torre campanario de tres cuerpos y un presbiterio cubierto con un artesonado de madera de pino serrano tallada de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40041','iglesia','Iglesia Parroquial de San Vicente Mártir','Templo del siglo XVI de tres naves separadas por columnas, edificado con aparejo toledano (ladrillo y cajones de mampostería caliza), con una robusta torre campanario y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40043','iglesia','Iglesia Parroquial de San Juan Bautista','Monumental templo edificado en el siglo XV de estilo gótico tardío; catalogado como BIC, destaca por su colosal cabecera caliza, sus impresionantes cubiertas interiores de madera de tradición mudéjar y un grandioso retablo mayor renacentista plateresco de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40043','ermita','Ermita del Bustar','Santuario barroco del siglo XVII de planta de cruz latina y cúpula sobre pechinas situado en un paraje natural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40044','monumento','Núcleos de población de Carrascal del Río','El término municipal incluye los siguientes núcleos de población: Burgomillodo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40044','ermita','Ermita de San Frutos (Duratón)','Aunque compartida con municipios vecinos por su ubicación en las Hoces del Duratón, esta joya del románico del siglo XII (BIC) destaca por su emplazamiento en un acantilado rocoso, sus arcos de medio punto de sillería y capiteles labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40044','iglesia','Iglesia Parroquial de la Asunción (Carrascal)','Templo renacentista del siglo XVI edificado en piedra caliza con una robusta espadaña castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40045','iglesia','Iglesia Parroquial de San Pedro','Edificio barroco rural del siglo XVII levantado con aparejo rústico de piedra caliza de la Serrezuela, con una espadaña de dos vanos adaptada al clima de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40047','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo del siglo XVI con trazas renacentistas, construido en ladrillo visto y piedra caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40048','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio barroco del siglo XVII de traza castellana tradicional, construido con ladrillo visto y cajones de mampostería caliza, con una torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40049','monumento','Núcleos de población de Castroserna de Abajo','El término municipal incluye los siguientes núcleos de población: Castroserna de Arriba.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40049','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora (Castroserna de Arriba)','Templo del siglo XVI edificado en piedra de sillería de líneas castellanas tradicionales; conserva elementos románicos en la base de sus muros y una espadaña tradicional de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40053','iglesia','Iglesia Parroquial de San Román Abad','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería de piedra caliza, con una fachada rematada por un gran frontón clásico y una torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40054','iglesia','Iglesia Parroquial de San Juan Bautista','Monumental templo del siglo XVI de estilo renacentista castellano; edificado con grandes sillares de granito berroqueño de las estribaciones de Somosierra, destaca por su amplia nave central y una espadaña robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40065','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI levantado en la comarca de la Tierra de Pinares; de estilo renacentista castellano, destaca por su robusta torre campanario de ladrillo visto y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40055','iglesia','Iglesia Parroquial de San Mamés','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero adaptado al clima.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40056','iglesia','Iglesia Parroquial de San Martín','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica mixta de ladrillo visto y mampostería caliza, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40057','monumento','Castillo de Coca','Obra maestra indiscutible de la arquitectura militar gótico-mudéjar (siglo XV) encargado por el arzobispo Alonso de Fonseca; espectacular','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40057','monumento','Murallas de Coca y Puerta de la Villa','Restos del recinto defensivo medieval del siglo XII de origen mudéjar; conserva paños de gran espesor construidos con mampostería y ladrillo visto, y la puerta monumental de acceso que funcionaba como aduana y concejo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40057','iglesia','Iglesia de Santa María la Mayor','Templo gótico y renacentista del siglo XVI levantado en sillería caliza calavera y ladrillo; alberga en su interior los monumentales sepulcros de la familia Fonseca, esculpidos en mármol de Carrara blanco de una finura renacentista extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40057','monumento','Torre de San Nicolás','Torre exenta de planta cuadrada construida en el siglo XII de ladrillo mudéjar con vanos apuntados y arquerías ciegas, único resto de una antigua iglesia bajomedieval destruída.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40058','monumento','Núcleos de población de Codorniz','El término municipal incluye los siguientes núcleos de población: Montuenga.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40058','iglesia','Iglesia Parroquial de Santo Domingo de Silos','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en piedra caliza, con una fachada rematada por un gran frontón clásico y una torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40059','iglesia','Monasterio de Santa María de la Sierra (Ruinas)','Espectaculares ruinas consolidadas de una gran abadía cisterciense fundada en el siglo XII (1133) declarada BIC; de piedra caliza berroqueña calavera, conserva su iglesia románica de tres naves, destacando las ventanas abocinadas con capiteles de una finura extrema y arcos fajones apuntados sobre las praderas de la sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40060','monumento','Núcleos de población de Condado de Castilnovo','El término municipal incluye los siguientes núcleos de población: Valdeprados, Torrecilla, Villafranca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40060','monumento','Castillo de Castilnovo','Impresionante fortaleza residencial e histórica cuyos tramos más antiguos datan del califato andalusí (siglo X) y ampliado en los siglos XIV y XV por los reinos cristianos; palacio fortificado de planta cuadrada construido en sillería caliza y ladrillo mudéjar, destacando sus seis robustas torres almenadas (cuadradas y cilíndricas) y un patio de armas majestuoso rodeado de leyendas señoriales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40061','iglesia','Iglesia Parroquial de San Juan Bautista','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave y espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40902','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado en la llanura; edificado con fábrica mixta de mampostería caliza e hleras de ladrillo, con una sobria espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40062','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta torre campanario de líneas sencillas y un interior muy austero adaptado al entorno rural castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40063','monumento','Castillo de los Duques de Alburquerque','Impresionante fortaleza señorial e histórica construida entre los siglos XII y XVI; mezcla el estilo gótico militar mudéjar con reformas palaciegas renacentistas, conservando muros almenados, una colosal torre del homenaje de cantería caliza y un patio de armas con galerías porticadas de doble piso de una finura renacentista extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40063','monumento','Recinto Amurallado de Cuéllar','El conjunto de murallas medievales mudéjares más grande de toda la provincia; conserva cerca de dos kilómetros de perímetro perimetral intacto jalonado por contrafuertes de piedra caliza, adarves transitables y monumentales puertas como el Arco de San Basilio y el Arco de San Andrés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40063','iglesia','Iglesia de San Martín','Joya cumbre del románicomudéjar abulense-segoviano (siglo XII); declarada Monumento Nacional, posee tres espectaculares ábsides semicirculares de ladrillo visto con pisos de arquerías ciegas superpuestas y dobles, que hoy alberga el centro de interpretación del mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40063','iglesia','Iglesia de San Esteban','Templo mudéjar del siglo XII clasificado como BIC; destaca por su gran ábside de ladrillo visto profusamente decorado y por albergar en su interior sepulcros monumentales gótico-mudéjares decorados con yeserías polícromas únicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40063','iglesia','Iglesia de San Andrés','Templo mudéjar que conserva una espectacular fachada occidental y un interior cubierto con un artesonado de madera de par y nudillo con yeserías de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40063','palacio','Palacio de Pedro I el Cruel','Edificio civil señorial bajomedieval del siglo XIV; presenta una portada románica de transición de sillería de piedra caliza calavera con ventanas molduradas y escudos nobiliarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40069','iglesia','Iglesia Parroquial de San Lorenzo','Templo de origen barroco (siglo XVIII) construido en ladrillo visto y cajones de mampostería siguiendo el aparejo castellano, con una espadaña tradicional de dos vanos y un interior de nave única muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40070','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo que conserva trazas del románico de transición (siglo XII) en su cabecera y una notable pila bautismal; destaca su torre campanario barroca de sillería caliza calavera y sus yeserías interiores decorativas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40071','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI edificado con fábrica de piedra caliza de la Serrezuela; presenta una sólida torre campanario de líneas castellanas tradicionales, muros de mampostería y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40072','iglesia','Iglesia Parroquial de San Vicente Mártir','Sencillo templo barroco rural (siglo XVII) edificado con muros bastos de mampostería caliza, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40073','iglesia','Iglesia Parroquial de San Zoilo','Monumental templo del siglo XVI de tres naves, construido en sillería de piedra caliza; destaca por albergar una techumbre de madera tallada de tradición mudéjar de gran interés y una esbelta torre campanario de tres cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40073','ermita','Ermita de Nuestra Señora de la Redonda','Pequeña construcción devocional barroca del siglo XVII ejecutada en ladrillo visto con tejado castellano tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40074','iglesia','Iglesia Parroquial de San Benito','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica de ladrillo visto y cajones de mampostería caliza, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40075','monumento','Núcleos de población de Escobar de Polendos','El término municipal incluye los siguientes núcleos de población: Parral de Villovela, Peñarrubias, Villovela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40075','iglesia','Iglesia de San Pedro (Peñarrubias de Pirón)','Joya del románico rural (siglo XII) levantada sobre un espolón','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40076','monumento','Núcleos de población de El Espinar','El término municipal incluye los siguientes núcleos de población: San Rafael, Estación de El Espinar, Los Ángeles de San Rafael.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40076','iglesia','Iglesia de San Eutropio','Monumental obra del siglo XVI diseñada por el célebre arquitecto Rodrigo Gil de Hontañón; templo de proporciones catedralicias construido en sillería de granito berroqueño, destaca por su majestuosa fachada herreriana limpia, bóvedas de crucería estrellada complejas y un colosal retablo mayor barroco decorado con pinturas de Alonso Sánchez Coello.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40076','iglesia','Convento de Santa Isabel (Ruinas Consolidadas)','Complejo monástico de la orden de las clarisas del siglo XVII edificado en sillería de granito, del que se conserva la fachada de líneas clasicistas de gran sobriedad geométrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40076','ermita','Ermita del Santo Cristo del Caloco','Templo barroco del siglo XVII de planta de cruz latina, que constituye un conjunto monumental exento situado en las lomas de la Sierra de Guadarrama.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40077','monumento','Núcleos de población de Espirdo','El término municipal incluye los siguientes núcleos de población: La Higuera y Tizneros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40077','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra caliza, con una esbelta torre campanario de líneas herrerianas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40078','iglesia','Iglesia Parroquial de Nuestra Señora de la Visitación','Templo del siglo XVI levantado en la comarca de la Tierra de Pinares; de estilo renacentista castellano, destaca por su robusta torre campanario de ladrillo visto y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40079','monumento','Castillo de Fresno y Cerca Vieja','Ruinas de la fortaleza bajomedieval de frontera (siglos XII-XV) mandada edificar por los reyes castellanos sobre un espolón estratégico; conserva lienzos de murallas defensivas de tapial y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40079','iglesia','Iglesia Parroquial de San Nicolás de Bari','Monumental templo del siglo XVI edificado con grandes sillares de piedra de la Serrezuela, con una torre campanario robusta que domina la loma histórica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40080','monumento','Frumales','Frumales','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40082','iglesia','Iglesia Parroquial de Santa Cruz','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica mixta de ladrillo visto y mampostería caliza, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40083','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca de Fuentidueña, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40084','iglesia','Iglesia Parroquial de San Cristóbal','Templo del siglo XVI edificado con fábrica de mampostería caliza y ladrillo visto en la llanura de la Tierra de Pinares, con una robusta torre campanario barroca de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40086','iglesia','Iglesia de Santa María','Monumental obra del siglo XV al XVI de proporciones catedralicias; levantada íntegramente con sillería caliza calavera y ladrillo, destaca por su portada plateresca, sus altísimas bóvedas de crucería estrellada y un impresionante artesonado mudéjar policromado de gran valor artístico en la capilla mayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40086','iglesia','Iglesia del Salvador','Templo mudéjar que conserva un espectacular ábside de ladrillo visto con pisos de arquerías ciegas de gran pureza formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40087','iglesia','Iglesia Parroquial de San Nicolás de Bari','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40092','monumento','Recinto Amurallado de Fuentidueña','Impresionante muralla medieval de sillería de piedra caliza que abraza el casco histórico; conserva casi intacto su perímetro perimetral jalonado por contrafuertes, adarves transitables y monumentales puertas como el Arco de Alfonso VIII y la Puerta del Palacio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40092','monumento','Castillo de Fuentidueña','Ruinas de la fortaleza señorial bajomedieval (siglos XII-XV) que corona el cerro de la villa; conserva un cinturón defensivo masivo de cantería caliza calavera, cubos cilíndricos y estancias de la fortaleza de los Luna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40092','iglesia','Iglesia de San Miguel','Joya del románico clásico (siglo XII) declarada Monumento Nacional; destaca por su espectacular galería porticada norte con arquerías de medio punto sobre columnas pareadas con capiteles magníficamente esculpidos y su ábside semicircular intacto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40092','iglesia','Iglesia de San Martín (Ruinas Consolidadas)','Antiguo templo románico del que procedía el ábside que fue trasladado en el siglo XX al museo de los Claustros de Nueva York; conserva la base de sus muros perimetrales y sepulcros medievales de granito.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40092','monumento','Hospital de la Magdalena','Edificio civil asistencial gótico del siglo XV fundado por la hidalguía local, que conserva su portada apuntada de piedra caliza calavera con ventanas molduradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40093','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado con fábrica de mampostería caliza en la falda de la sierra, con una robusta torre campanario de líneas sencillas y un interior muy austero adaptado al entorno rural castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40094','iglesia','Iglesia Parroquial de San Andrés Apóstol','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40095','iglesia','Iglesia Parroquial de Santa María Magdalena','Templo del siglo XVI levantado en la comarca de la Tierra de Pinares; de estilo renacentista castellano, destaca por su robusta torre campanario de ladrillo visto y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40097','iglesia','Iglesia Parroquial de San Vitores','Edificio barroco rural del siglo XVII levantado con aparejo rústica de piedra caliza de la Serrezuela, con una espadaña de dos vanos adaptada al clima.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40097','monumento','Pueblos en Segovia Fresno de Cantespino es un municipio que se halla localizado cerca del límite oriental de la provinci','Pueblos en Segovia Fresno de Cantespino es un municipio que se halla localizado cerca del límite oriental de la provincia segoviana ( ciudad de Segov...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40100','iglesia','Iglesia Parroquial de San Pedro Templo renacentista del siglo XVI levantado con fábrica de mampostería caliza e hileras','Iglesia Parroquial de San Pedro Templo renacentista del siglo XVI levantado con fábrica de mampostería caliza e hileras de ladrillo; posee una robusta torre campanario de piedra, un ábside poligonal bien conservado y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40101','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Sencillo templo de origen barroco (siglo XVII) edificado con muros de ladrillo y mampostería, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40105','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI edificado con fábrica de mampostería caliza de la cuenca del río Moros, con una robusta torre campanario de líneas sencillas y un interior muy sobrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40106','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del siglo XVI de estilo renacentista rural castellano, edificado con muros de mampostería y ladrillo visto, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40107','iglesia','Iglesia Parroquial de San Pedro','Templo del siglo XVI de gran envergadura con proporciones herrerianas; posee muros recios de sillería de piedra caliza, una fachada rematada por un gran frontón clásico y un retablo mayor barroco de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40110','ermita','Ermita de Nuestra Señora de Salcedón','Joya del románico-mudéjar (siglo XIII); conserva un espectacular ábside de ladrillo visto con pisos de arquerías ciegas de gran pureza formal e hileras de aparejo tradicional castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40110','iglesia','Iglesia Parroquial de El Salvador','Templo renacentista del siglo XVI edificado en piedra caliza con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40111','iglesia','Iglesia Parroquial de San Juan Bautista','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería de piedra caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40113','iglesia','Iglesia Parroquial de San Juan Evangelista','Templo del siglo XVI edificado con grandes bloques de granito berroqueño serrano; posee una espadaña defensiva de dos cuerpos y un coro de madera tallada tradicional en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40115','monumento','Recinto Amurallado de Maderuelo y Arco de la Villa','Espectacular muralla medieval de sillería de piedra caliza del siglo XII que abraza todo el perímetro del cerro;','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40115','iglesia','Iglesia-Castillo de Santa María del Castillo','Templo del siglo XII fortificado, edificado sobre la antigua fortificación que corona la villa; conserva lienzos de murallas defensivas de sillería de granito, una gran torre del homenaje robusta y un interior gótico tardío de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40115','ermita','Ermita de la Vera Cruz','Joya del románico clásico (siglo XII) declarada Monumento Nacional; situada a las afueras, destaca por haber albergado un espectacular conjunto de pinturas murales románicas excepcionales (cuyos originales fueron trasladados al Museo del Prado).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40115','monumento','Torreón del Castillo','Ruinas consolidadas de la torre de vigía y fortificación bajomedieval de planta cuadrada, levantada en mampostería de piedra caliza viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40122','iglesia','Iglesia Parroquial de San Nicolás de Bari','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40124','iglesia','Iglesia de San Esteban','Joya del románico-mudéjar (siglo XIII); conserva un espectacular ábside de ladrillo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40123','monumento','Núcleos de población de Matabuena','El término municipal incluye los siguientes núcleos de población: Matamala y Cañicosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40123','iglesia','Iglesia Parroquial de San Cristóbal','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica rústica de mampostería de piedra caliza, con una espadaña de dos cuerpos adaptada al clima serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40126','iglesia','Iglesia de Santa María','Templo que conserva una cabecera mudéjar del siglo XIII levantada con la técnica de cajones de mampostería e hileras de ladrillo visto; destaca por su arco triunfal apuntado en el interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40127','iglesia','Iglesia Parroquial de San Martín','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca de la Hoz, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40128','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza e hileras de ladrillo, con una robusta torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40129','iglesia','Iglesia Parroquial de Santo Tomás Aquino','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de la Moraña Segoviana, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40130','ermita','Ermita de el Casuar (Ruinas Consolidadas)','Espectaculares ruinas de un templo románico del siglo XII declarado BIC; situado en el fondo de las Hoces del río Riaza, conserva su ábside de sillería caliza calavera y capiteles labrados integrados en el paisaje rocoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40130','iglesia','Iglesia Parroquial de San Andrés','Templo renacentista del siglo XVI edificado en piedra caliza con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40131','iglesia','Iglesia Parroquial de San Pedro','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave y espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40132','iglesia','Santuario de Nuestra Señora de Hornuez','Gran templo barroco del siglo XVIII de planta de cruz latina; catalogado como BIC, destaca por albergar una cúpula sobre pechinas ricamente decorada con yeserías ornamentales y un colosal retablo mayor que cobija a la virgen milagrosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40134','iglesia','Iglesia Parroquial de San Juan Bautista','Monumental templo edificado en el siglo XVI con sillería de piedra caliza; de estilo renacentista castellano, conserva una fachada herreriana limpia, tres amplias naves de gran altura y un espectacular retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40135','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza, con una fachada rematada por un gran frontón clásico y una torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40136','iglesia','Iglesia Parroquial de San Félix','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo y un coro de madera tallada tradicional en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40138','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI con importantes reformas barrocas en el XVII; de tres naves separadas por columnas, destaca por su fábrica mixta de ladrillo y mampostería caliza y un majestuoso retablo mayor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40138','ermita','Ermita del Santo Cristo de la Expiración','Pequeña construcción barroca del siglo XVII exenta, de planta de cajón castellana con porche porticado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40141','iglesia','Iglesia Parroquial de los Santos Justo y Pastor','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería e hileras de ladrillo visto; conserva una sobria torre campanario barroca de ladrillo y un coro de madera tallada tradicional en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40139','monumento','El Martinete de Navafría','Joya de la arqueología industrial preindustrial del siglo XIX; fundición de cobre hidráulica que conserva intacto un colosal mazo de madera accionado por el agua del río, único en Europa por su estado de conservación funcional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40139','iglesia','Iglesia Parroquial de San Lorenzo','Templo del siglo XVI edificado con grandes bloques de granito berroqueño de la sierra, con una espadaña defensiva maciza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40145','monumento','Torre de Santa María','Esbelta torre exenta de planta cuadrada construida en el siglo XII de ladrillo mudéjar con vanos de medio punto, único resto conservado de una antigua iglesia bajomedieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40904','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica rústica de mampostería de granito serrano, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25146','monumento','Núcleos de población de Navès','El término municipal incluye los siguientes núcleos de población: Besora, Tentellatge, Linya y La Valldora.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25146','iglesia','Monasterio de San Pedro de Graudescales','Excepcional y bellísima iglesia románica aislada del siglo XII emplazada en el recóndito desfiladero de la Valldora, la cual destaca por su planta de cruz latina con tres ábsides semicirculares, un cimborrio octogonal alzado sobre trompas y muros de sillería perfecta de piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25146','monumento','Castillo de Besora','Ruinas consolidadas de una estratégica fortaleza defensiva militar del siglo X erigida sobre una colina rocosa de las que subsisten potentes lienzos de muralla de mampostería basta y los cimientos de la torre del homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25146','iglesia','Iglesia de San Miguel de Linya','Edificio religioso románico del siglo XII modificado en la época barroca que presenta un ábside semicircular liso orientado al este, un portal con dovelas de piedra arenisca y un campanario de espadaña de dos vanos ejecutado con aparejo tosco.','inventario_monumentos_pdf');
