INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40150','monumento','Núcleos de población de Orejana','El término municipal incluye los siguientes núcleos de población: El Arenal, Orejanilla, Revilla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40150','iglesia','Iglesia de San Juan Bautista (Revilla de Orejana)','Joya absoluta del románico porticado (siglo XII) declarada Monumento Nacional; destaca por su espectacular galería porticada con arquerías de medio punto sobre columnas pareadas con capiteles decorados con esmero y una robusta torre de sillería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40151','iglesia','Iglesia Parroquial de San Cristóbal','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza e hileras de ladrillo, con una robusta torre campanario barroca de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40901','iglesia','Iglesia Parroquial de San Julián','Templo del siglo XVI edificado con grandes bloques de granito berroqueño de la sierra de Guadarrama, con una espadaña de dos cuerpos de cantería tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40152','monumento','Yacimiento de el Cerro de los Almadenes','Espectacular enclave arqueológico minero con restos de explotación y fundición de cobre que datan desde la época romana hasta la medieval, de gran interés nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40152','iglesia','Iglesia Parroquial de los Santos Justo y Pastor','Monumental templo del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de granito berroqueño; destaca su esbelta torre de tres cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40155','monumento','Núcleos de población de Palazuelos de Eresma','El término municipal incluye los siguientes núcleos de población: Tabanera del Monte, Quitapesares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40155','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería e hileras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40157','iglesia','Iglesia Parroquial de San Vicente','Joya del románico de transición (siglo XII); conserva un espectacular ábside semicircular de sillería caliza limpia y, en su interior, alberga un impresionante conjunto de pinturas murales medievales fragmentarias de gran interés arqueológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40159','iglesia','Iglesia de Nuestra Señora de la Asunción','Joya del románico-mudéjar (siglo XIII); conserva un espectacular ábside de ladrillo visto con pisos de arquerías ciegas de gran pureza formal e hileras de aparejo toledano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40160','iglesia','Iglesia Parroquial de San Nicolás de Bari','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca de la Tierra de Pinares, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40162','monumento','Yacimiento de la Cueva de los Enebralejos','Impresionante santuario arqueológico prehistórico del Calcolítico (Edad del Cobre); conserva en su interior una necrópolis con grabados rupestres parietales, pinturas esquemáticas y enterramientos en cista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40162','iglesia','Iglesia Parroquial de San Juan Bautista','Templo monumental neoclásico del siglo XVIII edificado en piedra de sillería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40163','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica mixta de ladrillo visto y mampostería caliza, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40164','iglesia','Iglesia de San Pedro (Convento de la Santísima Trinidad)','Joya del románico-mudéjar (siglo XII); de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40181','monumento','Núcleos de población de Real Sitio de San Ildefonso','El término municipal incluye los siguientes núcleos de población: Valsaín y Riofrío.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40181','palacio','Palacio Real de La Granja','Obra cumbre de la arquitectura palaciega barroca europea encargada por el rey Felipe V en el siglo XVIII; diseñado por arquitectos reales franceses e italianos (Juvarra y Sachetti), destaca por su majestuosa fachada de piedra caliza y mármol, la Colegiata con la cripta real de los primeros Borbones y un interior deslumbrante de frescos y tapices.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40181','monumento','Jardines y Fuentes Monumentales de La Granja','Espectacular parque paisajístico de diseño versallesco del siglo XVIII; alberga una red monumental de fuentes mitológicas de plomo pintado que imita bronce (La Fama, Los Baños de Diana, El Caballo de Troya) accionadas por un sistema de presión hidráulica preindustrial único en el mundo por su estado funcional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40181','monumento','Real Fábrica de Cristales de La Granja','Monumental e histórico edificio industrial neoclásico del siglo XVIII fundado para la manufactura de vidrios reales de la corte; conserva sus hornos de ladrillo, naves de sillería caliza e infraestructuras preindustriales intactas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40181','palacio','Palacio Real de Riofrío','Palacio residencial de recreo neoclásico del siglo XVIII diseñado por encargo de Isabel de Farnesio; de proporciones cúbicas perfectas de influencia italiana, presenta fachadas limpias de color rosa cantera rodeadas por un inmenso bosque forestal protegido.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40181','palacio','Palacio de Valsaín (Ruinas Consolidadas)','Vestigios del primer palacio residencial real campestre de la dinastía de los Austrias (siglo XVI) diseñado por Gaspar de Vega por orden de Felipe II, destruido por incendios históricos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40166','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI levantado en la comarca de la Tierra de Pinares; de estilo renacentista castellano, destaca por su robusta torre campanario de ladrillo visto y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40170','monumento','Plaza Mayor de Riaza','Espectacular plaza elíptica y porticada de origen medieval y renacentista; de estructura irregular adaptada para coso taurino tradicional, está rodeada de casas de dos y tres plantas con balconadas de madera sustentadas por pies derechos de piedra y madera castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40170','iglesia','Iglesia Parroquial de Nuestra Señora del Manto','Monumental templo neoclásico del siglo XVIII edificado en piedra de sillería caliza de la Serrezuela; destaca por su gran torre campanario de tres cuerpos que domina el casco histórico serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40170','ermita','Ermita de San Juan','Pequeño templo barroco del siglo XVII situado en un paraje natural periférico, ejemplo de devoción popular ganadera de la sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40171','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta torre campanario de líneas sencillas y un interior muy austero adaptado al entorno rural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40172','iglesia','Iglesia Parroquial de San Miguel Arcángel','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica rústica de mampostería de piedra caliza, con una espadaña de dos cuerpos adaptada al clima de montaña de la sierra de Ayllón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40173','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra caliza, con una esbelta torre campanario de líneas herrerianas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40174','iglesia','Monasterio de Santa María la Real (Coto de San Bernardo)','Impresionante complejo monástico cisterciense fundado en el siglo XII (1141) por Alfonso VII; conserva una monumental iglesia románica y parte de sus estancias de sillería caliza calavera, famoso históricamente porque su claustro y refectorio fueron trasladados en el siglo XX a Miami (EE.UU.).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40174','iglesia','Iglesia Parroquial de San Martín','Templo del siglo XVI edificado con fábrica de sillería y ladrillo visto castellano, con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40174','ermita','Ermita de San Miguel','Oratorio románico del siglo XII situado en lo alto de un cerro, que destaca por su ábside semicircular limpio y canecillos labrados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40176','iglesia','Iglesia de San Baudilio (Samboal)','Joya absoluta del románico-mudéjar de la Tierra de Pinares (siglo XII); declarada BIC, destaca por su espectacular ábside semicircular de ladrillo visto con tres pisos de arquerías ciegas superpuestas y dobles, y una esbelta torre campanario mudéjar exenta de gran valor formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40177','iglesia','Iglesia Parroquial de San Cristóbal','Templo del siglo XVI con importantes modificaciones barrocas; construido con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40182','iglesia','Iglesia Parroquial de San Martín (San Martín)','Templo renacentista del siglo XVI levantado con muros de mampostería caliza y ladrillo visto, con una robusta torre campanario de líneas castellanas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40184','iglesia','Iglesia Parroquial de San Pedro','Joya del románico porticado (siglo XII); conserva una espectacular galería porticada meridional con arquerías de medio punto sobre columnas pareadas con capiteles magníficamente esculpidos con motivos zoomorfos, y una torre fortificada de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40179','iglesia','Iglesia Parroquial de Tomás Apóstol','Templo del siglo XVI levantado en la comarca de la Tierra de Pinares; de estilo renacentista castellano, destaca por su robusta torre campanario de ladrillo visto y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40180','iglesia','Iglesia Parroquial de San Bartolomé','Espectacular templo del siglo XVIII de estilo barroco clasicista madrileño; destaca por sus colosales dimensiones, su planta basilical de gran altura ejecutada en ladrillo y sillería caliza, y un interior decorado con ricas yeserías ornamentales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40189','iglesia','Iglesia Parroquial de San Juan Bautista','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza, con una fachada rematada por un gran frontón clásico y una torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40190','iglesia','Iglesia Parroquial de Santo Domingo','Templo del siglo XVI edificado con fábrica de mampostería caliza en la cuenca del río Pirón, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40191','monumento','Núcleos de población de Santo Tomé del Puerto','El término municipal incluye los siguientes núcleos de población: Villarejo, Rosuero y Siguero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40191','iglesia','Iglesia de la Natividad (Siguero)','Templo que conserva trazas del románico de transición (siglo XII) en su portada abocinada y contrafuertes de sillería caliza calavera en los accesos al puerto de Somosierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40192','iglesia','Iglesia Parroquial de San Pedro','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica de ladrillo visto y cajones de mampostería caliza, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40193','iglesia','Convento de Nuestra Señora de la Hoz (Ruinas Consolidadas)','Espectaculares ruinas de una abadía franciscana fundada en el siglo XIII (1231) declarada BIC; situada en el fondo de un meandro vertical de las Hoces del río Duratón, conserva sus muros de sillería caliza y arcos fajones apuntados integrados de forma increíble en el paisaje rocoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40193','iglesia','Iglesia Parroquial de San Miguel','Templo renacentista del siglo XVI edificado en piedra caliza con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40195','iglesia','Iglesia de San Salvador','Obra maestra del románico temprano castellano (siglo XI, año 1093) declarada Monumento Nacional; considerada el templo románico porticado más antiguo de la provincia, destaca por su galería porticada norte, su ábside semicircular exento de sillería impecable y una robusta torre campanario exenta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40195','monumento','Recinto Amurallado de Sepúlveda y Puertas','Impresionante muralla medieval de sillería de piedra caliza que abraza el casco histórico sobre el desfiladero; conserva siete monumentales puertas intactas (como la Puerta del Ecce Homo y la Puerta de la Fuerza) y tramos de adarves defensivos transitables.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40195','iglesia','Iglesia de los Santos Justo y Pastor (Museo de los Fueros)','Templo románico de transición (siglo XII-XIII) clasificado como BIC; posee tres naves de gran altura y una cripta subterránea sepulcral de gran valor arqueológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40195','iglesia','Santuario de Nuestra Señora de la Peña','Iglesia románica del siglo XII situada en el borde del precipicio de las hoces; destaca por su portada abocinada con arquivoltas labradas y un tímpano esculpido único en la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40195','palacio','Palacio de los Proaño (Casa del Moro)','Edificio civil señorial plateresco del siglo XVI con una grandiosa fachada simétrica que alberga una colosal portada y escudos de armas nobiliarios tallados en piedra caliza calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40198','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta torre campanario de líneas sencillas y un interior muy austero adaptado al entorno rural castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40199','iglesia','Iglesia Parroquial de San Miguel','Obra maestra indiscutible del románico clásico porticado (siglo XII) declarada Monumento Nacional; destaca por su espectacular galería porticada meridional con arquerías de medio punto apoyadas sobre columnas geminadas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40200','iglesia','Iglesia Parroquial de Santa María','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de las llanuras, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40201','iglesia','Iglesia Parroquial de San Pedro Apóstol','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería en el límite de la comarca de la Moraña Segoviana, con un interior sobrio de una sola nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40206','monumento','Núcleos de población de Torre Val de San Pedro','El término municipal incluye los siguientes núcleos de población: Torre Val, La Salceda y Valle de San Pedro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40206','iglesia','Iglesia Parroquial de San Pedro (Valle de San Pedro)','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una robusta torre campanario de piedra de sillería serrana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40202','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza de la Serrezuela, con una fachada rematada por un gran frontón clásico y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40203','monumento','Núcleos de población de Torrecaballeros','El término municipal incluye los siguientes núcleos de población: Cabanillas del Monte, Aldehuela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40203','iglesia','Iglesia de San Miguel (Cabanillas del Monte)','Joya del románico de transición (siglo XII); conserva una espectacular galería porticada de medio punto y muros de sillería caliza calavera, vinculada históricamente al paso de los esquileos de la Mesta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40203','iglesia','Iglesia Parroquial de San Nicolás de Bari (Torrecaballeros)','Templo renacentista del siglo XVI edificado con grandes bloques de granito berroqueño serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40204','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado con fábrica de mampostería caliza y ladrillo en la llanura de la Tierra de Pinares, con una robusta torre campanario barroca de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40208','iglesia','Castillo de Turégano e Iglesia de San Miguel','Obra maestra absoluta de la arquitectura militar y religiosa bajomedieval (siglos XII-XV) encargada por los obispos de Segovia; colosal fortaleza de planta cuadrada construida en sillería caliza calavera que abraza e integra por completo en su interior las tres naves de la iglesia románica de San Miguel, destacando una imponente fachada-torre del homenaje fortificada con matacanes y una espadaña defensiva massiva única en España.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40208','monumento','Plaza Mayor de Turégano (Plaza de los Cien Postes)','Espectacular plaza porticada castellana de origen medieval; de planta rectangular irregular, está rodeada de casas tradicionales con soportales sustentados por columnas de piedra caliza y madera calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40208','iglesia','Iglesia de Santiago','Templo románico de transición (siglo XII) profundamente reformado; alberga en su interior un presbiterio con un retablo de piedra caliza policromado de gran valor para la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40210','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado con fábrica de mampostería caliza de la Serrezuela, con una robusta torre campanario de líneas sencillas y un interior muy austero adaptado al entorno rural castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40211','monumento','Núcleos de población de Valdeprados','El término municipal incluye los siguientes núcleos de población: Guijasalbas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40211','monumento','Torreón de los Condes de Puñonrostro','Espectacular torre del homenaje bajomedieval del siglo XV; construida con recia mampostería de piedra caliza y esquinas de sillería, conserva saeteras, ventanas ojivales y un carácter netamente defensivo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40211','iglesia','Iglesia Parroquial de Santa Eulalia','Templo renacentista del siglo XVI edificado en piedra caliza con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40213','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave y espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40218','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza e hleras de ladrillo, con una robusta torre campanario de líneas sencillas y restos góticos en el presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40219','iglesia','Iglesia Parroquial de Santo Tomás Apóstol','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de la cuenca de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40220','monumento','Núcleos de población de Valleruela de Pedraza','El término municipal incluye los siguientes núcleos de población: Tejadilla y Berzal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40220','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta torre campanario de líneas sencillas y un interior muy austero adaptado al entorno rural castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40221','iglesia','Iglesia Parroquial de San Antonio de Padua','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica de ladrillo visto y cajones de mampostería caliza, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40214','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo edificado en el siglo XVI con sillería de piedra caliza; de estilo renacentista castellano, conserva una fachada herreriana limpia, tres amplias naves de gran altura y un espectacular retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40215','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre campanario de piedra de sillería de la Serrezuela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40216','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Monumental templo del siglo XVI edificado con grandes sillares de piedra caliza; de estilo renacentista herreriano, destaca por su esbelta torre campanario de tres cuerpos y un presbiterio con bóvedas de crucería góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40222','iglesia','Iglesia Parroquial de San Juan Bautista','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza, con una fachada rematada por un gran frontón clásico y una torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40223','monumento','Los Hornos de Cal de Vegas (Zamarramala)','Impresionante conjunto de patrimonio industrial etnológico que conserva una red de colosales hornos preindustriales de piedra caliza del siglo XVI encargados','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40223','iglesia','Iglesia Parroquial de Tomás Apóstol','Templo del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de granito berroqueño; destaca su ábside poligonal con contrafuertes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40225','catedral','Iglesia Parroquial de San Sebastián (La Catedral de la Sierra)','Obra maestra indiscutible de la arquitectura clasicista y herreriana del siglo XVI proyectada por Rodrigo Gil de Hontañón y continuada por los maestros de El Escorial; colosal templo de proporciones catedralicias construido íntegramente en sillería de granito berroqueño, destacando su imponente espacio interior de tres naves de igual altura (planta de salón), colosales columnas toscanas de piedra y un majestuoso retablo mayor barroco de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40225','monumento','Monumento de los Lavaderos de la Mesta','Edificio civil de arquitectura preindustrial del siglo XVIII de piedra berroqueña, ligado históricamente a la esquila y comercio textil de la lana nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40228','iglesia','Iglesia Parroquial de San Sebastián','Templo del siglo XVI levantado en la comarca de la Tierra de Pinares; de estilo renacentista castellano, destaca por su robusta torre campanario de ladrillo visto y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40229','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica rústica de mampostería de piedra caliza de la Serrezuela, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40230','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza e hleras de ladrillo, con una robusta torre campanario barroca de líneas sencillas y un interior muy austero adaptado a las llanuras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40231','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre campanario de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40233','iglesia','Iglesia de San Vicente','Joya del románico-mudéjar (siglo XIII); conserva un espectacular ábside de ladrillo visto con tres pisos de arquerías ciegas de gran pureza formal e hleras de aparejo toledano castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40234','iglesia','Iglesia Parroquial de la Exaltación de la Santa Cruz','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de la cuenca de la Tierra de Pinares, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90129','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica mixta de mampostería y ladrillo siguiendo la tradición constructiva de la cuenca del Jalón; presenta un interior sobrio de nave única cubierto con bóvedas de crucería estrellada góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90130','iglesia','Iglesia Parroquial de San Miguel Arcángel','Espléndido templo barroco del siglo XVIII diseñado bajo la influencia de los talleres reales de Zaragoza; destaca por sus colosales dimensiones, sus tres amplias naves de gran altura, una cúpula sobre pechinas monumental y una fachada flanqueada por dos torres simétricas de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90131','iglesia','Iglesia Parroquial de Nuestra Señora del Rosario','Edificio del siglo XVI de estilo gótico-renacentista rural aragonés, construido con fábrica mixta de ladrillo y cajones de mampostería caliza, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49001','palacio','Palacio Abacial de Ainzón','Edificio civil señorial de arquitectura renacentista aragonesa del siglo XVI construido por los abades de Veruela; presenta una fachada de ladrillo con la clásica galería de arquerías de medio punto corrida y un porche porticado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49001','iglesia','Iglesia Parroquial de Nuestra Señora de la Piedad','Templo barroco del siglo XVIII con un rico patrimonio de retablos en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49001','monumento','Arco de San Antón','Antigua puerta de acceso fortificada del recinto amurallado medieval del siglo XIV que protegía la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90132','iglesia','Iglesia Parroquial de Santiago Apóstol','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con ladrillo y mampostería, con un interior sobrio de una sola nave y espadaña tradicional adaptada al clima de la comarca de Cariñena.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13008','iglesia','Iglesia Parroquial de San Pedro Apóstol','Obra maestra indiscutible del arte mudéjar aragonés (siglo XIV) declarada BIC; destaca por su espectacular Torre Campanario Mudéjar de planta octogonal construida íntegramente en ladrillo visto, decorada de forma inverosímil con frisos de esquinillas, arcos de herradura','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13008','monumento','Colegio de la Compañía de Jesús (Casa de la Cultura)','Edificio barroco del siglo XVIII de grandes proporciones con un bellísimo claustro porticado interior de ladrillo y una iglesia jesuítica de líneas sobrias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13008','ermita','Ermita de Nuestra Señora del Castillo','Santuario edificado en lo alto de un cerro, de planta barroca con muros de ladrillo toledano y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90133','iglesia','Iglesia Parroquial de San Lorenzo','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto sobre zócalo de piedra, con una fachada rematada por un gran frontón clásico y una torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90134','iglesia','Iglesia de la Asunción de Nuestra Señora','Joya mudéjar del siglo XIV que conserva un ábside poligonal de ladrillo visto profusamente decorado con frisos de arquerías ciegas y dientes de sierra, y una torre campanario asociada a la Orden de San Juan de Jerusalén.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90135','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo del siglo XVI edificado con fábrica de mampostería y ladrillo visto en el Valle del Huecha, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90136','iglesia','Iglesia Parroquial de Nuestra Señora de los Ángeles','Templo barroco del siglo XVII de planta de cajón con muros de ladrillo y mampostería caliza en la comarca de la Ribera Baja del Ebro, con una sobria torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90136','monumento','El Castillo de Alborge (Ruinas)','Vestigios y restos de un antiguo bastión fortificado bajomedieval situado sobre el cerro que domina el casco urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90137','iglesia','Iglesia Parroquial de la Santísima Trinidad','Templo herreriano del siglo XVI edificado en ladrillo visto de líneas aragonesas tradicionales; las crónicas históricas y literarias vinculan los palacios de la villa con la Ínsula Barataria de Don Quijote de la Mancha.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90138','monumento','Casco de Alcalá (Conjunto de la Villa)','Todo el pueblo funciona como monumento defensivo medieval;','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90138','iglesia','Iglesia Parroquial de la Asunción','Templo gótico tardío del siglo XVI edificado en piedra y ladrillo mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90139','iglesia','Iglesia Parroquial de Nuestra Señora de la Leche','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica rústica de mampostería caliza, con una espadaña de dos cuerpos adaptada al extremo clima de las lomas de Ariza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90140','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de las llanuras, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90141','monumento','Castillo de Alfajarín','Impresionante fortaleza bajomedieval de origen musulmán (siglo XII) reconstruida por los reinos cristianos sobre un crestón rocoso de yesos; conserva una colosal Torre del Homenaje de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90141','iglesia','Iglesia Parroquial de San Miguel Arcángel','Joya del mudéjar aragonés (siglo XIV) catalogada como BIC; destaca por su espectacular decoración exterior de paños de ladrillo resaltado, frisos de esquinillas y una torre campanario esbelta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90142','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo del siglo XVI levantado con la técnica de cajones de mampostería e hileras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo de la llanura de Cariñena.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90143','iglesia','Iglesia Parroquial de San Pedro','Templo del siglo XVI edificado con fábrica de mampostería caliza y ladrillo en la cuenca del río Ebro, con una robusta torre campanario barroca de líneas sencillas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90144','monumento','Castillo de Alhama (El Castillazo)','Fortaleza bajomedieval de frontera (siglos XII-XIV) erigida sobre una cresta de roca viva; conserva una imponente torre de sillería caliza y muros defensivos almenados que controlaban el paso del Jalón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90144','monumento','Termas y Balnearios Históricos','Espacio de patrimonio arquitectónico e hidráulico de origen romano; conserva el espectacular Lago Termal Natural, una infraestructura única en España por donde emanan aguas mineromedicinales a temperatura constante.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90144','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo barroco del siglo XVII de ladrillo visto con yeserías interiores policromas de tradición mudéjar aragonesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90145','iglesia','Iglesia Parroquial de San Agustín','Sencillo templo de arquitectura barroca popular (siglo XVIII) construido con ladrillo y mampostería basta en las llanuras agrícolas del Campo de Belchite.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90146','ermita','Ermita de San Antón y San Juan','Gran santuario barroco del siglo XVII de planta de cruz latina erigido en lo alto de una loma en los Monegros; destaca por albergar una cúpula sobre pechinas ricamente decorada con yeserías ornamentales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90146','iglesia','Iglesia Parroquial de Nuestra Señora de la Luz','Templo gótico-renacentista del siglo XVI de tres naves, construido en sillería caliza calavera y ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90147','monumento','Presa Romana de Almonacid','Obra cumbre de la ingeniería civil hidráulica romana (siglo I d.C., época del emperador Augusto) construida sobre el río Aguasvivas; colosal e impresionante muro de contención de más de 34 metros de altura ejecutado en opus caementicium y revestido de sillería caliza, considerada la presa romana más alta conservada en todo el mundo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90147','iglesia','Iglesia Parroquial de Santa María','Templo renacentista del siglo XVI con una espectacular torre mudéjar de ladrillo con vanos de medio punto y paños resaltados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90148','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo edificado en el siglo XVIII con sillería de piedra caliza y ladrillo; de estilo barroco clasicista, conserva una fachada herreriana limpia, tres amplias naves de gran altura y una espectacular torre del campanario de ladrillo mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90149','iglesia','Iglesia de la Asunción de Nuestra Señora y Torre Mudéjar','Monumental templo del siglo XVIII diseñado por el arquitecto real Ventura Rodríguez; posee una impresionante Torre Campanario Mudéjar exenta del','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90149','palacio','Casona de los Palacios de la Orden de San Juan','Complejo de arquitectura civil y militar señorial del siglo XV; conserva suntuosas fachadas de ladrillo con portalones de medio punto de sillería caliza con ventanas molduradas y escudos nobiliarios de los caballeros hospitalarios.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90149','ermita','Ermita de Nuestra Señora de Cabañas','Templo de origen románico de transición (siglo XIII); conserva en su presbiterio pinturas murales góticas excepcionales y una techumbre mudéjar de madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90150','iglesia','Iglesia Parroquial de Nuestra Señora de los Ángeles','Templo renacentista del siglo XVI edificado en la comarca de Valdejalón; de planta castellano-aragonesa de ladrillo visto y mampostería, conserva una sobria espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90151','palacio','Palacio de los Sanjuanistas (Palacio del Temple)','Impresionante e histórico complejo palaciego y fortificado fundado en el siglo XII por la Orden de los Templarios y ampliado en el XIV por la Orden de Malta; edificado en sillería caliza y ladrillo, destaca por su patio de armas amurallado, sus salas con techumbres artesonadas de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90151','iglesia','Iglesia Parroquial de San Miguel','Templo mudéjar del siglo XIV adosado de forma unificada al complejo del palacio señorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90152','iglesia','Iglesia Parroquial de San Blas','Templo románico de transición (siglo XIII) edificado en piedra caliza; alberga en su presbiterio el colosal Retablo de San Blas, obra cumbre indiscutible del pintor gótico Blasco de Grañén, compuesto por decenas de tablas pintadas con pan de oro de una riqueza artística y conservación intacta únicas en Europa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90152','monumento','Castillo de Anento','Ruinas de la fortaleza bajomedieval del siglo XIV erigida en sillería; conserva tramos de sus murallas defensivas de gran espesor, cubos defensivos y torreones que protegían la villa en el fondo del valle.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90153','iglesia','Iglesia de Nuestra Señora del Castillo','Obra maestra absoluta del arte mudéjar aragonés (siglo XIV) declarada BIC; destaca por su espectacular Fachada-Ábside Exterior construida íntegramente en ladrillo visto profusamente decorada con tapices de rombos, esquinillas, frisos de arquerías ciegas entrelazadas y un espléndido despliegue de azulejos y cerámica vidriada','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90154','monumento','Castillo de Arándiga','Impresionante fortaleza bajomedieval de origen musulmán (siglo XII) que corona de forma espectacular un afilado crestón rocoso sobre los ríos Aranda y Jalón; conserva una imponente torre defensiva de sillería caliza y adarves colgados.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90154','iglesia','Iglesia Parroquial de San Martín','Templo barroco del siglo XVII de ladrillo visto con una torre de traza castellana tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90155','iglesia','Iglesia Parroquial de Santa Ana','Templo que combina una cabecera del gótico tardío (siglo XV) con reformas renacentistas, construido en aparejo de mampostería caliza y ladrillo en la comarca de las Cinco Villas, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49064','monumento','Castillo de Ariza','Ruinas monumentales de la fortaleza bajomedieval del siglo XI que corona de forma espectacular la muela de la villa; conserva cubos defensivos circulares y lienzos de murallas de sillería','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49064','monumento','Puente Medieval sobre el río Jalón','Espectacular estructura de ingeniería civil construida en el siglo XIV en sillería de piedra caliza; presenta un perfil en lomo de asno con grandes arcos asimétricos de medio punto y monumentales tajamares triangulares exentos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49064','iglesia','Iglesia Parroquial de Santa María','Templo monumental del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares calveros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90156','iglesia','Iglesia Parroquial de San Martín','Templo gótico del siglo XIV edificado con grandes bloques de piedra caliza serrana; posee muros limpios adaptados al clima de la comarca de la Jacetania y una robusta torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90156','monumento','Casco Histórico de Artieda','Conjunto de calles porticadas y casas señoriales de cantería de piedra con los escudos esculpidos en las fachadas, representativo del Pirineo aragonés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90157','iglesia','Iglesia Parroquial de Santa María','Joya del románico de transición de las Cinco Villas (siglo XII); conserva un ábside semicircular intacto con capiteles labrados con esmero y una portada abocinada de sillería de piedra caliza calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90158','iglesia','Iglesia de Santa María y Torre Mudéjar','Monumental templo del gótico tardío (siglo XV) que alberga la espectacular Torre Campanario Mudéjar del siglo XIII (BIC); de planta cuadrada construida íntegramente en ladrillo visto de excelente factura, destaca por sus muros exteriores decorados como un tapiz con frisos de esquinillas, rombos y azulejería polícroca, rematada por un carácter defensivo militar con saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90158','monumento','Castillo de Ateca (Fuerte de Ateca)','Fortaleza señorial e histórica cuyos tramos más antiguos datan del califato andalusí (siglo X) y reformado en los siglos XIV y XV; conserva muros almenados de gran espesor y una gran torre del homenaje de mampostería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22041','monumento','Yacimiento de la Villa Romana de La Malena','Impresionante conjunto de la ciudad y gran villa residencial romana (siglos III-IV d.C.); conserva el espectacular Mosaico de las Nereidas, uno de los mosaicos geométricos y figurativos más grandes de la provincia, que atestigua el refinamiento del Imperio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22041','iglesia','Iglesia Parroquial de Nuestra Señora de la Piedad','Templo mudéjar y renacentista del siglo XVI construido en ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90159','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza, con una fachada rematada por un gran frontón clásico y una espadaña castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90160','iglesia','Iglesia de los Santos Julián y Basilisa','Joya absoluta del románico primitivo de influencia lombarda (siglo XI) declarada Monumento Nacional; destaca por la pureza de sus líneas, su ábside semicircular de sillería impecable con columnas adosadas y capiteles; de aquí procedía el espectacular ciclo de pinturas murales románicas que hoy se expone en el Museo Diocesano de Jaca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90161','iglesia','Iglesia Parroquial de la Virgen del Rosario','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con ladrillo visto y cajones de mampostería caliza, con un interior sobrio de una sola nave y espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50043','monumento','Núcleos de población de Bárboles','El término municipal incluye los siguientes núcleos de población: Oitura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50043','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo de la cuenca del Jalón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50044','iglesia','Iglesia Parroquial de Nuestra Señora de los Ángeles','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra, con una esbelta torre campanario de ladrillo mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50045','monumento','Ruinas del Pueblo Viejo de Belchite (Monumento Memorial)','Espectacular y colosal conjunto de ruinas urbanas consolidadas que atestigua de forma sobrecogedora los efectos de los combates de 1937; conserva el trazado de las calles de ladrillo, fachadas palaciegas y cráteres de artillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50045','iglesia','Iglesia de San Martín de Tours','Monumental templo del gótico mudéjar (siglo XIV) integrado en las ruinas del Pueblo Viejo; conserva su imponente ábside de ladrillo visto con arquerías ciegas y una esbelta torre campanario mudéjar decorada con paños resaltados acribillada por metralla.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50045','iglesia','Torre e Iglesia del Reloj','Torre civil de planta cuadrada construida en el siglo XV de ladrillo mudéjar con vanos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50045','iglesia','Santuario de Nuestra Señora del Pueyo','Gran complejo barroco del siglo XVIII situado a las afueras, de ladrillo con una cúpula sobre pechinas de gran valor espacial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50046','palacio','Castillo del Palacio y Recinto Amurallado','Fortaleza bajomedieval (siglos XII-XV) mandada edificar por los reinos cristianos sobre el espolón estratégico de la muela; conserva una imponente torre del homenaje de sillería caliza y lienzos amuralladas con cubos defensivos enteros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50046','iglesia','Iglesia de San Miguel y Torre Mudéjar','Joya del mudéjar aragonés (siglo XIV) clasificada como BIC; destaca por su gran ábside de ladrillo visto profusamente decorado con frisos de esquinillas y una torre campanario esbelta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50047','monumento','Castillo de Berdejo','Impresionante fortaleza bajomedieval de frontera (siglos XII-XIV) emplazada de forma espectacular sobre un afilado crestón rocoso que vigilaba el río Manubles; conserva una imponente torre de sillería caliza y adarves defensivos intactos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50047','iglesia','Iglesia Parroquial de San Millán','Templo renacentista del siglo XVI edificado en piedra caliza con una robusta torre campanario de líneas herrerianas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50048','monumento','Castillo de Berrueco','Ruinas consolidadas de una pequeña fortaleza bajomedieval (siglo XIV) de mampostería de piedra caliza viva, que corona el cerro dominando el paisaje natural de la laguna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50901','monumento','Castillo de Biel (Torre del Homenaje)','Obra maestra de la arquitectura militar románica del siglo XI (año 1070) encargada por el rey Sancho Ramírez; colosal y espectacular torre del homenaje de sillería caliza de gran espesor y más de 30 metros de altura, que conserva saeteras, ventanas germinadas y muros almenados intactos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50901','iglesia','Iglesia Parroquial de San Martín','Templo de estilo gótico puro (siglo XIV) edificado en sillería exenta; presenta una imponente fachada unificada históricamente al complejo del castillo y un interior de gran valor con bóvedas de crucería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50901','monumento','Barrio Judío de Biel (Judería)','Uno de los mejores conjuntos de arquitectura popular medieval de las Cinco Villas; conserva un laberinto de calles empedradas con viviendas tradicionales de mampostería, adobe y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50050','monumento','Castillo de los Guzmanes','Impresionante fortaleza bajomedieval de frontera (siglos XII-XIV) colgada de forma inverosímil sobre el precipicio de la muela rocosa sobre el río Manubles; conserva una imponente torre de sillería caliza y adarves defensivos intactos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50050','iglesia','Iglesia Parroquial de San Miguel','Templo renacentista del siglo XVI de piedra de cantería con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50051','iglesia','Iglesia Parroquial de San Miguel','Joya absoluta del románico clásico (siglo XII) declarada Monumento Nacional; destaca por su espectacular portada meridional con un tímpano esculpido magistralmente por el Maestro de Agüero que representa la Epifanía y canecillos de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50051','palacio','Palacio de los Condes de Aranda y Torre del Palacio','Edificio civil señorial barroco del siglo XVIII adosado a una imponente torre del homenaje bajomedieval del siglo XIV de planta cuadrada construida en sillería de piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50052','iglesia','Iglesia Parroquial de San Juan Bautista','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con ladrillo y mampostería caliza, con un interior sobrio de una sola nave y espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50053','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza e hileras de ladrillo visto de la cuenca del Ebro, con una robusta torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50054','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo del siglo XVI edificado con fábrica de piedra caliza de la Serrezuela en la frontera castellanoaragonesa; presenta una sólida torre campanario de líneas sencillas y un interior con bóvedas de crucería góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50055','iglesia','Excolegiata de Santa María','Majestuoso templo iniciado en el gótico (siglo XIV) que fusiona el mudéjar y el barroco clasicista; de proporciones catedralicias, posee','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50055','palacio','Palacio de los Sanclemente (Casa de las Conchas)','Obra maestra de la arquitectura civil renacentista aragonesa (siglo XVI); palacio levantado en impecable ladrillo visto, destacando su espectacular fachada decorada con motivos geométricos y la clásica galería de arquerías de medio punto corrida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50055','iglesia','**Convento de la Concepción','**Convento de la Concepción (Monjas Claris','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50068','palacio','Castillo-Palacio de los Priores','Imponente fortaleza señorial bajomedieval (siglos XIV-XVI) erigida en piedra caliza negra de sus propias canteras; combina elementos del gótico aragonés y del renacimiento, con un patio porticado y una gran torre del homenaje almenada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50068','iglesia','Iglesia Parroquial de San Bartolomé','Templo neoclásico del siglo XVIII que alberga en su interior el famoso Santo Cristo de Calatorao, una talla gótica del siglo XIV de gran valor devocional y artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50067','iglesia','Colegiata de Santa María la Mayor','Joya del mudéjar aragonés declarada Patrimonio de la Humanidad; destaca su colosal torre octogonal de ladrillo visto con filigranas geométricas y un impresionante ábside mudéjar, además de su monumental portada renacentista de alabastro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50067','monumento','Recinto Fortificado Islámico (Castillo de Ayud)','El complejo defensivo de origen árabe más antiguo de la','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50067','iglesia','Colegiata del Santo Sepulcro','Casa matriz de la Orden del Santo Sepulcro en España; magnífico templo barroco del siglo XVII de planta centralizada con una gran cúpula sobre pechinas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50067','iglesia','Iglesia de San Andrés','Templo gótico-mudéjar que posee una esbelta torre octogonal mudéjar con decoración de rombos y arquerías ciegas de ladrillo visto, uno de los iconos del perfil urbano bilbilitano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50067','monumento','Yacimiento Arqueológico de Augusta Bilbilis','Restos consolidados de la ciudad romana (siglo I d.C.) a las afueras; conserva el foro monumental, el teatro excavado en la ladera y el complejo de termas públicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50069','iglesia','Iglesia Colegiata de Nuestra Señora de los Reyes','Templo monumental que combina elementos platerescos y renacentistas (siglo XVI); destaca por su imponente torre campanario de piedra caliza, sus bóvedas de crucería estrellada y un valioso retablo mayor renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50070','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica rústica de mampostería caliza, que conserva una sólida torre defensiva medieval reaprovechada como campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50070','iglesia','Iglesia Parroquial de San Juan Bautista','Templo barroco del siglo XVII de planta de cruz latina, construido con muros de mampostería y ladrillo castellano, con una fachada rematada por un sobrio frontón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50072','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo barroco del siglo XVII edificado en ladrillo visto sobre una base de sillería; destaca por su decoración interior con ricas yeserías mudéjares de tradición aragonesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50073','iglesia','Iglesia de la Asunción de Nuestra Señora','Monumental templo de proporciones catedralicias construido en el siglo XVII; conserva una robusta torre campanario de origen gótico (siglo XIV) levantada en sillería de piedra caliza calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50073','monumento','Torre de las Monjas y Murallas','Restos del antiguo recinto amurallado bajomedieval de la villa, destacando el torreón fortificado de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50074','iglesia','Colegiata de Santa María la Mayor del Pilar','Obra cumbre del gótico puro aragonés (siglos XIV-XV) declarada Monumento Nacional; de proporciones massivas en sillería caliza, destaca por su portada ojival, sus altísimas columnas y por haber sido el escenario del célebre Compromiso de Caspe en 1412.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50074','palacio','Castillo del Compromiso (Palacio de los Bailíos)','Fortaleza bajomedieval de la Orden de San Juan de Jerusalén, rehabilitada, con ventanales ojivales y muros almenados que dominan el valle del Ebro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50074','ermita','Ermita de Santa María de Horta (Trasladada)','Templo románico del siglo XIII que fue trasladado piedra a piedra a las afueras de la ciudad debido a la construcción del embalse de Mequinenza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50075','iglesia','Iglesia Parroquial de San Cristóbal','Templo barroco rural (siglo XVII) edificado con muros bastos de mampostería caliza, con una espadaña tradicional de dos vanos para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50076','iglesia','Iglesia Parroquial de El Salvador','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50077','iglesia','Iglesia Parroquial de Santa María la Mayor','Templo que conserva una notable torre de estilo mudéjar aragonés (siglo XIV) levantada en ladrillo visto con decoración de arquerías ciegas y frisos en diente de sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50078','iglesia','Iglesia Parroquial de San Juan Bautista','Templo románico del siglo XII (BIC) que alberga en su altar mayor un espectacular Sarcófago Paleocristiano del siglo IV d.C. tallado en mármol de Carrara con relieves de escenas bíblicas, considerado una de las mayores joyas arqueológicas de Aragón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50078','monumento','Castillo de Castiliscar','Ruinas de la fortaleza bajomedieval de frontera de la comarca de las Cinco Villas, de mampostería caliza calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50079','iglesia','Iglesia de Santa Tecla','Obra maestra del mudéjar aragonés (siglo XIV) declarada Patrimonio de la Humanidad por la UNESCO; construida sobre los restos de un antiguo castillo defensivo, destaca por sus muros de ladrillo visto policromo y un interior deslumbrante cubierto con motivos heráldicos, yeserías e inscripciones mudéjares de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50080','iglesia','Iglesia Parroquial de Santiago Apóstol','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50093','monumento','Plaza de España de Chodes','Espectacular e inusual conjunto de urbanismo neoclásico ilustrado (siglo XVIII); plaza porticada poligonal perfecta rodeada de casas unificadas de ladrillo visto destinadas históricamente a los operarios agrícolas del señorío.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50093','iglesia','Iglesia de San Miguel','Templo neoclásico integrado simétricamente en el propio entramado porticado de la plaza monumental.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50082','iglesia','Iglesia Parroquial de la Presentación de la Virgen','Templo del siglo XVI edificado con fábrica mixta de ladrillo y mampostería, que conserva muros perimetrales originales y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50083','iglesia','Iglesia Parroquial de San Blas','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la cuenca del Ebro, con una espadaña tradicional de dos vanos para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50084','iglesia','Iglesia Parroquial de Nuestra Señora del Castillo','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica rústica de mampostería caliza, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50085','iglesia','Iglesia Parroquial de San Bernardo','Templo barroco del siglo XVII de traza castellano-aragonesa tradicional, construido con ladrillo visto y cajones de mampostería caliza, profundamente restaurado tras los daños históricos de contiendas bélicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50086','iglesia','Iglesia Parroquial de Santa María','Templo que destaca por su esbelta torre campanario de estilo mudéjar aragonés (siglo XIV) levantada en ladrillo visto con vanos apuntados y arquerías ciegas geométricas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50087','iglesia','Iglesia Parroquial de San Bartolomé','Sencillo templo de arquitectura barroca popular (siglo XVII) edificado con aparejo rústico de piedra caliza, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50089','iglesia','Iglesia Parroquial de la Santa Cruz','Templo de origen barroco (siglo XVII) edificado con muros de ladrillo visto y mampostería caliza en el entorno metropolitano, de líneas muy sobrias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50090','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza calavera en la zona más alta de la comarca, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50091','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza en las inmediaciones de la Laguna de Gallocanta, con una espadaña tradicional de dos vanos y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50094','iglesia','Basílica de Santa María de los Sagrados Corporales','Monumental templo que fusiona los estilos románico (del que conserva un ábside único), gótico y renacentista (siglos XII-XVI); catalogado como BIC, alberga la Capilla','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50094','monumento','Recinto Amurallado de Daroca','Uno de los conjuntos defensivos medievales más colosales de España; conserva más de tres kilómetros de murallas de piedra caliza y tapial que trepan por los cerros, jalonado por 114 torreones defensivos enteros y las monumentales Puerta Baja (flanqueada por dos torreones imponentes) y Puerta Alta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50094','iglesia','Iglesia de San Miguel','Joya del románico de transición (siglo XII); destaca por su espectacular ábside semicircular de sillería impecable y, en su interior, un conjunto de pinturas murales góticas del siglo XIV de gran valor para la arqueología aragonesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50094','monumento','La Mina de Daroca','Espectacular obra de ingeniería civil del siglo XVI (1555-1560) proyectada por Juan de Marquina; colosal túnel de 600 metros de longitud excavado directamente en la roca caliza viva de la montaña para desviar las aguas torrenciales que amenazaban la ciudad fortificada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50095','monumento','Núcleos de población de Ejea de los Caballeros','El término municipal incluye los siguientes núcleos de población: Bardenas, Farasdués, Pinsoro, Rivas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50095','iglesia','Iglesia de Santa María de la Corona','Templo románico de transición (siglo XII) con aspecto de bastión fortificado levantado en lo alto de la villa; posee muros recios de sillería caliza, un ábside poligonal rematado con almenas y una portada occidental con capiteles labrados con esmero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50095','iglesia','Iglesia de San Salvador','Joya del románico tardío (siglo XIII) declarada Monumento Nacional; destaca por su','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50110','monumento','Núcleos de población de El Frasno','El término municipal incluye los siguientes núcleos de población: Aluenda, Inogés y Pietas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50110','iglesia','Iglesia Parroquial de Nuestra Señora de la Piedad','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo de tradición aragonesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50096','monumento','Castillo de Embid','Fortaleza bajomedieval de frontera (siglos XIV-XV) emplazada de forma espectacular sobre una cresta de roca caliza viva; conserva una imponente torre del homenaje poligonal de mampostería rústica y tramos de murallas almenadas que controlaban el paso del valle.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50096','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de piedra de líneas castellano-aragonesas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50098','iglesia','Iglesia de Santa María','Joya que combina el gótico mudéjar y el renacimiento (siglos XIV-XVI); destaca por','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50099','palacio','Palacio de los Condes de Aranda','Obra cumbre de la arquitectura civil renacentista y barroca aragonesa (siglos XVI-XVIII); majestuoso complejo residencial edificado con sillería de piedra caliza calavera y ladrillo, destacando sus portadas neoclásicas simétricas y dependencias señoriales que albergaron una de las cortes nobiliarias más ilustradas de la región.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50099','iglesia','Iglesia Parroquial de Santa María la Mayor','Majestuoso templo barroco clasicista del siglo XVIII de proporciones catedralicias, diseñado por los arquitectos reales; presenta una monumental fachada de dos cuerpos y un interior decorado con ricas yeserías ornamentales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50100','monumento','Torre del Señorío de Erla','Espectacular torre fortificada bajomedieval del siglo XIV erigida en sillería de piedra caliza; de planta cuadrada con saeteras defensivas intactas, ejemplo único de arquitectura militar señorial en las Cinco Villas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50100','iglesia','Iglesia Parroquial de Santa María','Templo renacentista del siglo XVI de líneas extremeño-aragonesas tradicionales, con una robusta torre campanario de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50101','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo barroco del siglo XVIII; catalogado como BIC, alberga en su presbiterio el espectacular Retablo Mayor del Monasterio de Rueda, una colosal estructura del siglo XVII esculpida íntegramente en alabastro de las canteras locales de una finura y detalle artístico extremos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50102','monumento','Mausoleo Romano de Fabara (Mausoleo de Lucio Emilio Lupo)','Obra maestra indiscutible de la arquitectura funeraria de la Hispania Romana del siglo II d.C. (época de Adriano o Antonino Pío) declarada Monumento Nacional; se trata de un templo sepulcral exento de planta rectangular construido íntegramente con colosales sillares de piedra caliza unidos sin argamasa, destacando su fachada con cuatro columnas jónicas que sostienen un frontón y entablamento decorados con motivos vegetales intactos, un monumento único en la península por su estado de conservación absoluto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50102','iglesia','Iglesia Parroquial de San Juan Bautista','Templo de estilo gótico rural (siglo XV) levantado con muros de cantería y contrafuertes robustos de piedra caliza de la cuenca del Matarraña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50105','iglesia','Torre de la Antigua Iglesia de Fayón','Esbelto campanario barroco de ladrillo y piedra caliza del siglo XVIII que emerge de forma monumental de las aguas del embalse de Ribarroja, único resto visible del antiguo pueblo sumergido.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50106','monumento','Eremitorio Rupestre de San Atilano','Monumental templo e iglesia altomedieval excavada directamente en un gran paredón vertical de roca caliza viva de las estribaciones del Moncayo; conserva salas abovedadas naturales y nichos sepulcrales medievales utilizados por monjes anacoretas primitivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50106','monumento','Castillo de los Fayos','Ruinas de la fortaleza bajomedieval de frontera, de mampostería basta adaptada a los cortes de la roca viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50107','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica de ladrillo visto y cajones de mampostería caliza, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50108','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave y espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50109','iglesia','Iglesia Parroquial de San Nicolás de Bari','Joya del románico clásico de las Cinco Villas (siglo XII); destaca por su espectacular ábside semicircular de sillería caliza limpia y una hermosa portada abocinada con un tímpano esculpido con un Pantocrátor y motivos del zodíaco medieval.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50109','ermita','Ermita de San Miguel','Pequeña construcción religiosa románica exenta del siglo XII de planta de cajón con muros de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50113','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI levantado con la técnica de cajones de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50114','monumento','Casa Natal de Francisco de Goya','Vivienda tradicional de arquitectura civil popular del siglo XVIII; conserva sus muros de piedra rústica y mampostería basta de la comarca de Belchite, convertida en museo con dependencias domésticas de época restauradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50114','monumento','Neveras de Fuendetodos (Las Culadas)','Conjunto monumental de patrimonio industrial e hidráulico del siglo XVIII; colosales estructuras circulares excavadas en la roca caliza viva y cubiertas con cúpulas de piedra caliza destinadas al almacenamiento y conservación de hielo para el surtido de la corte de Zaragoza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50115','monumento','Núcleos de población de Fuentes de Ebro','El término municipal incluye los siguientes núcleos de población: Rodén.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50115','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo que destaca por su esbelta torre campanario de estilo mudéjar aragonés (siglo XIV) levantada en ladrillo visto con decoración de arquerías ciegas geométricas y rombos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50115','monumento','Ruinas del Pueblo Viejo de Rodén','Espectacular y colosal conjunto monumental exento de un micro-pueblo fortificado bajomedieval y del siglo XVIII excavado y edificado en piedra caliza sobre un cerro, conservando','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50116','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza e hileras de ladrillo visto, con una robusta torre campanario de líneas sencillas de la cuenca del Jiloca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50117','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI edificado con fábrica de sillería caliza calavera en las inmediaciones de la Laguna de Gallocanta; presenta una robusta torre campanario barroca de líneas herrerianas y un interior de tres naves de gran altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50118','iglesia','Iglesia Parroquial de San Pedro','Monumental templo edificado en el siglo XVI con sillería de piedra caliza calavera; de estilo renacentista con trazas neoclásicas barrocas en su fachada, destaca por su esbelta torre campanario de ladrillo visto que domina el cauce del río Ebro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50118','monumento','Infraestructuras del Canal Imperial de Aragón','Obra cumbre de la ingeniería civil de la Ilustración (siglo XVIII); conserva esclusas, acueductos de sillería caliza y','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50119','iglesia','Iglesia Parroquial de San Pedro','Templo renacentista del siglo XVI de tres naves, construido en ladrillo visto y cajones de mampostería caliza siguiendo el aparejo mudéjar aragonés, con un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50123','iglesia','Iglesia Parroquial de San Martín','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica de ladrillo visto y cajones de mampostería caliza, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50124','iglesia','Iglesia Parroquial de San Juan Bautista','Joya del mudéjar aragonés (siglo XIV); destaca su impresionante torre-fortaleza de ladrillo visto profusamente decorada con frisos de esquinillas, rombos y arquerías ciegas, además de un ábside poligonal con almenas defensivas de gran valor formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50124','iglesia','Santuario de la Virgen de Herrera','Complejo religioso barroco del siglo XVII de planta de cruz latina, erigido en sillería de piedra caliza y ladrillo en lo alto de la sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50125','iglesia','Iglesia Parroquial de San Miguel Arcángel','Monumental templo del siglo XVI de estilo gótico tardío; levantado íntegramente con grandes sillares de piedra caliza de la cuenca del río Mesa, destaca por sus altísimas bóvedas de crucería estrellada y su magnífico retablo mayor renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50125','monumento','Gruta de las Maravillas (Estructuras Hidráulicas)','Entorno de formaciones kársticas donde se conservan antiguos neveros y canalizaciones hidráulicas preindustriales de sillería rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50126','palacio','Palacio-Castillo del Papa Luna','Obra cumbre de la arquitectura civil renacentista y mudéjar aragonesa','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50126','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI con una robusta torre de ladrillo visto, conectado históricamente al señorío del palacio pontificio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50129','iglesia','Santuario de la Virgen de Jaraba','Impresionante complejo religioso edificado a partir del siglo XVI; destaca por su emplazamiento espectacular colgado de forma inverosímil sobre las paredes verticales de piedra caliza roja del desfiladero del río Mesa, construido en sillería rústica calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50129','monumento','Instalaciones Termales Históricas','Conjunto de patrimonio arquitectónico e hidráulico preindustrial del siglo XIX ligado a la explotación de sus baños medicinales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50130','monumento','Castillo de Jarque','Fortaleza bajomedieval de frontera (siglos XIV-XV) de planta cuadrangular levantada en sillería y mampostería de piedra caliza sobre un cerro; conserva recios lienzos de murallas almenadas y torres angulares cuadradas que controlaban el valle del Aranda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50130','iglesia','Iglesia Parroquial de la Presentación de la Virgen','Templo renacentista del siglo XVI de traza tradicional castellano-aragonesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50131','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido con fábrica de ladrillo visto y cajones de mampostería caliza, con una torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50135','monumento','Yacimiento de los Bañales (Entorno)','Espectacular conjunto arqueológico de la Hispania Romana (siglos I a.C. - II d.C.); conserva los pilares monumentales de sillería de un colosal acueducto romano de granito, un complejo de termas públicas y el foro de la antigua ciudad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50135','monumento','Torre de Layana','Imponente torre fortificada bajomedieval del siglo XIV erigida en sillería de piedra caliza; de planta cuadrada con saeteras y modillones defensivos intactos, hoy rehabilitada como centro de interpretación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50135','iglesia','Iglesia Parroquial de San Juan Bautista','Templo de estilo gótico rural (siglo XV) levantado en piedra caliza con una robusta espadaña castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50136','iglesia','Iglesia Parroquial de Santa María Magdalena','Monumental templo edificado en el siglo XVI con fábrica mixta de ladrillo visto y mampostería caliza; de estilo barroco con trazas mudéjares aragonesas en su esbelta torre campanario de planta cuadrada decorada con esquinillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50138','iglesia','Iglesia Parroquial de San Lorenzo Mártir','Sencillo templo de arquitectura barroca popular (siglo XVII) edificado con aparejo rústico de piedra caliza en el límite con la provincia de Teruel, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50140','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto en las faldas del Moncayo, que conserva una sobria torre campanario barroca de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50141','monumento','Castillo de Lituénigo','Torre-fortaleza bajomedieval del siglo XIV erigida en sillería caliza; de planta cuadrada con saeteras, modillones y matacanes defensivos intactos, ejemplo único de arquitectura militar señorial en la comarca de Tarazona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50141','iglesia','Iglesia Parroquial de la Purísima Concepción','Templo gótico del siglo XV que conserva muros de sillería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50143','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental obra del siglo XVI de proporciones catedralicias, atribuida a Alonso de Covarrubias; levantada íntegramente con sillería de piedra caliza calavera y ladrillo visto, destaca por su esbelta Torre Mudéjar exenta del siglo XIV decorada con rombos y arquerías ciegas de gran pureza formal, y sus altísimas columnas herrerianas interiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50144','monumento','Casco Histórico de Longás','Todo el entramado urbano destaca por su arquitectura popular de piedra seca de los siglos XVI y XVII, con pasadizos, portadas adoveladas de medio punto y viviendas unifamiliares construidas con bloques de piedra rústica caliza sin argamasa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50144','iglesia','Iglesia Parroquial de Santa María','Templo del siglo XVI levantado en piedra caliza con una robusta torre campanario de líneas sencillas adaptada al clima de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50146','iglesia','Iglesia Parroquial de San Antonio de Padua','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica de ladrillo visto y cajones de mampostería caliza, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50147','iglesia','Iglesia Parroquial de la Purificación de Nuestra Señora','Templo del siglo XVI edificado en piedra de sillería caliza de líneas tradicionales, que conserva elementos mudéjares aragoneses en la base de sus muros y una robusta torre campanario de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50148','monumento','Castillo de Luesia','Impresionante fortaleza señorial e histórica cuyos tramos más antiguos datan de la repoblación cristiana del siglo X (BIC); corona un crestón rocoso caliza inaccesible y conserva un perímetro amurallado de sillería, cubos defensivos circulares y una imponente torre del homenaje que domina la comarca de las Cinco Villas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50148','iglesia','Iglesia de San Salvador','Joya absoluta del románico clásico (siglo XII) declarada Monumento Nacional; destaca por su espectacular ábside semicircular exento de sillería impecable y su monumental portada occidental con arquivoltas magníficamente esculpidas por el taller de la zona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50148','iglesia','Iglesia de San Esteban (Museo de Arte Religioso)','Templo románico de transición (siglo XII-XIII) clasificado como BIC; posee tres naves de gran altura levantadas sobre los restos de un antiguo alcázar y una cripta subterránea sepulcral de gran valor arqueológico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50148','monumento','Barrio Judío y Casco Medieval','Trazado urbano medieval de la villa que conserva calles empedradas tradicionales, pasadizos de piedra y casonas de cantería de piedra con portadas de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50150','iglesia','Iglesia Parroquial de San Francisco de Asís','Templo que destaca por su esbelta torre campanario de estilo mudéjar aragonés (siglo XIV) levantada en ladrillo visto con decoración de arquerías ciegas geométricas e hleras de aparejo tradicional castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50151','monumento','Castillo de la Corona y Castillo de Yéquera','Conjunto de fortalezas bajomedievales de frontera (siglos XII-XV) mandadas edificar por la corona aragonesa; conservan imponentes torres del homenaje de sillería caliza calavera y lienzos de murallas almenadas enteros sobre los cerros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50151','iglesia','Iglesia Parroquial de Santiago','Templo monumental del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de piedra caliza; destaca su ábside poligonal con recios contrafuertes y un magnífico artesonado mudéjar en la nave.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50152','palacio','Castillo-Palacio de los Pérez de Almazán','Colosal fortaleza bajomedieval (siglos XIV-XVI) erigida en sillería de piedra caliza sobre un cerro; conserva una monumental fachada gótica con ventanales ojivales y torres defensivas de gran valor militar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50152','iglesia','Iglesia de San Esteban','Templo que combina el románico tardío y el gótico aragonés; posee un ábside semicircular limpio y una torre campanario robusta de sillería calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50152','monumento','Torre del Reloj','Antigua puerta de la muralla medieval reconvertida en torre civil barroca en el siglo XVI, hito del urbanismo de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50153','iglesia','Iglesia de San Lorenzo','Templo mudéjar del siglo XIV edificado sobre el antiguo castillo señorial; destaca por su gran nave basilical de ladrillo visto con frisos de esquinillas y una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50153','ermita','Ermita de Nuestra Señora de la Huerta','Oratorio gótico-mudéjar del siglo XV que conserva elementos decorativos de gran interés formal en su cabecera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50154','iglesia','Iglesia Parroquial de Santa Ana','Templo que alberga una de las torres campanario mudéjares del siglo XVI más esbeltas y decoradas de la comarca del Campo de Daroca; levantada íntegramente en ladrillo visto con filigranas de rombos, esquinillas y arquerías ciegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50157','palacio','Castillo-Palacio de Malón','Ruinas consolidadas y estancias integradas de la antigua fortaleza medieval de frontera con Navarra, levantada en mampostería de piedra caliza calavera sobre un cerro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50157','iglesia','Iglesia Parroquial de San Vicente Mártir','Templo del siglo XVI edificado con fábrica de sillería y ladrillo de líneas aragonesas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50159','iglesia','Iglesia de las Santas Justa y Rufina','Obra maestra del mudéjar aragonés (siglo XIV) declarada Monumento Nacional; destaca por su aspecto exterior fortificado de ladrillo visto y un interior deslumbrante cubierto con un artesonado de madera policromado, yeserías caladas de una finura extrema y un coro alto mudéjar intacto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50159','iglesia','Iglesia de Santa María','Templo gótico-mudéjar del siglo XIV que conserva un espectacular ábside de ladrillo visto profusamente decorado con frisos geométricos y rombos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50159','monumento','Castillo de Maluenda','Ruinas señoriales de la antigua fortaleza defensiva de origen árabe y bajomedieval, de tapial y piedra caliza, que domina el valle del Jiloca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50161','iglesia','Iglesia Parroquial de la Conversión de San Pablo','Templo renacentista del siglo XVI de tres naves separadas por columnas, edificado con aparejo mixto de ladrillo visto y mampostería caliza, con una sobria torre de líneas herrerianas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50162','monumento','Yacimiento de Segeda (Entorno)','Espectacular conjunto arqueológico de la antigua ciudad celtíbera (siglos II-I a.C.); conserva recintos habitacionales, talleres preindustriales y murallas de piedra seca claves para la historia nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50162','iglesia','Iglesia Parroquial de San Andrés','Templo barroco rural del siglo XVII edificado en ladrillo y mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50163','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50902','iglesia','Iglesia Parroquial de Santa Catalina','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave y espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50164','iglesia','Iglesia Parroquial de Santa Ana','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50165','monumento','Castillo de Mequinenza','Impresionante fortaleza bajomedieval del siglo XIV erigida por los señores de Moncada; de planta poligonal perfecta asentada sobre un precipicio de roca viva sobre la confluencia de los ríos Ebro y Segre, destaca por sus muros de sillería caliza calavera, torres cuadradas almenadas y adarves defensivos intactos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50165','monumento','Ruinas del Pueblo Viejo de Mequinenza','Conjunto de patrimonio arqueológico y etnológico; restos consolidados de las calles y cimientos del antiguo casco','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50167','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero adaptado a la comarca del Huerva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50168','iglesia','Iglesia Parroquial de Santa María','Templo del siglo XVI de estilo gótico rural, construido con fábrica rústica de mampostería de piedra caliza de la Jacetania Zaragozana, con una robusta torre campanario de dos cuerpos adaptada al clima de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50172','monumento','Castillo de Monreal','Fortaleza bajomedieval de frontera (siglos XII-XIV) mandada edificar por la corona aragonesa frente a Castilla sobre un cerro; conserva lienzos de murallas defensivas de sillería de piedra caliza y restos de una gran torre del homenaje robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50173','monumento','Núcleos de población de Monterde','El término municipal incluye los siguientes núcleos de población: Llumes y Campillo de Dueñas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50173','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería de piedra caliza, con una fachada rematada por un gran frontón clásico y una torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50174','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, con una robusta torre de ladrillo de tradición aragonesa de la cuenca del Jiloca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50175','palacio','Palacio de los Condes de Morata','Obra maestra del barroco civil aragonés del siglo XVII (BIC) diseñada por el arquitecto Juan de Marca; presenta una imponente fachada de sillería caliza calavera y ladrillo, destacando','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50175','monumento','Puente de Capurnos','Hermoso puente medieval del siglo XIV de piedra caliza con perfil lomo de asno y un gran ojo central de medio punto sobre el río Jalón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50175','iglesia','Iglesia Parroquial de Santa Ana','Templo neoclásico del siglo XVIII que cierra el conjunto monumental de la plaza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50176','iglesia','Iglesia Parroquial de San Martín','Joya del mudéjar aragonés (siglo XIV); destaca por su espectacular fachada-tapiz occidental de ladrillo visto profusamente decorada con frisos de arquerías ciegas entrelazadas, rombos y azulejería polícroca, y en su interior alberga un impresionante presbiterio gótico con bóvedas de crucería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50177','monumento','Núcleos de población de Morés','El término municipal incluye los siguientes núcleos de población: Purroy.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50177','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo de la cuenca del Jalón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50178','iglesia','Iglesia Parroquial de San Eulalia','Templo góticomudéjar del siglo XIV levantado de forma espectacular sobre el espolón del cerro que corona el pueblo; destaca por su ábside de ladrillo visto con pisos de arquerías ciegas de gran pureza formal e hleras de aparejo tradicional aragonés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50178','monumento','Casco Medieval de Moros','Conjunto de calles concéntricas estrechas y empedradas con casas tradicionales de tapial y piedra caliza colgadas sobre el desfiladero del río Manubles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50179','iglesia','Iglesia Parroquial de Nuestra Señora de la Piedad','Templo que destaca por su esbelta torre campanario de estilo mudéjar aragonés (siglo XIV) levantada en ladrillo visto con decoración de arquerías ciegas geométricas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50179','monumento','Necrópolis Altomedieval de San Clemente','Conjunto arqueológico de tumbas antropomorfas talladas directamente sobre afloramientos de roca caliza viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50180','palacio','Palacio fortificado de los duques de Villahermosa (Castillo de Mozota)','Espectacular fortaleza residencial civil bajomedieval del siglo XV; construida en sillería caliza calavera y ladrillo mudéjar, presenta una gran planta cuadrada con cubos en los ángulos y almenas defensivas de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50180','iglesia','Iglesia Parroquial de Santa María','Templo de estilo gótico rural con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50181','ermita','Ermita de Nuestra Señora de la Fuente','Templo barroco del siglo XVIII edificado de forma espectacular sobre los restos de una presa romana; declarado BIC, alberga en las pechinas de su gran cúpula centralizada los frescos originales pintados por Francisco de Goya en su juventud que representan a los Padres de la Iglesia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50181','iglesia','Torre de la Iglesia Parroquial de San Cristóbal','Esbelta torre campanario de estilo mudéjar aragonés (siglo XIV) levantada en ladrillo visto con filigranas geométricas e hleras de aparejo tradicional castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50181','monumento','Presa Romana de Muel','Monumental infraestructura civil hidráulica de la Hispania Romana (siglo I d.C.); colosal muro de sillería de piedra caliza de cantería impecable que servía para regular las aguas del río Huerva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50184','iglesia','Iglesia de la Asunción','Templo barroco del siglo XVII edificado en aparejo mixto de ladrillo macizo y cajones de mampostería basta caliza, dotado de una torre campanario baja y un presbiterio con arco triunfal clasicista moldurado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50185','iglesia','Iglesia del Salvador','Obra maestra del románico clásico (siglo XII) de proporciones catedralicias declarada Monumento Nacional; destaca por su espectacular ábside semicircular exento de sillería impecable levantado sobre la ladera de los Mallos de Riglos, con tres pisos de ventanas abocinadas y capiteles magníficamente esculpidos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50185','ermita','Ermita de la Virgen de la Liena','Pequeño santuario románico de planta de cajón con muros de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50186','monumento','Núcleos de población de Navardún','El término municipal incluye los siguientes núcleos de población: Gordún y Gordués.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50186','monumento','Torreón de Navardún','Espectacular torre del homenaje bajomedieval del siglo XIV erigida por la corona aragonesa en la Val de Onsella; colosal baluarte de planta cuadrada construido en sillería de piedra caliza calavera, con saeteras, modillones y matacanes defensivos intactos que domina el paisaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50186','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo que conserva un ábside románico (siglo XII) de sillería caliza, adosado a un cuerpo renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50189','palacio','Castillo de Nonaspe (Palacio de la Encomienda)','Fortaleza residencial bajomedieval de la Orden de los Hospitalarios (siglo XIV) de sillería caliza; conserva sus muros almenados, un patio interior porticado y salas residenciales rehabilitadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50189','iglesia','Iglesia Parroquial de San Bartolomé','Templo gótico del siglo XV de líneas tradicionales con una robusta torre campanario de piedra caliza calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50190','palacio','Castillo-Palacio de Novallas','Ruinas señoriales de la antigua fortaleza defensiva de frontera con Navarra, levantada en mampostería de piedra caliza y ladrillo sobre un cerro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50190','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI que conserva elementos mudéjares aragoneses en su torre campanario de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50191','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de la cuenca de las riberas del Ebro, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50192','iglesia','Monasterio de Piedra (Real Monasterio de Santa María de Piedra)','Colosal e histórico complejo monástico cisterciense fundado en 1194 por Alfonso II de Aragón; declarado Monumento Nacional, destaca por su inmensa iglesia gótica cisterciense en ruinas líricas, su Claustro Gótico de sillería caliza calavera con arquerías ojivales caladas intactas, la Sala Capitular con colosales columnas palmera, el Refectorio y su espectacular parque paisajístico integrado de cascadas y grutas naturales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50192','monumento','Castillo de Nuévalos','Ruinas consolidadas de la fortaleza medieval del siglo XIV que vigilaba el paso del valle del río Piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50192','iglesia','Iglesia Parroquial de San Julián y Santa Basilisa','Templo gótico del siglo XV edificado sobre un espolón rocoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50195','iglesia','Iglesia Parroquial de San Bernabé','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca del Campo de Daroca, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50196','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo mudéjar del siglo XIV levantado con la técnica de cajones de mampostería e hileras de ladrillo visto, que conserva una cabecera mudéjar bien conservada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50198','iglesia','Iglesia Parroquial de Santa María Magdalena','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave y espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50214','iglesia','Iglesia Parroquial de San Jorge','Templo barroco rural del siglo XVII construido en mampostería de piedra caliza y ladrillo visto, con una espadaña tradicional de dos vanos y un interior de nave única muy austero adaptado al Moncayo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50215','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI de estilo renacentista rural de frontera, edificado con fábrica mixta de ladrillo visto y mampostería, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50216','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre de ladrillo de tradición aragonesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50217','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio del siglo XVI de estilo renacentista, construido con fábrica de ladrillo visto y cajones de mampostería caliza en la ribera del Ebro, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50208','iglesia','Convento de San Francisco (Ruinas Consolidadas)','Espectaculares ruinas de una gran abadía barroca de la orden franciscana, que conserva su portada de líneas clasicistas de gran sobriedad geométrica y muros de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50208','iglesia','Torre de la Iglesia Parroquial','Esbelta torre campanario de estilo mudéjar aragonés levantada en ladrillo visto con vanos de medio punto y arquerías ciegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50200','iglesia','Iglesia Parroquial de Nuestra Señora de los Ángeles','Templo mudéjar del siglo XVI; destaca por su esbelta torre campanario de planta octogonal levantada íntegramente en ladrillo visto con filigranas de rombos y esquinillas ciegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50203','palacio','Palacio del Barón de Guía Real','Edificio civil residencial del siglo XVIII de estilo barroco clasicista; presenta una fachada de ladrillo con portalada de sillería caliza decorada con escudos heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50203','iglesia','Iglesia Parroquial de San Pedro','Templo renacentista del siglo XVI edificado con fábrica mixta de mampostería caliza y ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50204','palacio','Palacio de los Duques de Villahermosa','Obra cumbre de la arquitectura civil renacentista y barroca aragonesa (siglos XVI-XVIII); majestuoso complejo residencial edificado con ladrillo y piedra, destacando su fachada monumental y dependencias señoriales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50204','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Majestuoso templo barroco clasicista del siglo XVIII de proporciones catedralicias, diseñado por los arquitectos reales; presenta una monumental fachada de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50206','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado en la comarca de Monegros con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50207','iglesia','Iglesia Parroquial de San Sebastián','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería de piedra caliza, con una fachada rematada por un gran frontón clásico y una torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44184','iglesia','Iglesia de la Santa Cruz','Obra parroquial barroca del siglo XVII ejecutada en aparejo toledano combinando hiladas de ladrillo macizo y cajones de mampostería basta caliza, rematada por una modesta torre campanario adosada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50220','iglesia','Iglesia Parroquial de San Nicolás','Templo del siglo XVI edificado con fábrica de mampostería caliza de la cuenca del Gállego, con una robusta torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50221','iglesia','Iglesia Parroquial de El Salvador','Pequeño templo de arquitectura barroca popular del siglo XVII, levantado en mampostería basta de piedra caliza colgada sobre el precipicio del Moncayo, con una espadaña rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50222','iglesia','Iglesia de la Asunción de Nuestra Señora (El Piquete)','Joya del mudéjar aragonés (siglo XV); destaca por su espectacular e imponente fachada-tapiz de ladrillo visto profusamente decorada con frisos de arquerías ciegas, rombos y una esbelta torre campanario mudéjar, hoy rehabilitada como espacio museístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50222','monumento','Portales de la Alquibla, San Antón y San Roque','Antiguas puertas fortificadas de la muralla bajomedieval que daban acceso al núcleo urbano histórico de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50223','iglesia','Iglesia Parroquial de San Juan Bautista','Templo neoclásico del siglo XVIII que alberga en las pechinas de su gran cúpula centralizada las pinturas murales originales de Francisco de Goya que representan a los Santos Padres.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50225','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental obra del siglo XVI de proporciones catedralicias; destaca por su esbelta Torre Mudéjar del siglo XV levantada íntegramente con ladrillo visto y decoración geométrica, considerada una de las cumbres de este estilo en la cuenca del Jalón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50225','monumento','Castillo de Ricla','Ruinas señoriales de la antigua fortaleza defensiva bajomedieval (siglo XIV) que corona el espolón rocoso de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50227','iglesia','Iglesia Parroquial de San Pedro Apóstol','Joya del mudéjar aragonés (siglo XIV); conserva un espectacular ábside de ladrillo visto con pisos de arquerías ciegas de gran pureza formal e hleras de aparejo tradicional castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50241','palacio','Palacio del Conde de Argillo (Casa de las Tres Puertas)','Gran edificio civil renacentista y barroco del siglo XVII edificado en ladrillo visto; albergó históricamente el cráneo embalsamado del Papa Luna.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50241','iglesia','Iglesia Parroquial de San Pedro','Templo que conserva una esbelta torre mudéjar aragonesa (siglo XIV) con decoración de rombos y arquerías ciegas de gran finura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50241','iglesia','Iglesia del Señorío de La Señoría (San Roque)','Pequeña construcción mudéjar con un interesante ábside de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50230','monumento','Castillo de Sádaba','Obra cumbre de la arquitectura militar medieval (siglo XIII) de influencia bajomedieval francesa; espectacular e imponente fortaleza de planta rectangular construida en sillería caliza calavera, destacando sus cuatro recias torres angulares, muros almenados rectilíneos perfectos y un patio de armas majestuoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50230','monumento','Mausoleo de los Atilios (El Altar de los Moros)','Monumento de la Hispania Romana del siglo II d.C. (época de los Antoninos); conserva la espectacular fachada monumental de sillería de piedra con hornacinas y epigrafía latina dedicada a la familia Atilia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50230','monumento','Mausoleo de la Sinagoga','Restos consolidados de un gran edificio sepulcral romano de planta centralizada y forma absidial del siglo IV d.C.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50230','iglesia','Iglesia de Santa María','Templo de estilo gótico tardío puro (siglo XVI) levantado en piedra caliza con un coro tallado y una esbelta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50231','iglesia','Iglesia Parroquial de San Martín','Templo que destaca por su esbelta torre campanario de estilo mudéjar aragonés (siglo XIV) levantada en ladrillo visto con decoración de arquerías ciegas geométricas y frisos de esquinillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50232','iglesia','Iglesia Parroquial de San Salvador','Monumental templo del siglo XVI de estilo gótico tardío y renacentista, levantado íntegramente con grandes sillares de piedra de la Jacetania Zaragozana; posee una robusta torre campanario defensiva y un órgano barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50233','iglesia','Iglesia Parroquial de San Pedro','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza y ladrillo, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50234','iglesia','Iglesia Parroquial de San Martín','Templo renacentista del siglo XVI levantado con la técnica de mampostería y piedra de las estribaciones de la sierra del Moncayo, adaptado a la orografía montañosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50235','iglesia','Iglesia de San Mateo','Templo mudéjar del siglo XIV levantado de forma espectacular sobre una loma sobre el río Gállego; destaca por su gran ábside poligonal de ladrillo visto profusamente decorado con frisos de rombos y una esbelta torre campanario mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50236','iglesia','Iglesia Parroquial de San Blas','Sencillo templo de arquitectura barroca popular (siglo XVII) edificado con muros bastos de mampostería caliza, con una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50237','iglesia','Iglesia Parroquial de la Exaltación de la Santa Cruz','Templo renacentista del siglo XVI construido en ladrillo visto y cajones de mampostería caliza castellanoaragonesa, con una torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50238','iglesia','Iglesia Parroquial de Santa Eulalia','Templo del siglo XVI edificado con fábrica mixta de mampostería y piedra caliza de la cuenca del Gállego, con una robusta torre campanario de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50239','iglesia','Iglesia Parroquial de San Jaime','Edificio barroco rural del siglo XVII de traza castellana tradicional, construido con ladrillo visto y cajones de mampostería caliza, con una torre de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50240','iglesia','Real Monasterio de Nuestra Señora de Rueda','Colosal e histórico complejo monástico cisterciense fundado en el siglo XII (1202) declarado Monumento Nacional; de piedra caliza calavera, conserva de forma impecable su iglesia románico-gótica cisterciense de tres naves, su Claustro Gótico con galerías de arquerías ojivales caladas intactas, la Sala Capitular con columnas palmera, el gran Refectorio y la colosal Noria Hidráulica de Madera de 16 metros de diámetro (la "Rueda") que da nombre al cenobio y suministraba agua al complejo preindustrial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50240','monumento','Castillo de Palma','Ruinas de la fortaleza defensiva bajomedieval (siglo XIV) que corona un meandro estratégico sobre el río Ebro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50240','iglesia','Iglesia Parroquial de Nuestra Señora del Pilar','Templo barroco del siglo XVII edificado en ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50242','iglesia','Iglesia Parroquial de San Pedro','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero adaptado al entorno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50243','monumento','Núcleos de población de Sestrica','El término municipal incluye los siguientes núcleos de población: Viver de la Sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50243','monumento','Torre de los Duques de Villahermosa','Imponente torre fortificada bajomedieval del siglo XIV erigida en sillería caliza; de planta cuadrada con saeteras, modillones y matacanes defensivos intactos, ejemplo único de arquitectura militar señorial en la comarca del Aranda.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50243','iglesia','Iglesia Parroquial de San Miguel','Templo renacentista del siglo XVI levantado con muros de cantería y una gran torre de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50244','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de estilo castellanoaragonesa rural, construido con fábrica de ladrillo visto y cajones de mampostería caliza, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50245','monumento','Núcleos de población de Sigüés','El término municipal incluye los siguientes núcleos de población: Asso-Veral, Ruesta y Tiermas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50245','monumento','Castillo de Ruesta y Conjunto Medieval','Espectaculares ruinas de una fortaleza bajomedieval del siglo XI-XII en el Camino de Santiago Aragonés; de sillería de piedra caliza, conserva dos grandes torres cuadradas defensivas y adarves rodeados por un micropueblo despoblado de gran valor lírico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50245','monumento','Termas Romanas de Tiermas','Restos arqueológicos de un complejo termal de la Hispania Romana del siglo II d.C. que emergen de forma estacional de las aguas del embalse de Yesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50245','iglesia','Iglesia Parroquial de San Esteban (Sigüés)','Templo románico del siglo XII fortificado, con una robusta torre de piedra berroqueña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50246','monumento','Torreón de los Liñán','Espectacular torre del homenaje bajomedieval del siglo XV; construida con recia mampostería de piedra caliza y esquinas de sillería, conserva matacanes y saeteras.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50246','iglesia','Iglesia Parroquial de San Martín','Templo renacentista del siglo XVI edificado en piedra caliza con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50247','iglesia','Iglesia Parroquial de Santiago Apóstol','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica de ladrillo visto y cajones de mampostería caliza de las riberas del Ebro, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50248','palacio','Palacio de los Sada','Edificio civil residencial fortificado del siglo XV de sillería caliza de cantería impecable, famoso históricamente por haber sido el lugar de nacimiento del rey Fernando el Católico en 1452; destaca por su fachada gótica con ventanas ojivales, portada de medio punto y blasones reales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50248','iglesia','Iglesia de San Esteban y Cripta de Santa María del Perdón','Obra maestra que fusiona el románico clásico y el gótico (siglos XII-XIV) declarada Monumento Nacional; destaca por su monumental portada septentrional con arquivoltas magníficamente esculpidas por el taller del prepirineo y, en su subsuelo, una espectacular cripta románica de tres naves que conserva pinturas murales góticas del siglo XIV excepcionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50248','monumento','Recinto Amurallado de Sos','Impresionante muralla medieval de piedra que abraza todo el perímetro del cerro de la villa; conserva siete monumentales puertas intactas (como la Puerta de Zaragoza, la Puerta del Mudo y la Puerta de Sangüesa) y adarves transitables.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50248','monumento','Torre del Homenaje del Castillo','Recio torreón fortificado medieval del siglo XII de piedra caliza con almenas que corona la cresta de la Peña Feliciana, origen defensivo de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50248','palacio','Plaza de la Villa y Palacio de la Lonja','Espectacular conjunto de urbanismo renacentista aragonés; plaza porticada castellano-aragonesa presidida por la Lonja (siglo XVI), que presenta una doble galería de arquerías de gran finura artística y el Ayuntamiento de fachada monumental de cantería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50248','monumento','Barrio Judío (La Judería)','Un laberinto de calles estrechas y empedradas medievales intactas en torno a la Plaza de la Sartén, con viviendas de piedra con el vano de la cruz calada tradicional de los conversos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50249','iglesia','Iglesia Parroquial de San Juan Bautista','Templo renacentista del siglo XVI levantado en la comarca del Campo de Borja con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50250','monumento','Castillo de Talamantes','Fortaleza bajomedieval de frontera (siglos XII-XIV) emplazada de forma espectacular sobre una cresta de roca caliza viva de las estribaciones del Moncayo; conserva lienzos de murallas de mampostería y restos de una torre del homenaje robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50250','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI edificado en piedra de líneas extremeñoaragonesas tradicionales, con una espadaña castellana tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','catedral','Catedral de Nuestra Señora de la Huerta','Obra cumbre que fusiona el gótico puro, el mudéjar aragonés y el renacimiento (siglos XIII-XVI) declarada Monumento Nacional; destaca por su imponente fachada mudéjar con un colosal cimborrio calado de ladrillo visto polícromo, una esbelta torre campanario mudéjar decorada con azulejería y un impresionante claustro mudéjar con celosías de yeso caladas de una finura extrema única en el mundo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','palacio','Palacio Episcopal','Majestuoso e histórico complejo residencial de los obispos de Tarazona erigido a partir del siglo XIV sobre el antiguo alcázar musulmán; colosal palacio que corona la ciudad colgada sobre el río Queiles, edificado en sillería de piedra caliza calavera y ladrillo, destacando su espectacular Salón de los Obispos decorado con un artesonado mudéjar policromado y retratos de los prelados, y su fachada renacentista con arquerías aragonesas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','monumento','Plaza de Toros Vieja de Tarazona','Obra maestra única del urbanismo civil e industrial barroco (año 1792); espectacular coso taurino tradicional de planta octogonal perfecto rodeado por un conjunto unificado de casas de cuatro plantas con portadas de ladrillo visto y galerías de arquerías destinadas originalmente a palcos y viviendas particulares, una rareza arquitectónica a nivel nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','monumento','Ayuntamiento de Tarazona (Casa Consistorial)','Monumental palacio renacentista del siglo XVI; destaca por su espectacular fachada de sillería caliza decorada con un colosal friso esculpido en piedra que representa la cabalgata triunfal de Carlos V en Bolonia, coronado por','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','iglesia','Iglesia de Santa María Magdalena','Templo mudéjar que corona el casco histórico; destaca por su esbelta y esbelta torre campanario de estilo mudéjar aragonés levantada en ladrillo visto con filigranas de rombos y esquinillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50251','monumento','Casco Histórico y Judería','Conjunto urbano fortificado de calles empedradas concéntricas y empinadas de origen medieval (siglos XIV-XV) rodeado de restos de murallas de piedra, destacando las Casas Colgadas edificadas sobre los adarves defensivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50252','iglesia','Iglesia de Santa María de la Asunción','Obra maestra del mudéjar aragonés (siglo XIV) declarada Patrimonio de la Humanidad por la UNESCO; de proporciones monumentales, posee la espectacular Torre de Tauste, una colosal torre campanario octogonal de ladrillo visto que se eleva más de 40 metros de altura, profusamente decorada con un catálogo de filigranas geométricas, rombos y frisos de arquerías ciegas de una finura técnica extrema, junto a un impresionante retablo mayor renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50252','iglesia','Monasterio de San Jorge (Ruinas Consolidadas)','Vestigios del antiguo complejo monástico barroco del siglo XVII de ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50253','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Joya del románico-mudéjar (siglo XIII); conserva un espectacular ábside de ladrillo visto con pisos de arquerías ciegas de gran pureza formal e hleras de aparejo toledano aragonés, integrado en un edificio ampliado en época renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50254','monumento','Yacimiento celtíbero de Terkiatza (Entorno)','Restos excavados y arqueológicos de una gran oppidum celtíbera con talleres preindustriales de metalurgia del hierro que datan de la Edad del Hierro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50254','iglesia','Iglesia Parroquial de San Juan Bautista','Templo renacentista del siglo XVI edificado en piedra caliza con una robusta torre campanario de ladrillo mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50255','iglesia','Iglesia de la Virgen de Tobed','Obra maestra indiscutible del mudéjar aragonés (siglo XIV) declarada Patrimonio de la Humanidad por la UNESCO; se trata de una iglesia-fortaleza prototípica de la Orden del Santo Sepulcro perfectamente conservada, destacando sus fachadas de ladrillo visto decoradas con frisos de esquinillas y azulejería polícroca azul y verde, y un interior deslumbrante cubierto por completo con una techumbre de madera policromada, motivos heráldicos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50256','iglesia','Iglesia Parroquial de Nuestra Señora de la Blanca','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca del Campo de Daroca, con una espadaña de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50257','iglesia','Iglesia de San Félix','Obra maestra de la tipología de iglesia-fortaleza de estilo mudéjar aragonés (siglo XIV) declarada Patrimonio de la Humanidad por la UNESCO; de sillería de piedra caliza calavera y ladrillo, destaca por su aspecto militar exterior y un interior majestuoso cubierto con bóvedas de crucería y yeserías caladas de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50258','iglesia','Iglesia Parroquial de San Lorenzo','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de la cuenca del río Moros, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50259','monumento','Torre de los Liñán','Espectacular torre del homenaje bajomedieval del siglo XV de sillería caliza; de planta cuadrada con saeteras defensivas intactas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50259','iglesia','Iglesia Parroquial de Nuestra Señora de la Blanca','Templo del siglo XVI levantado con la técnica de cajones de mampostería e hleras de ladrillo visto, cuna del santo local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50260','iglesia','Iglesia Parroquial de Nuestra Señora de Malanca','Templo renacentista del siglo XVI de tres naves separadas por columnas, edificado con aparejo mixto de ladrillo visto y mampostería caliza castellana, con un retablo barroco del siglo XVIII en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50261','iglesia','Iglesia Parroquial de San Martín','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo de la comarca de Tarazona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50262','iglesia','Iglesia Parroquial de San Andrés','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica de ladrillo visto y cajones de mampostería caliza en la confluencia de los ríos Ebro y Jalón, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50263','monumento','Torre del Reloj y Murallas','Antigua torre exenta del siglo XIV de planta cuadrada construida en sillería caliza calavera, único resto conservado de la fortificación defensiva que controlaba el paso del valle del Manubles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50263','iglesia','Iglesia Parroquial de Nuestra Señora del Hito','Templo monumental del gótico tardío y renacimiento (siglo XVI).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50264','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza y ladrillo visto, con una robusta torre campanario de líneas sencillas de la comarca del Campo de Cariñena.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50265','monumento','Castillo de Trasmoz','Impresionante fortaleza bajomedieval (siglos XII-XIV) rodeada de crónicas de brujería y leyendas; de planta irregular adaptada al cerro','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50265','iglesia','Iglesia Parroquial de la Virgen de la Huerta','Templo renacentista del siglo XVI edificado en granito y mampostería, de líneas sobrias serranas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50266','iglesia','Convento de Nuestra Señora de la Asunción (Ruinas Consolidadas)','Vestigios del antiguo complejo monástico agustino y cisterciense fundado en el siglo XII por la corona aragonesa, que conserva su portada de líneas renacentistas y muros de sillería de granito caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50267','iglesia','Iglesia de Santa María de la Asunción','Obra maestra del románico clásico europeo (siglo XII, año 1179) de proporciones catedralicias declarada Monumento Nacional; destaca por su espectacular galería porticada norte, su ábside semicircular exento de sillería impecable y su monumental portada meridional con arquivoltas magníficamente esculpidas con un catálogo de relieves medievales de una finura técnica extrema, coronada por una torre fortificada del siglo XIV.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50267','palacio','Castillo de Uncastillo (Torre del Homenaje y Palacio Gótico)','Fortaleza señorial e histórica de origen del siglo X (BIC) que corona la Peña Ayllón; conserva una colosal Torre del Homenaje cuadrada de sillería caliza calavera','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50267','iglesia','Iglesia de San Martín (Centro de Interpretación del Románico)','Templo románico de transición (siglo XII) clasificado como BIC; de una sola nave de gran altura, destaca por su ábside semicircular limpio y su torre fortificada masiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50267','iglesia','Iglesia de San Juan','Templo románico del siglo XII edificado sobre un espolón rocoso; conserva pinturas murales medievales fragmentarias de gran interés arqueológico en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50267','palacio','Palacio Consistorial (Ayuntamiento)','Espléndido palacio de arquitectura civil renacentista del siglo XVI; presenta una fachada monumental de sillería decorada con un diseño clásico de arquerías aragonesas y matacanes defensivos que atestigua el rango de villa judicial autónoma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50267','monumento','Barrio Judío (La Judería)','Un laberinto de calles estrechas y empedradas medievales intactas que conserva la estructura de la sinagoga y viviendas tradicionales de piedra con portadas adoveladas de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50268','iglesia','Iglesia Parroquial de San Martín','Templo del siglo XVI de estilo gótico rural con importantes reformas renacentistas, construido con fábrica de mampostería caliza, con una robusta torre campanario de líneas sencillas adaptada al clima de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50269','monumento','Castillo de Urrea','Fortaleza bajomedieval de frontera (siglos XII-XIV) de planta cuadrangular levantada en tapial y mampostería caliza calavera sobre un cerro; conserva lienzos de murallas que controlaban el paso del río Jalón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50269','iglesia','Iglesia Parroquial de El Salvador','Templo renacentista del siglo XVI edificado con fábrica de mampostería caliza y ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50270','monumento','Casco Histórico de Urriés','Todo el entramado urbano destaca por su arquitectura popular de piedra seca de los siglos XVI y XVII, con calles estrechas (como la mítica calle de los Siete Pasos), portadas adoveladas de medio punto y viviendas unifamiliares construidas con bloques de piedra rústica caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50270','iglesia','Iglesia Parroquial de San Esteban','Templo del siglo XVI levantado en piedra caliza con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50272','iglesia','Torre de la Iglesia Parroquial de Nuestra Señora de la Asunción (Torre de los Espejos)','Obra maestra absoluta indiscutible del mudéjar aragonés final (siglo XVI) declarada Monumento Nacional; espectacular torre campanario de planta octogonal construida íntegramente con ladrillo visto y decorada de forma inverosímil con más de 8.000 azulejos y piezas cerámicas polícromas de Muel (verdes, blancas y azules) que reflejan la luz del sol, considerada el icono máximo del mudéjar civil y religioso aragonés.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50272','iglesia','Iglesia de la Asunción','Templo gótico y renacentista del siglo XVI levantado en sillería caliza y ladrillo que cobija la base de la monumental torre.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50274','iglesia','Iglesia Parroquial de San Bla','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la comarca del Campo de Daroca, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50273','iglesia','Iglesia Parroquial de San Juan Bautista','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de la cuenca del Jiloca, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50275','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave y espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50276','iglesia','Iglesia Parroquial de San Ponciano','Templo del siglo XVI edificado con fábrica de mampostería caliza y ladrillo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50277','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza, con una espadaña tradicional de dos vanos para las campanas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50278','monumento','Yacimiento Arqueológico de Lepida Celsa','Impresionante conjunto monumental de la colonia romana del siglo I a.C. (año 44 a.C.) fundada por Lépido sobre el río Ebro; conserva trazas urbanas simétricas de las calles pavimentadas, la Casa de los Delfines (gran domus que conserva espectaculares mosaicos de opus signinum y pinturas murales decorativas) y estructuras del foro comercial de gran valor arqueológico nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50278','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI edificado en piedra y ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50279','iglesia','Iglesia de San Juan Bautista','Joya del románico-mudéjar (siglo XIII); conserva un espectacular ábside de ladrillo visto con tres pisos de arquerías ciegas de gran pureza formal e hleras de aparejo toledano aragonés, integrado en un edificio de la cuenca del Jiloca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50280','iglesia','Real Monasterio de Santa María de Veruela','Colosal e histórico complejo monástico fortificado, primera fundación de la Orden del Císter en Aragón (siglo XII); catalogado como BIC, conserva un recinto amurallado con torreones, una majestuosa iglesia románica de transición, un claustro gótico calado de una finura extrema, una sala capitular impecable y el refectorio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50280','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo del siglo XVI edificado con fábrica de sillería y ladrillo visto, con una robusta torre campanario de tradición aragonesa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50281','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo barroco rural (siglo XVII) edificado con muros de ladrillo visto y mampostería en la cuenca del río Queiles, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50283','iglesia','Iglesia Parroquial de Santiago Apóstol','Joya del mudéjar aragonés (siglo XIV); conserva un espectacular ábside de ladrillo visto con pisos de arquerías ciegas de gran pureza formal e hileras de aparejo tradicional castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50284','iglesia','Iglesia Parroquial de San Miguel','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, con una robusta torre de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50285','palacio','Palacio de los de la Caballería','Edificio civil residencial del siglo XVII de estilo barroco clasicista aragonés; presenta una fachada de ladrillo con portalada de sillería caliza decorada con escudos heráldicos monumentales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50285','iglesia','Iglesia Parroquial de San Pedro','Templo renacentista del siglo XVI edificado con fábrica mixta de mampostería caliza y ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50286','iglesia','Iglesia Parroquial de San Cristóbal','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en ladrillo visto y piedra caliza de la cuenca del Perejil, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50287','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo de la cuenca del Jalón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50903','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo que alberga una de las torres campanario mudéjares del siglo XVI más esbeltas y decoradas de la cuenca del Gállego; levantada íntegramente en ladrillo visto con filigranas de rombos, esquinillas y arquerías ciegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50288','iglesia','Iglesia Parroquial de El Salvador','Edificio de origen renacentista (siglo XVI) profundamente modificado en los siglos XVII y XVIII; conserva muros con cajones de mampostería, esquinales de sillería caliza y una robusta torre campanario de ladrillo de traza aragonesa tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50289','iglesia','Iglesia Parroquial de San Gil Abad','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza, con una fachada rematada por un gran frontón clásico y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50291','iglesia','Iglesia Parroquial de San Pedro','Joya del románicomudéjar (siglo XIII); conserva un espectacular ábside de ladrillo visto con tres pisos de arquerías ciegas y dobladas de gran pureza formal e hleras de aparejo toledano aragonés, escenario de batallas históricas carlistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50292','iglesia','Iglesia Parroquial de San Miguel','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, con una robusta torre de ladrillo de tradición aragonesa de la cuenca del río Huerva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50293','iglesia','Iglesia-Fortaleza de San Pedro','Espléndido templo del siglo XV de estilo gótico puro mudéjar; de proporciones catedralicias, se levanta como un auténtico bastión militar defensivo con muros de ladrillo massivos, contrafuertes y almenas caladas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50293','monumento','Puertas de la Muralla (Arco de la Fuente y de San Pedro)','Restos del recinto amurallado bajomedieval del siglo XIV que protegía la villa judicial autónoma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90162','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo de origen barroco rural (siglo XVII) edificado con muros bastos de mampostería caliza, con una espadaña de dos vanos para las campanas y un interior muy austero adaptado a la comarca del Huerva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50297','palacio','Palacio de la Aljafería','Obra cumbre de la arquitectura palaciega hispanomusulmana califal de la época de Taifas (siglo XI) con ampliaciones de los Reyes Católicos (siglo XV), declarada Patrimonio de la Humanidad por la UNESCO; colosal alcázar amurallado con torreones circulares, que alberga en su interior el patio de Santa Isabel con arquerías de filigranas de yeso entrelazadas inverosímiles, el Oratorio islámico con un mihrab intacto y el Salón del Trono de los Reyes Católicos con un impresionante alfarje mudéjar dorado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50297','catedral','Catedral del Salvador (La Seo)','Monumental templo que fusiona los estilos románico, gótico, mudéjar y barroco (siglos XII-XVIII) Patrimonio de la Humanidad; destaca su espectacular Muro Mudéjar de la Parroquieta, un colosal tapiz exterior de ladrillo visto y azulejería polícroca con diseños geométricos infinitos, su retablo mayor gótico de alabastro esculpido por Hans de Suabia y el cimborrio mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50297','iglesia','Basílica de Nuestra Señora del Pilar','Obra cumbre de la arquitectura barroca y neoclásica española (siglos XVII-XVIII) diseñada por Francisco de Herrera el Mozo y Ventura Rodríguez; colosal templo de proporciones masivas a orillas del Ebro, coronado por 11 cúpulas decoradas con azulejos de colores y 4 esbeltas torres de 92 metros, que alberga en su interior la Santa Capilla de mármoles y jaspes y los frescos originales pintados por Francisco de Goya (Regina Martyrum).','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50297','monumento','Lonja de Zaragoza','El edificio civil renacentista más importante de Aragón (siglo XVI) proyectado por Juan de Sariñena; monumental palacio de ladrillo visto que emula a los palacios florentinos, destacando su espectacular espacio interior de planta de salón con colosales','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50297','monumento','Teatro Romano de Caesaraugusta','Impresionante conjunto de la Hispania Romana del siglo I d.C. (época de Tiberio); uno de los teatros romanos más grandes de la península con capacidad para 6.000 espectadores, conservando graderías, la orchestra y cimientos consolidados protegidos por una colosal cubierta contemporánea. [1]','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50298','iglesia','Iglesia Parroquial de San Pedro','Templo que alberga una esbelta torre campanario de estilo mudéjar aragonés (siglo XIV) levantada en ladrillo visto con decoración de arquerías ciegas geométricas y rombos, profundamente reformada en sus naves interiores en época barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50298','monumento','Anexo','Municipios de la provincia de Zaragoza Anexo: Municipios de la provincia de Zaragoza Municipio Vera de Moncayo Vierlas Población (2022) 316 80 Superficie (km²) 27,66 2,6...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50298','monumento','5 pueblos bonitos cerca de Zaragoza','5 pueblos bonitos cerca de Zaragoza (con mapa) 11 ene 2024 — Uncastillo Uncastillo es otro de los pueblos bonitos cerca de Zaragoza donde pasar unas horas y descubrir sus calles empedradas y ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50298','monumento','Zaragoza También alberga frescos de Goya','Zaragoza También alberga frescos de Goya ( Francisco de Goya ) y Francisco Bayeu, entre otros. La Catedral del Salvador (La Seo ( Catedral ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24001','monumento','Castillo de Albanchez','Impresionante fortaleza de origen bereber (siglos XII-XIV) construida sobre un imponente peñón vertical de roca viva en Sierra Mágina; conserva su majestuosa Torre del Homenaje de mampostería gruesa y lienzos de murallas defensivas de difícil acceso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24001','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con trazas renacentistas;','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24003','monumento','Castillo de Alcaudete','Colosal fortaleza de origen califal (siglo X) reconstruida por la Orden de Calatrava entre los siglos XIII y XIV; destaca por su imponente recinto amurallado perimetral con cubos defensivos circulares, su magnífica Torre del Homenaje de cantería regular y sus estancias palaciegas restauradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24003','iglesia','Iglesia de Santa María la Mayor','Monumental templo del gótico tardío y renacimiento (siglo XVI), proyectado bajo la influencia de los talleres reales; posee una impresionante cabecera cubierta con bóvedas de crucería estrellada y un coro de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24003','iglesia','Iglesia de San Pedro','Espléndido templo renacentista diseñado por los arquitectos Francisco del Castillo y Andrés de Vandelvira, con una severa portada clasicista de líneas geométricas impecables.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24004','monumento','Pinturas Rupestres de la Cimbarra (Tabla de Pochico)','Espectacular santuario arqueológico al aire libre con arte rupestre esquemático datado en el Neolítico y la Edad del Bronce, pintado sobre los abrigos rocosos de pizarra caliza en el entorno del desfiladero, Patrimonio de la Humanidad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24004','iglesia','Iglesia Parroquial de la Purísima Concepción','Templo de estilo colonial ilustrado (siglo XVIII) mandado edificar por Carlos III para el poblamiento de las Nuevas Poblaciones de Sierra Morena, de líneas muy sobrias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','monumento','Puente Romano sobre el río Guadalquivir','Monumental obra de ingeniería civil romana construida originalmente en el siglo II d.C. (época de Septimio Severo); cuenta con 15 arcos asimétricos de medio punto construidos en piedra de cantería y tajamares angulares, profundamente reformado en la Edad Media.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','monumento','Murallas Almohades y Torre de Tavira','Restos del recinto defensivo hispanomusulmán del siglo XII; conserva paños de gran espesor construidos con la técnica de tapial y hormigón árabe, jalonados por cubos defensivos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','iglesia','Iglesia de San Miguel Arcángel','Monumental templo gótico del siglo XV; destaca por su magnífica cabecera y por albergar en su interior el famoso lienzo original de El Greco "La Oración en el Huerto".','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24005','palacio','Palacio de los Niños de Don Gome','Edificio civil señorial barroco del siglo XVII; presenta una imponente fachada de sillería de piedra con portada de medio punto,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24006','iglesia','Santuario de los Santos Mártires y Cripta del Barón de Velasco','Impresionante conjunto neobarroco y neoclásico edificado en el siglo XIX sobre los restos del antiguo alcázar medieval; alberga una cripta funeraria espectacular esculpida con mármoles polícromos y jaspes de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24006','monumento','Aljibe Almohade del Alcázar','Estructura hidráulica subterránea de origen musulmán (siglo XII) perfectamente conservada bajo el suelo del municipio, con arcos de herradura y bóvedas de mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24006','iglesia','Iglesia de Santa María','Templo del siglo XVI de traza renacentista herreriana con una sobria portada de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24007','monumento','Castillo de Macías el Enamorado','Fortaleza bajomedieval del siglo XIV erigida por la Orden de Calatrava; conserva su imponente Torre del Homenaje cuadrada de sillería caliza y el patio de armas, escenario de célebres leyendas literarias medievales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24007','iglesia','Iglesia Parroquial de la Encarnación','Templo góticorenacentista del siglo XVI de tres naves separadas por robustas columnas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24008','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo del estilo colonial ilustrado del siglo XVIII edificado por orden de Carlos III dentro del plan de las Nuevas Poblaciones de Sierra Morena, de planta de cajón con fachada sobria de ladrillo y piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24011','iglesia','Iglesia Parroquial de la Encarnación','Monumental templo del siglo XVI que fusiona el gótico flamígero y el renacimiento; edificado en sillería de arenisca, destaca por su portada plateresca, sus bóvedas de crucería y por albergar los restos del General Castaños, héroe de la contienda de 1808.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24011','ermita','Ermita de la Limpia Concepción','Edificio barroco del siglo XVII de planta de cajón castellana con una sobria fachada de piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24012','monumento','Castillo de Bury al-Hammam','Obra maestra absoluta de la arquitectura militar del Califato de Córdoba, mandado construir por el califa Al-Hakam II en el año 968 d.C.; espectacular fortaleza elíptica que conserva casi intacto su perímetro defensivo original de 14 torres cuadradas construidas con tapial de arcilla y cal polícromo (llamado tabiyya), coronado por la colosal Torre del Homenaje cristiana o del Alcaide añadida en el siglo XIV de sillería impecable.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24012','iglesia','Iglesia Parroquial de San Mateo','Monumental templo gótico y renacentista del siglo XV-XVI; posee una imponente torre campanario de tres cuerpos, un interior de tres naves y un espectacular sagrario barroco de madera tallada dorada de gran valor artístico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24012','ermita','Ermita de Jesús del Llano','Santuario barroco del siglo XVII que alberga en su interior un Camarín Barroco Churrigueresco colosal, una de las obras cumbre de la yesería polícroca y el barroco andaluz, decorado con una profusión y detalle tridimensional inverosímiles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24012','monumento','Molino de Viento del Santo','Estructura industrial etnológica del siglo XVIII de sillería caliza, uno de los poquísimos molinos de viento de tipo manchego conservados en el norte de Andalucía.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24013','iglesia','Monasterio de San José del Salvador (Carmelitas Descalzas)','Complejo monástico fundado en el siglo XVI (1575) por Santa Teresa de Jesús y San Juan de la Cruz; de estilo barroco conventual sobrio, conserva las estancias, la iglesia de ladrillo visto y una rica colección de reliquias de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24013','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI edificado en sillería de piedra serrana con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24015','palacio','Palacio Episcopal de Begíjar','Espléndido edificio civil señorial renacentista del siglo XVI proyectado por Andrés de Vandelvira; presenta una imponente fachada de sillería con portada adovelada de medio punto y blasones heráldicos de los obispos de Jaén.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24015','monumento','Torre del Homenaje del Castillo','Ruinas consolidadas de la antigua fortaleza medieval de origen árabe de la que se conserva la majestuosa torre cuadrada de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24018','monumento','Castillo de Bélmez','Fortaleza bajomedieval de frontera (siglos XIII-XV) emplazada de forma espectacular sobre un crestón rocoso de Sierra Mágina; conserva su torre del homenaje cuadrada de mampostería gruesa y lienzos defensivos que vigilaban el reino de Granada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24018','monumento','Torre del Lucero','Esbelta torre vigía circular de sillería medieval situada en una cima estratégica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24016','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del siglo XVI edificado con fábrica rústica de mampostería de piedra caliza de la Sierra de Segura, con una espadaña tradicional de dos vanos y un interior muy sobrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23017','iglesia','Iglesia Parroquial de Nuestra Señora de la Expectación','Monumental templo edificado en el siglo XVII, obra cumbre del barroco clasicista jiennense diseñada por Juan de Aranda Salazar; destaca por su espectacular fachada de sillería caliza con una gran portalada jónica y un presbiterio majestuoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23017','palacio','Palacio de los Marqueses de San Juan','Edificio civil señorial barroco del siglo XVIII con una hermosa fachada con blasones heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23018','monumento','Núcleos de población de Cambil','El término municipal incluye los siguientes núcleos de población: Arbuniel.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23018','monumento','Castillo de Cambil y Castillo de Alhabar','Espectaculares ruinas de dos fortalezas bajomedievales de frontera (siglo XV) erigidas frente a frente en dos crestones rocosos verticales que encajonan el río, enclaves estratégicos de la conquista de Granada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23018','iglesia','Iglesia Parroquial de la Encarnación','Templo renacentista del siglo XVI edificado en piedra caliza con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23019','iglesia','Iglesia Parroquial de la Encarnación','Templo renacentista del siglo XVI de tres naves, construido con ladrillo visto y cajones de mampostería caliza castellana, con un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23020','palacio','Castillo-Palacio de Canena','Obra maestra indiscutible de la arquitectura civil renacentista española, transformado en el siglo XVI por Andrés de Vandelvira para el secretario imperial Francisco de los Cobos; fortaleza residencial de planta cuadrada levantada en sillería caliza calavera, destacando sus cuatro robustas torres circulares en los ángulos y un espectacular patio interior porticado de doble piso de una finura renacentista extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23020','iglesia','Iglesia Parroquial de la Concepción','Templo del siglo XVI edificado con muros de piedra caliza de líneas herrerianas sobrias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23901','monumento','Núcleos de población de Cárcheles','El término municipal incluye los siguientes núcleos de población: Cárchel y Carchelejo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23901','iglesia','Iglesia Parroquial de Nuestra Señora de los Remedios (Carchelejo)','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica mixta de ladrillo visto y mampostería caliza, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24024','monumento','Conjunto Urbano de las Nuevas Poblaciones (Casco Histórico)','Espectacular y colosal conjunto de urbanismo neoclásico ilustrado planificado en el siglo XVIII por Pablo de Olavide bajo el reinado de Carlos III; trazo ortogonal perfecto de calles simétricas, jalonado por las Torres de la Aduana (monumentales monolitos de sillería caliza calavera que daban acceso al reino), la Plaza de los Delgados y palacios institucionales unificados de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24024','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo neoclásico del siglo XVIII simétricamente integrado en el entramado porticado de la plaza monumental, que sirvió históricamente de eje espiritual del poblamiento ilustrado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23025','monumento','Yacimiento Íbero de la Cueva de la Lobera','Espectacular santuario arqueológico de la cultura íbera (siglos IV-III a.C.) localizado en un abrigo natural sobre los desfiladeros; conserva estructuras votivas excavadas en la roca de donde proceden la mayor colección de exvotos de bronce del país.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23025','iglesia','Iglesia Parroquial de la Encarnación','Templo renacentista del siglo XVI edificado en piedra caliza con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23026','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI edificado con fábrica de mampostería caliza y esquinas de sillería berroqueña, que conserva una robusta torre campanario barroca de líneas herrerianas y un interior de tres naves de gran altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23026','monumento','Torre de la Cabeza','Esbelta torre vigía bajomedieval de frontera de planta circular de mampostería gruesa caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23027','iglesia','Iglesia Parroquial de Santa María Magdalena','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta torre campanario de líneas sencillas y un interior muy austero adaptado al entorno agrícola.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','iglesia','Ruinas de la Iglesia de Santa María','Obra maestra absoluta y audacia arquitectónica del Renacimiento español (siglo XVI) diseñada por Andrés de Vandelvira; templo monumental construido en sillería de piedra caliza blanca levantado de forma increíble sobre la bóveda del río Cerezuelo (un túnel de cantería monumental de 150 metros excavado para canalizar el cauce bajo la iglesia), cuyas ruinas líricas conservan una colosal cúpula casetonada y una torre defensiva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','monumento','Castillo de la Yedra (Castillo de las Cuatro Esquinas)','Impresionante fortaleza bajomedieval de frontera (siglos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','monumento','Castillo de las Cinco Esquinas','Ruinas de una torre defensiva pentagonal exenta del siglo XIV que corona la cresta de la montaña sobre el castillo principal, hito militar de gran valor estratégico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23028','monumento','Plaza de Santa María y Casas Consistoriales','Conjunto de calles y palacios tradicionales renacentistas de los siglos XVI y XVII sustentados por columnas de piedra caliza calavera en el corazón del casco histórico serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23029','monumento','Casco Histórico de Chiclana (Pueblo Colgado)','Todo el entramado urbano destaca por su emplazamiento espectacular colgado de forma inverosímil sobre un inmenso frente vertical de roca viva de arenisca roja; conserva calles empedradas, pasadizos de piedra y casonas de cantería que asoman sobre el valle del Guadalimar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23029','iglesia','Iglesia Parroquial de San Pedro','Templo monumental del siglo XVI edificado en lo alto de la peña de sillería caliza calavera con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23030','iglesia','Iglesia Parroquial de Nuestra Señora de la Paz','Templo del siglo XVI edificado con fábrica de mampostería caliza en la comarca de la Sierra de Cazorla, con una robusta torre campanario de líneas sencillas y un interior muy austero adaptado al entorno de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23031','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo de origen renacentista (siglo XVI) con remodelaciones barrocas; presenta muros de mampostería con refuerzo','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24035','monumento','Castillo de Espeluy','Fortaleza bajomedieval de frontera (siglos XIV-XV) levantada en sillería de piedra caliza sobre una loma que domina el Guadalquivir; conserva su majestuosa Torre del Homenaje de planta cuadrada con saeteras y modillones defensivos intactos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24035','iglesia','Iglesia Parroquial de Santa Catalina','Templo renacentista rural del siglo XVI de líneas sobrias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23033','iglesia','Iglesia Parroquial de Santa Lucía','Edificio del siglo XVI diseñado bajo las influencias del Renacimiento de la comarca de la Sierra Sur; construido con fábrica rústica de mampostería caliza, presenta un interior de una sola nave con techumbre de viguería y espadaña tradicional de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23034','iglesia','Iglesia Parroquial de Nuestra Señora de la Fuensanta','Templo del siglo XVI edificado en piedra de sillería caliza con una robusta torre campanario de líneas sencillas; conserva elementos renacentistas en su portada y capillas interiores.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23035','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Sencillo templo de arquitectura barroca popular (siglo XVII) edificado con muros de ladrillo visto y mampostería caliza de la campiña jiennense, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23039','monumento','Conjunto Urbano de las Nuevas Poblaciones','Trazado urbano ortogonal y simétrico planificado en el siglo XVIII por Pablo de Olavide bajo el reinado de Carlos III;','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23039','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo neoclásico del siglo XVIII simétricamente integrado en el entramado de la plaza monumental, concebido bajo los cánones de la Ilustración.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23041','monumento','Torre del Homenaje del Castillo','Imponente torre fortificada bajomedieval del siglo XIV erigida en sillería de piedra caliza; de planta cuadrada con saeteras defensivas intactas, único vestigio de la antigua fortaleza de la orden militar en la campiña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23041','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo gótico del siglo XV que conserva muros de mampostería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23042','iglesia','Iglesia Parroquial de San Marcos Evangelista','Templo del siglo XVI edificado con fábrica de mampostería caliza en la cuenca del río Guadiana Menor, con una robusta torre campanario de líneas sencillas y un interior muy austero adaptado al entorno rural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23043','monumento','Castillo de Hornos y Recinto Amurallado','Espectacular fortaleza bajomedieval de frontera (siglos XII-XIV) que corona un precipicio vertical de roca viva; conserva casi intacto su perímetro de murallas de sillería de piedra caliza, tres torres defensivas cuadradas y una imponente Torre del Homenaje que hoy alberga el centro de observación astronómica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23043','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Joya del gótico tardío y renacimiento (siglo XVI) declarada BIC; destaca por su portalada plateresca diseñada por los talleres de la comarca, un presbiterio cubierto con complejas bóvedas de crucería estrellada y un coro alto de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23043','monumento','El Fuerte de Hornos','Ruinas y restos consolidados de una gran torre-fortaleza exenta de planta poligonal integrada en los restos defensivos de la villa amurallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23044','iglesia','Iglesia de la Inmaculada Concepción','Obra maestra del Renacimiento español (siglo XVI) proyectada y construida por Andrés de Vandelvira; templo monumental edificado en impecable sillería caliza calavera, destacando su fachada principal de líneas geométricas perfectas, tres naves de gran altura de planta de salón y un presbiterio con bóvedas decoradas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23044','monumento','Castillo de los Duques de Alburquerque (Castillo de Huelma)','Impresionante fortaleza bajomedieval de frontera (siglos XIV-XV) asentada sobre un cerro; conserva muros almenados, una colosal torre del homenaje de cantería y restos residenciales de una de las cortes nobiliarias que vigilaban la frontera con Granada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23045','iglesia','Iglesia Parroquial de Nuestra Señora de las Preces','Templo del siglo XVI de traza renacentista rural herreriana de la sierra de Cazorla, edificado con grandes bloques de granito berroqueño y sillería, con una robusta espadaña de dos cuerpos y muros de mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23046','monumento','Muralla Ciclópea de Ibros','Joya de la arqueología nacional (BIC) de la cultura íbera y romana (siglos III-II a.C.); espectacular tramo de muro defensivo construido íntegramente con bloques colosales de piedra caliza viva encajados sin argamasa, considerado una rareza arquitectónica de la península.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23046','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI con importantes modificaciones barrocas y neoclásicas, diseñado bajo la influencia de los talleres renacentistas de Baeza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23048','monumento','Casco Histórico y Murallas de Iznatoraf','Declarado Conjunto Histórico-Artístico; conserva un laberinto de calles estrechas y empedradas de origen hispanomusulmán (siglos XI-XII) colgado sobre un cerro de la comarca de Las Villas, rodeado de restos de','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23048','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Monumental templo del siglo XVI que combina el gótico flamenco y el renacimiento, levantado íntegramente con grandes sillares de piedra, con un magnífico coro de madera tallada tradicional en su interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23048','monumento','EL CASCO ANTIGUO DE GUARROMÁN, CONJUNTO HISTÓRICO 28 sept 2012 — Guarromán','EL CASCO ANTIGUO DE GUARROMÁN, CONJUNTO HISTÓRICO 28 sept 2012 — Guarromán es un claro exponente del urbanismo ilustrado típico de las Nuevas Poblaciones construidas en Sierra Morena en el siglo ...','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23049','palacio','Palacio de los Marqueses de Jabalquinto','Edificio civil residencial de arquitectura clasicista y barroca; presenta una sobria fachada de sillería caliza con portalada monumental y el escudo de armas señorial tallado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23049','iglesia','Iglesia Parroquial de la Encarnación','Templo renacentista del siglo XVI levantado con muros de cantería y contrafuertes robustos, que destaca por su artesonado de madera de tradición mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','catedral','Catedral de la Asunción de la Virgen','Obra cumbre del Renacimiento español y modelo para las catedrales americanas, diseñada en el siglo XVI por Andrés de Vandelvira; destaca por su fachada monumental barroca esculpida en piedra caliza flanqueada por dos torres de 68 metros, su interior basilical de planta de salón impecable, las bóvedas de la sacristía y un fastuoso coro de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','palacio','Baños Árabes de Jaén (Palacio de Villardompardo)','Los baños hispanomusulmanes del siglo XI más grandes y mejor conservados de toda España (BIC); situados en los sótanos del palacio renacentista, destacan por sus salas abovedadas con tragaluces estrellados sostenidas por arcos de herradura y columnas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','monumento','Castillo de Santa Catalina','Colosal fortaleza medieval bajomedieval de frontera (siglos XIII-XV) erigida por la corona castellana sobre el antiguo alcázar almohade; corona el cerro de la ciudad con un perímetro amurallado de sillería berroqueña, cubos defensivos circulares y una impresionante Torre del Homenaje de 30 metros de altura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','iglesia','Real Monasterio de Santo Domingo','Complejo monástico de la orden de predicadores (siglos XIV-XVI) que hoy alberga el archivo provincial; destaca su espectacular claustro renacentista de doble piso de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23050','iglesia','Iglesia de San Ildefonso','Monumental basílica del gótico tardío y renacimiento; posee tres portadas de diferentes estilos (gótico, plateresco y neoclásico) y custodia a la patrona de la ciudad en un camarín profusamente decorado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23051','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo del siglo XVI diseñado bajo las influencias del Renacimiento de Francisco del Castillo; construido con fábrica mixta de mampostería y ladrillo visto, posee una robusta torre campanario de líneas herrerianas y un interior de gran sobriedad.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23053','monumento','Castillo de Jódar','Fortaleza bajomedieval de frontera (siglos XII-XIV) que corona el casco histórico; conserva dos imponentes torres defensivas de sillería de piedra','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23053','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado sobre trazas góticas, con una portada neoclásica de piedra y una robusta torre de sillería calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23054','iglesia','Iglesia Parroquial de San Pedro Apóstol','Sencillo templo de arquitectura popular religiosa (siglo XVIII) construido con piedras calizas y mampostería basta en la llanura agrícola, con una espadaña tradicional de un solo vano para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23055','monumento','Yacimiento Arqueológico de Cástulo','Impresionante conjunto de la ciudad íbera y romana (siglo I a.C. - IV d.C.) a las afueras; conserva recintos monumentales, murallas de sillería caliza, el foro romano y el espectacular Mosaico de los Amores, un mosaico romano geométrico y figurativo de una finura y detalle pictórico extremos considerado una joya arqueológica nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23055','monumento','Hospital de los Marqueses de Linares','Edificio civil asistencial monumental de estilo neogótico francés e historicista construido a principios del siglo XX (1917); destaca por su fachada simétrica con torres cuadradas,','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23055','iglesia','Iglesia Parroquial de Santa María la Mayor','Monumental templo gótico del siglo XV con importantes ampliaciones renacentistas proyectadas por Andrés de Vandelvira, que conserva un presbiterio cubierto con complejas bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23056','monumento','Castillo de Lopera','Obra maestra de la arquitectura militar medieval de las órdenes militares (siglos XIII-XIV); espectacular fortaleza residencial de planta pentagonal irregular construida íntegramente con sillería de piedra caliza, destacando su foso defensivo perimetral, dos grandes torres almenadas (la Torre de San Miguel y la Torre del Homenaje) conectadas por adarves transitables y un patio de armas intacto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23056','iglesia','Iglesia Parroquial de la Purísima Concepción','Templo monumental del estilo gótico tardío (siglo XV) levantado en sillería caliza calavera; posee una cabecera poligonal y alberga en su interior capillas con bóvedas de crucería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23056','monumento','Casa de la Tercia (Pósito)','Edificio civil preindustrial del siglo XVI de piedra y ladrillo visto, concebido originalmente para el almacenamiento de grano de la orden militar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23057','monumento','Torre de Lupión','Esbelta torre vigía bajomedieval de frontera de planta circular construida en el siglo XIV con mampostería gruesa caliza, único resto visible de la antigua fortificación señorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23057','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de tres naves separadas por robustas columnas Apoyadas sobre arcos de medio punto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23058','iglesia','Iglesia Parroquial de San Juan Evangelista','Monumental templo edificado en el siglo XVI por orden real; obra maestra del Renacimiento clasicista andaluz proyectada por Andrés de Vandelvira y continuada por Juan de Aranda, destaca por su colosal fachada de sillería caliza con una gran portalada jónica, tres naves de gran altura y un espectacular coro.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23059','monumento','Complejo Histórico del Balneario de Marmolejo','Conjunto monumental de arquitectura civil y de ocio del siglo XIX; conserva templetes de estilo ecléctico y herrajes, jardines decimonónicos e infraestructuras preindustriales ligadas a la explotación de sus aguas mineromedicinales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23059','iglesia','Iglesia Parroquial de Nuestra Señora de la Paz','Templo del siglo XVI edificado con fábrica de sillería caliza calavera de líneas herrerianas sobrias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','monumento','Castillo de la Peña de Martos','Impresionante fortaleza bajomedieval de frontera (siglos XII-XIV) erigida por la Orden de Calatrava sobre el alcázar almohade; corona la inmensa peña rocosa vertical que domina la campiña y conserva lienzos de murallas defensivas de sillería y restos de su torre del homenaje, un baluarte inexpugnable.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','monumento','Castillo de la Villa y Torre del Almedina','Complejo defensivo urbano integrado en el casco antiguo; conserva la robusta torre de planta cuadrada construida en el siglo XIV por los caballeros calatravos, hoy rehabilitada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','iglesia','Real Iglesia de Santa Marta','Monumental templo del siglo XIV al XVI; de estilo gótico y renacentista diseñado por Francisco del Castillo, destaca por su espectacular portada de sillería caliza y por albergar enterramientos nobiliarios de la orden militar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23060','monumento','Cárcel y Cabildo de Martos','Joya del Manierismo civil andaluz del siglo XVI proyectada por Francisco del Castillo; presenta una grandiosa fachada simétrica que alberga una colosal portada jónica decorada con relieves mitológicos y un patio interior clásico de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23061','monumento','Torre del Homenaje del Castillo de Mengíbar','Espectacular torre bajomedieval (siglo XIV) declarada BIC; de planta cuadrada y gran altura construida en sillería de piedra caliza y ladrillo mudéjar, presenta un remate almenado y un carácter defensivo de control sobre el río Guadalquivir.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23061','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra caliza calavera, con un magnífico retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23063','iglesia','Iglesia Parroquial de San Juan Bautista','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería de piedra caliza, con una fachada rematada por un gran frontón clásico y una torre campanario robusta de tres cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23064','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Edificio del siglo XVI de estilo renacentista rural de frontera, construido con fábrica mixta de ladrillo visto y mampostería caliza en el límite con el reino de Granada, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23065','monumento','Torres de Santa Catalina (Las Tres Monjas)','Conjunto de tres esbeltas torres vigía de origen califal y almohade (siglos X-XII) de planta cuadrada, construidas con tapial de hormigón árabe rústico y piedra, enclaves defensivos de la Sierra de Segura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23065','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo monumental del siglo XVI de estilo gótico tardío y renacentista, que conserva una portada plateresca y un artesonado de madera de tradición mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23065','monumento','Fuente de los Tres Caños','Obra civil hidráulica renacentista del siglo XVI esculpida en piedra de cantería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23066','monumento','Torre del Reloj y Torre Mocha','Restos monumentales del castillo bajomedieval (siglo XIV) edificado por el Arzobispado de Toledo; colosales baluartes de planta cuadrada construidos en sillería de piedra caliza viva que presiden el casco urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23066','monumento','Cámara Sepulcral Ibérica de Toya','Joya absoluta de la arqueología nacional (BIC) de la cultura íbera (siglo IV a.C.) situada a las afueras; espectacular tumba subterránea construida íntegramente con grandes sillares de piedra perfectamente tallados y encajados sin argamasa, dividida en tres naves con arcos y puertas apuntadas de gran valor formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23066','iglesia','Iglesia Parroquial de Nuestra Señora de la Encarnación','Templo barroco de traza tradicional castellano-andaluza, restaurado tras sufrir destrucciones bélicas históricas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23067','monumento','Torre del Homenaje del Castillo y Arco de la Villa','Ruinas de la fortaleza bajomedieval de la que se conserva la majestuosa torre cuadrada de cantería caliza y el arco monumental que servía de puerta del recinto defensivo de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23067','monumento','La Charca de Pegalajar (Patrimonio Hidráulico)','Monumental infraestructura civil hidráulica y embalse preindustrial de origen medieval y renacentista construido en piedra de cantería, eje de un sistema de riego tradicional catalogado por su alto valor cultural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23067','iglesia','Iglesia Parroquial de la Santa Cruz','Templo renacentista del siglo XVI diseñado por los talleres de Juan de Aranda, con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23069','monumento','Torre de Boabdil (Castillo de la Orden de Calatrava)','Obra maestra indiscutible de la arquitectura militar gótica del siglo XV declarada Monumento Nacional; colosal torre del homenaje de planta octogonal perfecta construida íntegramente en sillería de piedra caliza, destacando sus bóvedas de crucería góticas caladas con una finura extrema en su interior y por haber sido el lugar de cautiverio del rey granadino Boabdil el Chico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23069','monumento','Yacimiento de Obulco (Cerrillo Blanco y Paseo de Jesús)','Impresionante conjunto arqueológico íbero y de la Hispania Romana; conserva la mayor cisterna romana de la provincia (la Cisterna de la Caldereros de sillería impecable), restos del foro y el Cerrillo Blanco, de donde procede el conjunto escultórico íbero más importante del país.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23069','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Monumental e histórico templo neoclásico del siglo XVIII de proporciones catedralicias, que alberga pinturas de gran formato e interiores columnados majestuosos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23069','monumento','Casa de la Piedra','Obra civil contemporánea colosal construida de forma autodidacta a lo largo de 30 años por el cantero Antonio Aguilera, esculpida íntegramente combinando grandes bloques de piedra caliza sin argamasa, hito de la arquitectura popular regional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23070','iglesia','Iglesia Parroquial de la Encarnación','Templo del siglo XVI con importantes modificaciones barrocas y neoclásicas; edificado en mampostería caliza y sillería en los esquinales, con una robusta torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23071','monumento','Puente Viejo sobre el río Guadalimar','Hermoso puente medieval e ilustrado (siglos XIV-XVIII) construido en sillería de piedra caliza; presenta arcos de medio punto y tajamares angulares, clave en las rutas de postas de la Sierra de Segura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23071','iglesia','Iglesia Parroquial de San Isidro Labrador','Templo barroco rural del siglo XVII de traza tradicional castellana con una sobria fachada de ladrillo y piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23072','iglesia','Iglesia Parroquial de San Mateo','Templo del siglo XVI edificado con fábrica de sillería caliza de líneas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23072','monumento','Puente del río Guadalimar','Antigua infraestructura de paso de cantería de piedra que controlaba el acceso natural a la cuenca alta de la sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23073','monumento','Yacimiento de la Villa Romana de Bruñel','Impresionante conjunto de una gran villa residencial y agrícola de la Hispania Romana (siglos II-IV d.C.); conserva el diseño de sus estancias, termas públicas y una notable colección de mosaicos geométricos polícromos de gran valor para la arqueología andaluza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23073','monumento','Arco de los Santos y Murallas','Antigua puerta de acceso fortificada de origen hispanomusulmán y bajomedieval, de sillería rústica de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23073','iglesia','Iglesia Parroquial de San Pedro','Templo monumental del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de piedra caliza, con una hermosa portada plateresca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23074','monumento','Oratorio Hipogeo de Valdecanales','Joya absoluta de la arqueología visigoda y paleocristiana de Andalucía (siglo VI d.C.) declarada Monumento Nacional; espectacular eremitorio excavado íntegramente en un frente vertical de roca arenisca caliza viva, destacando su fachada monumental con una arcada ciega de arcos de herradura','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23074','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI diseñado bajo las influencias de los talleres de Andrés de Vandelvira, de impecable fábrica de sillería con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23075','palacio','Castillo-Palacio de Sabiote','Obra maestra indiscutible de la arquitectura civil y militar renacentista del siglo XVI, reformado por el célebre arquitecto Andrés de Vandelvira por encargo de Francisco de los Cobos; destaca por su fisonomía defensiva abaluartada con troneras preparadas para la artillería pesada y un interior con un espectacular patio porticado renacentista de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23075','monumento','Recinto Amurallado de Sabiote','Impresionante cinturón de murallas medievales y renacentistas que abraza todo el casco histórico; conserva casi intacto su perímetro jalonado por torres corachas y puertas monumentales como la Puerta de los Santos y el Arco de la Canal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23075','iglesia','Iglesia Parroquial de San Pedro','Templo monumental del gótico tardío y renacimiento (siglo XVI), proyectado bajo la influencia de los talleres de Vandelvira; posee una espectacular portada plateresca norte y un presbiterio cubierto con intrincadas bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23076','monumento','Yacimiento de Las Navas de Tolosa y Castillo de las Navas','Restos y vestigios consolidados de la fortaleza defensiva bajomedieval (siglo XII-XIII) ligada a la mítica contienda de 1212 entre los reinos cristianos y los almohades, con una robusta torre Mocha de sillería rústica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23076','iglesia','Iglesia Parroquial de Santa Elena','Templo de estilo colonial ilustrado del siglo XVIII edificado por orden de Carlos III dentro del plan de las Nuevas Poblaciones de Sierra Morena, de líneas geométricas muy limpias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23077','iglesia','Iglesia Parroquial de la Virgen de la Estrella','Templo del siglo XVI edificado con fábrica de mampostería caliza de la campiña, que conserva una espadaña tradicional de dos vanos para las campanas y reformas barrocas, vinculado históricamente a las tierras feudales de la Orden de Calatrava.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23079','monumento','Castillo de San Esteban (Ruinas de las Torres)','Fortaleza bajomedieval de frontera (siglos XII-XIV) que corona el espolón del cerro de la villa; conserva lienzos de murallas defensivas de sillería caliza calavera y restos de su torre del homenaje robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23079','iglesia','Iglesia Parroquial de Santa María del Collado','Monumental templo edificado en el siglo XV; de estilo gótico con importantes añadidos renacentistas, destaca por su aspecto exterior fortificado y un magnífico artesonado mudéjar en su cabecera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23079','monumento','Yacimiento de Huellas de Dinosaurio (Icnitas)','Aunque natural (Cretácico), este afloramiento conserva espectaculares huellas fosilizadas integradas de forma monumental en el patrimonio didáctico de la comarca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23080','iglesia','Iglesia Parroquial de Santo Tomás Apóstol','Templo renacentista del siglo XVI de tres naves, construido en sillería de piedra caliza, que destaca por su robusta torre campanario barroca de líneas sencillas que funciona como hito del casco urbano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23081','monumento','Castillo de Segura de la Sierra','Impresionante y colosal fortaleza de origen califal y almohade, reconstruida en el siglo XIV por la Orden de Santiago de forma inexpugnable a 1.200 metros de altura; conserva un cinturón defensivo massivo de sillería berroqueña, cubos cilíndricos, una colosal Torre del Homenaje cuadrada y un patio de armas con un gran aljibe árabe subterráneo intacto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23081','monumento','Baños Árabes de Segura','Joya de la arquitectura civil hispanomusulmana (siglo XI-XII) perfectamente conservada en el casco histórico; destaca por su sala abovedada con tragaluces en forma de estrella y muros de tapial árabe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23081','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo monumental del gótico de transición y renacimiento, que alberga sepulcros nobiliarios asociados a los caballeros de la orden militar y una notable escultura de la virgen gótica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23081','monumento','Fuente Imperial de Carlos V','Obra civil hidráulica renacentista del siglo XVI esculpida en piedra caliza','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23082','monumento','Torre de El Cubo','Espectacular torre defensiva bajomedieval del siglo XIV erigida por la Orden de Santiago; colosal baluarte de planta circular construido en sillería de piedra caliza rústica, con saeteras, modillones y matacanes defensivos intactos que domina el casco urbano de la Sierra de Segura.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23082','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo renacentista del siglo XVI edificado en piedra caliza con una robusta torre campanario de líneas herrerianas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23084','iglesia','Iglesia Parroquial de Santa Águeda','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre de ladrillo de tradición aragonesa-andaluza en Las Villas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23085','iglesia','Iglesia Parroquial de San José','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza de la campiña, con una espadaña tradicional de dos','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23086','iglesia','Iglesia Parroquial de San Bartolomé','Monumental templo edificado en el siglo XVI con fábrica de sillería; de estilo renacentista herreriano, destaca por su esbelta torre campanario de tres cuerpos, su amplia nave central y un presbiterio con bóvedas de crucería góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23087','monumento','Castillo de Torredonjimeno','Espectacular fortaleza bajomedieval del siglo XIII erigida por la Orden de Calatrava sobre restos árabes; de planta cuadrangular, conserva muros defensivos almenados con torres cuadradas en las esquinas y un foso perimetral, hoy rehabilitado como espacio cultural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23087','palacio','Palacio Municipal (Ayuntamiento)','Joya de la arquitectura civil renacentista plateresca del siglo XVI; presenta una grandiosa fachada simétrica que alberga una colosal portada y escudos de armas nobiliarios tallados en piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23087','iglesia','Iglesia de San Pedro Apóstol','Monumental templo del gótico tardío y renacimiento (siglo XVI), construido íntegramente con grandes sillares de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23088','monumento','Las Torres Oscuras (Castillo de Pero Gil)','Espectaculares ruinas de la fortaleza señorial bajomedieval del siglo XIII erigida por el caballero Pero Gil; conserva dos imponentes torres de planta cuadrada de sillería de piedra caliza viva oscurecida (la Torre Ochavada y la Torre del Homenaje), consideradas iconos militares de la comarca de La Loma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23088','iglesia','Iglesia Parroquial de Santa María','Templo renacentista del siglo XVI diseñado bajo las influencias de los talleres de Andrés de Vandelvira, de impecable fábrica de sillería de gran altura basilical.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24086','iglesia','Iglesia Parroquial de Santo Domingo de Guzmán','Templo del siglo XVI de la comarca de Sierra Mágina edificado en sillería de granito y caliza, con una robusta torre campanario de líneas herrerianas y un presbiterio con techumbre de madera tallada tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','iglesia','Sacra Capilla del Salvador','Obra cumbre de la arquitectura civil y religiosa del Renacimiento español (siglo XVI), diseñada por Diego de Siloé y construida por Andrés de Vandelvira como panteón de Francisco de los Cobos; destaca por su colosal fachada plateresca que es un tapiz de piedra caliza esculpida con filigranas de una finura extrema, un interior circular deslumbrante cubierto con una inmensa cúpula casetonada y el retablo de la Transfiguración de Alonso Berruguete.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','palacio','Palacio de las Cadenas (Palacio de Juan de Vázquez de Molina / Ayuntamiento)','Obra maestra de la arquitectura palaciega renacentista, proyectada por Andrés de Vandelvira en el siglo XVI; presenta una grandiosa fachada de tres cuerpos de proporciones clásicas perfectas de influencia italiana, con un bellísimo patio interior porticado de arquerías de piedra caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','iglesia','Basílica de Santa María de los Reales Alcázares','Templo monumental que corona la plaza de Vázquez de Molina, levantado sobre la antigua mezquita mayor; fusiona el gótico, el mudéjar y el renacimiento, destacando su espectacular claustro gótico flamígero calado y portadas monumentales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','monumento','Hospital de Santiago','Conocido como "El Escorial Andaluz"; colosal complejo asistencial herreriano y clasicista diseñado en el siglo XVI por Andrés de Vandelvira por encargo del obispo Diego de los Cobos, destacando sus dos esbeltas torres con tejados de cerámica vidriada, una monumental iglesia de planta de salón y un gran patio porticado de columnas de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','palacio','Palacio del Marqués de Mancera','Espléndida mansión señorial renacentista del siglo XVI edificada con fábrica de sillería, que destaca por su torre del homenaje residencial almenada y portadas platerescas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23092','monumento','Murallas de Úbeda y Puerta del Losal','Restos del imponente recinto defensivo medieval fortificado por los','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23093','iglesia','Iglesia Parroquial de Santiago Apóstol','Monumental templo edificado en el siglo XVI por los grandes maestros renacentistas, obra de Juan de Aranda Salazar en la comarca de la Sierra Sur; posee una espectacular sillería de piedra, tres naves de gran altura y un presbiterio con bóvedas limpias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23094','ermita','Castillo de Vilches (Ermita de la Virgen del Castillo)','Ruinas señoriales de la antigua fortaleza medieval de origen árabe (siglo X) que corona el espolón del cerro, de la que se conservan lienzos defensivos de mampostería gruesa y una robusta torre, hoy rehabilitada de forma religiosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23094','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo gótico del siglo XV con importantes ampliaciones renacentistas, de sillería de piedra caliza calavera con una imponente torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23095','catedral','Iglesia Parroquial de la Asunción de Nuestra Señora (La Catedral de la Loma)','Obra maestra indiscutible de la arquitectura del Renacimiento clasicista y de planta de salón del siglo XVI, proyectada y construida por Andrés de Vandelvira; colosal templo de proporciones catedralicias construido íntegramente en sillería de piedra caliza, destacando su imponente espacio interior de tres naves de igual altura con colosales columnas anilladas y bóvedas vaídas de una finura arquitectónica universal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23096','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo renacentista del siglo XVI de tres naves separadas por columnas toscanas de piedra caliza calavera en la ribera del Guadalquivir, con una sobria torre campanario barroca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23097','iglesia','Iglesia Parroquial de San Andrés Apóstol','Monumental templo edificado en el siglo XVI con sillería de piedra; de estilo renacentista con trazas herrerianas puras, presenta muros limpios, una gran torre campanario de tres cuerpos y un presbiterio con bóvedas de crucería góticas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23097','iglesia','Santuario de Nuestra Señora de la Fuensanta','Complejo religioso barroco del siglo XVII de planta de cruz latina, foco de devoción comarcal de las Cuatro Villas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23098','monumento','Castillo de Villardompardo','Ruinas consolidadas de la fortaleza gótico-renacentista del siglo XV; conserva lienzos de murallas de mampostería de piedra caliza con cubos cilíndricos y elementos defensivos de gran interés histórico vinculados al marquesado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23101','iglesia','Iglesia Parroquial de San Bartolomé','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería de piedra caliza en el límite con la provincia de Albacete, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24095','iglesia','Iglesia Parroquial de San Juan Bautista','Edificio del siglo XVI de estilo renacentista rural, construido con fábrica de ladrillo visto y cajones de mampostería caliza en el entorno metropolitano, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23903','monumento','Núcleos de población de Villatorres','El término municipal incluye los siguientes núcleos de población: Torrequebradilla y Villargordo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23903','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora (Torrequebradilla)','Templo del siglo XVI edificado con','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90163','iglesia','Iglesia Parroquial de San Pedro','Templo de origen gótico rural (siglo XVI) edificado con muros de mampostería de piedra caliza, contrafuertes robustos y una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90163','monumento','Conjunto Arqueológico-Militar de el Castillo','Impresionante red de búnkeres, nidos de ametralladoras y trincheras excavadas en la roca caliza viva de la loma histórica que domina el valle del Tajuña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90164','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI construido en mampostería de piedra con refuerzo de sillares calizos en las esquinas, que destaca por su espadaña tradicional de dos vanos y su cuerpo de campanas en el Alto Tajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90165','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Sencillo templo de arquitectura barroca popular (siglo XVII) edificado con muros de mampostería caliza y adobe, con una espadaña de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90166','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza de la Alcarria, con una robusta espadaña de líneas sencillas y un interior desprovisto de grandes adornos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90167','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica de ladrillo visto y cajones de mampostería caliza a los pies de la muela de Alarilla, con una espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90168','iglesia','Iglesia Parroquial de San Andrés','Espléndido templo del siglo XV al XVI de estilo gótico tardío; catalogado como BIC, destaca por sus recios contrafuertes calizos, bóvedas de crucería estrellada y por custodiar la célebre Cruz de Albalate, joya de la orfebrería bajomedieval castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90168','monumento','Fuente de los Trece Caños','Obra civil hidráulica renacentista del siglo XVI esculpida íntegramente en bloques de piedra caliza con escudos heráldicos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90169','iglesia','Alminar de Salares (Torre de la Iglesia)','Joya monumental de la arquitectura almohade del siglo XIV declarada Monumento Nacional, erigida enteramente en ladrillo visto rojo tejar con paños de sebka en relieve y azulejería vidriada que se conserva intacta como torre','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90169','monumento','Puente Romano sobre el río Salares','Estructura caminera tradicional de sillería de piedra que salva el cauce del barranco mediante un robusto arco de medio punto ejecutado con dovelas de gran solidez.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90170','catedral','Iglesia Parroquial de la Asunción de Nuestra Señora (La Catedral de la Alcarria)','Obra maestra indiscutible del gótico de transición y gótico puro (siglos XIII-XIV) de proporciones catedralicias; levantada íntegramente con colosales sillares de piedra caliza calavera, destaca por su majestuoso interior de tres naves de gran altura, un ábside poligonal contrafuerteado con vitrales ojivales y una imponente torre campanario con remate de linterna barroca exenta única en la provincia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90171','monumento','Núcleos de población de Alcolea de las Peñas','El término municipal incluye los siguientes núcleos de población: Mezquetillas y Radona.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90171','iglesia','Iglesia de San Martín (Alcubilla de las Peñas)','Edificación de origen románico reformada en el período barroco en mampostería, de la que sobresale su portada meridional románica exenta de decoración con arquivoltas de medio punto sobre jambas lisas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90171','iglesia','Iglesia de la Inmaculada Concepción (Mezquetillas)','Templo románico rural del siglo XII levantado en cantería basta caliza, que conserva intacto su ábside semicircular con canecillos lisos bajo la cornisa y una espadaña de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90172','monumento','Núcleos de población de Alcolea del Pinar','El término municipal incluye los siguientes núcleos de población: Cortes de Tajuña, Garbajosa, Villaverde del Ducado.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90172','monumento','La Casa de Piedra','Obra civil de arquitectura popular esculpida de forma autodidacta a principios del siglo XX por el cantero Lino Bueno; se trata de una vivienda íntegramente excavada en el interior de una colosal roca exenta de granito vivo, hito de la arquitectura popular regional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90172','iglesia','Iglesia de Nuestra Señora de la Asunción (Villaverde del Ducado)','Templo que conserva trazas del románico de transición (siglo XII) en su portada y muros.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90173','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería de piedra arenisca roja de la comarca de Molina de Aragón, con una espadaña castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90174','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica mixta de ladrillo visto y mampostería caliza, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90175','iglesia','Iglesia Parroquial de Santo Domingo de Guzmán','Templo del siglo XVI edificado con fábrica de mampostería caliza en el valle del río Mesa, con una robusta torre campanario de líneas sencillas y restos góticos en el presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90176','iglesia','Iglesia Parroquial de San Juan Bautista','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre campanario de piedra en la Alcarria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90177','iglesia','Iglesia Parroquial de San Juan Bautista','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería basta, con un interior sobrio de una sola nave y espadaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90178','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo del siglo XVI de traza castellana tradicional edificado en sillería caliza calavera, profundamente reformado en su estructura contemporánea tras sufrir graves destrucciones en contiendas bélicas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90179','monumento','Castillo de Almoguera','Ruinas señoriales de una imponente fortaleza bajomedieval (siglos XII-XIV) erigida sobre un espolón estratégico de roca viva; conserva lienzos de murallas defensivas de sillería de piedra caliza y la base de su torre del homenaje robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90179','iglesia','Iglesia Parroquial de la de Nuestra Señora de la Asunción','Monumental templo del siglo XVI de tres naves, construido en sillería caliza calavera, con un espectacular retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90180','monumento','Recinto Amurallado de Almonacid y Puerta de Santa María','Espectacular muralla medieval de sillería de piedra caliza del siglo XIV que abraza el casco histórico; conserva casi intacto su perímetro jalonado por contrafuertes y la puerta monumental con arcos apuntados góticos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90180','iglesia','Iglesia Parroquial de Santo Domingo de Silos','Templo monumental iniciado en el siglo XV de estilo gótico tardío; de proporciones colosales, posee una espectacular sillería caliza calavera y bóvedas de crucería estrellada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90180','ermita','Ermita de la Virgen de la Luz','Gran santuario barroco del siglo XVII de planta de cruz latina y cúpula sobre pechinas, vinculado históricamente a las tierras feudales de la orden militar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90181','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo del siglo XVI de estilo renacentista rural herreriano, edificado con grandes bloques de piedra caliza sobre el espolón que domina el embalse de Entrepeñas, con una gran torre campanario robusta de tres cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90182','iglesia','Iglesia Parroquial de San Miguel Arcángel','Monumental templo del siglo XVI levantado con la técnica de cajones de mampostería caliza y ladrillo; declarado BIC, alberga en su presbiterio el colosal Retablo Mayor plateresco esculpido por los talleres reales de la escuela madrileña, de gran riqueza formal.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90183','monumento','Núcleos de población de Alustante','El término municipal incluye los siguientes núcleos de población: Motos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90183','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Espléndido templo del siglo XVI de estilo gótico tardío de transición al herreriano, levantado íntegramente con sillería de piedra arenisca de canteras locales; posee un aspecto exterior fortificado massivo con contrafuertes, un coro de madera tallada tradicional en su interior y un retablo mayor barroco de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90183','palacio','Palacio de los Marqueses de Alustante','Edificio civil señorial de arquitectura renacentista y herreriana del siglo XVII con una fachada de sillería de gran sobriedad geométrica y escudos de armas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19031','iglesia','Iglesia Parroquial de San Catherine','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19032','monumento','Núcleos de población de Anguita','El término municipal incluye los siguientes núcleos de población: Aguilar de Anguita, Santa María de Espino, Villarejo de Medina.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19032','monumento','Torre de la Cigüeña (Torre de Anguita)','Espectacular torre defensiva de planta cuadrada de origen andalusí y califal (siglo X) construida en mampostería gruesa caliza rústica, único vestigio de la red militar califal conservada intacta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19032','iglesia','Iglesia de San Pedro (Aguilar de Anguita)','Joya del románico de transición (siglo XII); conserva un espectacular ábside semicircular de sillería caliza calavera y una hermosa portada abocinada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19032','monumento','Yacimiento de las Necrópolis Celtíberas de Aguilar','Conjunto de campos de urnas y enterramientos prehistóricos de la Edad del Hierro de gran interés para la arqueología nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19033','iglesia','Iglesia Parroquial de San Martín','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras de arenisca y mampostería, con un interior sobrio de una sola nave y espadaña castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19034','iglesia','Iglesia Parroquial de San Martín','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería e hileras de ladrillo visto, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19036','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza y ladrillo en la vega del río Tajuña, con una robusta torre campanario barroca de líneas sencillas y un coro alto de madera tallada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19037','iglesia','Iglesia de Nuestra Señora de la Asunción','Monumental fábrica del gótico tardío y transición renacentista construida en sillería caliza de primer orden que destaca por sus tres naves columnarias a igual altura, sus intrincadas bóvedas de crucería estrellada y un fastuoso retablo mayor plateresco tallado en madera policromada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19037','palacio','Palacio del Duque de Riánsares','Suntuosa residencia civil del siglo XIX mandada edificar por Agustín Fernando Muñoz en estilo clasicista que exhibe una fachada de sillería simétrica con balcones moldurados y un gran patio porticado interior.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19037','monumento','Casco Antiguo y El Castillejo','Entramado urbano medieval que conserva restos de la muralla de mampostería encintada del siglo XII con el llamado Arco de la Malena como principal torre-puerta de acceso dovelada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19037','ermita','Ermita de San Roque','Oratorio barroco del siglo XVIII construido con aparejo toledano que cuenta con un crucero rematado en cúpula de media naranja decorada con molduras de yesería clasicistas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19039','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, con una robusta torre de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19040','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza en el corazón del Alto Tajo, con una robusta espadaña de líneas sencillas y un interior muy austero adaptado al entorno serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19041','iglesia','Iglesia Parroquial de San Juan Evangelista','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en piedra caliza, con una fachada rematada por un gran frontón clásico, tres amplias naves de gran altura y un espectacular retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19042','monumento','Casco Urbano (Arquitectura Negra)','Todo el pueblo destaca por su arquitectura popular de lajas de pizarra de los siglos XVI y XVII, con viviendas unifamiliares, corrales e infraestructuras agrarias construidas íntegramente con este material.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19042','iglesia','Iglesia Parroquial de San Ildefonso','Edificio religioso barroco popular edificado siguiendo los cánones constructivos tradicionales de pizarra rústica local, con una espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19043','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo del siglo XVI de estilo renacentista rural castellano herreriano, edificado con grandes bloques de piedra caliza de la Alcarria; destaca por su amplia nave central, su portada neoclásica simétrica y una torre campanario robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19046','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo de origen barroco (siglo XVII) edificado con muros de ladrillo visto y mampostería caliza en el corredor del Henares, profundamente restaurado en su estructura contemporánea.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19047','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza en el valle del río Henares, con una robusta torre campanario de líneas sencillas y restos góticos en el presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19048','iglesia','Iglesia Parroquial de San Juan Bautista','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza, con una espadaña de dos vanos para las campanas y un interior muy austero adaptado al entorno del río Tajuña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19049','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica rústica de mampostería de piedra caliza, con una espadaña de dos cuerpos adaptada al entorno rural.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19050','iglesia','Iglesia Parroquial de San Pedro','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería, con un interior sobrio de una sola nave y espadaña tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19051','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre campanario de piedra de la Alcarria y un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19052','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo del siglo XVI edificado con fábrica de mampostería caliza en las estribaciones de la sierra, con una robusta torre campanario de líneas sencillas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19054','monumento','Plaza Mayor de Budia','Espectacular plaza porticada castellana de origen renacentista (siglo XVI); presenta edificios de tres plantas con balconadas de madera y el tradicional sistema de soportales con pies derechos de piedra caliza calavera y madera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19054','iglesia','Iglesia Parroquial de San Pedro Apóstol','Monumental templo del siglo XVI que combina el gótico tardío y el renacimiento; posee una espectacular sillería caliza','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19054','iglesia','Convento de los Carmelitas Descalzos (Ruinas Consolidadas)','Complejo monástico de la orden carmelita del siglo XVII de ladrillo visto y piedra caliza calavera, del que se conserva la monumental fachada de líneas clasicistas de gran sobriedad geométrica.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19055','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza en el valle del Henares, con una robusta torre de líneas sencillas y restos góticos en el presbiterio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19057','iglesia','Iglesia Parroquial de San Lorenzo','Joya del románico rural (siglo XII) que conserva de forma excepcional una portada abocinada de arcos de medio punto y una espadaña defensiva massiva, construida íntegramente con lajas rústicas de pizarra local combinada con sillería de piedra caliza berroqueña calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19057','monumento','Casco Urbano (Arquitectura Negra)','Conjunto de viviendas e infraestructuras agrarias tradicionales hechas de pizarra sin argamasa adaptadas a la ladera de la Sierra de Ayllón.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19058','iglesia','Iglesia Parroquial de San Pedro Apóstol','Monumental templo del siglo XVI levantado en sillería de piedra caliza y ladrillo castellano; destaca por su gran nave barroca del siglo XVII decorada con ricas yeserías en el Corredor del Henares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19059','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de piedra arenisca roja de la comarca del Señorío de Molina, con una sólida torre de líneas castellanas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19060','monumento','Núcleos de población de Campillo de Ranas','El término municipal incluye los siguientes núcleos de población: Robleluengo, Majaelrayo, El Espinar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19060','monumento','Casco Urbano (Arquitectura Negra)','Uno de los conjuntos de arquitectura popular de lajas de pizarra más perfectos e intactos de España; viviendas, cercas y pajares de los siglos XVI al XVIII construidos íntegramente en pizarra oscura y madera de roble serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19060','iglesia','Iglesia Parroquial de la Santa Cruz','Edificio religioso único en su tipología, levantado íntegramente con muros de lajas de pizarra rústica local y una espadaña tradicional del mismo material que corona el paisaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19061','iglesia','Iglesia de San Bartolomé y Capilla de San Galindo','Joya absoluta del románico clásico (siglo XII) declarada Monumento Nacional; destaca por la pureza de sus líneas en sillería caliza calavera, pero de forma única en el mundo por el Mensario o Calendario Agrícola Románico labrado en los muros exteriores de la capilla, un friso de relieves pétreos de una finura extrema que detalla las labores del campo mes a mes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19064','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19065','monumento','Castillo de Diempures','Ruinas de una imponente fortaleza bajomedieval de frontera (siglos XII-XIV) emplazada de forma espectacular sobre un crestón de roca caliza viva; controlaba los accesos al norte serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19065','iglesia','Iglesia Parroquial de San Julián','Templo de mampostería basta de pizarra y piedra caliza adaptado al clima de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19066','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo serrano construido en mampostería de piedra rústica que presenta una espadaña de dos ojos exenta y un presbiterio con bóveda de arista tosca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19073','iglesia','Iglesia Parroquial de San Juan Evangelista','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta torre campanario de líneas sencillas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19075','iglesia','Iglesia Parroquial de San Martín','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre campanario de piedra de sillería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19076','iglesia','Iglesia Parroquial de Nuestra Señora de la Carrasca','Templo del siglo XVI de estilo renacentista rural del Señorío de Molina, construido con fábrica rústica de mampostería de piedra arenisca, con una espadaña castellana tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19078','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo que conserva trazas góticas (siglo XV) en su cabecera y muros de sillería caliza calavera, con un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19079','monumento','Casa-Fuerte de Castilnuevo','Espectacular torre y complejo residencial fortificado bajomedieval del siglo XIV erigido en sillería de piedra arenisca roja sobre la vega del río Gallo, ejemplo único de arquitectura militar señorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19079','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Templo de estilo gótico rural mudéjar integrado en el entorno.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19082','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en piedra caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19086','monumento','Núcleos de población de Cifuentes','El término municipal incluye los siguientes núcleos de población: Gárgoles de Abajo, Gárgoles de Arriba, Val de San García.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19086','monumento','Castillo de Don Juan Manuel','Impresionante fortaleza señorial bajomedieval construida en el siglo XIV (año 1324) por el célebre infante y escritor Don Juan Manuel; de planta cuadrangular perfecta construida en sillería caliza, destaca por sus muros almenados, torres cuadradas y cilíndricas angulares y una esbelta torre del homenaje.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19086','iglesia','Iglesia Parroquial de San Salvador','Monumental templo iniciado en el románico (siglo XIII) con ampliaciones góticas y renacentistas; catalogado como BIC, destaca por su espectacular Portada de Santiago, una de las cumbres del románico tardío alcarreño con arquivoltas profusamente esculpidas con relieves figurativos y un rosetón calado de una finura extrema.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19086','iglesia','Convento de Santo Domingo y Convento de San Blas','Conjunto de colosales conventos barrocos del siglo XVII de muros de cantería caliza, focos de la historia eclesiástica de la villa señorial.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19086','monumento','Casa de los Gallos','Edificio civil señorial de arquitectura renacentista del siglo XVI; presenta una gran fachada de sillería con un monumental escudo heráldico flanqueado por dos gallos esculpidos en piedra caliza viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19087','iglesia','Iglesia Parroquial de San Vicente','Joya del románico rural (siglo XII); conserva un espectacular ábside de sillería caliza calavera con tres pisos de arquerías ciegas','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19088','iglesia','Iglesia Parroquial de San Pedro','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería caliza, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19090','monumento','Torre de Cobeta','Espectacular torre del homenaje bajomedieval del siglo XIV erigida en sillería de piedra caliza viva sobre un escarpado peñón de roca que corona la villa; baluarte cuadrado defensivo intacto de gran valor estratégico en el Alto Tajo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19090','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI de traza tradicional castellana, edificado con grandes sillares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19092','monumento','Núcleos de población de Cogolludo','El término municipal incluye los siguientes núcleos de población: Aleas, Beleña de Sorbe, Torrebeleña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19092','palacio','Palacio de los Duques de Medinaceli (Palacio de Cogolludo)','Obra cumbre e hito histórico de la arquitectura renacentista española (siglo XV, año 1492) diseñado por Lorenzo Vázquez; considerado el primer palacio puramente renacentista edificado fuera de Italia en la península, destaca por su fachada monumental de almohadillado florentino ejecutada en sillería caliza, ventanales platerescos esculpidos con filigranas de una finura extrema, una espectacular crestería góticoflamígera de remate y un patio porticado clásico majestuoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19092','iglesia','Iglesia de Santa María','Monumental templo gótico del siglo XVI de tres naves separadas por colosales columnas de piedra; posee portadas renacentistas y alberga en su presbiterio una techumbre calada de gran valor, además del lienzo original de la escuela italiana de José de Ribera "El Españoleto".','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19092','monumento','Castillo de Cogolludo','Ruinas señoriales de la imponente fortaleza bajomedieval (siglos XII-XV) que corona el cerro de la villa; conserva lienzos de murallas defensivas de cantería caliza calavera y la torre de la campana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19092','iglesia','Iglesia de San Pedro (Beleña de Sorbe)','Joya del románico porticado (siglo XII) situada en su pedanía; catalogada como BIC, posee una espectacular galería con arquerías de medio punto y una de las portadas con el calendario agrícola románico más importantes de la provincia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19095','iglesia','Iglesia Parroquial de San Juan Bautista','Templo del siglo XVI edificado con fábrica de mampostería caliza serrana, con una robusta torre campanario de líneas sencillas y un interior muy austero adaptado al entorno montañoso de la Sierra de Pela.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19096','iglesia','Iglesia Parroquial de San Vicente Mártir','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica rústica de mampostería de piedra caliza, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19097','monumento','Casco Urbano (Arquitectura Negra)','Conjunto de viviendas e infraestructuras agrarias tradicionales hechas de lajas de pizarra rústica local sin argamasa adaptadas a las estribaciones serranas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19097','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio de origen renacentista (siglo XVI) construido siguiendo los cánones constructivos tradicionales de pizarra rústica local.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19098','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica mixta de mampostería caliza e hleras de ladrillo, con una robusta torre campanario barroca de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19099','monumento','Núcleos de población de Corduente','El término municipal incluye los siguientes núcleos de población: Aragoncillo, Teroleja, Cuevas Minadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19099','monumento','Castillo de Santiuste','Impresionante fortaleza residencial bajomedieval del siglo XV erigida en sillería de piedra arenisca roja sobre una loma que domina el Barranco de la Hoz; de planta cuadrangular perfecta, conserva sus muros almenados, torres cilíndricas angulares y una imponente torre del homenaje robusta en perfecto estado de conservación.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19099','iglesia','Santuario de la Virgen de la Hoz','Complejo religioso edificado en el fondo de las Hoces del río Gallo; de sillería de arenisca roja calavera, se encaja de forma increíble en el paisaje rocoso.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19107','monumento','Yacimiento Arqueológico de la Ciudad Romana de Caraca','Impresionante enclave de la Hispania Romana excavado y consolidado a las afueras; conserva las trazas del foro, estructuras de viviendas y un colosal acueducto subterránea de sillería de gran valor arqueológico nacional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19107','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con muros de mampostería caliza y ladrillo visto castellano, con una robusta torre campanario de líneas sobrias.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19108','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo del siglo XVI de traza renacentista con reformas barrocas del XVII en la Alcarria; destaca por su gran nave central con bóvedas de cañón, una robusta torre de sillería caliza y su patrimonio de bodegas tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19108','ermita','Ermita de la Virgen de la Esperanza','Pequeña construcción devocional barroca del siglo XVII que constituye un conjunto monumental exento sobre el embalse de Entrepeñas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19109','monumento','Castillo de Embid','Espectacular fortaleza bajomedieval de frontera (siglos XII-XIV) emplazada de forma monumental sobre un espolón estratégico de roca viva caliza; de planta cuadrangular, conserva muros defensivos almenados con torres cilíndricas en las esquinas y una imponente Torre del Homenaje cuadrada de cantería impecable.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19109','iglesia','Iglesia Parroquial de Santa Catherine','Templo del siglo XVI edificado en piedra de líneas tradicionales castellano-aragonesas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19110','iglesia','Iglesia Parroquial de la Purificación de Nuestra Señora','Joya absoluta del barroco clasicista alcarreño (siglo XVIII) declarada BIC; destaca de forma única por su espectacular Torre Campanario Giralda, una esbelta estructura de cuatro cuerpos de piedra caliza calavera profusamente labrada con pináculos y arquerías ciegas de una finura extrema que domina la Alcarria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19110','monumento','Castillo de Escamilla','Ruinas señoriales de la antigua fortaleza defensiva bajomedieval (siglo XIV) de muros de cantería de granito y caliza que corona la peña de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19111','iglesia','Iglesia Parroquial de San Miguel','Joya que conserva trazas del románico de transición (siglo XII) en su cabecera semicircular de sillería caliza calavera con canecillos labrados, adosada a un cuerpo de nave renacentista levantado en piedra con un retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19112','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero de nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19113','monumento','Núcleos de población de Espinosa de Henares','El término municipal incluye los siguientes núcleos de población: Carrascosa de Henares y Hitaburgo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19113','monumento','Puente Medieval sobre el río Henares','Hermoso puente medieval e ilustrado (siglos XIV-XVIII) construido en sillería de piedra caliza; presenta arcos de medio punto y monumentales tajamares triangulares exentos, clave en las comunicaciones históricas de la Alcarria.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19113','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo monumental del siglo XVI edificado con grandes sillares de piedra de canteras locales, con una robusta torre campanario de traza castellana tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19114','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica rústica de mampostería de piedra caliza, con una espadaña de dos cuerpos adaptada al clima de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19116','iglesia','Iglesia Parroquial de San Pedro','Sencillo templo de arquitectura barroca popular (siglo XVII) construido con piedras calizas y mampostería basta en la llanura, con una espadaña tradicional de dos vanos para las campanas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19117','iglesia','Iglesia Parroquial de San Andrés Apóstol','Pequeño templo de montaña construido en mampostería de pizarra rústica y cuarcita local que conserva una','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19117','monumento','Yacimiento Arqueológico de Malamoneda','Complejo histórico de gran envergadura que engloba una necrópolis altomedieval con tumbas excavadas en la roca granítica, un asentamiento hispanorromano y los restos de una torre defensiva bajomedieval de planta cuadrada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19118','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería de piedra arenisca roja de la comarca del Señorío de Molina, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19119','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio del siglo XVI de estilo renacentista rural castellano, construido con fábrica mixta de ladrillo visto y cajones de mampostería caliza, con una espadaña de dos cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19120','iglesia','Iglesia Parroquial de San Juan Bautista','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería de piedra caliza, con una fachada rematada por un gran frontón clásico y una torre campanario robusta de tres cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19121','monumento','Torre de la Mora (Restos de la Muralla)','Espectacular torre defensiva de planta cuadrada de origen hispanomusulmán y bajomedieval (siglo XII) construida en cantería caliza regular, vestigio del antiguo recinto defensivo de la villa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19121','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo del siglo XVI que combina el gótico flamenco y el renacimiento; levantado íntegramente con grandes sillares de piedra, destaca por sus bóvedas de crucería y un colosal retablo mayor renacentista de gran valor.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19122','monumento','Castillo de Fuentelsaz','Ruinas de la fortaleza señorial bajomedieval de frontera (siglos XIV-XV) que corona el cerro de la villa; conserva un cinturón defensivo masivo de cantería de piedra arenisca y restos de su torre del homenaje robusta.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19122','iglesia','Iglesia Parroquial de Santiago Apóstol','Templo del siglo XVI edificado en piedra de líneas tradicionales con una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19123','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, con una sobria espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19124','monumento','La Picota de Fuentenovilla','Joya absoluta del arte renacentista y plateresco civil (siglo XVI, año 1548) situada en la Plaza Mayor; colosal y esbelta columna de piedra caliza calavera magníficamente tallada con motivos platerescos, gárgolas con cabezas de león y un remate piramidal que atestigua el rango de villa judicial autónoma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19124','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo monumental del siglo XVI edificado con grandes sillares de piedra caliza de la Alcarria, con una robusta torre campanario de tres cuerpos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19125','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo barroco neoclásico edificado dentro del plan de reconstrucción monumental unificada de la comarca, de planta de cajón con muros de piedra caliza berroqueña calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19126','palacio','Palacio de los Condes de Galápagos (Casa Grande)','Edificio civil señorial de arquitectura renacentista y barroca (siglos XVI-XVII) construido en ladrillo visto y piedra; destaca por su patio porticado de madera de tradición mudéjar castellana.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19126','iglesia','Iglesia Parroquial de San Pedro','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería e hileras de ladrillo visto, que conserva una robusta torre campanario.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19127','monumento','Castillo de Galve de Sorbe (Castillo de los Zúñiga)','Impresionante fortaleza señorial bajomedieval construida en el siglo XV (año 1460) por los condes de Miranda de la familia Zúñiga; corona el cerro de la villa con un perímetro amurallado de sillería de piedra caliza, cubos defensivos circulares y una colosal Torre del Homenaje de planta cuadrada que domina el perfil del norte serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19127','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo gótico y renacentista del siglo XVI levantado con sillería de canteras locales, con una robusta torre campanario herreriana de líneas sencillas adaptada al clima de montaña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19132','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo renacentista del siglo XVI levantado con muros de mampostería caliza y sillería en las esquinas, que destaca por su espadaña de tres vanos y su patrimonio de bodegas tradicionales excavadas en el subsuelo alcarreño.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19133','iglesia','Iglesia Parroquial de San Miguel Arcángel','Templo barroco rural del siglo XVII edificado con fábrica mixta de ladrillo visto y cajones de mampostería caliza en la vega del río Henares, con un interior sobrio de nave única y una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19134','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Edificio del siglo XVI de estilo renacentista rural del Señorío de Molina, construido con sillería de piedra arenisca roja de canteras locales, con una robusta torre campanario de líneas sencillas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19135','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI con importantes modificaciones neoclásicas, levantado en piedra de sillería de la sierra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19138','monumento','Murallas de Hita y Puerta de Santa María','Espectacular recinto defensivo medieval del siglo XIV mandado edificar por los señores de Mendoza; conserva tramos de gran espesor construidos con mampostería y sillería caliza calavera, destacando la puerta monumental flanqueada por garitas almenadas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19138','iglesia','Ruinas de la Iglesia de San Pedro','Espectaculares ruinas consolidadas de una monumental colegiata del gótico mudéjar (siglo XIV) levantada en ladrillo visto y piedra caliza, que conserva sepulcros de la nobleza e hidalguía alcarreña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19138','monumento','Bodegas y Bodegones Subterráneos (Patrimonio Etnológico)','Red de más de un centenar de bodegas medievales excavadas en el subsuelo del cerro por la antigua comunidad judía y mudéjar de la villa, con lagares tradicionales enteros de piedra.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19138','iglesia','Iglesia Parroquial de San Juan Bautista','Templo gótico mudéjar del siglo XV al XVI; posee una esbelta torre','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19139','iglesia','Iglesia Parroquial de Nuestra Señora de la Asunción','Templo herreriano del siglo XVI de gran sobriedad geométrica, construido en sillería de piedra arenisca de la comarca de Molina de Aragón, con una fachada rematada por un gran frontón clásico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19142','iglesia','Iglesia Parroquial de San Pedro','Joya que conserva una magnífica cabecera y ábside semicircular del románico de transición (siglo XII) levantada en sillería caliza calavera con canecillos labrados, adosada a un cuerpo de nave renacentista.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19143','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo del siglo XVI de tres naves de gran altura, diseñado por los maestros platerescos; posee una espectacular sillería caliza, un coro de madera tallada tradicional en su interior y un colosal retablo mayor barroco.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19143','ermita','Ermita de la Virgen de la Soledad','Gran santuario barroco del siglo XVII de planta de cruz latina y cúpula sobre pechinas ricamente decorada con yeserías ornamentales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19143','monumento','Red de Bodegas Subterráneas (Patrimonio Etnológico)','Laberinto de galerías excavadas en el subsuelo arcilloso entre los siglos XV y XVIII, con tinajas históricas y arcos de piedra caliza viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19145','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza, con una robusta espadaña tradicional de dos vanos para las campanas y un interior muy austero de nave única.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19146','monumento','Núcleos de población de La Huerce','El término municipal incluye los siguientes núcleos de población: Umbralejo, Valdepinillos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19146','monumento','Conjunto Urbano de Umbralejo (Patrimonio Etnológico)','Espectacular pueblo deshabitado rehabilitado de forma íntegra; viviendas, corrales e infraestructuras agrarias de los siglos XVI al XVIII construidos combinando lajas rústicas de pizarra oscura y tapial de arcilla, modelo único de hábitat serrano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19146','iglesia','Iglesia Parroquial de la Asunción (La Huerce)','Edificio religioso edificado siguiendo los cánones constructivos tradicionales de pizarra rústica local, con una espadaña tradicional del mismo material.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19148','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo del siglo XVI edificado con fábrica de mampostería caliza en el corazón del Alto Tajo, con una robusta espadaña de líneas sencillas y un interior muy austero.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','monumento','Muelle del Tinto (Cargadero de Mineral de la Compañía de Riotinto)','Monumental e histórica infraestructura de la arquitectura industrial de finales del siglo XIX proyectada por la escuela de Eiffel, consistente en un colosal viaducto y muelle marítimo de hierro calado y madera que se adentra de forma monumental en la ría de Huelva asentado sobre recios pilares de fundición.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','catedral','Santa Iglesia Catedral de Nuestra Señora de la Merced','Monumental fábrica de estilo barroco academicista del siglo XVII erigida como iglesia del convento de los mercedarios, que destaca por su espaciosa planta basilical sostenida por pilares toscanos y una espectacular fachada monumental de gran plasticidad esculpida.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','iglesia','Santuario de Nuestra Señora de la Cinta','Joya monumental gótico-mudéjar de los siglos XV y XVI exenta sobre el cabezo del Conquero, edificado en ladrillo visto y mampostería encalada que conserva de forma magistral sus tres naves techadas por armaduras de madera y un claustro tradicional.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','monumento','Barrio Obrero / Barrio Reina Victoria','Espectacular y colosal conjunto residencial y urbanístico de la arquitectura civil británica de principios del siglo XX, constituido por decenas de viviendas de estilo victoriano con entramados de madera pintada y cubiertas inclinadas de teja que configuran un paisaje único en la urbe.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19150','iglesia','Iglesia de San Pedro','El templo cristiano más antiguo de la capital, datado en el siglo XV de estilo góticomudéjar primitivo, edificado sobre los restos de una antigua mezquita andalusí con una esbelta torre campanario barroca de ladrillo visto moldurado profusamente decorada.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19151','monumento','Núcleos de población de Humanes','El término municipal incluye los siguientes núcleos de población: Cerezo de Mohernando.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19151','iglesia','Iglesia Parroquial de San Esteban Protomártir','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hileras de ladrillo visto, que conserva una sobria torre campanario barroca de ladrillo.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19152','palacio','Palacio de los Goyeneche (Casa Grande)','Edificio civil señorial de arquitectura barroca y clasicista del siglo XVIII diseñado por los talleres reales; presenta una gran fachada de sillería caliza con portalada de medio punto y blasones heráldicos nobiliarios esculpidos en piedra caliza viva.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19152','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Monumental templo edificado en el siglo XVI con grandes sillares de piedra caliza; de estilo renacentista castellano, conserva una fachada herreriana limpia.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19153','iglesia','Iglesia Parroquial de la Asunción','Monumental fábrica columnaria de transición gótico-renacentista del siglo XVI erigida en sillería caliza calavera que exhibe una nave','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19153','palacio','Palacio del Marqués de Melgarejo','Casona palaciega barroca del siglo XVIII construida con muros exteriores de aparejo toledano y piedra labrada que conserva una portada monumental flanqueada por pilastras jónicas y rematada por un gran escudo heráldico tallado en relieve.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19153','ermita','Ermita de la Concepción','Oratorio del siglo XVII ejecutado en mampostería encintada y verdugadas de ladrillo visto que presenta una fachada clasicista rematada por un frontón herreriano y una espadaña de dos ojos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19156','monumento','Castillo de Jadraque (Castillo del Cid)','Obra maestra de la arquitectura militar y palaciega bajomedieval (siglo XV) encargada por el cardenal Pedro González de Mendoza sobre una antigua fortaleza andalusí; colosal fortaleza residencial de planta rectangular perfecta y sillería caliza calavera que corona de forma espectacular un cerro de la vega del Henares, destacando sus muros almenados, torres cilíndricas angulares y contrafuertes.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19156','iglesia','Iglesia Parroquial de San Juan Bautista','Monumental templo del siglo XVI que combina el gótico flamenco y el renacimiento; posee una espectacular sillería caliza, tres amplias naves de gran altura y alberga en su interior el famoso óleo sobre lienzo de Francisco de Zurbarán "La Inmaculada Niña".','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19156','palacio','Casona de las Cadenas','Edificio civil señorial de arquitectura renacentista del siglo XVI; presenta una gran fachada de sillería con un monumental escudo heráldico y herrajes de forja tradicionales.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19157','iglesia','Iglesia Parroquial de San Bartolomé','Joya del románico rural (siglo XII); conserva un espectacular ábside de sillería caliza calavera con tres pisos de arquerías ciegas de gran pureza formal e hleras de aparejo tradicional castellano.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19159','monumento','Núcleos de población de Ledanca','El término municipal incluye los siguientes núcleos de población: Valfermoso de las Monjas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19159','iglesia','Monasterio de San Juan Bautista (Valfermoso de las Monjas)','Impresionante complejo monástico benedictino femenino fundado en el siglo XII; conserva de forma impecable su iglesia de sillería caliza calavera, portadas románicas y estancias abovedadas de gran valor histórico.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19159','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora (Ledanca)','Templo renacentista del siglo XVI edificado con grandes sillares.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19160','iglesia','Iglesia Parroquial de San Pedro Apóstol','Monumental templo herreriano del siglo XVI de gran sobriedad','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19160','iglesia','Ruinas del Monasterio de la Espeja','Vestigios consolidados de una gran abadía bajomedieval de muros de mampostería caliza.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19161','iglesia','Monasterio de San Bartolomé de Lupiana','Colosal e histórico complejo monástico fundado en el siglo XIV (año 1330) declarado Monumento Nacional; destaca de forma única en el mundo por su espectacular Claustro Plateresco de tres plantas diseñado por el arquitecto Alonso de Covarrubias en el siglo XVI, una obra cumbre del Renacimiento español esculpida en piedra caliza con una profusión y delicadeza de filigranas, bustos y motivos heráldicos inverosímiles.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19161','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo monumental del siglo XVI que combina el gótico tardío y el renacimiento; levantado íntegramente con grandes sillares de piedra caliza de la comarca, con una esbelta torre campanario herreriana y un magnífico artesonado de madera de tradición mudéjar.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19161','monumento','Picota Jurisdiccional de Lupiana','Joya del arte gótico civil (siglo XV) situada en el casco histórico; columna tallada en piedra caliza calavera que atestigua el rango de villa judicial autónoma.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19162','monumento','Yacimiento Celtíbero de el Castillo de Luzaga','Espectacular oppidum y castro de la Edad del Hierro de gran interés para la arqueología nacional; de donde procedía el famoso Bronce de Luzaga con epigrafía celtíbera, conserva recintos habitacionales de piedra seca.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19162','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo que conserva trazas del románico de transición (siglo XII) en su cabecera y muros de sillería caliza calavera.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19163','iglesia','Iglesia Parroquial de San Pedro Apóstol','Templo del siglo XVI de estilo renacentista rural castellano herreriano, edificado con grandes bloques de piedra caliza de canteras locales, con una robusta torre campanario de tres cuerpos y muros de mampostería.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19167','iglesia','Iglesia Parroquial de la Asunción','Fábrica del siglo XVI reformada en el barroco levantada con muros de mampostería encintada que aloja un crucero amplio y una torre campanario de dos cuerpos rematada en ladrillo visto.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19168','monumento','Núcleos de población de Mandayona','El término municipal incluye los siguientes núcleos de población: Aragosa.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19168','iglesia','Iglesia de San Pedro Apóstol (Mandayona)','Templo de origen románico reformado en el siglo XVI en sillería caliza y mampostería, cuyo interior alberga un notable retablo mayor plateresco con relieves tallados y una pila bautismal románica decorada con arquerías ciegas.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19168','iglesia','Iglesia de San Juan Bautista (Aragosa)','Pequeño edificio románico rural del siglo XII edificado en cantería basta caliza, que conserva su ábside semicircular original con canecillos lisos bajo la cornisa y una espadaña de dos vanos a los pies.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19173','iglesia','Iglesia Parroquial de la Asunción de Nuestra Señora','Templo barroco rural del siglo XVII edificado con muros de mampostería caliza, con una espadaña tradicional de dos vanos para las campanas y un interior muy sobrio.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19174','iglesia','Iglesia Parroquial de la Inmaculada Concepción','Sencillo templo de arquitectura popular (siglo XVII) edificado con muros bastos de mampostería y piedra caliza calavera, con una espadaña tradicional de dos vanos.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19176','iglesia','Iglesia Parroquial de Santo Domingo de Silos','Templo renacentista del siglo XVI levantado con la técnica de cajones de mampostería caliza e hleras de ladrillo visto, que conserva una sobria torre de ladrillo de tradición alcarreña.','inventario_monumentos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19177','iglesia','Iglesia Parroquial de la Natividad de Nuestra Señora','Templo barroco rural (siglo XVII) edificado con muros bastos de mampostería caliza, con una espadaña tradicional de dos vanos y un interior desprovisto de grandes adornos.','inventario_monumentos_pdf');
